window.H=window.H||{};H[36]={"36회-1차-004":{"한줄":"택지(ㄱ), 일단지(ㄷ), 후보지(ㅁ)의 정의만 맞고, ㄴ은 필지, ㄹ은 빈지의 정의다.","근거":[{"이론":"토지 관련 용어","내용":"필지는 지적공부에 등록하는 법적 단위, 획지는 가격수준이 비슷한 일단의 토지, 빈지는 소유권이 인정되지 않는 바다와 육지 사이의 해변 토지, 포락지는 지적공부에 등록된 토지가 물에 침식되어 수면 아래로 잠긴 토지다."}],"선지":[{"번호":1,"판정":"-","설명":"ㄴ이 틀려 조합이 성립하지 않는다."},{"번호":2,"판정":"-","설명":"ㄹ이 틀려 조합이 성립하지 않는다."},{"번호":3,"판정":"-","설명":"ㄱ, ㄷ, ㅁ이 옳다."},{"번호":4,"판정":"-","설명":"ㄴ이 틀렸다."},{"번호":5,"판정":"-","설명":"ㄴ, ㄹ이 틀렸다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"택지는 주거용·상업용·공업용으로 이용 중이거나 그 용도로 조성된 토지다."},{"기호":"ㄴ","판정":"틀림","설명":"지적공부에 등록하는 단위는 필지다. 획지는 인위적·자연적·행정적 조건이 같아 가격수준이 비슷한 일단의 토지다."},{"기호":"ㄷ","판정":"옳음","설명":"일단지는 용도상 불가분 관계에 있는 2필지 이상의 토지다."},{"기호":"ㄹ","판정":"틀림","설명":"소유권이 인정되지 않는 바다와 육지 사이의 토지는 빈지다. 포락지는 지적공부에 등록됐다가 물에 잠겨 이용할 수 없게 된 토지다."},{"기호":"ㅁ","판정":"옳음","설명":"후보지는 택지·농지·임지지역 상호 간에 전환 중인 지역의 토지다. 같은 용도지역 안에서 세분된 지역 간 전환 중인 토지는 이행지다."}],"개념":[{"종류":"표","제목":"토지 용어 구분","머리":["용어","뜻"],"행":[["필지","지적공부에 등록하는 법적 단위 토지"],["획지","가격수준이 비슷한 일단의 토지(이용·가격 단위)"],["일단지","용도상 불가분 관계에 있는 2필지 이상의 토지"],["빈지","소유권이 인정되지 않는 바다와 육지 사이의 해변 토지"],["포락지","지적공부에 등록된 토지가 침식되어 물에 잠긴 토지"],["후보지","택지·농지·임지지역 상호 간에 전환 중인 토지"],["이행지","같은 용도지역 안의 세분된 지역 간에 전환 중인 토지"]]}],"함정":"필지와 획지를 바꿔 묻고, 빈지와 포락지를 바꿔 묻는 방식이 반복된다. 지적공부에 등록하는 단위는 필지, 소유권 없는 해변은 빈지다."},"36회-1차-003":{"한줄":"건축법 시행령 별표 1에서 단독주택은 단독주택·다중주택·다가구주택·공관이고, 다중주택이 여기에 속한다.","근거":[{"법령":"건축법 시행령","조문":"별표 1 제1호","원문":"가. 단독주택 / 나. 다중주택: 다음의 요건을 모두 갖춘 주택을 말한다. 1) 학생 또는 직장인 등 여러 사람이 장기간 거주할 수 있는 구조로 되어 있는 것 2) 독립된 주거의 형태를 갖추지 않은 것(각 실별로 욕실은 설치할 수 있으나, 취사시설은 설치하지 않은 것을 말한다) 3) 1개 동의 주택으로 쓰이는 바닥면적(부설 주차장 면적은 제외한다. 이하 같다)의 합계가 660제곱미터 이하이고 주택으로 쓰는 층수(지하층은 제외한다)가 3개 층 이하일 것 / 다. 다가구주택 / 라. 공관(公館)"}],"선지":[{"번호":1,"판정":"-","설명":"아파트는 주택으로 쓰는 층수가 5개 층 이상인 공동주택이다(별표 1 제2호가목)."},{"번호":2,"판정":"-","설명":"연립주택은 1개 동 바닥면적 합계 660제곱미터 초과, 4개 층 이하의 공동주택이다(별표 1 제2호나목)."},{"번호":3,"판정":"-","설명":"다중주택은 단독주택의 하위 유형이다(별표 1 제1호나목)."},{"번호":4,"판정":"-","설명":"오피스텔은 업무시설이다(별표 1 제14호나목2))."},{"번호":5,"판정":"-","설명":"다세대주택은 1개 동 바닥면적 합계 660제곱미터 이하, 4개 층 이하의 공동주택이다(별표 1 제2호다목)."}],"개념":[{"종류":"표","제목":"건축법상 주택 분류","머리":["구분","유형","요건"],"행":[["단독주택","단독주택","1세대가 거주하는 일반 단독주택"],["단독주택","다중주택","독립 주거형태 아님(취사시설 없음), 바닥면적 합계 660㎡ 이하, 3개 층 이하"],["단독주택","다가구주택","3개 층 이하, 바닥면적 합계 660㎡ 이하, 19세대 이하"],["단독주택","공관","공적 직위 수행자의 관사"],["공동주택","아파트","5개 층 이상"],["공동주택","연립주택","1개 동 바닥면적 합계 660㎡ 초과, 4개 층 이하"],["공동주택","다세대주택","1개 동 바닥면적 합계 660㎡ 이하, 4개 층 이하"]]}],"함정":"다가구주택과 다세대주택을 혼동해 다세대를 단독주택으로 고르기 쉽다. 다가구는 단독, 다세대는 공동이다. 오피스텔은 주택이 아니라 업무시설(주택법상으로는 준주택)이다."},"36회-1차-001":{"한줄":"생산할 수 없어 공급이 제한된다는 성질이 부증성이고, 이 때문에 지대·지가가 생기고 집약적 이용과 최유효이용이 요구된다.","근거":[{"이론":"토지의 자연적 특성 중 부증성","내용":"토지는 물리적으로 생산해 늘릴 수 없다. 공급이 비탄력적이어서 희소성이 생기고, 지대(지가) 발생, 집약적 이용, 최유효이용의 근거, 토지 소유 욕구와 투기 문제의 원인이 된다."}],"선지":[{"번호":1,"판정":"-","설명":"부증성: 물리적 생산 불가, 지대·지가 발생, 집약적 이용, 최유효이용의 근거."},{"번호":2,"판정":"-","설명":"인접성은 토지가 인접 토지와 연결되어 있어 외부효과가 생긴다는 성질이다. 자연적 특성의 표준 목록(부동성·영속성·부증성·개별성)에 들지 않는다."},{"번호":3,"판정":"-","설명":"개별성은 똑같은 토지가 없어 완전한 대체가 안 되는 성질이다. 시장의 비표준화, 개별 분석의 근거가 된다."},{"번호":4,"판정":"-","설명":"영속성은 소모되지 않는 성질이다. 감가상각 배제(토지), 가치보존, 소유권 중심 거래의 근거가 된다."},{"번호":5,"판정":"-","설명":"적재성은 토지 위에 물건을 쌓을 수 있다는 성질로 자연적 특성의 표준 목록에 들지 않는다."}],"개념":[{"종류":"표","제목":"토지의 자연적 특성과 파생 현상","머리":["특성","내용","파생 현상"],"행":[["부동성","위치가 고정","지역분석, 임장활동, 국지적 시장, 외부효과, 지역 간 가격 차이"],["영속성","소모되지 않음","재생산 불가, 감가상각 배제, 가치보존, 소유권 중심 거래"],["부증성","생산 불가, 물리적 공급 한정","지대·지가 발생, 집약적 이용, 최유효이용의 근거"],["개별성","동일한 토지가 없음","비표준화, 개별 분석, 일물일가 법칙 배제"]]}],"함정":"영속성이 가치보존·수익 지속이므로 ‘지가 발생’과 연결해 고르는 경우가 있다. 지대·지가 발생과 최유효이용의 근거는 부증성이고, 물리적 생산 불가라는 문구가 결정 단서다."},"36회-1차-006":{"한줄":"대체재 가격이 오르면 소비자가 해당 부동산으로 옮겨 오므로 수요곡선은 우측으로 이동한다.","근거":[{"이론":"수요·공급 곡선의 이동 요인","내용":"가격 이외의 요인이 바뀌면 곡선 자체가 이동한다. 대체재 가격 상승과 보완재 가격 하락은 해당 재화의 수요를 늘리고, 투입요소 가격 하락과 보조금은 공급을 늘린다."}],"선지":[{"번호":1,"판정":"옳음","설명":"대출금리가 내리면 자금조달 부담이 줄어 수요가 늘어 수요곡선이 우측으로 이동한다."},{"번호":2,"판정":"옳음","설명":"건축자재 가격 하락은 생산비 절감이어서 공급이 늘어 공급곡선이 우측으로 이동한다."},{"번호":3,"판정":"틀림","설명":"대체재 가격 상승은 해당 부동산의 수요를 늘린다(우측 이동). 좌측 이동이라는 서술이 틀렸다."},{"번호":4,"판정":"옳음","설명":"보조금은 공급자의 비용을 줄여 공급곡선을 우측으로 이동시킨다."},{"번호":5,"판정":"옳음","설명":"보완재 가격 하락은 함께 쓰는 해당 부동산의 수요를 늘려 수요곡선이 우측으로 이동한다."}],"개념":[{"종류":"표","제목":"수요곡선·공급곡선 이동 요인","머리":["구분","수요 증가(우측 이동)","수요 감소(좌측 이동)","공급 증가(우측 이동)","공급 감소(좌측 이동)"],"행":[["소득","정상재 소득 증가","정상재 소득 감소","-","-"],["관련 재화 가격","대체재 가격 상승, 보완재 가격 하락","대체재 가격 하락, 보완재 가격 상승","-","-"],["금리","대출금리 인하","대출금리 인상","금리 인하(자금조달비용 감소)","금리 인상"],["생산비·기술","-","-","건축자재·임금 하락, 기술 진보","건축자재·임금 상승"],["정부 정책","-","-","보조금, 세금 인하","세금 인상, 규제 강화"],["기대·인구","가격 상승 기대, 인구·가구 증가","가격 하락 기대, 인구 감소","공급자 수 증가","공급자 수 감소"]]}],"함정":"가격이 변해서 곡선 위를 움직이는 수량 변화와, 다른 요인으로 곡선이 이동하는 변화를 섞기 쉽다. 이 문항은 모두 곡선 이동이고, 대체재와 보완재의 방향을 반대로 외운 수험생이 3번에서 걸린다."},"36회-1차-011":{"한줄":"시장수요는 같은 가격에서 개별수요량을 가로(수량)로 더한 것이므로 QdM = 1.5(100 − P), 즉 P = 100 − 2/3 QdM이다.","근거":[{"이론":"시장수요곡선의 도출","내용":"시장수요곡선은 개별수요곡선을 수평(수량)으로 합산해서 구한다. 수요함수를 P=…꼴로 두고 더하면 틀리므로 Q=…꼴로 바꿔 합한 뒤 다시 P=…꼴로 바꾼다."}],"선지":[{"번호":1,"판정":"옳음","설명":"QdA = 100 − P, QdB = (100 − P)/2, 합 QdM = 1.5(100 − P). P로 풀면 P = 100 − (2/3)QdM."},{"번호":2,"판정":"틀림","설명":"기울기를 3/2로 둔 값은 QdM = (2/3)(100 − P)로 잘못 합산한 결과다."},{"번호":3,"판정":"틀림","설명":"절편 200은 P 식을 그대로 더해 100+100을 한 값이다. 수평합산이 아니라 수직합산이다."},{"번호":4,"판정":"틀림","설명":"절편이 200이 될 수 없다. 두 수요함수의 가격 절편이 모두 100이므로 시장수요의 가격 절편도 100이다."},{"번호":5,"판정":"틀림","설명":"절편 200이 될 수 없다."}],"개념":[{"종류":"계산","제목":"시장수요함수 구하기","단계":[{"설명":"각 수요함수를 수량 기준으로 바꾼다","식":"QdA = 100 − P, QdB = (100 − P)/2","값":"QdA = 100 − P, QdB = 50 − 0.5P"},{"설명":"같은 가격에서 수량을 더한다","식":"QdM = QdA + QdB","값":"QdM = 150 − 1.5P"},{"설명":"P에 대해 푼다","식":"P = (150 − QdM)/1.5","값":"P = 100 − (2/3)QdM"}]}],"함정":"P=… 상태에서 식을 그대로 더해 P = 200 − …로 만드는 오답이 가장 흔하다. 시장수요는 가격을 고정하고 수량을 더하므로 수량 기준으로 바꿔 합산한다."},"36회-1차-015":{"한줄":"할당효율적 시장은 불완전경쟁시장에서도 성립할 수 있다. 정보비용이 초과이윤과 같아지면 정보로 얻는 순이윤이 0이 되기 때문이다.","근거":[{"이론":"효율적 시장가설과 할당효율성","내용":"약성은 과거 정보, 준강성은 공표된 정보, 강성은 미공개 정보까지 가격에 반영된 시장이다. 할당효율적 시장은 자원이 최유효이용자에게 배분되는 시장이며, 정보비용이 있으면 정보를 이용한 초과이윤이 정보비용과 상쇄되어 불완전경쟁시장도 할당효율적일 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"약성 효율적 시장은 과거 정보가 가격에 반영되어 기술적 분석으로 초과이윤을 얻을 수 없다."},{"번호":2,"판정":"옳음","설명":"준강성 효율적 시장은 공표된 정보가 반영되어 기본적 분석으로도 초과이윤을 얻을 수 없다."},{"번호":3,"판정":"옳음","설명":"강성 효율적 시장은 미공개 정보까지 반영되어 어떤 정보로도 초과이윤을 얻을 수 없다."},{"번호":4,"판정":"틀림","설명":"불완전경쟁시장도 할당효율적일 수 있다. ‘될 수 없다’는 단정이 틀렸다."},{"번호":5,"판정":"옳음","설명":"불완전경쟁시장에서는 정보의 비대칭 등으로 초과이윤이 발생할 수 있다."}],"개념":[{"종류":"표","제목":"효율적 시장 구분","머리":["구분","반영되는 정보","초과이윤 가능한 분석","초과이윤 불가능한 분석"],"행":[["약성","과거 정보","기본적 분석, 미공개 정보 이용","기술적 분석"],["준강성","과거 + 공표된 정보","미공개 정보 이용","기술적 분석, 기본적 분석"],["강성","과거 + 공표 + 미공개 정보","없음","모든 분석"]]},{"종류":"비교","제목":"완전경쟁시장과 할당효율적 시장","왼쪽":{"이름":"완전경쟁시장","항목":["다수의 수요자·공급자","동질적 상품, 정보 완전","진입·퇴출 자유","초과이윤 없음"]},"오른쪽":{"이름":"불완전경쟁시장","항목":["정보 비대칭, 거래비용 존재","초과이윤 발생 가능","정보비용을 감안하면 할당효율적일 수 있음","부동산시장은 대표적 불완전경쟁시장"]}}],"함정":"‘불완전경쟁’과 ‘비효율’을 동의어로 보는 수험생이 4번을 맞는 문장으로 읽는다. 정보비용을 고려하면 불완전경쟁시장에서도 할당효율이 성립한다."},"36회-1차-014":{"한줄":"리카도의 차액지대설(ㄱ)만 맞다. ㄴ은 마르크스의 절대지대, ㄷ은 한계지대곡선이 아니라 튀넨의 위치지대 설명이다.","근거":[{"이론":"지대이론","내용":"리카도는 비옥도 차이에 따른 차액지대, 마르크스는 토지 소유 독점에 의한 절대지대, 튀넨은 시장까지의 거리(운송비)에 따른 위치지대, 알론소는 튀넨의 이론을 도시에 적용한 입찰지대를 설명했다."}],"선지":[{"번호":1,"판정":"-","설명":"ㄱ만 옳다."},{"번호":2,"판정":"-","설명":"ㄷ만으로는 성립하지 않는다."},{"번호":3,"판정":"-","설명":"ㄷ이 틀렸다."},{"번호":4,"판정":"-","설명":"ㄴ이 틀렸다."},{"번호":5,"판정":"-","설명":"ㄴ, ㄷ이 틀렸다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"리카도의 차액지대설. 지대는 잉여이므로 곡물가격이 지대를 결정하고 지대가 곡물가격을 결정하지 않는다."},{"기호":"ㄴ","판정":"틀림","설명":"토지소유의 독점이 지대를 낳고 비옥도와 무관하게 발생한다는 주장은 마르크스의 절대지대설이다. 알론소는 입찰지대 이론이다."},{"기호":"ㄷ","판정":"틀림","설명":"튀넨의 이론은 시장까지의 거리와 운송비에 따라 지대가 정해진다는 위치지대설이다. 운송수단 차이로 한계지대곡선의 기울기가 달라진다는 보기 내용은 이 이론의 설명과 맞지 않는다."}],"개념":[{"종류":"표","제목":"지대이론 비교","머리":["학자","지대","핵심"],"행":[["리카도","차액지대","비옥도 차이, 수확체감, 지대는 가격 결정 요인이 아님"],["마르크스","절대지대","토지 소유 독점 때문에 최열등지에도 지대 발생"],["튀넨","위치지대(고립국)","시장까지의 거리·운송비에 따른 농업 입지"],["알론소","입찰지대","지대지불능력 곡선, 도시 내 토지이용 배분"],["마샬","준지대","인간이 만든 고정설비에서 나오는 일시적 소득"],["파레토","경제지대","공급이 고정된 생산요소가 전용수입을 넘어 받는 보수"]]}],"함정":"알론소와 마르크스를 섞는 오답이 많다. 독점적 지위라는 문구가 나오면 마르크스, 입찰지대라는 문구가 나오면 알론소다."},"36회-1차-016":{"한줄":"2022년 점유율 25%에서 월 매출 4억이면 지역 전체 월 구매액은 16억이고, 2024년 점유율 62.5%를 곱하면 10억이다.","근거":[{"이론":"허프모형","내용":"점포 i의 이용 확률 = (Si ÷ Dⁿ) ÷ Σ(Sj ÷ Djⁿ). S는 매장면적, D는 거리, n은 거리마찰계수. 점포 매출액 = 이용 확률 × 지역 전체 구매액."}],"선지":[{"번호":1,"판정":"-","설명":"6억은 점유율 37.5%에 해당하는 값이다. 2024년 점유율은 62.5%이므로 아니다."},{"번호":2,"판정":"-","설명":"100/(100+20+40) = 62.5%, 16억 × 0.625 = 10억."},{"번호":3,"판정":"-","설명":"16억은 A가 100% 점유할 때의 값, 즉 지역 전체 월 구매액이다."},{"번호":4,"판정":"-","설명":"20억은 지역 전체 구매액 16억을 넘어 성립할 수 없다."},{"번호":5,"판정":"-","설명":"26억도 지역 전체 구매액 16억을 넘어 성립할 수 없다."}],"개념":[{"종류":"계산","제목":"허프모형 매출 계산","단계":[{"설명":"2022년 매력도 S/D² 계산","식":"A: 500/25, B: 2,000/100, C: 1,000/25","값":"A 20, B 20, C 40 (합 80)"},{"설명":"2022년 A의 점유율","식":"20/80","값":"25%"},{"설명":"지역 전체 월 구매액 역산","식":"4억 ÷ 0.25","값":"16억원"},{"설명":"2024년 매력도 (A만 2,500㎡)","식":"A: 2,500/25 = 100","값":"A 100, B 20, C 40 (합 160)"},{"설명":"2024년 A의 점유율과 매출","식":"100/160 = 62.5%, 16억 × 0.625","값":"10억원"}]}],"함정":"2024년 점유율만 구하고 지역 전체 구매액 16억을 역산하지 않으면 계산이 막힌다. 2022년 매출액 4억은 점유율 25%와 짝을 이루는 값으로 총 구매액을 구하는 단서다."},"36회-1차-013":{"한줄":"등비용선은 최소운송비지점에서 벗어날 때 늘어나는 추가 운송비가 같은 지점을 이은 선이다.","근거":[{"이론":"베버의 최소비용이론","내용":"1단계로 운송비 최소지점을 구하고, 2단계에서 노동비 절감액과 집적이익이 추가 운송비보다 크면 입지를 이동한다. 임계등비용선은 노동비·집적이익에 의한 절감액과 추가 운송비가 같아지는 등비용선이다. 원료지수 = 국지원료 중량 ÷ 제품 중량."}],"선지":[{"번호":1,"판정":"틀림","설명":"원료지수는 중량의 비율이어서 음수가 될 수 없다. 국지원료가 더 무거우면 1보다 크다."},{"번호":2,"판정":"옳음","설명":"등비용선의 정의 그대로다."},{"번호":3,"판정":"틀림","설명":"임계등비용선은 추가 운송비와 노동비·집적이익에 의한 비용 절감액이 같아지는 선이다. 운송비 절감액이 아니다."},{"번호":4,"판정":"틀림","설명":"최소운송비지점은 원료·제품의 중량(운송비)으로 정해진다. 노동비와 집적이익은 그 뒤 2단계에서 반영한다."},{"번호":5,"판정":"틀림","설명":"최대수익 입지는 뢰시의 이론이다. 베버는 비용이 가장 적은 곳을 최적입지로 본다."}],"개념":[{"종류":"흐름","제목":"베버 입지 결정 순서","단계":[{"이름":"운송비 최소지점","설명":"원료·제품 중량과 거리로 운송비가 최소인 지점을 찾는다(원료지수로 판단)"},{"이름":"등비용선 작성","설명":"최소운송비지점에서 멀어질수록 늘어나는 추가 운송비가 같은 지점을 연결한다"},{"이름":"임계등비용선 확인","설명":"추가 운송비가 노동비 절감액·집적이익과 같아지는 등비용선을 구한다"},{"이름":"입지 이동 판단","설명":"절감액이 추가 운송비보다 크면 노동비·집적이익이 큰 쪽으로 입지를 옮긴다"}]},{"종류":"표","제목":"원료지수와 입지","머리":["원료지수","의미","입지 경향"],"행":[["1 초과","국지원료 중량이 제품보다 큼","원료산지"],["1 미만","국지원료 중량이 제품보다 작음","소비지"],["1","중량이 같음","중간 어디나 가능"],["0(보편원료만 사용)","국지원료 없음","소비지"]]}],"함정":"임계등비용선을 ‘운송비 절감액’과 연결한 문장이 정답처럼 보이기 쉽다. 절감되는 것은 노동비·집적이익에 따른 비용이다. 또 최소비용(베버)과 최대수익(뢰시)을 바꿔 묻는 선지가 반복된다."},"36회-1차-022":{"한줄":"임대료 보조, 재산세, 개발부담금은 가격 기능을 통한 간접개입이고, 공공임대주택·토지비축·토지거래허가는 정부가 시장에 직접 참여하거나 제한하는 직접개입이다.","근거":[{"이론":"정부 개입 방식 구분","내용":"직접개입은 정부가 시장에 참여하거나 사적 거래를 직접 제한하는 방식, 간접개입은 조세·보조금·금융 등으로 민간의 유인을 바꾸는 방식이다."}],"선지":[{"번호":1,"판정":"-","설명":"ㄷ이 직접개입이다."},{"번호":2,"판정":"-","설명":"ㄱ, ㄴ, ㅂ."},{"번호":3,"판정":"-","설명":"모두 직접개입이다."},{"번호":4,"판정":"-","설명":"ㄹ, ㅁ이 직접개입이다."},{"번호":5,"판정":"-","설명":"ㄷ, ㄹ, ㅁ이 직접개입이다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"임대료 보조는 보조금으로 수요자의 지불능력을 높이는 간접개입이다."},{"기호":"ㄴ","판정":"옳음","설명":"재산세 부과는 조세를 통한 간접개입이다."},{"기호":"ㄷ","판정":"틀림","설명":"공공임대주택 공급은 정부가 공급자로 직접 참여한다."},{"기호":"ㄹ","판정":"틀림","설명":"공공토지비축은 정부가 토지를 직접 매입·비축한다."},{"기호":"ㅁ","판정":"틀림","설명":"토지거래허가제는 거래를 직접 제한한다."},{"기호":"ㅂ","판정":"옳음","설명":"개발부담금은 개발이익을 환수하는 부담금으로 간접개입이다."}],"개념":[{"종류":"표","제목":"정부 개입 방식","머리":["구분","수단"],"행":[["직접개입","토지은행·공공토지비축, 공공임대주택 공급, 토지수용, 토지거래허가제, 용도지역·지구제, 개발권 규제, 분양가상한제, 임대료 규제"],["간접개입","재산세·종합부동산세·양도소득세 등 조세, 개발부담금, 임대료 보조, 주택바우처, 담보인정비율(LTV)·총부채상환비율(DTI) 등 금융규제"]]}],"함정":"개발부담금과 토지거래허가를 모두 ‘규제’라 하여 같은 쪽으로 묶는 오답이 많다. 가격 기능을 통해 유인을 바꾸면 간접, 거래·공급을 직접 막거나 정부가 대신하면 직접이다."},"36회-1차-018":{"한줄":"준주거지역, 근린상업지역, 자연녹지지역이 도시지역에 속하고, 농림·계획관리·자연환경보전지역은 도시지역이 아니다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제36조제1항","원문":"1. 도시지역: 다음 각 목의 어느 하나로 구분하여 지정한다. 가. 주거지역 나. 상업지역 다. 공업지역 라. 녹지지역 / 2. 관리지역: 다음 각 목의 어느 하나로 구분하여 지정한다. 가. 보전관리지역 나. 생산관리지역 다. 계획관리지역 / 3. 농림지역 / 4. 자연환경보전지역"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제30조제1항","원문":"1. 주거지역 가. 전용주거지역(제1종, 제2종) 나. 일반주거지역(제1종, 제2종, 제3종) 다. 준주거지역 / 2. 상업지역 가. 중심상업지역 나. 일반상업지역 다. 근린상업지역 라. 유통상업지역 / 3. 공업지역 가. 전용공업지역 나. 일반공업지역 다. 준공업지역 / 4. 녹지지역 가. 보전녹지지역 나. 생산녹지지역 다. 자연녹지지역"}],"선지":[{"번호":1,"판정":"-","설명":"도시지역은 3개다."},{"번호":2,"판정":"-","설명":"도시지역은 3개다."},{"번호":3,"판정":"-","설명":"준주거(주거지역), 근린상업(상업지역), 자연녹지(녹지지역) 3개."},{"번호":4,"판정":"-","설명":"계획관리지역은 관리지역이어서 도시지역이 아니다(법 제36조제1항제2호)."},{"번호":5,"판정":"-","설명":"농림지역과 자연환경보전지역도 도시지역이 아니다(법 제36조제1항제3호·제4호)."}],"개념":[{"종류":"표","제목":"용도지역 체계","머리":["대분류","중분류","세분"],"행":[["도시지역","주거지역","전용주거(제1종·제2종), 일반주거(제1종·제2종·제3종), 준주거"],["도시지역","상업지역","중심상업, 일반상업, 근린상업, 유통상업"],["도시지역","공업지역","전용공업, 일반공업, 준공업"],["도시지역","녹지지역","보전녹지, 생산녹지, 자연녹지"],["관리지역","보전·생산·계획관리","보전관리, 생산관리, 계획관리"],["농림지역","-","-"],["자연환경보전지역","-","-"]]}],"함정":"계획관리지역은 도시지역 편입이 예상되는 곳이라 도시지역으로 착각하기 쉽다. 이름에 ‘지역’이 붙은 분류가 도시·관리·농림·자연환경보전의 4개 대분류에 속하는지 먼저 본다."},"36회-1차-024":{"한줄":"주택을 소유한 사람도 주거급여를 받을 수 있다. 자가 가구는 수선유지급여의 대상이므로 ‘모든 사람이 될 수 없다’는 서술이 틀렸다.","근거":[{"법령":"공공주택 특별법 시행령","조문":"제2조제1항제3의2호","원문":"통합공공임대주택: 국가나 지방자치단체의 재정이나 주택도시기금의 자금을 지원받아 최저소득 계층, 저소득 서민, 젊은 층 및 장애인ㆍ국가유공자 등 사회 취약계층 등의 주거안정을 목적으로 공급하는 공공임대주택"},{"이론":"주거급여법의 급여 종류","내용":"주거급여는 임차인에게 지급하는 임차급여와, 자기 소유 주택에 거주하는 사람에게 지급하는 수선유지급여로 나뉜다. 소득인정액이 기준 중위소득의 일정 비율 이하이면 자가 가구도 수급권자가 될 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"공공임대주택은 저소득층에게 낮은 임대료로 공급되어 소득재분배 효과가 있다."},{"번호":2,"판정":"옳음","설명":"최고가격이 시장가격 아래면 초과수요가 생겨 암시장에서 더 높은 가격이 형성되는 이중가격이 나타날 수 있다."},{"번호":3,"판정":"옳음","설명":"공공주택 특별법 시행령 제2조제1항제3의2호의 정의와 같다."},{"번호":4,"판정":"옳음","설명":"임대료 보조는 임차인의 지불능력을 높여 실질소득을 증가시킨다."},{"번호":5,"판정":"틀림","설명":"자가 가구도 수선유지급여를 받을 수 있어 소유자 전체를 배제한다는 서술이 틀렸다."}],"개념":[{"종류":"표","제목":"공공임대주택 유형(공공주택 특별법 시행령 제2조)","머리":["유형","목적·특징"],"행":[["영구임대주택","최저소득 계층, 50년 이상 또는 영구 임대"],["국민임대주택","저소득 서민, 30년 이상 임대"],["행복주택","대학생·사회초년생·신혼부부 등 젊은 층"],["통합공공임대주택","최저소득 계층부터 중산층까지 통합, 30년 임대"],["장기전세주택","전세계약 방식으로 공급"],["분양전환공공임대주택","일정 기간 임대 후 분양전환"]]},{"종류":"비교","제목":"주거급여 종류","왼쪽":{"이름":"임차급여","항목":["임차료를 부담하는 가구 대상","기준임대료 범위에서 지급","기준임대료는 지역·가구원 수별로 산정"]},"오른쪽":{"이름":"수선유지급여","항목":["자가 주택에 거주하는 가구 대상","주택의 노후도에 따라 수선 비용 지원","주택 소유자도 수급권자가 될 수 있음"]}}],"함정":"‘주거급여는 임차인만 받는다’고 단순화하면 5번이 옳은 문장으로 읽힌다. 임차급여와 수선유지급여를 나누어 기억해야 한다."},"36회-1차-021":{"한줄":"P=120에서 수요량 760호, 공급량 580호이므로 초과수요는 180호다.","근거":[{"이론":"최고가격제","내용":"최고가격이 균형가격보다 낮으면 규제 가격에서 수요량이 공급량을 넘는 초과수요가 생긴다. 초과수요량 = 규제 가격에서의 수요량 − 공급량."}],"선지":[{"번호":1,"판정":"-","설명":"100호는 계산 결과(180호)와 다르다."},{"번호":2,"판정":"-","설명":"120호는 규제 가격 숫자를 호수로 읽은 값이다."},{"번호":3,"판정":"-","설명":"150은 균형가격(150만원)이다. 수량이 아니다."},{"번호":4,"판정":"-","설명":"760 − 580 = 180호."},{"번호":5,"판정":"-","설명":"200호는 계산 결과와 다르다."}],"개념":[{"종류":"계산","제목":"최고가격제와 초과수요","단계":[{"설명":"균형가격을 구해 규제가 구속력 있는지 확인","식":"1,000 − 2P = 100 + 4P","값":"P = 150 (규제 가격 120 < 150, 구속력 있음)"},{"설명":"P=120에서 수요량","식":"1,000 − 2×120","값":"760호"},{"설명":"P=120에서 공급량","식":"100 + 4×120","값":"580호"},{"설명":"초과수요량","식":"760 − 580","값":"180호"}]}],"함정":"균형가격(150)에서 수량을 구해 비교하는 실수가 많다. 규제 가격 120을 각 함수에 대입해야 한다. 규제 가격이 균형가격보다 높으면 효력이 없다."},"36회-1차-017":{"한줄":"종합부동산세는 국세이면서 보유 단계에 부과되는 보유세다.","근거":[{"이론":"부동산 조세의 분류","내용":"과세 주체에 따라 국세와 지방세로, 부과 단계에 따라 취득·보유·처분 단계로 나눈다. 보유 단계 조세는 재산세(지방세)와 종합부동산세(국세)다."}],"선지":[{"번호":1,"판정":"-","설명":"재산세는 보유세이지만 지방세다."},{"번호":2,"판정":"-","설명":"상속세는 국세이지만 무상 취득 단계의 조세다."},{"번호":3,"판정":"-","설명":"등록면허세는 지방세이고 등기·등록하는 취득 단계의 조세다."},{"번호":4,"판정":"-","설명":"양도소득세는 국세이지만 처분 단계의 조세다."},{"번호":5,"판정":"-","설명":"종합부동산세는 국세이며 보유세다."}],"개념":[{"종류":"표","제목":"부동산 조세 분류","머리":["단계","국세","지방세"],"행":[["취득","상속세, 증여세, 인지세","취득세, 등록면허세"],["보유","종합부동산세","재산세"],["처분","양도소득세, 부가가치세","지방소득세(양도소득분)"]]}],"함정":"재산세와 종합부동산세가 둘 다 보유세라서 국세·지방세 구분을 놓치면 1번을 고른다. 재산세는 지방세다."},"36회-1차-025":{"한줄":"법령·세제·이용규제 변화로 생기는 불확실성은 법적 위험이고, 유동성 위험은 현금화가 어렵거나 늦어지는 위험이다.","근거":[{"이론":"부동산투자의 위험 유형","내용":"사업위험(시장·운영·위치적 위험), 금융위험, 법적 위험(정부정책·세제·규제 변화), 인플레이션 위험, 유동성 위험(환금성)으로 나눈다."},{"이론":"요구수익률","내용":"요구수익률 = 무위험률 + 위험할증률(+ 예상 인플레이션율). 위험이 커지면 위험할증률이 올라 요구수익률도 올라간다."}],"선지":[{"번호":1,"판정":"옳음","설명":"위험할증률이 위험에 따라 붙으므로 위험과 요구수익률은 같은 방향으로 움직인다."},{"번호":2,"판정":"옳음","설명":"기대수익률이 요구수익률보다 크면 투자해도 요구한 수준 이상을 얻으므로 투자가치가 있다. 위험회피형 투자자도 같다."},{"번호":3,"판정":"옳음","설명":"민감도분석은 투입요소(임대료·공실률·환원율 등)를 바꿔 가며 NPV·IRR이 얼마나 달라지는지 본다."},{"번호":4,"판정":"옳음","설명":"부(-)의 레버리지는 차입이자율이 총투자수익률보다 높을 때 생긴다. 이때 부채비율을 높일수록 자기자본수익률이 내려간다."},{"번호":5,"판정":"틀림","설명":"정부정책·세제·이용규제 변화에서 오는 불확실성은 법적 위험이다. 유동성 위험은 매각해 현금으로 바꾸기 어려운 위험이다."}],"개념":[{"종류":"표","제목":"부동산투자 위험의 종류","머리":["위험","원인","예"],"행":[["사업위험(시장)","수요·공급 변화","임대료 하락, 공실 증가"],["사업위험(운영)","관리 실패, 임차인 변동","관리비 증가, 임차인 이탈"],["금융위험","차입에 따른 이자·상환 부담","금리 상승, 상환불능"],["법적 위험","정부정책·세제·이용규제 변화","토지이용규제 강화, 세율 인상"],["인플레이션 위험","물가 상승","실질수익률 하락"],["유동성 위험","매각 지연·현금화 곤란","매수자를 못 찾아 처분 늦어짐"]]},{"종류":"표","제목":"수익률 세 가지","머리":["구분","의미","시점","구성·판단"],"행":[["기대수익률","투자로 얻을 것으로 예상하는 수익률","투자 전(사전)","예상 현금흐름에서 산정"],["요구수익률","투자자가 최소한 얻어야 한다고 요구하는 수익률","투자 전(사전)","무위험률 + 위험할증률 + 예상 인플레이션율"],["실현수익률","투자 종료 후 실제로 얻은 수익률","투자 후(사후)","실제 현금흐름에서 산정"],["투자 결정","기대수익률 > 요구수익률이면 투자, 같으면 중립, 낮으면 기각","-","위험회피형도 같은 기준"]]}],"함정":"민감도분석은 NPV와 IRR 모두에 미치는 영향을 본다. 4번의 부(-)의 레버리지는 부채비율을 올릴수록 자기자본수익률이 하락하는 현상이므로 맞는 문장이다. 법적 위험과 유동성 위험의 이름을 바꿔 놓은 5번을 놓치기 쉽다."},"36회-1차-027":{"한줄":"자기자본 1억 6천만원에 대해 순영업소득 4천만원과 가격상승분 4천만원을 더하고 이자 3,200만원을 빼면 4,800만원이 남아 자기자본수익률은 30%다.","근거":[{"이론":"자기자본수익률(지분수익률)","내용":"자기자본수익률 = (순영업소득 + 매각차익 − 대출이자) ÷ 자기자본. 자기자본 = 매입가격 − 대출금."}],"선지":[{"번호":1,"판정":"-","설명":"15%는 계산값 30%와 다르다."},{"번호":2,"판정":"-","설명":"25%는 수익을 4,000만원 하나로만 보고 이자 3,200만원을 반영하지 않은 값이다(4,000 ÷ 16,000)."},{"번호":3,"판정":"-","설명":"(4,000 + 4,000 − 3,200) ÷ 16,000 = 30%."},{"번호":4,"판정":"-","설명":"40%는 계산값 30%와 다르다."},{"번호":5,"판정":"-","설명":"45%는 이자를 자기자본(1.6억)에 5%를 곱한 800만원으로 잡았을 때 나오는 값이다. 이자는 대출금 6.4억에 붙는다."}],"개념":[{"종류":"계산","제목":"자기자본수익률 계산","단계":[{"설명":"자기자본 = 매입가격 − 대출금 (대출 80%)","식":"8억 − 8억 × 0.8","값":"1.6억원"},{"설명":"대출이자 = 대출금 × 이자율 (대출 6.4억, 연 5%)","식":"6.4억 × 0.05","값":"3,200만원"},{"설명":"매각차익 = 매입가격 × 가격상승률","식":"8억 × 0.05","값":"4,000만원"},{"설명":"지분 수익 = 순영업소득 + 매각차익 − 이자","식":"4,000 + 4,000 − 3,200","값":"4,800만원"},{"설명":"자기자본수익률 = 지분 수익 ÷ 자기자본","식":"4,800 ÷ 16,000","값":"30%"}]},{"종류":"비교","제목":"정(+)의 레버리지와 부(-)의 레버리지","왼쪽":{"이름":"정(+)의 레버리지","항목":["총투자수익률 > 차입이자율","부채비율을 높일수록 자기자본수익률 상승","지렛대효과"]},"오른쪽":{"이름":"부(-)의 레버리지","항목":["총투자수익률 < 차입이자율","부채비율을 높일수록 자기자본수익률 하락","중립적 레버리지는 두 수익률이 같을 때"]}}],"함정":"수익률 분모를 매입가격 8억으로 잡으면 6%가 되고, 이자를 빼지 않으면 50%가 되어 보기 밖의 값이 나온다. 25%와 45%는 이자 처리를 틀린 값이다."},"36회-1차-029":{"한줄":"유효총소득 8,640만원에서 영업경비 50%인 4,320만원을 빼면 순영업소득은 4,320만원이다.","근거":[{"이론":"영업수지 구조","내용":"가능총소득 − 공실·불량부채 = 유효총소득, 유효총소득 − 영업경비 = 순영업소득. 부채서비스액은 순영업소득 뒤(세전현금흐름)에서 뺀다."}],"선지":[{"번호":1,"판정":"-","설명":"3,820만원은 계산값 4,320만원과 다르다."},{"번호":2,"판정":"-","설명":"1,600㎡ × 6만원 = 9,600만원, 공실 960만원을 빼면 8,640만원, 경비 50%를 빼면 4,320만원."},{"번호":3,"판정":"-","설명":"6,900만원은 계산값과 다르다."},{"번호":4,"판정":"-","설명":"7,680만원은 계산값과 다르다."},{"번호":5,"판정":"-","설명":"8,640만원은 영업경비를 빼기 전 유효총소득이다."}],"개념":[{"종류":"계산","제목":"순영업소득 계산","단계":[{"설명":"유효임대면적 = 연면적 × 80%","식":"2,000 × 0.8","값":"1,600㎡"},{"설명":"가능총소득 = 면적 × ㎡당 임대료","식":"1,600 × 6만원","값":"9,600만원"},{"설명":"공실손실 = 가능총소득 × 10%","식":"9,600 × 0.1","값":"960만원"},{"설명":"유효총소득 = 가능총소득 − 공실","식":"9,600 − 960","값":"8,640만원"},{"설명":"영업경비 = 유효총소득 × 50%, 순영업소득 = 유효총소득 − 영업경비","식":"8,640 − 4,320","값":"4,320만원"}]},{"종류":"흐름","제목":"영업현금흐름 구조","단계":[{"이름":"가능총소득","설명":"공실이 없다고 가정한 소득"},{"이름":"유효총소득","설명":"− 공실·불량부채 + 기타 소득"},{"이름":"순영업소득","설명":"− 영업경비(재산세·보험료·관리비 등). 감가상각비·소득세·원리금은 영업경비가 아님"},{"이름":"세전현금흐름","설명":"− 부채서비스액(원리금 상환액)"},{"이름":"세후현금흐름","설명":"− 영업소득세"}]}],"함정":"연면적 2,000㎡에 임대료를 곱하면 출발값이 틀린다. 임대료는 유효임대면적에만 붙는다. 연부채상환액 1,000만원은 순영업소득에서 빼지 않는다."},"36회-1차-019":{"한줄":"할인현금수지분석법은 현금흐름을 현재가치로 할인하는 기법으로 순현재가치법, 내부수익률법, 수익성지수법이 해당한다.","근거":[{"이론":"투자분석기법의 분류","내용":"할인현금수지분석법(DCF)은 화폐의 시간가치를 반영한다: 순현재가치법·내부수익률법·수익성지수법. 회수기간법·평균회계수익률법·승수법·비율분석법은 시간가치를 반영하지 않는 어림셈법이다."}],"선지":[{"번호":1,"판정":"-","설명":"ㄴ(회수기간법)은 시간가치를 반영하지 않고, ㄷ·ㅁ이 빠졌다."},{"번호":2,"판정":"-","설명":"ㄱ·ㄷ·ㅁ이 모두 현금흐름을 할인하는 기법이다."},{"번호":3,"판정":"-","설명":"ㄹ(승수법)은 소득과 가격의 배수 비교여서 할인하지 않는다."},{"번호":4,"판정":"-","설명":"ㄴ·ㄹ이 섞여 있어 맞지 않고, ㄱ도 빠졌다."},{"번호":5,"판정":"-","설명":"ㄴ·ㄹ이 포함되어 틀리다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"순현재가치법은 현금유입의 현가에서 유출의 현가를 뺀다. 할인법이다."},{"기호":"ㄴ","판정":"틀림","설명":"회수기간법은 투자금을 회수하는 데 걸리는 기간을 보는 어림셈법이다."},{"기호":"ㄷ","판정":"옳음","설명":"내부수익률은 순현재가치를 0으로 만드는 할인율이다."},{"기호":"ㄹ","판정":"틀림","설명":"승수법은 가격을 소득으로 나눈 배수를 비교한다."},{"기호":"ㅁ","판정":"옳음","설명":"수익성지수는 현금유입 현가 ÷ 현금유출 현가다."}],"개념":[{"종류":"표","제목":"투자분석기법 분류","머리":["구분","기법","판단 기준"],"행":[["할인기법","순현재가치법(NPV)","NPV > 0 이면 채택"],["할인기법","내부수익률법(IRR)","IRR > 요구수익률이면 채택"],["할인기법","수익성지수법(PI)","PI > 1 이면 채택"],["비할인기법","회수기간법","회수기간이 짧은 안 선택"],["비할인기법","평균회계수익률법","평균 회계이익률이 높은 안 선택"],["비할인기법(승수법·비율분석)","순소득승수, 종합자본환원율, 부채감당률 등","비교 지표"]]},{"종류":"비교","제목":"순현재가치법과 내부수익률법","왼쪽":{"이름":"순현재가치법","항목":["요구수익률로 할인","현금유입 현가 − 현금유출 현가","재투자율을 요구수익률로 가정"]},"오른쪽":{"이름":"내부수익률법","항목":["순현재가치가 0이 되는 할인율","요구수익률과 비교","재투자율을 내부수익률로 가정"]}}],"함정":"회수기간법은 현금흐름을 쓰지만 할인하지 않는다. 현금흐름을 쓴다는 이유로 DCF에 넣으면 ㄴ을 고르게 된다."},"36회-1차-028":{"한줄":"현금유입의 현재가치 2,530만원을 현금유출의 현재가치 1,771만원으로 나누면 수익성지수는 1.43이다.","근거":[{"이론":"수익성지수(PI)","내용":"수익성지수 = 현금유입의 현재가치 합 ÷ 현금유출의 현재가치 합. 1보다 크면 순현재가치가 양(+)이므로 채택한다."}],"선지":[{"번호":1,"판정":"-","설명":"0.70은 유출이 유입의 70%라는 조건의 비율이다. 수익성지수는 현가끼리의 비율이라 1.43이 된다."},{"번호":2,"판정":"-","설명":"0.93은 계산값 1.43과 다르다."},{"번호":3,"판정":"-","설명":"1.22는 계산값 1.43과 다르다."},{"번호":4,"판정":"-","설명":"2,530 ÷ 1,771 = 1.4286 → 1.43."},{"번호":5,"판정":"-","설명":"1.62는 계산값 1.43과 다르다."}],"개념":[{"종류":"계산","제목":"수익성지수 계산","단계":[{"설명":"현금유입 현가 = 매년 유입 × 현가계수","식":"800×0.90 + 1,000×0.85 + 1,200×0.80","값":"720 + 850 + 960 = 2,530만원"},{"설명":"현금유출 = 유입의 70% (560, 700, 840), 유출 현가","식":"560×0.90 + 700×0.85 + 840×0.80","값":"504 + 595 + 672 = 1,771만원"},{"설명":"수익성지수 = 유입 현가 ÷ 유출 현가","식":"2,530 ÷ 1,771","값":"1.4286 → 1.43"},{"설명":"검산: 순현재가치 = 유입 현가 − 유출 현가","식":"2,530 − 1,771","값":"759만원 (> 0)"}]},{"종류":"표","제목":"NPV·IRR·PI 비교","머리":["기법","산식","채택 기준","단위"],"행":[["순현재가치(NPV)","유입 현가 − 유출 현가","0보다 크면 채택","금액"],["내부수익률(IRR)","NPV = 0 이 되는 할인율","요구수익률보다 크면 채택","%"],["수익성지수(PI)","유입 현가 ÷ 유출 현가","1보다 크면 채택","비율"],["관계","NPV > 0 ⇔ PI > 1 ⇔ IRR > 요구수익률","세 기법의 판단이 일치","-"]]}],"함정":"수익성지수는 순현재가치(759만원)를 유출 현가로 나눈 값(0.43)이 아니다. 유입 현가를 유출 현가로 나눈다. 현가계수는 유입·유출 모두에 곱해야 한다."},"36회-1차-034":{"한줄":"원금균등분할상환은 초기에 원금과 이자가 모두 커서 1회차 원리금이 원리금균등보다 크다.","근거":[{"이론":"원금균등분할상환","내용":"매기 원금이 같고 이자가 줄어 원리금이 점차 감소한다. 초기 상환 부담이 가장 크다."},{"이론":"원리금균등분할상환","내용":"매기 원리금이 일정하고 원금은 늘고 이자는 준다. 원금균등보다 초기 부담이 작고 가중평균상환기간이 길다."}],"선지":[{"번호":1,"판정":"틀림","설명":"원금균등은 1회차에 원금 몫이 원리금균등보다 크고 이자는 같아서 1회차 원리금상환액이 더 크다."},{"번호":2,"판정":"옳음","설명":"만기일시상환은 만기까지 이자만 내고 원금은 만기에 한꺼번에 갚는다."},{"번호":3,"판정":"옳음","설명":"원리금균등은 매 회차 원리금이 같다."},{"번호":4,"판정":"옳음","설명":"원금을 늦게 갚는 쪽이 가중평균상환기간이 길다. 원금균등보다 원리금균등이 길다."},{"번호":5,"판정":"옳음","설명":"체증식은 초기 원리금을 낮게 두고 시간이 지나며 늘려 간다. 장래 소득이 늘 차입자에게 맞는다."}],"개념":[{"종류":"표","제목":"상환방식 비교 (고정금리·같은 조건)","머리":["구분","원금","이자","원리금","초기 부담","가중평균상환기간","총이자"],"행":[["원금균등","매기 일정","점차 감소","점차 감소","가장 큼","가장 짧음","원리금균등보다 적음"],["원리금균등","점차 증가","점차 감소","매기 일정","원금균등보다 작음","원금균등보다 김","원금균등보다 많음"],["체증(점증)식","처음엔 적고 점차 증가","원금이 천천히 줄어 이자 부담이 오래 감","점차 증가","작음","원리금균등보다 김","많음"],["만기일시","만기에 전액","만기까지 일정","이자만 납부","가장 작음","가장 김","가장 많음"]]},{"종류":"비교","제목":"원금균등과 원리금균등","왼쪽":{"이름":"원금균등분할상환","항목":["원금 매기 같음","원리금은 점차 감소","대출 초기 상환부담 큼","총이자 적음"]},"오른쪽":{"이름":"원리금균등분할상환","항목":["원리금 매기 같음","원금은 점차 증가","초기 상환부담 작음","총이자 더 많음"]}}],"함정":"원금균등은 이름 때문에 매기 같은 금액을 내는 방식으로 보이지만, 같은 것은 원금뿐이다. 원리금이 일정한 쪽은 원리금균등이다."},"36회-1차-023":{"한줄":"DSR은 차입자의 연소득 대비 모든 금융부채의 연간 원리금상환액 비율이다.","근거":[{"이론":"LTV·DTI·DSR","내용":"LTV = 대출금 ÷ 담보가치. DTI = (주택담보대출 연 원리금 + 기타 대출 연 이자) ÷ 연소득. DSR = 모든 금융부채 연 원리금 ÷ 연소득."}],"선지":[{"번호":1,"판정":"틀림","설명":"LTV가 올라가면 대출 비중이 커져 자기자본비율(1 − LTV)은 감소한다."},{"번호":2,"판정":"틀림","설명":"DTI의 기준은 차입자의 연소득이다. 상업용 부동산의 순수입 대비 부채서비스액은 부채감당률(순영업소득 ÷ 부채서비스액)의 역수 관계다."},{"번호":3,"판정":"틀림","설명":"고정금리대출은 금리가 내려가거나 오를 때 대출자도 기회손실·조달금리 부담을 진다. 위험이 없는 것이 아니다."},{"번호":4,"판정":"옳음","설명":"DSR은 연소득 대비 연간 금융부채 원리금 상환액 비율로 총 상환부담을 본다."},{"번호":5,"판정":"틀림","설명":"정해진 시기에 원리금을 갚지 못하는 위험은 채무불이행위험이다. 조기상환위험은 만기 전에 상환해 대출자가 이자수입을 잃는 위험이다."}],"개념":[{"종류":"표","제목":"LTV·DTI·DSR","머리":["지표","분모","분자","의미"],"행":[["LTV(담보인정비율)","담보물 가치","대출금","높을수록 대출 의존, 자기자본비율 하락"],["DTI(총부채상환비율)","연소득","주택담보대출 연 원리금 + 기타 대출 연 이자","소득 대비 상환부담"],["DSR(총부채원리금상환비율)","연소득","모든 금융부채의 연 원리금","DTI보다 넓은 부담 지표"],["부채감당률(DCR)","부채서비스액","순영업소득","1보다 커야 상환 가능"]]},{"종류":"표","제목":"대출 관련 위험","머리":["위험","의미","부담 주체"],"행":[["채무불이행위험","원리금을 약정대로 갚지 못함","대출자"],["조기상환위험","만기 전 상환으로 이자수입 감소","대출자(증권 투자자)"],["이자율위험","금리 변동에 따른 손익 변동","고정금리: 대출자 / 변동금리: 차입자 쪽 부담 큼"],["유동성위험","대출채권을 현금화하기 어려움","대출자"]]}],"함정":"DTI와 DSR을 같은 지표로 보면 4번을 놓친다. 5번의 금리 인상 상황은 이자율위험 이야기처럼 읽히지만 서술된 결과(상환 불이행)는 채무불이행위험이다."},"36회-1차-030":{"한줄":"프로젝트 금융은 비소구 또는 제한적 소구라서 프로젝트가 부실해지면 대출기관의 채권회수에도 영향이 생긴다.","근거":[{"이론":"프로젝트 금융(PF)","내용":"사업주의 신용이 아니라 프로젝트의 사업성·미래 현금흐름을 상환재원으로 하는 금융이다. 비소구 또는 제한적 소구이며, 별도 법인(SPC)과 에스크로우 계정으로 자금을 관리한다."},{"법령":"부동산투자회사법","조문":"제6조, 제10조","원문":"제6조 ① 자기관리 부동산투자회사의 설립 자본금은 5억원 이상으로 한다. ② 위탁관리 부동산투자회사 및 기업구조조정 부동산투자회사의 설립 자본금은 3억원 이상으로 한다. / 제10조 1. 자기관리 부동산투자회사: 70억원 2. 위탁관리 부동산투자회사 및 기업구조조정 부동산투자회사: 50억원"}],"선지":[{"번호":1,"판정":"옳음","설명":"상환재원이 프로젝트의 사업성과 현금흐름이다."},{"번호":2,"판정":"옳음","설명":"사업주에게 상환청구를 하지 않거나 일정 범위로만 한다."},{"번호":3,"판정":"틀림","설명":"소구 범위가 제한되므로 프로젝트가 부실해지면 대출기관은 프로젝트 자산·현금흐름에서만 회수하게 되어 손실을 입을 수 있다."},{"번호":4,"판정":"옳음","설명":"시행사·시공사·금융기관 등 여러 주체가 참여하고 계약으로 위험을 나눈다."},{"번호":5,"판정":"옳음","설명":"사업자금 입출금은 에스크로우 계정으로 관리해 목적 외 사용을 막는다."}],"개념":[{"종류":"표","제목":"프로젝트 금융과 기업금융","머리":["구분","프로젝트 금융","기업금융"],"행":[["상환재원","프로젝트의 미래 현금흐름","기업 전체의 신용·자산"],["소구","비소구 또는 제한적 소구","소구(사업주 책임)"],["차입 주체","별도 설립한 사업 법인(SPC)","사업주(기업) 자신"],["자금관리","에스크로우 계정","기업 일반계정"],["위험","참여자 간 배분","사업주가 대부분 부담"]]},{"종류":"표","제목":"부동산투자회사(리츠) 종류","머리":["구분","투자·운용","설립 자본금","최저자본금(인가 6개월 후)"],"행":[["자기관리 리츠","상근 임직원이 직접 운용","5억원 이상","70억원"],["위탁관리 리츠","자산관리회사에 위탁","3억원 이상","50억원"],["기업구조조정 리츠","구조조정 부동산에 투자, 자산관리회사에 위탁","3억원 이상","50억원"]]}],"함정":"'채권회수에는 영향이 없다'는 단정은 제한적 소구와 맞지 않는다. 비소구라는 말은 사업주에게 청구할 수 없다는 뜻일 뿐 프로젝트 실패의 위험을 대출기관이 안 진다는 뜻이 아니다."},"36회-1차-002":{"한줄":"부동산 임대 및 공급업은 부동산업 소분류의 하나이고, 부동산관련 서비스업에는 포함되지 않는다.","근거":[{"이론":"한국표준산업분류의 부동산업","내용":"부동산업은 '부동산 임대 및 공급업'과 '부동산 관련 서비스업'으로 나뉜다. 부동산 관련 서비스업은 부동산 관리업과 부동산 중개, 자문 및 감정평가업(중개 및 대리업, 투자 자문업, 감정 평가업, 분양 대행업)으로 구성된다."}],"선지":[{"번호":1,"판정":"틀림","설명":"부동산 임대 및 공급업은 부동산관련 서비스업과 나란한 별도 소분류라서 서비스업에 해당하지 않는다."},{"번호":2,"판정":"옳음","설명":"부동산 중개 및 대리업은 부동산관련 서비스업에 해당한다."},{"번호":3,"판정":"옳음","설명":"부동산 감정 평가업은 부동산관련 서비스업에 해당한다."},{"번호":4,"판정":"옳음","설명":"부동산 투자 자문업은 부동산관련 서비스업에 해당한다."},{"번호":5,"판정":"옳음","설명":"부동산 분양 대행업은 부동산관련 서비스업에 해당한다."}],"개념":[{"종류":"표","제목":"한국표준산업분류상 부동산업","머리":["소분류","세분류","해당 업종"],"행":[["부동산 임대 및 공급업","부동산 임대업","주거용·비주거용 건물, 토지 임대 등"],["부동산 임대 및 공급업","부동산 개발 및 공급업","주거용·비주거용 건물 개발 및 공급 등"],["부동산 관련 서비스업","부동산 관리업","주거용·비주거용 부동산 관리"],["부동산 관련 서비스업","부동산 중개, 자문 및 감정평가업","중개 및 대리업, 투자 자문업, 감정 평가업, 분양 대행업"]]}],"함정":"임대와 중개를 모두 '부동산 사업'이라 하나로 묶어 서비스업에 넣기 쉽다. 임대 및 공급업은 별도 소분류다."},"36회-1차-005":{"한줄":"STP의 P는 동반자관계(Partnership)가 아니라 포지셔닝(Positioning)이다.","근거":[{"이론":"STP 전략","내용":"시장세분화(Segmentation) → 표적시장 선정(Targeting) → 포지셔닝(Positioning). 포지셔닝은 표적시장 고객의 인식 속에 경쟁 상품과 구별되는 위치를 만드는 일이다."}],"선지":[{"번호":1,"판정":"옳음","설명":"4P는 제품, 가격, 유통경로, 판매촉진이다."},{"번호":2,"판정":"옳음","설명":"관계 마케팅은 고객과 일회성이 아닌 지속적 관계를 유지해 효과를 낸다."},{"번호":3,"판정":"옳음","설명":"AIDA는 주의, 관심, 욕구, 행동의 구매 심리 단계다."},{"번호":4,"판정":"틀림","설명":"STP의 P는 포지셔닝(Positioning)이다."},{"번호":5,"판정":"옳음","설명":"시장세분화는 고객 집단을 기준에 따라 나누는 일이다."}],"개념":[{"종류":"표","제목":"부동산마케팅 전략 세 갈래","머리":["전략","초점","수단"],"행":[["시장점유 마케팅","공급자 중심, 시장 경쟁","STP, 4P Mix"],["고객점유 마케팅","소비자 중심, 구매 심리","AIDA 원리"],["관계 마케팅","고객과 지속적 관계","고객 유지, 재구매·추천"]]},{"종류":"흐름","제목":"STP와 4P Mix","단계":[{"이름":"S 시장세분화","설명":"고객 집단을 기준에 따라 나눈다"},{"이름":"T 표적시장 선정","설명":"세분 시장 중 공략할 시장을 정한다"},{"이름":"P 포지셔닝","설명":"표적시장에서 경쟁 상품과 구별되는 위치를 만든다"},{"이름":"4P Mix","설명":"제품·가격·유통경로·판매촉진을 조합한다"}]}],"함정":"STP의 마지막 글자를 Partnership으로 바꾼 4번이 정답 선지다. 4P와 STP 영어 단어를 정확히 외워야 한다."},"36회-1차-036":{"한줄":"인근지역은 지역요인을 공유하는 지역이고, 개별요인은 부동산마다 다르다.","근거":[{"법령":"감정평가에 관한 규칙","조문":"제2조제13호","원문":"\"인근지역\"이란 감정평가의 대상이 된 부동산(이하 \"대상부동산\"이라 한다)이 속한 지역으로서 부동산의 이용이 동질적이고 가치형성요인 중 지역요인을 공유하는 지역을 말한다."},{"법령":"감정평가에 관한 규칙","조문":"제2조제14호","원문":"\"유사지역\"이란 대상부동산이 속하지 아니하는 지역으로서 인근지역과 유사한 특성을 갖는 지역을 말한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"최유효이용은 대상 부동산 자체의 개별 사정을 보는 개별분석에서 판정한다."},{"번호":2,"판정":"옳음","설명":"유사지역은 대상부동산이 속하지 않고 인근지역과 특성이 비슷한 지역이다(제2조제14호)."},{"번호":3,"판정":"옳음","설명":"지역분석으로 지역 성격을 먼저 파악하고 개별분석으로 내려간다(선행 분석)."},{"번호":4,"판정":"옳음","설명":"지역분석으로 지역 내 표준적 이용과 가격수준을 파악한다."},{"번호":5,"판정":"틀림","설명":"인근지역은 가치형성요인 중 지역요인을 공유하는 지역이다(제2조제13호). 개별요인은 부동산마다 다르다."}],"개념":[{"종류":"비교","제목":"지역분석과 개별분석","왼쪽":{"이름":"지역분석","항목":["대상: 인근지역·유사지역·동일수급권","표준적 이용과 가격수준 파악","지역요인 분석","개별분석에 앞서 실시(선행분석)"]},"오른쪽":{"이름":"개별분석","항목":["대상: 개별 부동산","최유효이용 판정과 구체적 가격 결정","개별요인 분석","지역분석 뒤 실시(후행분석)"]}},{"종류":"흐름","제목":"감정평가 절차 (제8조)","단계":[{"이름":"1 기본적 사항 확정","설명":"의뢰인·대상물건·목적·기준시점·조건 등"},{"이름":"2 처리계획 수립","설명":"감정평가 일정·방법 등 계획"},{"이름":"3 대상물건 확인","설명":"현장 조사로 대상물건 확인"},{"이름":"4 자료수집 및 정리","설명":"거래사례·임대사례 등 자료 수집"},{"이름":"5 자료검토·가치형성요인 분석","설명":"지역분석·개별분석 포함"},{"이름":"6 감정평가방법 선정·적용","설명":"주된 방법 적용, 다른 방법으로 합리성 검토"},{"이름":"7 감정평가액 결정·표시","설명":"시산가액 조정 후 감정평가액 결정"}]}],"함정":"인근지역의 정의에서 '지역요인'을 '개별요인'으로 바꿔 놓았다. 지역요인은 지역 전체가 공유하고, 개별요인은 부동산 하나씩 다르다. 유사지역 정의와 헷갈리지 않아야 한다."},"36회-1차-037":{"한줄":"5,000,000 × 1.05(지가변동률) × 1.026(개별요인) × 1.6(그 밖의 요인)으로 대상토지 단위면적당 시산가액은 8,618,400원이다.","근거":[{"법령":"감정평가에 관한 규칙","조문":"제14조제2항제2호","원문":"시점수정: 「부동산 거래신고 등에 관한 법률」 제19조에 따라 국토교통부장관이 조사ㆍ발표하는 비교표준지가 있는 시ㆍ군ㆍ구의 같은 용도지역 지가변동률을 적용할 것."},{"법령":"감정평가에 관한 규칙","조문":"제14조제2항제5호","원문":"그 밖의 요인 보정: 대상토지의 인근지역 또는 동일수급권내 유사지역의 가치형성요인이 유사한 정상적인 거래사례 또는 평가사례 등을 고려할 것"}],"선지":[{"번호":1,"판정":"-","설명":"5,386,500원은 그 밖의 요인 보정(1.6)을 빼먹은 값이다."},{"번호":2,"판정":"-","설명":"5,643,000원은 상업지역 변동률 10%를 쓰고 그 밖의 요인 보정도 빼먹은 값이다."},{"번호":3,"판정":"-","설명":"8,400,000원은 개별요인(1.026) 비교를 빼먹은 값이다."},{"번호":4,"판정":"-","설명":"5,000,000 × 1.05 × (0.95 × 1.08) × 1.6 = 8,618,400원."},{"번호":5,"판정":"-","설명":"9,028,800원은 시점수정에 상업지역 변동률 10%를 쓴 값이다."}],"개념":[{"종류":"계산","제목":"공시지가기준법 계산","단계":[{"설명":"시점수정: 같은 용도지역(제2종일반주거지역) 지가변동률 5% 적용","식":"5,000,000 × 1.05","값":"5,250,000원"},{"설명":"지역요인: 인근지역이라 동일","식":"× 1.000","값":"5,250,000원"},{"설명":"개별요인: 가로조건 5% 열세, 획지조건 8% 우세 (상승식=곱셈)","식":"0.95 × 1.08","값":"1.026"},{"설명":"개별요인 반영","식":"5,250,000 × 1.026","값":"5,386,500원"},{"설명":"그 밖의 요인 60% 증액 보정","식":"5,386,500 × 1.6","값":"8,618,400원"}]},{"종류":"흐름","제목":"공시지가기준법 순서 (제14조제2항)","단계":[{"이름":"비교표준지 선정","설명":"인근지역 표준지 중 용도지역·이용상황·주변환경이 같거나 비슷한 것. 없으면 동일수급권 유사지역"},{"이름":"시점수정","설명":"같은 용도지역 지가변동률. 부적절하면 비슷한 용도지역·이용상황별·평균 지가변동률, 그것도 불가하면 생산자물가상승률"},{"이름":"지역요인 비교","설명":"인근지역이면 동일"},{"이름":"개별요인 비교","설명":"가로·획지·환경 등 개별 조건 비교"},{"이름":"그 밖의 요인 보정","설명":"인근지역 또는 유사지역의 거래사례·평가사례 고려"}]}],"함정":"시점수정에는 이용상황(상업용)이 아니라 용도지역(주거지역)의 지가변동률을 쓴다. 상업지역 10%를 고르면 5,643,000원 또는 9,028,800원으로 간다. 그 밖의 요인 보정을 빼면 5,386,500원이다."},"36회-1차-039":{"한줄":"재조달원가 3억 5천만원에서 6년 경과분 감가 12%(4,200만원)를 빼면 시산가액은 3억 800만원이다.","근거":[{"법령":"감정평가에 관한 규칙","조문":"제2조제5호","원문":"\"원가법\"이란 대상물건의 재조달원가에 감가수정(減價修正)을 하여 대상물건의 가액을 산정하는 감정평가방법을 말한다."},{"법령":"감정평가에 관한 규칙","조문":"제15조제1항","원문":"감정평가법인등은 건물을 감정평가할 때에 원가법을 적용해야 한다."}],"선지":[{"번호":1,"판정":"-","설명":"246,400,000원은 건축비지수 보정 없이 1,400,000원 기준(2억 8천만원)에서 12%를 감가한 값이다."},{"번호":2,"판정":"-","설명":"274,400,000원은 계산값 308,000,000원과 다르다."},{"번호":3,"판정":"-","설명":"1,400,000 × 125/100 × 200 = 350,000,000원, 감가 6/50 = 12% → 308,000,000원."},{"번호":4,"판정":"-","설명":"329,000,000원은 감가를 6%로 잡은 값이다."},{"번호":5,"판정":"-","설명":"350,000,000원은 감가수정을 하지 않은 재조달원가다."}],"개념":[{"종류":"계산","제목":"원가법 계산","단계":[{"설명":"기준시점 ㎡당 재조달원가 = 신축공사비 × 지수 비율","식":"1,400,000 × 125/100","값":"1,750,000원/㎡"},{"설명":"재조달원가 = ㎡당 × 연면적","식":"1,750,000 × 200","값":"350,000,000원"},{"설명":"경과연수 = 사용승인시점 2019.10.25 → 기준시점 2025.10.25","식":"-","값":"6년"},{"설명":"정액법 감가누계 = (재조달원가 − 잔존가치) ÷ 내용연수 × 경과연수","식":"350,000,000 × 6/50","값":"42,000,000원"},{"설명":"시산가액 = 재조달원가 − 감가누계","식":"350,000,000 − 42,000,000","값":"308,000,000원"}]},{"종류":"표","제목":"감가수정 방법과 감가 요인","머리":["구분","내용"],"행":[["정액법(직선법)","매년 같은 금액 감가. 내용연수 만료 시 잔존가치에 수렴"],["정률법(체감법)","미상각 잔액에 일정 비율 적용, 초기 감가 큼"],["상환기금법","감가액을 적립해 이자를 붙여 재조달원가에 이르게 계산"],["감가 요인","물리적(마모·노후), 기능적(설계·설비 낡음), 경제적(주변 환경 변화) 감가"]]}],"함정":"신축공사비 1,400,000원은 사용승인시점 값이므로 기준시점으로 올려야 한다(×125/100). 내용연수 50년을 경과연수 6년과 바꾸면 감가율이 틀어진다."},"36회-1차-035":{"한줄":"선지 2의 설명은 수익분석법의 정의이고, 적산법은 기초가액에 기대이율을 곱한 기대수익에 필요 경비를 더해 임대료를 구한다.","근거":[{"법령":"감정평가에 관한 규칙","조문":"제2조제6호","원문":"\"적산법(積算法)\"이란 대상물건의 기초가액에 기대이율을 곱하여 산정된 기대수익에 대상물건을 계속하여 임대하는 데에 필요한 경비를 더하여 대상물건의 임대료[(賃貸料), 사용료를 포함한다. 이하 같다]를 산정하는 감정평가방법을 말한다."},{"법령":"감정평가에 관한 규칙","조문":"제2조제11호","원문":"\"수익분석법\"이란 일반기업 경영에 의하여 산출된 총수익을 분석하여 대상물건이 일정한 기간에 산출할 것으로 기대되는 순수익에 대상물건을 계속하여 임대하는 데에 필요한 경비를 더하여 대상물건의 임대료를 산정하는 감정평가방법을 말한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"법령에 다른 규정이 있으면 시장가치 외의 가치를 기준으로 결정할 수 있다(제5조제2항제1호)."},{"번호":2,"판정":"틀림","설명":"서술된 내용은 수익분석법(제2조제11호)이다. 적산법은 기초가액 × 기대이율 + 필요경비(제2조제6호)."},{"번호":3,"판정":"옳음","설명":"일체로 거래되거나 용도상 불가분이면 일괄하여 감정평가할 수 있다(제7조제2항)."},{"번호":4,"판정":"옳음","설명":"임대사례비교법의 정의와 같다(제2조제8호)."},{"번호":5,"판정":"옳음","설명":"법령에 다른 규정이 있으면 감정평가조건을 붙일 수 있다(제6조제2항제1호)."}],"개념":[{"종류":"표","제목":"감정평가 3방식 6방법","머리":["방식","가액을 구하는 방법","임대료를 구하는 방법"],"행":[["원가방식","원가법","적산법"],["비교방식","거래사례비교법, 공시지가기준법","임대사례비교법"],["수익방식","수익환원법","수익분석법"]]},{"종류":"비교","제목":"적산법과 수익분석법 (임대료)","왼쪽":{"이름":"적산법","항목":["기초가액 × 기대이율 = 기대수익","+ 임대에 필요한 경비","원가방식"]},"오른쪽":{"이름":"수익분석법","항목":["기업 경영으로 산출된 총수익 분석","순수익 + 임대에 필요한 경비","수익방식"]}}],"함정":"적산법과 수익분석법은 둘 다 '임대에 필요한 경비를 더한다'는 마지막 구절이 같아서 구분하기 어렵다. 적산법은 기초가액에 기대이율을 곱하고, 수익분석법은 총수익에서 출발한다."},"36회-1차-040":{"한줄":"기업가치 - 수익환원법, 건물 - 원가법 두 개만 규칙과 일치한다.","근거":[{"법령":"감정평가에 관한 규칙","조문":"제15조제1항","원문":"감정평가법인등은 건물을 감정평가할 때에 원가법을 적용해야 한다."},{"법령":"감정평가에 관한 규칙","조문":"제24조제3항","원문":"감정평가법인등은 기업가치를 감정평가할 때에 수익환원법을 적용해야 한다."},{"법령":"감정평가에 관한 규칙","조문":"제19조제2항, 제20조, 제22조, 제18조","원문":"광업재단: 수익환원법 / 자동차: 거래사례비교법 / 항공기: 원가법 / 임대료: 임대사례비교법 / 과수원: 거래사례비교법"}],"선지":[{"번호":1,"판정":"-","설명":"일치하는 것은 기업가치와 건물 두 개다."},{"번호":2,"판정":"-","설명":"일치하는 연결은 3개가 아니라 2개다(기업가치, 건물)."},{"번호":3,"판정":"-","설명":"일치하는 연결은 4개가 아니라 2개다."},{"번호":4,"판정":"-","설명":"일치하는 연결은 5개가 아니라 2개다."},{"번호":5,"판정":"-","설명":"일치하는 연결은 6개가 아니라 2개다."}],"보기판정":[{"기호":"광업재단 - 원가법","판정":"틀림","설명":"광업재단은 수익환원법(제19조제2항)."},{"기호":"항공기 - 거래사례비교법","판정":"틀림","설명":"항공기는 원가법(제20조제4항)."},{"기호":"기업가치 - 수익환원법","판정":"옳음","설명":"제24조제3항."},{"기호":"임대료 - 수익환원법","판정":"틀림","설명":"임대료는 임대사례비교법(제22조)."},{"기호":"건물 - 원가법","판정":"옳음","설명":"제15조제1항."},{"기호":"과수원 - 수익환원법","판정":"틀림","설명":"과수원은 거래사례비교법(제18조)."},{"기호":"자동차 - 원가법","판정":"틀림","설명":"자동차는 거래사례비교법(제20조제1항)."}],"개념":[{"종류":"표","제목":"대상물건별 주된 감정평가방법","머리":["대상물건","주된 방법","조문"],"행":[["토지","공시지가기준법","제14조"],["건물","원가법","제15조"],["토지와 건물 일괄","거래사례비교법","제16조"],["산림","산지와 입목 구분(입목은 거래사례비교법), 일괄은 거래사례비교법","제17조"],["과수원","거래사례비교법","제18조"],["공장재단","구성 물건 감정평가액 합산(일괄 시 수익환원법 가능)","제19조제1항"],["광업재단","수익환원법","제19조제2항"],["자동차","거래사례비교법","제20조제1항"],["건설기계·선박·항공기","원가법","제20조제2~4항"],["동산","거래사례비교법(기계·기구류는 원가법)","제21조"],["임대료","임대사례비교법","제22조"],["무형자산(영업권 등)","수익환원법","제23조제3항"],["기업가치","수익환원법","제24조제3항"]]}],"함정":"광업재단과 공장재단, 자동차와 건설기계·항공기가 서로 방법이 다르다. 임대료는 가액이 아니라서 수익환원법이 아니라 임대사례비교법이 주된 방법이다."},"36회-1차-038":{"한줄":"분할·합병 등 사유가 1월 1일~6월 30일에 생기면 그 해 7월 1일, 7월 1일~12월 31일에 생기면 다음 해 1월 1일이 개별공시지가 기준일이다.","근거":[{"법령":"부동산 가격공시에 관한 법률 시행령","조문":"제16조제2항","원문":"1. 1월 1일부터 6월 30일까지의 사이에 제1항 각 호의 사유가 발생한 토지: 그 해 7월 1일 2. 7월 1일부터 12월 31일까지의 사이에 제1항 각 호의 사유가 발생한 토지: 다음 해 1월 1일"}],"선지":[{"번호":1,"판정":"옳음","설명":"표준지공시지가의 공시기준일은 1월 1일이고, 부득이하면 일부 지역은 따로 정할 수 있다(시행령 제3조)."},{"번호":2,"판정":"옳음","설명":"표준지공시지가 이의신청은 공시일부터 30일 이내 서면으로 국토교통부장관에게 한다(법 제7조제1항)."},{"번호":3,"판정":"옳음","설명":"표준지로 선정된 토지는 개별공시지가를 결정·공시하지 않을 수 있다(법 제10조제2항)."},{"번호":4,"판정":"틀림","설명":"개별공시지가의 기준일은 그 해 7월 1일 또는 다음 해 1월 1일이다(시행령 제16조제2항). 6월 1일은 개별주택가격·공동주택가격의 기준일이다."},{"번호":5,"판정":"옳음","설명":"표준지공시지가의 효력이다(법 제9조)."}],"개념":[{"종류":"표","제목":"공시기준일을 다르게 하는 경우","머리":["공시 대상","1~5월(또는 6월) 사유 발생","그 이후 사유 발생","결정·공시 시기"],"행":[["개별공시지가","1.1~6.30 사유: 그 해 7월 1일","7.1~12.31 사유: 다음 해 1월 1일","매년 5월 31일까지"],["개별주택가격","1.1~5.31 사유: 그 해 6월 1일","6.1~12.31 사유: 다음 해 1월 1일","매년 4월 30일까지"],["공동주택가격","1.1~5.31 사유: 그 해 6월 1일","6.1~12.31 사유: 다음 해 1월 1일","매년 4월 30일까지(국토교통부장관)"],["비주거용 개별부동산가격","1.1~5.31 사유: 그 해 6월 1일","6.1~12.31 사유: 다음 해 1월 1일","매년 4월 30일까지"]]},{"종류":"표","제목":"공시 주체와 이의신청","머리":["공시","주체","이의신청"],"행":[["표준지공시지가","국토교통부장관","공시일부터 30일 이내, 국토교통부장관에게"],["개별공시지가","시장·군수·구청장","결정·공시일부터 30일 이내, 시장·군수·구청장에게"],["표준지로 선정된 토지","-","개별공시지가를 결정·공시하지 않을 수 있고, 이 경우 표준지공시지가를 개별공시지가로 본다"]]}],"함정":"6월 1일은 주택 쪽 날짜(사유가 1.1~5.31이면 그 해 6월 1일)다. 토지는 7월 1일로 외워야 한다."},"36회-1차-047":{"한줄":"무경험은 일반적인 생활체험의 부족, 곧 거래 일반에 대한 경험부족을 뜻하고 특정 영역의 경험부족은 포함하지 않으므로 2번이 틀리다.","근거":[{"법령":"민법","조문":"제104조","원문":"제104조(불공정한 법률행위) 당사자의 궁박, 경솔 또는 무경험으로 인하여 현저하게 공정을 잃은 법률행위는 무효로 한다."},{"판례":"대법원 2002. 10. 22. 선고 2002다38927 판결","요지":"무경험은 일반적인 생활체험의 부족을 뜻하고 어느 특정 영역에서의 경험부족이 아니라 거래 일반에 대한 경험부족이다. 대리인이 계약을 맺은 때 경솔·무경험은 대리인을 기준으로, 궁박은 본인을 기준으로 판단한다."},{"판례":"대법원 1996. 6. 14. 선고 94다46374 판결","요지":"궁박은 급박한 곤궁을 뜻하며 경제적 원인뿐 아니라 정신적·심리적 원인에서 생긴 것도 포함한다."},{"판례":"대법원 2010. 7. 15. 선고 2009다50308 판결","요지":"급부와 반대급부의 현저한 불균형은 시가와의 차액이나 배율만으로 정하지 않고 사회통념에 따라 구체적·개별적으로 판단한다. 불공정한 법률행위로 무효가 된 경우에도 제138조 무효행위 전환이 적용될 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"궁박은 급박한 곤궁이고 경제적 원인에 한하지 않는다. 정신적·심리적 곤궁도 포함한다(94다46374)."},{"번호":2,"판정":"틀림","설명":"무경험은 특정 영역이 아니라 거래 일반에 대한 경험부족이다(2002다38927)."},{"번호":3,"판정":"옳음","설명":"현저한 불균형은 시가와의 비율 같은 일률적 기준 없이 사회통념에 따라 구체적·개별적으로 정한다(2009다50308)."},{"번호":4,"판정":"옳음","설명":"불공정한 법률행위에도 제138조의 전환이 적용될 수 있다. 당사자가 무효를 알았다면 다른 내용으로 합의했으리라고 인정되는 경우에 한한다(2009다50308)."},{"번호":5,"판정":"옳음","설명":"대리인이 한 법률행위에서 궁박 여부는 본인을 기준으로 판단한다(2002다38927). 경솔·무경험은 대리인을 기준으로 한다."}],"개념":[{"종류":"표","제목":"무효사유별 선의 제3자 보호","머리":["구분","근거","핵심 요건","선의 제3자 보호"],"행":[["반사회질서 행위","제103조","내용·조건·대가·표시된 동기가 사회질서에 반함","없음. 누구에게나 무효 주장 가능(96다29151)"],["불공정한 법률행위","제104조","궁박·경솔·무경험 + 현저한 불균형 + 상대방의 폭리 악의","규정 없음. 무효"],["통정허위표시","제108조","상대방과 통정한 허위의 의사표시","선의 제3자에게 대항 불가(제108조 제2항)"],["비진의표시","제107조","상대방이 진의 아님을 알았거나 알 수 있었음","선의 제3자에게 대항 불가(제107조 제2항)"]]},{"종류":"표","제목":"제104조 요건 요소","머리":["요소","의미","대리 사안의 기준"],"행":[["궁박","급박한 곤궁. 경제적·정신적·심리적 원인 모두 포함","본인"],["경솔","의사결정 때 보통 하여야 할 고려를 하지 않은 심리상태","대리인"],["무경험","거래 일반에 대한 경험부족","대리인"],["현저한 불균형","시가 비율이 아니라 사회통념에 따라 구체적으로 판단","해당 없음"],["폭리 악의","상대방이 궁박 등을 알고 이용하려는 의사","해당 없음"]]}],"함정":"무경험을 해당 거래 분야의 경험부족으로 바꾼 2번이 정답 선지다. 대리 사안에서 본인 기준은 궁박뿐이고 경솔·무경험은 대리인 기준이다. 4번에서 전환 법리가 불공정한 법률행위에 적용되지 않는다고 외운 수험생은 옳은 선지를 틀렸다고 읽는다."},"36회-1차-041":{"한줄":"반사회질서 법률행위의 무효는 허위표시와 달리 선의의 제3자에게도 주장할 수 있으므로 2번이 틀리다.","근거":[{"법령":"민법","조문":"제103조","원문":"제103조(반사회질서의 법률행위) 선량한 풍속 기타 사회질서에 위반한 사항을 내용으로 하는 법률행위는 무효로 한다."},{"판례":"대법원 1996. 10. 25. 선고 96다29151 판결","요지":"이중매매가 반사회적 법률행위로 무효이면 제2매수인으로부터 취득한 전득자는 선의여도 유효를 주장하지 못한다. 반사회질서 행위의 무효에는 선의 제3자 보호 규정이 없다."},{"판례":"대법원 1994. 3. 11. 선고 93다40522 판결","요지":"증인이 진실을 진술할 의무를 지는데 그 이행을 조건으로 용인되는 범위를 넘는 대가를 약정하면 제103조에 반해 무효다."},{"판례":"대법원 1992. 11. 27. 선고 92다7719 판결","요지":"내용 자체가 반사회적인 경우 외에 반사회적 조건·금전적 대가가 결부된 경우, 표시되었거나 상대방에게 알려진 동기가 반사회적인 경우도 포함한다. 성립 과정에 강박이라는 불법적 방법이 사용된 데 불과하면 반사회질서 법률행위가 아니다."}],"선지":[{"번호":1,"판정":"옳음","설명":"반사회질서 여부는 법률행위가 이루어진 당시를 기준으로 판단한다. 사후의 사정 변화로 결론이 달라지지 않는다."},{"번호":2,"판정":"틀림","설명":"제103조 위반의 무효는 선의의 제3자에게도 주장할 수 있다(96다29151). 선의 제3자에게 대항하지 못하는 것은 제108조·제107조의 무효다."},{"번호":3,"판정":"옳음","설명":"수사기관에 대한 허위진술의 대가를 주기로 한 약정은 제103조 위반으로 무효다. 증언의 대가가 용인 범위를 넘으면 무효로 본 판례가 같은 취지다(93다40522)."},{"번호":4,"판정":"옳음","설명":"강박이라는 불법적 방법이 쓰였을 뿐이면 반사회질서가 아니라 의사표시의 하자, 곧 제110조 취소로 다룬다(92다7719)."},{"번호":5,"판정":"옳음","설명":"상대방에게 표시된 동기가 반사회적이면 그 법률행위는 무효다(92다7719)."}],"개념":[{"종류":"표","제목":"제103조 해당 여부 사례","머리":["구분","사례","판단","근거"],"행":[["해당","증언·허위진술의 대가로 금전·지분을 주기로 한 약정","무효","93다40522"],["해당","제2매수인이 매도인의 배임행위에 적극 가담한 이중매매","절대적 무효","96다29151"],["해당","표시되었거나 상대방에게 알려진 동기가 반사회적인 법률행위","무효","92다7719"],["비해당","성립 과정에 강박이 사용된 데 불과한 법률행위","취소 문제","92다7719"],["비해당","강제집행을 피하려는 허위 근저당권설정등기","제103조 위반으로 보기 어려움","2003다70041"]]},{"종류":"비교","제목":"제103조 무효와 제108조 무효","왼쪽":{"이름":"반사회질서 행위(제103조)","항목":["사회질서에 반하는 내용·조건·대가·동기","무효를 누구에게나 주장 가능","선의 제3자 보호 규정 없음","이행한 급부는 불법원인급여 문제로 이어짐(제746조)"]},"오른쪽":{"이름":"통정허위표시(제108조)","항목":["상대방과의 통정이 있는 허위 의사표시","무효","선의 제3자에게 대항 불가(제108조 제2항)","제3자는 선의이면 족하고 무과실은 불요"]}}],"함정":"허위표시, 착오, 사기·강박 취소는 선의 제3자 보호 규정이 있어서 제103조도 같다고 보면 2번을 옳은 선지로 읽게 된다. 제103조에는 보호 규정이 없다. 4번의 강박은 무효가 아니라 취소 사유다."},"36회-1차-042":{"한줄":"가장채권의 가압류권자와 파산관재인은 허위표시를 기초로 새로운 법률상 이해관계를 맺은 제3자이고, 계약상 지위를 이전받은 자는 원계약 당사자의 지위를 승계할 뿐이므로 ㄱ, ㄴ이 제3자다.","근거":[{"법령":"민법","조문":"제108조","원문":"제108조(통정한 허위의 의사표시) ①상대방과 통정한 허위의 의사표시는 무효로 한다. ②전항의 의사표시의 무효는 선의의 제삼자에게 대항하지 못한다."},{"판례":"대법원 2004. 5. 28. 선고 2003다70041 판결","요지":"허위표시로 외형상 생긴 채권을 가압류한 자는 새로운 법률상 이해관계를 가지므로 제108조 제2항의 제3자다. 제3자는 선의이면 되고 무과실은 요건이 아니다."},{"판례":"대법원 2003. 6. 24. 선고 2002다48214 판결","요지":"가장소비대차의 대주가 파산한 경우 파산관재인은 파산자와 독립하여 이해관계를 가진 제3자로서 제108조 제2항의 제3자다."},{"판례":"대법원 2004. 1. 15. 선고 2002다31537 판결","요지":"허위표시 당사자로부터 계약이전을 받은 자는 원계약상 지위를 넘겨받을 뿐이어서 제3자가 아니다. 부실채권을 양수한 한국자산관리공사는 제3자다."}],"선지":[{"번호":1,"판정":"-","설명":"ㄱ만으로는 부족하다. 파산관재인 ㄴ도 제3자다."},{"번호":2,"판정":"-","설명":"ㄷ은 제3자가 아니다."},{"번호":3,"판정":"-","설명":"ㄱ, ㄴ이 제3자다."},{"번호":4,"판정":"-","설명":"ㄷ이 제3자가 아니므로 ㄴ, ㄷ 조합은 틀리다."},{"번호":5,"판정":"-","설명":"ㄷ이 제3자가 아니므로 ㄱ, ㄴ, ㄷ 조합은 틀리다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"가장채권을 가압류한 자는 허위표시로 형성된 외형을 기초로 새 이해관계를 맺었다(2003다70041)."},{"기호":"ㄴ","판정":"옳음","설명":"파산관재인은 파산채권자 전체의 이익을 위해 직무를 수행하는 제3자다. 선의 여부는 파산채권자 전체를 기준으로 본다(2002다48214)."},{"기호":"ㄷ","판정":"틀림","설명":"계약상 지위를 이전받은 자는 가장소비대차의 당사자가 된 것이다. 계약이전을 받은 자를 제3자로 보지 않은 판례가 있다(2002다31537)."}],"개념":[{"종류":"표","제목":"제108조 제2항의 제3자 해당 여부","머리":["구분","사례","제3자 여부","근거"],"행":[["해당","가장채권을 양수한 자","해당","2002다31537"],["해당","가장채권을 가압류한 자","해당","2003다70041"],["해당","가장소비대차의 대주가 파산한 때의 파산관재인","해당","2002다48214"],["해당","가장 전세권근저당권의 채권을 가압류·압류한 자","해당(선의이면 보호)","2012다49292"],["비해당","허위표시 당사자로부터 계약이전·계약인수를 받은 자","비해당","2002다31537"],["비해당","당사자의 포괄승계인(상속인), 대리인","비해당","당사자와 포괄승계인은 제3자에서 제외"]]},{"종류":"표","제목":"제3자 보호의 요건","머리":["쟁점","내용"],"행":[["제3자의 범위","당사자와 포괄승계인 이외의 자로서, 허위표시로 외형상 형성된 법률관계를 기초로 새로운 법률상 이해관계를 맺은 자"],["선의 요건","선의이면 충분하고 무과실은 요건이 아님"],["선의 증명","악의의 주장·증명은 무효를 주장하는 자가 한다. 제3자는 선의로 추정(2002다1321)"],["전득자","선의의 제3자로부터 취득한 전득자도 보호"]]}],"함정":"계약상 지위 이전과 채권양도를 같이 본 오답이 나온다. 가장채권의 양수인은 제3자이고 계약상 지위를 이전받은 자는 제3자가 아니다. 파산관재인은 개인이 아니라 파산채권자 전체를 기준으로 선의를 따진다."},"36회-1차-045":{"한줄":"경과실로 착오에 빠져 취소한 표의자는 제109조가 허용하는 권리를 행사한 것이어서 불법행위로 인한 손해배상책임을 지지 않으므로 3번이 틀리다.","근거":[{"법령":"민법","조문":"제109조","원문":"제109조(착오로 인한 의사표시) ①의사표시는 법률행위의 내용의 중요부분에 착오가 있는 때에는 취소할 수 있다. 그러나 그 착오가 표의자의 중대한 과실로 인한 때에는 취소하지 못한다. ②전항의 의사표시의 취소는 선의의 제삼자에게 대항하지 못한다."},{"법령":"민법","조문":"제112조","원문":"제112조(제한능력자에 대한 의사표시의 효력) 의사표시의 상대방이 의사표시를 받은 때에 제한능력자인 경우에는 의사표시자는 그 의사표시로써 대항할 수 없다. 다만, 그 상대방의 법정대리인이 의사표시가 도달한 사실을 안 후에는 그러하지 아니하다."},{"법령":"민법","조문":"제107조","원문":"제107조(진의 아닌 의사표시) ①의사표시는 표의자가 진의아님을 알고 한 것이라도 그 효력이 있다. 그러나 상대방이 표의자의 진의아님을 알았거나 이를 알 수 있었을 경우에는 무효로 한다. ②전항의 의사표시의 무효는 선의의 제삼자에게 대항하지 못한다."},{"판례":"대법원 1997. 8. 22. 선고 97다13023 판결","요지":"중대한 과실이 없는 착오자의 취소는 제109조가 허용하므로, 과실로 착오에 빠져 의사표시를 하고 이를 취소한 행위는 위법하지 않아 불법행위책임이 생기지 않는다."},{"판례":"대법원 2000. 4. 25. 선고 99다34475 판결","요지":"비진의표시의 진의는 특정한 내용의 의사표시를 하고자 하는 표의자의 생각이며, 마음속으로 진정 바라는 사항이 아니다."},{"판례":"대법원 1998. 2. 27. 선고 97다50985 판결","요지":"통정허위표시로 무효인 법률행위도 채권자취소권의 대상이 된다."},{"판례":"대법원 1997. 12. 12. 선고 97누13962 판결","요지":"공무원의 사직 의사표시에는 비진의표시에 관한 제107조가 준용되지 않는다."}],"선지":[{"번호":1,"판정":"옳음","설명":"상대방이 의사표시를 받은 때 제한능력자이면 표의자는 대항하지 못한다. 법정대리인이 도달 사실을 안 후에는 대항할 수 있다(제112조)."},{"번호":2,"판정":"옳음","설명":"진의는 특정 내용의 의사표시를 하고자 하는 생각이다. 최선이라고 판단해서 한 의사표시는 비진의표시가 아니다(99다34475)."},{"번호":3,"판정":"틀림","설명":"경과실 착오로 취소해도 불법행위책임은 없다(97다13023). 취소할 수 없는 경우는 중대한 과실이 있을 때다(제109조 제1항)."},{"번호":4,"판정":"옳음","설명":"허위표시로 무효인 법률행위도 사해행위취소의 대상이 된다(97다50985)."},{"번호":5,"판정":"옳음","설명":"사인의 공법행위인 공무원의 사직 의사표시에는 제107조가 적용되지 않는다(97누13962)."}],"개념":[{"종류":"표","제목":"의사표시 하자의 효과 비교","머리":["구분","근거","효과","선의 제3자 보호"],"행":[["비진의표시","제107조","원칙 유효. 상대방이 알았거나 알 수 있었으면 무효","선의 제3자에게 대항 불가"],["통정허위표시","제108조","무효","선의 제3자에게 대항 불가"],["착오","제109조","중요부분의 착오는 취소. 표의자의 중대한 과실이 있으면 취소 불가","선의 제3자에게 대항 불가"],["사기·강박","제110조","취소. 제3자가 한 경우 상대방이 알았거나 알 수 있었던 때에 한해 취소","취소 전의 선의 제3자에게 대항 불가"]]},{"종류":"비교","제목":"비진의표시와 통정허위표시","왼쪽":{"이름":"비진의표시(제107조)","항목":["상대방과의 통정이 없음","표의자 혼자 진의 아님을 알고 한 표시","원칙 유효, 상대방 악의·과실이면 무효","공무원 사직 등 사인의 공법행위에는 적용 안 됨"]},"오른쪽":{"이름":"통정허위표시(제108조)","항목":["상대방과 통정한 허위 표시","언제나 무효","채권자취소권 대상이 됨","선의 제3자는 보호"]}}],"함정":"착오 취소에는 손해배상책임이 따른다고 외운 수험생이 3번을 옳게 읽는다. 중과실이 없으면 취소는 적법한 권리행사다. 5번은 공법행위에 민법 규정을 그대로 적용하지 않는다는 점을 묻는다."},"36회-1차-044":{"한줄":"법정대리인이 부득이한 사유로 복대리인을 선임한 때에는 본인에 대해 선임감독상의 책임만 지므로 5번이 옳다.","근거":[{"법령":"민법","조문":"제120조","원문":"제120조(임의대리인의 복임권) 대리권이 법률행위에 의하여 부여된 경우에는 대리인은 본인의 승낙이 있거나 부득이한 사유있는 때가 아니면 복대리인을 선임하지 못한다."},{"법령":"민법","조문":"제121조","원문":"제121조(임의대리인의 복대리인선임의 책임) ①전조의 규정에 의하여 대리인이 복대리인을 선임한 때에는 본인에게 대하여 그 선임감독에 관한 책임이 있다. ②대리인이 본인의 지명에 의하여 복대리인을 선임한 경우에는 그 부적임 또는 불성실함을 알고 본인에게 대한 통지나 그 해임을 태만한 때가 아니면 책임이 없다."},{"법령":"민법","조문":"제122조","원문":"제122조(법정대리인의 복임권과 그 책임) 법정대리인은 그 책임으로 복대리인을 선임할 수 있다. 그러나 부득이한 사유로 인한 때에는 전조제1항에 정한 책임만이 있다."},{"법령":"민법","조문":"제123조","원문":"제123조(복대리인의 권한) ①복대리인은 그 권한내에서 본인을 대리한다. ②복대리인은 본인이나 제삼자에 대하여 대리인과 동일한 권리의무가 있다."},{"법령":"민법","조문":"제127조","원문":"제127조(대리권의 소멸사유) 대리권은 다음 각 호의 어느 하나에 해당하는 사유가 있으면 소멸된다. 1. 본인의 사망 2. 대리인의 사망, 성년후견의 개시 또는 파산"}],"선지":[{"번호":1,"판정":"틀림","설명":"복대리인은 대리인이 자기 이름으로 선임하는 대리인의 대리인이 아니라, 대리인이 본인의 이름으로 선임하는 본인의 대리인이다(제123조 제1항)."},{"번호":2,"판정":"틀림","설명":"복대리인을 선임해도 대리인의 대리권은 소멸하지 않는다. 소멸사유는 본인의 사망, 대리인의 사망·성년후견 개시·파산이다(제127조)."},{"번호":3,"판정":"틀림","설명":"임의대리인이 본인의 승낙을 얻어 복대리인을 선임해도 본인에 대한 선임감독 책임이 있다(제121조 제1항)."},{"번호":4,"판정":"틀림","설명":"법정대리인은 본인의 승낙이나 부득이한 사유가 없어도 자기 책임으로 복대리인을 선임할 수 있다(제122조 본문). 승낙·부득이한 사유를 요구하는 것은 임의대리인이다(제120조)."},{"번호":5,"판정":"옳음","설명":"법정대리인은 부득이한 사유로 복대리인을 선임한 때 제121조 제1항의 선임감독 책임만 진다(제122조 단서)."}],"개념":[{"종류":"표","제목":"복임권과 책임","머리":["구분","복대리인 선임","본인에 대한 책임"],"행":[["임의대리인","본인의 승낙 또는 부득이한 사유가 있어야 선임(제120조)","선임감독 책임(제121조 제1항)"],["임의대리인(본인 지명 선임)","지명된 자를 선임","부적임·불성실을 알고 통지·해임을 게을리한 때만 책임(제121조 제2항)"],["법정대리인","언제나 자기 책임으로 선임(제122조 본문)","복대리인의 행위 전반에 책임"],["법정대리인(부득이한 사유)","부득이한 사유로 선임","선임감독 책임만(제122조 단서)"]]},{"종류":"표","제목":"복대리인의 지위","머리":["항목","내용"],"행":[["성질","대리인이 본인의 이름으로 선임한 본인의 대리인"],["권한의 범위","대리인의 권한 내(제123조 제1항)"],["본인·제3자에 대한 권리의무","대리인과 동일(제123조 제2항)"],["복임 뒤 대리인의 대리권","소멸하지 않음"]]}],"함정":"임의대리와 법정대리의 복임 요건을 뒤바꾼 4번이 가장 많이 나온다. 법정대리인은 언제나 선임할 수 있고 책임이 무겁다. 부득이한 사유가 있을 때만 책임이 줄어든다."},"36회-1차-043":{"한줄":"무권대리의 추인은 의사표시 전체에 대해 해야 하고, 일부만 추인하려면 상대방의 동의가 있어야 하므로 1번이 틀리다.","근거":[{"법령":"민법","조문":"제130조","원문":"제130조(무권대리) 대리권없는 자가 타인의 대리인으로 한 계약은 본인이 이를 추인하지 아니하면 본인에 대하여 효력이 없다."},{"법령":"민법","조문":"제131조","원문":"제131조(상대방의 최고권) 대리권없는 자가 타인의 대리인으로 계약을 한 경우에 상대방은 상당한 기간을 정하여 본인에게 그 추인여부의 확답을 최고할 수 있다. 본인이 그 기간내에 확답을 발하지 아니한 때에는 추인을 거절한 것으로 본다."},{"법령":"민법","조문":"제132조","원문":"제132조(추인, 거절의 상대방) 추인 또는 거절의 의사표시는 상대방에 대하여 하지 아니하면 그 상대방에 대항하지 못한다. 그러나 상대방이 그 사실을 안 때에는 그러하지 아니하다."},{"법령":"민법","조문":"제134조","원문":"제134조(상대방의 철회권) 대리권없는 자가 한 계약은 본인의 추인이 있을 때까지 상대방은 본인이나 그 대리인에 대하여 이를 철회할 수 있다. 그러나 계약당시에 상대방이 대리권 없음을 안 때에는 그러하지 아니하다."},{"판례":"대법원 1982. 1. 26. 선고 81다카549 판결","요지":"무권대리의 추인은 의사표시 전체에 대하여 해야 한다. 일부만 추인하거나 내용을 바꿔 추인하면 상대방의 동의가 없는 한 효력이 없다. 추인은 명시적이든 묵시적이든 무방하다."},{"판례":"대법원 1994. 9. 27. 선고 94다20617 판결","요지":"무권대리인이 본인을 단독상속한 뒤 자신의 대리행위가 무권대리라고 주장하며 본인의 지위에서 효력을 부인하는 것은 신의칙에 반해 허용되지 않는다."}],"선지":[{"번호":1,"판정":"틀림","설명":"일부 추인은 상대방의 동의가 없으면 효력이 없다(81다카549). 본인의 추인은 상대방 동의 없이 할 수 있으나 전부에 대해 해야 한다."},{"번호":2,"판정":"옳음","설명":"본인이 매매대금을 받아 가지면 계약의 효과를 받아들인 행위여서 묵시적 추인으로 본다. 추인은 방식을 묻지 않는다(81다카549)."},{"번호":3,"판정":"옳음","설명":"무권대리인이 본인을 단독상속한 뒤 추인을 거절하는 것은 신의칙에 반한다(94다20617)."},{"번호":4,"판정":"옳음","설명":"상대방이 상당한 기간을 정해 확답을 최고했는데 본인이 확답을 발하지 않으면 추인을 거절한 것으로 본다(제131조)."},{"번호":5,"판정":"옳음","설명":"본인이 상대방 아닌 무권대리인에게 추인하면 상대방이 알기 전에는 그 추인을 상대방에게 대항하지 못하므로(제132조), 알지 못한 선의의 상대방은 철회할 수 있다(제134조)."}],"개념":[{"종류":"흐름","제목":"무권대리 계약 후의 법률관계","단계":[{"이름":"계약 체결","설명":"대리권 없는 자가 대리인으로 계약. 본인이 추인하지 않으면 본인에게 효력 없음(제130조)"},{"이름":"상대방의 최고","설명":"선의·악의 불문. 상당한 기간을 정해 추인 여부를 최고. 확답이 없으면 추인 거절로 간주(제131조)"},{"이름":"상대방의 철회","설명":"계약 당시 선의인 상대방만 가능. 본인의 추인이 있을 때까지(제134조)"},{"이름":"본인의 추인·거절","설명":"상대방에게 해야 대항 가능. 상대방이 안 때에는 예외(제132조). 추인하면 계약 시로 소급(제133조)"},{"이름":"무권대리인의 책임","설명":"상대방의 선택에 따라 이행 또는 손해배상(제135조 제1항)"}]},{"종류":"표","제목":"상대방 보호 수단 비교","머리":["수단","근거","요건","효과"],"행":[["최고권","제131조","선의·악의 불문","확답 없으면 추인 거절 간주"],["철회권","제134조","계약 당시 선의","추인 전까지 계약 철회"],["무권대리인 책임 추궁","제135조","상대방 선의·무과실, 무권대리인이 행위능력자","이행 또는 손해배상"],["표현대리 주장","제125조·제126조·제129조","본인의 귀책 + 상대방의 정당한 신뢰","본인에게 효력 귀속"]]}],"함정":"추인은 본인의 단독행위여서 상대방 동의가 필요 없다고만 외우면 일부 추인도 유효하다고 읽게 된다. 동의가 필요 없는 것은 추인 자체이고, 일부 추인은 내용을 바꾸는 것이라 동의가 필요하다. 5번은 제132조 단서와 제134조를 같이 읽어야 한다."},"36회-1차-050":{"한줄":"취소권자 자신이 하는 이행청구만 법정추인 사유이고(ㄱ), 제한능력자는 선악을 가리지 않고 현존이익 한도에서 상환하며(ㄴ), 상대방이 착오를 알고 이용했다면 중과실이 있어도 취소할 수 있으므로(ㄷ) ㄱ, ㄴ이 옳다.","근거":[{"법령":"민법","조문":"제145조","원문":"제145조(법정추인) 취소할 수 있는 법률행위에 관하여 전조의 규정에 의하여 추인할 수 있는 후에 다음 각호의 사유가 있으면 추인한 것으로 본다. 그러나 이의를 보류한 때에는 그러하지 아니하다. 1. 전부나 일부의 이행 2. 이행의 청구 3. 경개 4. 담보의 제공 5. 취소할 수 있는 행위로 취득한 권리의 전부나 일부의 양도 6. 강제집행"},{"법령":"민법","조문":"제141조","원문":"제141조(취소의 효과) 취소된 법률행위는 처음부터 무효인 것으로 본다. 다만, 제한능력자는 그 행위로 인하여 받은 이익이 현존하는 한도에서 상환(償還)할 책임이 있다."},{"법령":"민법","조문":"제109조","원문":"제109조(착오로 인한 의사표시) ①의사표시는 법률행위의 내용의 중요부분에 착오가 있는 때에는 취소할 수 있다. 그러나 그 착오가 표의자의 중대한 과실로 인한 때에는 취소하지 못한다. ②전항의 의사표시의 취소는 선의의 제삼자에게 대항하지 못한다."},{"판례":"대법원 2023. 4. 27. 선고 2017다227264 판결","요지":"착오가 표의자의 중대한 과실로 인한 때에도 상대방이 표의자의 착오를 알고 이용한 경우에는 취소할 수 있다. 상대방에게 단순한 과실이 있다는 사정만으로는 이 예외에 해당하지 않는다."}],"선지":[{"번호":1,"판정":"-","설명":"ㄴ도 옳다."},{"번호":2,"판정":"-","설명":"ㄷ은 틀렸다."},{"번호":3,"판정":"-","설명":"ㄱ, ㄴ이 옳다."},{"번호":4,"판정":"-","설명":"ㄷ이 틀렸으므로 ㄴ, ㄷ 조합은 틀리다."},{"번호":5,"판정":"-","설명":"ㄷ이 틀렸으므로 ㄱ, ㄴ, ㄷ 조합은 틀리다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"법정추인 사유인 이행의 청구는 취소권자가 상대방에게 하는 청구를 가리킨다. 상대방이 취소권자에게 이행을 청구한 것은 사유가 아니다(제145조 제2호)."},{"기호":"ㄴ","판정":"옳음","설명":"제141조 단서는 제한능력자 일반에 대해 현존이익 한도의 상환책임을 정한다. 악의 여부로 나누지 않는다."},{"기호":"ㄷ","판정":"틀림","설명":"상대방이 착오를 알고 이용했다면 표의자에게 중대한 과실이 있어도 취소할 수 있다(2017다227264)."}],"개념":[{"종류":"표","제목":"법정추인 사유(제145조)","머리":["호","사유","유의점"],"행":[["1","전부나 일부의 이행","취소권자가 이행하는 경우와 이행을 받는 경우"],["2","이행의 청구","취소권자가 청구하는 경우"],["3","경개","당사자가 채권채무를 새 것으로 바꿈"],["4","담보의 제공","취소권자가 제공하거나 제공받음"],["5","취소할 수 있는 행위로 취득한 권리의 전부나 일부의 양도","취소권자가 양도"],["6","강제집행","취소권자가 집행하거나 집행을 받음"]]},{"종류":"표","제목":"취소의 요건과 효과","머리":["항목","내용","근거"],"행":[["취소권자","제한능력자, 착오·사기·강박에 의한 의사표시자, 그 대리인·승계인","제140조"],["취소 상대방","상대방이 확정된 경우 그 상대방에 대한 의사표시","제142조"],["추인 시기","취소원인이 소멸한 후(법정대리인은 예외)","제144조"],["행사기간","추인할 수 있는 날부터 3년, 법률행위를 한 날부터 10년","제146조"],["효과","처음부터 무효. 제한능력자는 현존이익 한도 상환","제141조"]]}],"함정":"법정추인 사유는 취소권자의 행위라는 점을 놓치면 ㄱ을 틀리게 읽는다. 이의를 보류하면 법정추인이 되지 않는다는 단서도 같이 나온다. ㄷ은 중과실이면 무조건 취소 불가라고 외운 수험생이 속는다."},"36회-1차-052":{"한줄":"유치권의 견련관계는 법률이 정한 성립요건이어서 견련성 없는 채권을 피담보채권으로 하는 유치권을 합의로 인정하면 물권법정주의에 반하므로 2번이 틀리다.","근거":[{"법령":"민법","조문":"제185조","원문":"제185조(물권의 종류) 물권은 법률 또는 관습법에 의하는 외에는 임의로 창설하지 못한다."},{"법령":"민법","조문":"제320조","원문":"제320조(유치권의 내용) ①타인의 물건 또는 유가증권을 점유한 자는 그 물건이나 유가증권에 관하여 생긴 채권이 변제기에 있는 경우에는 변제를 받을 때까지 그 물건 또는 유가증권을 유치할 권리가 있다. ②전항의 규정은 그 점유가 불법행위로 인한 경우에 적용하지 아니한다."},{"법령":"민법","조문":"제649조","원문":"제649조(임차지상의 건물에 대한 법정저당권) 토지임대인이 변제기를 경과한 최후 2년의 차임채권에 의하여 그 지상에 있는 임차인소유의 건물을 압류한 때에는 저당권과 동일한 효력이 있다."},{"판례":"대법원 1970. 5. 26. 선고 69다1239 판결","요지":"온천에 관한 권리는 관습법상 물권으로 인정되지 않는다."},{"판례":"대법원 2018다40235 판결","요지":"전세권의 핵심인 사용·수익 권능을 완전히 배제하고 채권담보만을 위해 설정한 전세권설정등기는 물권법정주의에 반해 무효다."},{"판례":"대법원 1995. 2. 10. 선고 94다18508 판결","요지":"주로 채권담보 목적이더라도 장차 전세권자의 사용·수익을 완전히 배제하는 것이 아니면 전세권의 효력을 부인할 수 없다."},{"판례":"대법원 1995. 5. 23.자 94마2218 결정","요지":"근린공원을 자유롭게 이용할 수 있다는 사정만으로 인근 주민이 공원이용권이라는 배타적 권리를 취득하지 않는다."}],"선지":[{"번호":1,"판정":"옳음","설명":"온천권은 관습법상 물권이 아니다(69다1239)."},{"번호":2,"판정":"틀림","설명":"유치권은 그 물건에 관하여 생긴 채권일 것을 요건으로 하는 법정담보물권이다(제320조 제1항). 견련관계 없는 채권으로 유치권을 인정하는 것은 법률이 정하지 않은 내용의 물권을 만드는 것이라 제185조에 반한다."},{"번호":3,"판정":"옳음","설명":"저당권은 약정 외에 법률의 규정으로도 성립한다. 토지임대인이 최후 2년의 차임채권으로 임차인 소유 건물을 압류하면 저당권과 같은 효력이 있다(제649조)."},{"번호":4,"판정":"옳음","설명":"사용·수익 권능을 완전히 배제하고 채권담보만을 위해 설정한 전세권은 물권법정주의에 반해 무효다(2018다40235)."},{"번호":5,"판정":"옳음","설명":"근린공원을 자유롭게 이용했다는 사정만으로 공원이용권이라는 배타적 권리가 생기지 않는다(94마2218)."}],"개념":[{"종류":"표","제목":"물권법정주의 적용 사례","머리":["대상","판단","근거"],"행":[["온천권","물권 아님","69다1239"],["공원이용권","배타적 권리 아님","94마2218"],["견련관계 없는 채권의 유치권","합의로 인정 불가","제185조, 제320조"],["사용·수익을 완전히 배제한 담보 목적 전세권","무효","2018다40235"],["사용·수익을 완전히 배제하지 않은 담보 목적 전세권","유효","94다18508"],["관습법상 법정지상권","관습법상 물권으로 인정","70다2576"]]},{"종류":"표","제목":"민법상 물권의 종류","머리":["구분","종류","성립 방식"],"행":[["본권 중 소유권","소유권","법률"],["용익물권","지상권, 지역권, 전세권","계약 + 등기"],["담보물권(약정)","질권, 저당권","계약 + 인도·등기"],["담보물권(법정)","유치권","요건 충족 시 법률상 성립"],["법정저당권","임차지상 건물에 대한 법정저당권","차임채권으로 건물 압류(제649조)"]]}],"함정":"담보목적 전세권은 모두 무효라고 외우면 4번을 틀린 것으로 읽는다. 무효가 되는 것은 사용·수익을 완전히 배제한 경우다. 2번은 유치권의 견련관계가 법정 요건이라는 점을 묻는다."},"36회-1차-051":{"한줄":"진정명의회복을 원인으로 한 이전등기청구권은 물권적 청구권이고, 점유취득시효 완성에 의한 이전등기청구권은 채권적 청구권이어서 ㄴ, ㄷ이 옳다.","근거":[{"법령":"민법","조문":"제245조","원문":"제245조(점유로 인한 부동산소유권의 취득기간) ①20년간 소유의 의사로 평온, 공연하게 부동산을 점유하는 자는 등기함으로써 그 소유권을 취득한다."},{"판례":"대법원 1990. 11. 27. 선고 89다카12398 전원합의체 판결","요지":"소유자는 말소등기 대신 진정한 등기명의의 회복을 원인으로 한 소유권이전등기를 현재의 등기명의인에게 직접 구할 수 있다."},{"판례":"대법원 1996. 3. 8. 선고 95다34866, 34873 판결","요지":"점유취득시효 완성에 따른 이전등기청구권도 점유를 상실한 때부터 10년의 소멸시효에 걸린다. 채권적 청구권으로 다룬다."}],"선지":[{"번호":1,"판정":"-","설명":"ㄱ만으로는 부족하다. ㄱ은 틀렸다."},{"번호":2,"판정":"-","설명":"ㄷ만으로는 부족하다. ㄴ도 옳다."},{"번호":3,"판정":"-","설명":"ㄱ은 틀렸다."},{"번호":4,"판정":"-","설명":"ㄴ, ㄷ이 옳다."},{"번호":5,"판정":"-","설명":"ㄱ이 틀렸으므로 ㄱ, ㄴ, ㄷ 조합은 틀리다."}],"보기판정":[{"기호":"ㄱ","판정":"틀림","설명":"매매계약에 기한 이전등기청구권은 계약상 의무의 이행을 구하는 채권적 청구권이다."},{"기호":"ㄴ","판정":"옳음","설명":"진정명의회복 원인의 이전등기청구권은 소유권에 기초한 물권적 청구권이다(89다카12398)."},{"기호":"ㄷ","판정":"옳음","설명":"점유취득시효 완성에 따른 이전등기청구권은 채권적 청구권이다. 등기를 해야 소유권을 취득한다(제245조 제1항)."}],"개념":[{"종류":"흐름","제목":"부동산 점유취득시효","단계":[{"이름":"점유","설명":"20년간 소유의 의사로 평온·공연하게 부동산을 점유(제245조 제1항)"},{"이름":"시효 완성","설명":"점유자에게 소유자에 대한 이전등기청구권(채권적)이 생김"},{"이름":"등기","설명":"등기함으로써 소유권 취득(제245조 제1항). 등기 전에는 소유권을 취득하지 못함"},{"이름":"점유 상실","설명":"점유를 잃은 때부터 10년이 지나면 이전등기청구권의 소멸시효 완성(95다34866, 34873)"}]},{"종류":"표","제목":"등기청구권의 성질 분류","머리":["청구권","성질"],"행":[["매매에 기한 이전등기청구권","채권적"],["점유취득시효 완성 이전등기청구권","채권적"],["진정명의회복 이전등기청구권","물권적"],["원인무효 등기의 말소등기청구권","물권적"]]}],"함정":"시효취득자는 소유권을 취득하기 전에 이전등기청구권만 갖는다. 이것을 물권적 청구권으로 읽는 오답이 나온다. 진정명의회복은 소유자의 물권적 청구권이다."},"36회-1차-056":{"한줄":"공유물을 독점 점유하는 다른 소수지분권자에게 보존행위를 근거로 자기에게 인도하라고 청구할 수는 없으므로 4번이 틀리다.","근거":[{"법령":"민법","조문":"제263조","원문":"제263조(공유지분의 처분과 공유물의 사용, 수익) 공유자는 그 지분을 처분할 수 있고 공유물 전부를 지분의 비율로 사용, 수익할 수 있다."},{"법령":"민법","조문":"제264조","원문":"제264조(공유물의 처분, 변경) 공유자는 다른 공유자의 동의없이 공유물을 처분하거나 변경하지 못한다."},{"법령":"민법","조문":"제265조","원문":"제265조(공유물의 관리, 보존) 공유물의 관리에 관한 사항은 공유자의 지분의 과반수로써 결정한다. 그러나 보존행위는 각자가 할 수 있다."},{"법령":"민법","조문":"제267조","원문":"제267조(지분포기 등의 경우의 귀속) 공유자가 그 지분을 포기하거나 상속인없이 사망한 때에는 그 지분은 다른 공유자에게 각 지분의 비율로 귀속한다."},{"판례":"대법원 2020. 5. 21. 선고 2018다287522 전원합의체 판결","요지":"공유물의 소수지분권자가 다른 공유자와 협의 없이 공유물을 독점적으로 점유·사용하는 경우, 다른 소수지분권자는 보존행위를 근거로 공유물의 인도를 청구할 수 없다. 자기 지분권에 기초해 방해 제거나 공동 점유를 방해하는 행위의 금지 등을 청구할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"甲의 지분 4/7는 과반수여서 乙, 丙과 협의 없이 관리에 관한 사항을 정할 수 있다(제265조 본문)."},{"번호":2,"판정":"옳음","설명":"공유물의 처분에는 다른 공유자의 동의가 필요하다(제264조)."},{"번호":3,"판정":"옳음","설명":"공유자는 자기 지분을 자유롭게 처분하거나 담보로 제공할 수 있다(제263조)."},{"번호":4,"판정":"틀림","설명":"乙의 독점 점유에 대해 丙이 보존행위로 자기에게 인도를 청구할 수 없다(2018다287522). 지상물 수거 등 방해 제거나 공동 점유 방해 금지는 청구할 수 있다."},{"번호":5,"판정":"옳음","설명":"공유자가 지분을 포기하면 그 지분은 다른 공유자에게 각 지분의 비율로 귀속한다(제267조). 乙과 丙의 지분 비율은 2대 1이다."}],"개념":[{"종류":"표","제목":"공유물 점유 사안별 청구","머리":["상황","청구 가능 여부","근거"],"행":[["소수지분권자의 독점 점유에 대해 다른 소수지분권자가 인도 청구","불가(보존행위 아님)","2018다287522"],["같은 경우 방해 제거·공동 점유 방해 금지 청구","가능","2018다287522"],["공유자가 아닌 제3자의 무단 점유","각 공유자가 보존행위로 단독 청구 가능","제265조 단서"],["과반수 지분권자의 관리 결정으로 정한 사용 방법","그 범위에서 유효","제265조 본문"]]},{"종류":"표","제목":"지분 비율과 결정권","머리":["공유자","지분","결정에서의 지위"],"행":[["甲","4/7","단독으로 과반수 충족(관리 결정 가능)"],["乙","2/7","단독으로는 과반수 미달"],["丙","1/7","단독으로는 과반수 미달"],["乙 + 丙","3/7","합쳐도 과반수 미달"]]}],"함정":"종전에는 보존행위로 인도를 청구할 수 있다고 본 판례가 있었으나 2020년 전원합의체 판결로 변경되었다. 구판례로 4번을 옳게 읽는 오답이 나온다. 5번의 귀속 비율은 乙과 丙의 지분 비율 2대 1이다.","개정":"공유물 소수지분권자의 독점 점유에 대한 인도청구는 2020. 5. 21. 선고 2018다287522 전원합의체 판결로 종전 판례가 변경되어 허용되지 않는다."},"36회-1차-059":{"한줄":"담보 목적으로 설정된 지상권은 피담보채권이 변제로 소멸하면 함께 소멸하므로 2번이 옳다.","근거":[{"법령":"민법","조문":"제279조","원문":"제279조(지상권의 내용) 지상권자는 타인의 토지에 건물 기타 공작물이나 수목을 소유하기 위하여 그 토지를 사용하는 권리가 있다."},{"법령":"민법","조문":"제280조","원문":"제280조(존속기간을 약정한 지상권) ①계약으로 지상권의 존속기간을 정하는 경우에는 그 기간은 다음 연한보다 단축하지 못한다. 1. 석조, 석회조, 연와조 또는 이와 유사한 견고한 건물이나 수목의 소유를 목적으로 하는 때에는 30년 2. 전호이외의 건물의 소유를 목적으로 하는 때에는 15년 3. 건물이외의 공작물의 소유를 목적으로 하는 때에는 5년 ②전항의 기간보다 단축한 기간을 정한 때에는 전항의 기간까지 연장한다."},{"법령":"민법","조문":"제283조","원문":"제283조(지상권자의 갱신청구권, 매수청구권) ①지상권이 소멸한 경우에 건물 기타 공작물이나 수목이 현존한 때에는 지상권자는 계약의 갱신을 청구할 수 있다. ②지상권설정자가 계약의 갱신을 원하지 아니하는 때에는 지상권자는 상당한 가액으로 전항의 공작물이나 수목의 매수를 청구할 수 있다."},{"법령":"민법","조문":"제288조","원문":"제288조(지상권소멸청구와 저당권자에 대한 통지) 지상권이 저당권의 목적인 때 또는 그 토지에 있는 건물, 수목이 저당권의 목적이 된 때에는 전조의 청구는 저당권자에게 통지한 후 상당한 기간이 경과함으로써 그 효력이 생긴다."},{"법령":"민법","조문":"제369조","원문":"제369조(부종성) 저당권으로 담보한 채권이 시효의 완성 기타 사유로 인하여 소멸한 때에는 저당권도 소멸한다."},{"판례":"대법원 2011. 4. 14. 선고 2011다6342 판결","요지":"근저당권 등 담보권의 담보가치를 지키려고 채권자 앞으로 설정한 지상권은 피담보채권에 종속되어, 피담보채권이 변제나 시효로 소멸하면 지상권도 함께 소멸한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"갱신청구권은 형성권이 아니라 청구권이다. 지상권설정자가 응하지 않으면 지상권자가 매수청구를 할 수 있다(제283조). 갱신청구에 설정자의 승낙이 있어야 계약이 갱신된다."},{"번호":2,"판정":"옳음","설명":"담보지상권은 피담보채권에 종속되어 피담보채권이 소멸하면 소멸한다(2011다6342)."},{"번호":3,"판정":"틀림","설명":"최단존속기간은 건물·수목·공작물의 소유를 목적으로 하는 지상권에 적용한다(제279조, 제280조 제1항). 타인의 기존 건물을 사용하기 위한 설정은 소유 목적이 아니어서 30년 규정이 적용되지 않는다."},{"번호":4,"판정":"틀림","설명":"기존 건물의 소유를 목적으로 한 지상권은 건물이 멸실되어도 소멸하지 않는다. 민법은 건물 멸실을 지상권의 소멸사유로 정하지 않았다."},{"번호":5,"판정":"틀림","설명":"지료연체로 인한 소멸청구는 저당권자에게 통지한 후 상당한 기간이 경과해야 효력이 생긴다(제288조). 통지 즉시 효력이 생기지 않는다."}],"개념":[{"종류":"표","제목":"지상권 존속기간","머리":["구분","기간","근거"],"행":[["석조·석회조·연와조 등 견고한 건물, 수목의 소유 목적","최단 30년","제280조 제1항 제1호"],["그 밖의 건물의 소유 목적","최단 15년","제280조 제1항 제2호"],["건물 이외의 공작물의 소유 목적","최단 5년","제280조 제1항 제3호"],["최단기간보다 짧게 정한 때","최단기간까지 연장","제280조 제2항"],["기간을 정하지 않은 때","최단존속기간","제281조 제1항"],["공작물의 종류·구조를 정하지 않은 때","제2호 건물(15년)로 간주","제281조 제2항"]]},{"종류":"흐름","제목":"지료연체와 지상권 소멸청구","단계":[{"이름":"지료 연체","설명":"지상권자가 2년 이상의 지료를 지급하지 않음(제287조)"},{"이름":"소멸청구","설명":"지상권설정자가 지상권의 소멸을 청구"},{"이름":"저당권자 통지","설명":"지상권이 저당권의 목적인 때 저당권자에게 통지(제288조)"},{"이름":"효력 발생","설명":"통지 후 상당한 기간이 경과한 때(제288조)"},{"이름":"소멸 후 처리","설명":"지상권자의 수거·원상회복(제285조 제1항), 건물 현존 시 갱신청구·매수청구(제283조)"}]}],"함정":"갱신청구권을 형성권으로 읽으면 1번이 옳아 보인다. 청구권이어서 설정자가 거절하면 매수청구로 넘어간다. 5번은 통지 즉시가 아니라 상당한 기간 경과가 요건이다."},"36회-1차-060":{"한줄":"승역지 소유자가 지역권자의 공작물을 쓰려면 수익 정도의 비율로 설치·보존 비용을 분담해야 하므로 5번이 틀리다.","근거":[{"법령":"민법","조문":"제292조","원문":"제292조(부종성) ①지역권은 요역지소유권에 부종하여 이전하며 또는 요역지에 대한 소유권이외의 권리의 목적이 된다. 그러나 다른 약정이 있는 때에는 그 약정에 의한다. ②지역권은 요역지와 분리하여 양도하거나 다른 권리의 목적으로 하지 못한다."},{"법령":"민법","조문":"제295조","원문":"제295조(취득과 불가분성) ①공유자의 1인이 지역권을 취득한 때에는 다른 공유자도 이를 취득한다. ②점유로 인한 지역권취득기간의 중단은 지역권을 행사하는 모든 공유자에 대한 사유가 아니면 그 효력이 없다."},{"법령":"민법","조문":"제300조","원문":"제300조(공작물의 공동사용) ①승역지의 소유자는 지역권의 행사를 방해하지 아니하는 범위내에서 지역권자가 지역권의 행사를 위하여 승역지에 설치한 공작물을 사용할 수 있다. ②전항의 경우에 승역지의 소유자는 수익정도의 비율로 공작물의 설치, 보존의 비용을 분담하여야 한다."},{"법령":"민법","조문":"제301조","원문":"제301조(준용규정) 제214조의 규정은 지역권에 준용한다."},{"법령":"민법","조문":"제214조","원문":"제214조(소유물방해제거, 방해예방청구권) 소유자는 소유권을 방해하는 자에 대하여 방해의 제거를 청구할 수 있고 소유권을 방해할 염려있는 행위를 하는 자에 대하여 그 예방이나 손해배상의 담보를 청구할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"민법 제291조부터 제302조까지에 지역권의 존속기간을 정한 규정이 없다."},{"번호":2,"판정":"옳음","설명":"지역권은 요역지 소유권에 부종하여 이전하므로 요역지의 경매 매수인은 특약이 없으면 소유권과 함께 지역권을 취득한다(제292조 제1항)."},{"번호":3,"판정":"옳음","설명":"점유로 인한 지역권 취득기간의 중단은 지역권을 행사하는 모든 공유자에 대한 사유가 아니면 효력이 없다(제295조 제2항)."},{"번호":4,"판정":"옳음","설명":"지역권에는 제214조가 준용되어 방해 예방이나 손해배상 담보를 청구할 수 있다(제301조)."},{"번호":5,"판정":"틀림","설명":"승역지 소유자는 수익 정도의 비율로 공작물의 설치·보존 비용을 분담해야 한다(제300조 제2항)."}],"개념":[{"종류":"표","제목":"지역권의 성질","머리":["성질","내용","근거"],"행":[["부종성","요역지 소유권에 부종하여 이전. 요역지와 분리하여 양도·담보 불가","제292조"],["취득의 불가분성","공유자 1인이 취득하면 다른 공유자도 취득","제295조 제1항"],["시효 중단의 불가분성","점유 취득기간의 중단은 모든 공유자에 대한 사유여야 함","제295조 제2항"],["소멸시효 중단·정지","요역지 공유자 1인에 의한 중단·정지는 다른 공유자에게 효력","제296조"],["지분에 관한 소멸 금지","공유자 1인은 지분에 관한 지역권을 소멸시키지 못함","제293조 제1항"],["취득시효","계속되고 표현된 지역권에 한함","제294조"]]},{"종류":"비교","제목":"지상권과 지역권","왼쪽":{"이름":"지상권","항목":["타인 토지에 건물·공작물·수목을 소유하기 위해 사용","존속기간 최단 규정 있음(제280조)","지료 지급 가능","독립한 양도·임대 가능(제282조)"]},"오른쪽":{"이름":"지역권","항목":["타인 토지를 자기 토지의 편익에 이용","존속기간 규정 없음","요역지 소유권에 부종","요역지와 분리한 양도 불가(제292조)"]}}],"함정":"비용 분담 없이 공작물을 쓸 수 있다고 쓴 선지가 오답이다. 사용은 자유이나 수익 정도의 비율로 비용을 분담한다."},"36회-1차-061":{"한줄":"관습법상 법정지상권은 등기 없이 취득하고, 취득 당시 토지소유자로부터 토지를 양수한 제3자에게도 등기 없이 주장할 수 있으므로 4번이 옳다.","근거":[{"법령":"민법","조문":"제366조","원문":"제366조(법정지상권) 저당물의 경매로 인하여 토지와 그 지상건물이 다른 소유자에 속한 경우에는 토지소유자는 건물소유자에 대하여 지상권을 설정한 것으로 본다. 그러나 지료는 당사자의 청구에 의하여 법원이 이를 정한다."},{"법령":"민법","조문":"제305조","원문":"제305조(건물의 전세권과 법정지상권) ①대지와 건물이 동일한 소유자에 속한 경우에 건물에 전세권을 설정한 때에는 그 대지소유권의 특별승계인은 전세권설정자에 대하여 지상권을 설정한 것으로 본다. 그러나 지료는 당사자의 청구에 의하여 법원이 이를 정한다."},{"판례":"대법원 1971. 1. 26. 선고 70다2576 판결","요지":"대지와 건물이 한 사람 소유였다가 한쪽만 처분된 경우 건물을 철거해야 할 사정이나 별도 약정이 없으면 관습상 지상권을 취득한다. 관습법에 의한 물권 취득이므로 등기 없이 그 지상권 취득 당시의 토지소유자로부터 토지를 넘겨받은 제3자에게도 주장할 수 있다."},{"판례":"대법원 1988. 4. 12. 선고 87다카2404 판결","요지":"건물이 건물로서의 요건을 갖추고 있는 이상 무허가건물이든 미등기건물이든 가리지 않고 관습상 법정지상권이 성립한다."},{"판례":"대법원 1995. 4. 11. 선고 94다39925 판결","요지":"관습상 법정지상권이 있는 건물을 처분한 경우 등기하지 않은 양수인은 건물 소유권을 취득한 사실만으로 법정지상권을 취득하지 못한다. 법정지상권은 법정지상권자에게 남는다."}],"선지":[{"번호":1,"판정":"틀림","설명":"무허가건물도 건물로서의 요건을 갖추면 관습상 법정지상권이 성립한다(87다카2404)."},{"번호":2,"판정":"틀림","설명":"일시 사용을 위해 지은 가설건축물은 토지에 정착한 건물로 보기 어려워 원칙적으로 성립하지 않는다."},{"번호":3,"판정":"틀림","설명":"관습법상 법정지상권은 건물을 철거한다는 특약 같은 별도 약정이 없을 때 성립하므로, 당사자 약정으로 배제할 수 있다(70다2576)."},{"번호":4,"판정":"옳음","설명":"관습상 지상권은 관습법에 의한 물권 취득이어서 등기 없이 취득 당시 토지소유자와 그로부터 토지를 양수한 제3자에게 주장할 수 있다(70다2576)."},{"번호":5,"판정":"틀림","설명":"건물을 매수한 양수인은 등기를 하지 않으면 법정지상권을 취득하지 못한다(94다39925). 양도인에게 지상권이 남고, 양수인은 양도인을 대위해 설정등기를 청구할 수 있다."}],"개념":[{"종류":"표","제목":"법정지상권의 종류","머리":["구분","근거","성립 요건","등기"],"행":[["저당물 경매","제366조","저당권 설정 당시 토지·건물 동일 소유자 + 경매로 소유자 분리(저당권 설정 당시 건물 존재)","불요"],["전세권 설정","제305조","대지·건물이 동일 소유자에 속한 상태에서 건물에 전세권 설정 + 대지소유권 특별승계","불요"],["가등기담보","가등기담보 등에 관한 법률 제10조","토지·건물 동일 소유자 + 담보가등기에 따른 본등기 또는 소유권 취득","불요"],["관습법상","관습법","처분 당시 토지·건물 동일인 소유 + 소유자 분리 + 철거 특약 없음","불요(처분은 등기 필요)"]]},{"종류":"흐름","제목":"관습법상 법정지상권의 성립과 이전","단계":[{"이름":"처분 당시","설명":"토지와 건물이 동일인 소유(무허가·미등기 건물도 가능)"},{"이름":"소유자 분리","설명":"매매·증여·강제경매 등으로 토지와 건물의 소유자가 달라짐"},{"이름":"철거 특약 없음","설명":"철거 특약 등 별도 약정이 있으면 성립하지 않음"},{"이름":"지상권 취득","설명":"건물소유자가 등기 없이 취득. 토지 양수인에게도 주장 가능(70다2576)"},{"이름":"건물 양도","설명":"양수인은 등기하지 않으면 지상권을 취득하지 못하고, 양도인을 대위해 설정등기 청구(94다39925)"}]}],"함정":"관습법상 법정지상권과 제366조 법정지상권은 철거 특약의 효력이 다르다. 제366조는 공익상 강행규정이라 배제 특약이 무효다. 관습법상 법정지상권은 철거 특약이 있으면 성립하지 않는다. 건물 양수인은 등기 전에는 지상권자가 아니다."},"36회-1차-063":{"한줄":"저당권에는 제342조의 물상대위가 준용되므로(제370조) 괄호에는 물상대위권이 들어간다.","근거":[{"법령":"민법","조문":"제370조","원문":"제370조(준용규정) 제214조, 제321조, 제333조, 제340조, 제341조 및 제342조의 규정은 저당권에 준용한다."},{"법령":"민법","조문":"제342조","원문":"제342조(물상대위) 질권은 질물의 멸실, 훼손 또는 공용징수로 인하여 질권설정자가 받을 금전 기타 물건에 대하여도 이를 행사할 수 있다. 이 경우에는 그 지급 또는 인도전에 압류하여야 한다."}],"선지":[{"번호":1,"판정":"-","설명":"비용상환청구권은 점유자(제203조)·임차인(제626조)·유치권자(제325조) 등이 지출비용을 돌려받는 권리다. 저당권의 효력이 아니다."},{"번호":2,"판정":"-","설명":"저당물의 멸실·훼손·공용징수로 설정자가 받을 금전 기타 물건에 저당권을 행사하는 권리다(제370조, 제342조)."},{"번호":3,"판정":"-","설명":"매수청구권은 지상물(제283조·제643조)·부속물(제646조) 등에서 인정되고 저당권의 효력이 아니다."},{"번호":4,"판정":"-","설명":"해제권은 계약에서 발생하는 형성권이다. 물상대위와 관계없다."},{"번호":5,"판정":"-","설명":"갱신청구권은 지상권자(제283조)·토지임차인(제643조)의 권리다."}],"개념":[{"종류":"표","제목":"물상대위 대상","머리":["대상","물상대위 여부","이유"],"행":[["공용징수 보상금","대상","제342조가 명시"],["멸실·훼손으로 받을 보험금","대상","목적물의 멸실·훼손에 대신하는 금전(판례)"],["제3자의 불법행위로 목적물이 훼손되어 설정자가 갖는 손해배상청구권","대상","훼손으로 설정자가 받을 금전"],["저당목적물의 매각대금","대상 아님","저당권이 제3취득자에게 그대로 따라가므로 대위할 필요 없음"],["지급·인도 후의 금전","불가","지급 또는 인도 전에 압류해야 함(제342조 후단)"]]},{"종류":"흐름","제목":"물상대위 행사","단계":[{"이름":"사고 발생","설명":"멸실·훼손·공용징수로 설정자가 금전 기타 물건의 청구권 취득"},{"이름":"지급·인도 전 압류","설명":"저당권자 스스로 압류해야 한다. 특정성 유지와 제3자 보호 때문(제342조 후단)"},{"이름":"권리 행사","설명":"압류 후 추심·전부명령 등으로 우선변제"}]}],"함정":"용어 선지라 정확한 이름을 모르면 고르기 어렵다. 비용상환·매수청구·갱신청구는 임차인·지상권자·점유자의 권리라서 저당권 지문에서는 바로 지워진다. 물상대위는 질권·저당권에서 나온다는 점과 압류 요건까지 함께 묻는 문항이 자주 나온다."},"36회-1차-062":{"한줄":"저당권의 효력은 저당부동산에 부합된 물건에 미치고 설정 후에 부합된 물건도 포함하므로 4번이 틀리다.","근거":[{"법령":"민법","조문":"제358조","원문":"제358조(저당권의 효력의 범위) 저당권의 효력은 저당부동산에 부합된 물건과 종물에 미친다. 그러나 법률에 특별한 규정 또는 설정행위에 다른 약정이 있으면 그러하지 아니하다."},{"법령":"민법","조문":"제360조","원문":"제360조(피담보채권의 범위) 저당권은 원본, 이자, 위약금, 채무불이행으로 인한 손해배상 및 저당권의 실행비용을 담보한다. 그러나 지연배상에 대하여는 원본의 이행기일을 경과한 후의 1년분에 한하여 저당권을 행사할 수 있다."},{"법령":"민법","조문":"제363조제2항","원문":"제363조(저당권자의 경매청구권, 경매인) ②저당물의 소유권을 취득한 제삼자도 경매인이 될 수 있다."},{"법령":"민법","조문":"제356조","원문":"제356조(저당권의 내용) 저당권자는 채무자 또는 제삼자가 점유를 이전하지 아니하고 채무의 담보로 제공한 부동산에 대하여 다른 채권자보다 자기채권의 우선변제를 받을 권리가 있다."},{"이론":"피담보채권의 종류","내용":"저당권의 피담보채권은 금전채권에 한하지 않는다. 금전 외의 채권도 채무불이행 시 손해배상채권으로 바뀌어 저당권 실행으로 만족을 얻을 수 있다(통설)."}],"선지":[{"번호":1,"판정":"옳음","설명":"원본·이자·위약금·손해배상과 함께 저당권의 실행비용을 담보한다(제360조)."},{"번호":2,"판정":"옳음","설명":"금전채권이 아니어도 된다. 불이행 시 손해배상채권으로 전환해 경매로 만족을 얻는다(통설)."},{"번호":3,"판정":"옳음","설명":"저당물의 소유권을 취득한 제3자도 경매인이 될 수 있다(제363조 제2항)."},{"번호":4,"판정":"틀림","설명":"저당권의 효력은 부합물과 종물에 미친다(제358조 본문). 설정 후에 부합된 물건도 포함한다. 설정행위에서 달리 정하면 예외다."},{"번호":5,"판정":"옳음","설명":"「채무자 또는 제삼자」가 제공할 수 있으므로 물상보증인이 설정자가 될 수 있다(제356조)."}],"개념":[{"종류":"표","제목":"저당권 효력의 범위","머리":["구분","내용","근거"],"행":[["부합물·종물","설정 전후를 가리지 않고 미침. 특약으로 배제 가능","제358조"],["과실","압류 후 설정자가 수취한 또는 수취할 수 있는 과실에 미침. 제3취득자에게는 압류 통지 후부터","제359조"],["피담보채권","원본·이자·위약금·손해배상·실행비용. 지연배상은 이행기 경과 후 1년분","제360조"],["물상대위","멸실·훼손·공용징수로 받을 금전에 지급 전 압류하여 행사","제370조·제342조"],["저당지상 건물","토지와 함께 경매 청구 가능하나 건물 대가에는 우선변제권 없음","제365조"]]},{"종류":"표","제목":"제3취득자의 지위","머리":["내용","근거"],"행":[["저당물 경매에서 경매인이 될 수 있다","제363조 제2항"],["소유권·지상권·전세권을 취득한 제3자는 채권을 변제하고 저당권 소멸을 청구","제364조"]]}],"함정":"4번을 설정 당시 존재한 물건에만 효력이 미친다고 오해하게 만든 선지다. 부합 시점은 요건이 아니다. 지연배상 1년분 제한은 이자에는 적용되지 않는다는 점도 같이 나온다."},"36회-1차-074":{"한줄":"매매는 당사자의 합의만으로 효력이 생기는 낙성계약이다(제563조).","근거":[{"법령":"민법","조문":"제563조","원문":"제563조(매매의 의의) 매매는 당사자 일방이 재산권을 상대방에게 이전할 것을 약정하고 상대방이 그 대금을 지급할 것을 약정함으로써 그 효력이 생긴다."},{"법령":"민법","조문":"제596조","원문":"제596조(교환의 의의) 교환은 당사자 쌍방이 금전 이외의 재산권을 상호이전할 것을 약정함으로써 그 효력이 생긴다."},{"법령":"민법","조문":"제618조","원문":"제618조(임대차의 의의) 임대차는 당사자 일방이 상대방에게 목적물을 사용, 수익하게 할 것을 약정하고 상대방이 이에 대하여 차임을 지급할 것을 약정함으로써 그 효력이 생긴다."}],"선지":[{"번호":1,"판정":"틀림","설명":"요물계약은 물건 인도가 있어야 성립하는 계약이다. 매매는 합의만으로 성립한다(제563조)."},{"번호":2,"판정":"옳음","설명":"재산권 이전과 대금 지급의 약정만으로 효력이 생긴다(제563조)."},{"번호":3,"판정":"틀림","설명":"교환은 금전 이외의 재산권을 상호이전하기로 약정하면 효력이 생기며 방식이 필요 없다(제596조)."},{"번호":4,"판정":"틀림","설명":"임차인이 차임을 지급하므로 유상계약이다(제618조)."},{"번호":5,"판정":"틀림","설명":"임대인의 사용·수익 제공의무와 임차인의 차임지급의무가 대가관계에 있어 쌍무계약이다(제618조)."}],"개념":[{"종류":"표","제목":"계약의 분류","머리":["계약","쌍무/편무","유상/무상","낙성/요물","요식 여부"],"행":[["매매","쌍무","유상","낙성","불요식"],["교환","쌍무","유상","낙성","불요식"],["임대차","쌍무","유상","낙성","불요식"],["증여","편무","무상","낙성","불요식(서면 없는 증여는 해제 가능)"],["사용대차","편무","무상","낙성","불요식"]]},{"종류":"표","제목":"분류의 실익","머리":["분류","적용되는 규정"],"행":[["쌍무계약","동시이행항변권(제536조), 위험부담(제537조)"],["유상계약","매매 규정 준용(제567조), 매도인 담보책임"],["낙성계약","합의 시 성립. 계약금계약은 요물계약(판례)"],["요물계약","목적물 인도 등 급부가 성립요건"]]}],"함정":"매매·교환·임대차는 모두 쌍무·유상·낙성·불요식으로 같다. 증여·사용대차만 편무·무상이다. 계약금계약은 요물계약이라는 판례가 있어 요물 선지에 쓰이기도 한다."},"36회-1차-068":{"한줄":"합의해제를 무효화하고 해제된 계약을 되살리는 약정도 계약자유의 원칙상 유효하므로 4번이 틀리다.","근거":[{"법령":"민법","조문":"제548조제1항","원문":"제548조(해제의 효과, 원상회복의무) ①당사자 일방이 계약을 해제한 때에는 각 당사자는 그 상대방에 대하여 원상회복의 의무가 있다. 그러나 제삼자의 권리를 해하지 못한다."},{"법령":"민법","조문":"제551조","원문":"제551조(해지, 해제와 손해배상) 계약의 해지 또는 해제는 손해배상의 청구에 영향을 미치지 아니한다."},{"법령":"민법","조문":"제543조제1항","원문":"제543조(해지, 해제권) ①계약 또는 법률의 규정에 의하여 당사자의 일방이나 쌍방이 해지 또는 해제의 권리가 있는 때에는 그 해지 또는 해제는 상대방에 대한 의사표시로 한다."},{"판례":"대법원 91다2601 판결","요지":"합의해제에도 민법 제548조 제1항 단서가 유추적용되어 해제 전 이해관계를 맺고 등기·인도로 권리를 취득한 제3자를 해하지 못한다."},{"판례":"대법원 판례(합의해제의 법리)","요지":"합의해제는 계약으로 계약을 소멸시키는 것이라 손해배상은 합의 내용에 따른다. 합의해제를 무효화하고 계약을 부활시키는 약정도 유효하다. 묵시적 합의해제는 쌍방의 계약실현 의사 없음 또는 포기 의사가 인정될 정도여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"합의해제도 계약을 소급 소멸시키는 점은 같다. 이전된 소유권은 말소등기 없이도 복귀한다(판례)."},{"번호":2,"판정":"옳음","설명":"합의해제는 법정해제와 달리 제551조가 적용되지 않는다. 손해배상은 특약이 있을 때만 청구할 수 있다(판례)."},{"번호":3,"판정":"옳음","설명":"합의해제에도 제548조 제1항 단서를 유추적용해 제3자를 보호한다(판례)."},{"번호":4,"판정":"틀림","설명":"합의해제를 무효화하고 해제된 계약을 부활시키는 약정은 계약자유의 원칙상 당사자 사이에서 유효하다(판례)."},{"번호":5,"판정":"옳음","설명":"묵시적 합의해제는 쌍방 모두 계약을 실현할 의사가 없거나 포기한 것으로 볼 정도여야 한다(판례)."}],"개념":[{"종류":"비교","제목":"법정해제와 합의해제","왼쪽":{"이름":"법정해제","항목":["해제권 발생: 법률 규정 또는 약정(제543조 제1항)","일방의 의사표시, 철회 불가(제543조 제2항)","손해배상 별도 청구 가능(제551조)","반환 금전에 받은 날부터 이자 가산(제548조 제2항)","제3자 보호: 제548조 제1항 단서"]},"오른쪽":{"이름":"합의해제","항목":["당사자 쌍방의 합의 계약","합의 내용에 따라 효과 결정","특약이 없으면 손해배상 청구 불가","반환 금전의 이자 가산은 특약이 있어야 함(판례)","제548조 제1항 단서 유추적용"]}},{"종류":"흐름","제목":"이행지체로 인한 법정해제","단계":[{"이름":"이행지체","설명":"당사자 일방이 채무를 이행하지 않음"},{"이름":"최고","설명":"상당한 기간을 정해 이행을 최고. 이행거절 의사가 명백하면 최고 불필요(제544조)"},{"이름":"해제 의사표시","설명":"기간 내 이행하지 않으면 해제의 의사표시(제543조 제1항)"},{"이름":"원상회복","설명":"각 당사자가 원상회복. 동시이행 관계(제548조, 제549조)"}]}],"함정":"4번에서 합의해제를 확정적인 것으로 보고 되돌리는 약정은 안 된다고 추측하기 쉽다. 합의해제 자체가 계약이므로 그 합의를 다시 뒤집는 약정도 계약으로서 유효하다. 1번과 3번은 법정해제의 효과가 합의해제에도 똑같이 적용된다는 쪽으로 읽으면 맞다."},"36회-1차-066":{"한줄":"조건을 붙인 승낙은 청약의 거절이자 새 청약이므로(제534조) 합의해제의 청약도 효력을 잃는다.","근거":[{"법령":"민법","조문":"제534조","원문":"제534조(변경을 가한 승낙) 승낙자가 청약에 대하여 조건을 붙이거나 변경을 가하여 승낙한 때에는 그 청약의 거절과 동시에 새로 청약한 것으로 본다."},{"법령":"민법","조문":"제533조","원문":"제533조(교차청약) 당사자간에 동일한 내용의 청약이 상호교차된 경우에는 양청약이 상대방에게 도달한 때에 계약이 성립한다."},{"법령":"민법","조문":"제527조","원문":"제527조(계약의 청약의 구속력) 계약의 청약은 이를 철회하지 못한다."},{"판례":"대법원 판례(청약의 유인)","요지":"청약의 유인에 응한 의사표시는 그 자체가 청약이고, 상대방이 승낙해야 계약이 성립한다."},{"판례":"대법원 판례(명예퇴직 신청)","요지":"근로자의 명예퇴직 신청은 청약이고 사용자의 승인이 승낙이다. 승낙으로 합의가 성립하면 근로자는 철회할 수 없다. 승낙 전에는 신의칙에 반하지 않는 한 철회할 수 있다."},{"판례":"대법원 판례(매매의 일방예약)","요지":"매매의 일방예약이 성립하려면 본계약의 요소가 되는 내용이 확정되어 있거나 확정할 수 있어야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"유인에 대응한 의사표시는 청약이 될 뿐이다. 유인한 쪽이 승낙해야 계약이 성립한다."},{"번호":2,"판정":"틀림","설명":"교차청약은 두 청약이 상대방에게 도달한 때 성립한다(제533조). 발송이 아니다."},{"번호":3,"판정":"옳음","설명":"조건을 붙인 승낙은 청약의 거절과 동시에 한 새 청약이므로(제534조) 합의해제 청약은 실효한다."},{"번호":4,"판정":"틀림","설명":"사용자가 승낙해 명예퇴직 합의가 성립한 뒤에는 예정일 전이라도 근로자가 청약을 철회하지 못한다(판례)."},{"번호":5,"판정":"틀림","설명":"일방예약에도 본계약의 요소(목적물·대금 등)가 확정되었거나 확정할 수 있어야 한다(판례)."}],"개념":[{"종류":"표","제목":"계약 성립 시기와 청약·승낙의 효력","머리":["구분","내용","근거"],"행":[["청약의 구속력","청약은 철회하지 못함","제527조"],["승낙기간을 정한 청약","그 기간 내에 승낙 통지를 받지 못하면 효력 상실","제528조 제1항"],["승낙기간을 정하지 않은 청약","상당한 기간 내에 승낙 통지를 받지 못하면 효력 상실","제529조"],["연착된 승낙","청약자가 새 청약으로 볼 수 있음","제530조"],["변경을 가한 승낙","청약의 거절과 동시에 새 청약","제534조"],["교차청약","두 청약이 도달한 때 성립","제533조"],["격지자 간 계약","승낙의 통지를 발송한 때 성립","제531조"]]},{"종류":"비교","제목":"청약과 청약의 유인","왼쪽":{"이름":"청약","항목":["확정적 구속의사 + 계약 내용 확정","상대방 승낙만으로 계약 성립","청약자는 철회 불가(제527조)"]},"오른쪽":{"이름":"청약의 유인","항목":["타인을 유인하여 청약하게 하는 행위(광고·구인 등)","유인에 응한 상대방의 의사표시는 청약","유인한 쪽의 승낙이 있어야 계약 성립"]}}],"함정":"3번의 「실효」가 낯설어 4번이나 5번을 고르는 경우가 많다. 4번은 합의 후에는 철회가 막힌다는 점, 5번은 일방예약도 본계약 내용이 확정 가능해야 한다는 점이 어긋난다. 2번은 교차청약만 도달주의이고 승낙 쪽은 격지자 간에서 발송주의인 것과 섞이면 틀린다."},"36회-1차-067":{"한줄":"ㄱ·ㄴ·ㄷ 모두 두 의무가 서로 대가관계에 있지 않거나 이행 순서가 정해져 있어 동시이행이 아니다.","근거":[{"법령":"민법","조문":"제536조제1항","원문":"제536조(동시이행의 항변권) ①쌍무계약의 당사자 일방은 상대방이 그 채무이행을 제공할 때 까지 자기의 채무이행을 거절할 수 있다. 그러나 상대방의 채무가 변제기에 있지 아니하는 때에는 그러하지 아니하다."},{"법령":"상가건물 임대차보호법","조문":"제10조의4제3항","원문":"제10조의4(권리금 회수기회 보호 등) ③ 임대인이 제1항을 위반하여 임차인에게 손해를 발생하게 한 때에는 그 손해를 배상할 책임이 있다. 이 경우 그 손해배상액은 신규임차인이 임차인에게 지급하기로 한 권리금과 임대차 종료 당시의 권리금 중 낮은 금액을 넘지 못한다."},{"판례":"대법원 판례(담보 목적 등기의 말소)","요지":"채무 변제가 선이행이다. 채권자의 담보 목적 소유권이전등기 말소의무와 채무자의 변제의무는 동시이행 관계가 아니다."},{"판례":"대법원 판례(권리금 회수 방해 손해배상)","요지":"임차인의 목적물 반환의무와 임대인의 권리금 회수 방해 손해배상의무는 동시이행 관계가 아니다."},{"판례":"대법원 판례(경매 무효와 배당금 반환)","요지":"경매가 무효가 되어 채권자가 배당금을 반환할 의무와 경매매수인의 말소등기의무는 동시이행 관계가 아니다."}],"선지":[{"번호":1,"판정":"-","설명":"ㄱ만으로는 부족하다. ㄴ·ㄷ도 동시이행이 아니다."},{"번호":2,"판정":"-","설명":"ㄷ만으로는 부족하다. ㄱ·ㄴ도 동시이행이 아니다."},{"번호":3,"판정":"-","설명":"ㄷ도 동시이행이 아니므로 ㄱ, ㄴ만 고르면 모자란다."},{"번호":4,"판정":"-","설명":"ㄱ도 동시이행이 아니므로 ㄴ, ㄷ만 고르면 모자란다."},{"번호":5,"판정":"-","설명":"ㄱ, ㄴ, ㄷ 모두 동시이행이 인정되지 않는다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"변제가 선이행이다. 말소의무와 변제의무는 동시이행 관계가 아니다."},{"기호":"ㄴ","판정":"옳음","설명":"권리금 회수 방해로 인한 손해배상의무와 목적물 반환의무는 대가관계가 아니라 동시이행이 아니다."},{"기호":"ㄷ","판정":"옳음","설명":"배당금 반환의무와 말소등기의무는 동시이행 관계가 아니다."}],"개념":[{"종류":"표","제목":"동시이행 인정 여부","머리":["관계","동시이행","근거·이유"],"행":[["매수인의 대금지급 ↔ 매도인의 소유권이전등기·인도","인정","제568조 제2항"],["계약 해제 시 쌍방의 원상회복의무","인정","제549조"],["임대차 종료 시 보증금반환 ↔ 목적물 반환","인정","판례"],["가등기담보 청산금 지급 ↔ 본등기·인도","인정","가등기담보법 제4조 제3항"],["담보 목적 등기 말소 ↔ 피담보채무 변제","불인정","변제가 선이행"],["목적물 반환 ↔ 권리금 회수 방해 손해배상","불인정","대가관계 아님"],["임차권등기 말소 ↔ 보증금반환","불인정","보증금 반환이 먼저(판례)"],["경매 무효 시 배당금 반환 ↔ 매수인의 말소등기의무","불인정","판례"]]},{"종류":"비교","제목":"동시이행항변권의 요건과 효과","왼쪽":{"이름":"요건","항목":["같은 쌍무계약에서 생긴 대가관계 있는 채무(또는 공평의 관념상 견련관계)","상대방의 채무가 변제기에 있을 것(제536조 제1항 단서)","상대방이 자기 채무의 이행 또는 제공 없이 청구할 것"]},"오른쪽":{"이름":"효과","항목":["상대방이 이행을 제공할 때까지 자기 채무의 이행 거절","이행을 거절해도 이행지체 책임을 지지 않음","선이행의무자도 상대방의 이행이 곤란할 현저한 사유가 있으면 항변 가능(제536조 제2항)"]}}],"함정":"「동시이행 인정되지 않는 것」을 고르는 발문이라 ㄱ·ㄴ·ㄷ 전부가 답이다. 동시이행이 인정되는 관계(대금과 등기, 보증금과 인도, 원상회복)만 외우고 나머지를 소거하는 방식으로는 풀리지 않는다. 담보 목적 말소와 변제, 권리금 손해배상과 반환, 배당금 반환과 말소는 순서나 대가관계가 맞지 않는 예외라서 따로 알아야 한다."},"36회-1차-070":{"한줄":"계약 당시 목적물의 일부가 이미 멸실되었고 매수인이 이를 몰랐다면 대금감액을 청구할 수 있다(제574조, 제572조).","근거":[{"법령":"민법","조문":"제574조","원문":"제574조(수량부족, 일부멸실의 경우와 매도인의 담보책임) 전2조의 규정은 수량을 지정한 매매의 목적물이 부족되는 경우와 매매목적물의 일부가 계약당시에 이미 멸실된 경우에 매수인이 그 부족 또는 멸실을 알지 못한 때에 준용한다."},{"법령":"민법","조문":"제572조제1항","원문":"제572조(권리의 일부가 타인에게 속한 경우와 매도인의 담보책임) ①매매의 목적이 된 권리의 일부가 타인에게 속함으로 인하여 매도인이 그 권리를 취득하여 매수인에게 이전할 수 없는 때에는 매수인은 그 부분의 비율로 대금의 감액을 청구할 수 있다."},{"법령":"민법","조문":"제580조","원문":"제580조(매도인의 하자담보책임) ①매매의 목적물에 하자가 있는 때에는 제575조제1항의 규정을 준용한다. 그러나 매수인이 하자있는 것을 알았거나 과실로 인하여 이를 알지 못한 때에는 그러하지 아니하다. ②전항의 규정은 경매의 경우에 적용하지 아니한다."},{"법령":"민법","조문":"제581조제1항","원문":"제581조(종류매매와 매도인의 담보책임) ①매매의 목적물을 종류로 지정한 경우에도 그 후 특정된 목적물에 하자가 있는 때에는 전조의 규정을 준용한다."},{"법령":"민법","조문":"제582조","원문":"제582조(전2조의 권리행사기간) 전2조에 의한 권리는 매수인이 그 사실을 안 날로부터 6월내에 행사하여야 한다."},{"법령":"민법","조문":"제579조","원문":"제579조(채권매매와 매도인의 담보책임) ①채권의 매도인이 채무자의 자력을 담보한 때에는 매매계약당시의 자력을 담보한 것으로 추정한다. ②변제기에 도달하지 아니한 채권의 매도인이 채무자의 자력을 담보한 때에는 변제기의 자력을 담보한 것으로 추정한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"경매에는 하자담보책임 규정이 적용되지 않는다(제580조 제2항)."},{"번호":2,"판정":"틀림","설명":"종류매매도 특정된 목적물에 하자가 있으면 하자담보책임 규정을 준용한다(제581조 제1항)."},{"번호":3,"판정":"틀림","설명":"하자담보 권리는 안 날부터 6월 내에 행사한다(제582조). 1년은 제573조 등 다른 담보책임의 기간이다."},{"번호":4,"판정":"옳음","설명":"일부멸실을 알지 못한 매수인은 제572조를 준용해 대금감액을 청구할 수 있다(제574조)."},{"번호":5,"판정":"틀림","설명":"변제기 미도래 채권은 변제기의 자력을 담보한 것으로 추정한다(제579조 제2항). 계약 당시 자력은 변제기 도래 채권에 대한 추정이다(제1항)."}],"개념":[{"종류":"표","제목":"매도인 담보책임 비교","머리":["유형","매수인의 권리","행사기간","근거"],"행":[["권리 전부 타인 소속","해제(악의 매수인은 손배 불가), 선의 매도인의 손배·해제","기간 제한 없음","제570조·제571조"],["권리 일부 타인 소속","대금감액, 선의는 해제·손배 추가","선의 안 날부터 1년, 악의 계약일부터 1년","제572조·제573조"],["수량부족·일부멸실(선의)","일부 타인 소속 규정 준용","안 날부터 1년","제574조"],["제한물권(지상권·지역권·전세권·질권·유치권) 있음","목적 달성 불가 시 해제, 그 밖에는 손배","안 날부터 1년","제575조"],["저당권·전세권 행사","해제, 출재 상환, 손배","기간 제한 없음","제576조"],["물건의 하자(선의·무과실)","목적 달성 불가 시 해제, 그 밖에는 손배. 종류매매는 완전물급부 청구도 가능","안 날부터 6월","제580조~제582조"],["경매","하자담보 적용 없음","-","제580조 제2항"]]}],"함정":"1년·6월 기간을 섞어 3번을 고르는 경우가 많다. 하자담보는 6월, 권리하자·수량부족은 1년이다. 5번은 변제기 미도래 채권의 자력 기준 시점이 「변제기」라는 한 단어만 바꿨다."},"36회-1차-073":{"한줄":"지상물매수청구권을 배제하는 약정으로 임차인에게 불리한 것은 무효이므로(제652조) ㄷ만 옳다.","근거":[{"법령":"민법","조문":"제643조","원문":"제643조(임차인의 갱신청구권, 매수청구권) 건물 기타 공작물의 소유 또는 식목, 채염, 목축을 목적으로 한 토지임대차의 기간이 만료한 경우에 건물, 수목 기타 지상시설이 현존한 때에는 제283조의 규정을 준용한다."},{"법령":"민법","조문":"제283조","원문":"제283조(지상권자의 갱신청구권, 매수청구권) ①지상권이 소멸한 경우에 건물 기타 공작물이나 수목이 현존한 때에는 지상권자는 계약의 갱신을 청구할 수 있다. ②지상권설정자가 계약의 갱신을 원하지 아니하는 때에는 지상권자는 상당한 가액으로 전항의 공작물이나 수목의 매수를 청구할 수 있다."},{"법령":"민법","조문":"제635조제1항·제2항","원문":"제635조(기간의 약정없는 임대차의 해지통고) ①임대차기간의 약정이 없는 때에는 당사자는 언제든지 계약해지의 통고를 할 수 있다. ②상대방이 전항의 통고를 받은 날로부터 다음 각호의 기간이 경과하면 해지의 효력이 생긴다. 1. 토지, 건물 기타 공작물에 대하여는 임대인이 해지를 통고한 경우에는 6월, 임차인이 해지를 통고한 경우에는 1월 2. 동산에 대하여는 5일"},{"법령":"민법","조문":"제652조","원문":"제652조(강행규정) 제627조, 제628조, 제631조, 제635조, 제638조, 제640조, 제641조, 제643조 내지 제647조의 규정에 위반하는 약정으로 임차인이나 전차인에게 불리한 것은 그 효력이 없다."},{"판례":"대법원 1995. 7. 11. 선고 94다34265 전원합의체 판결","요지":"기간의 정함이 없는 임대차에서 임대인의 해지통고로 임차권이 소멸한 경우 임차인은 갱신청구 없이 바로 지상물매수청구를 할 수 있다."},{"판례":"대법원 판례(무허가건물)","요지":"무허가·미등기 건물이라도 지상물매수청구의 대상이 될 수 있다."}],"선지":[{"번호":1,"판정":"-","설명":"ㄱ은 틀린 보기다. 무허가건물도 매수청구 대상이다."},{"번호":2,"판정":"-","설명":"ㄷ만 옳은 조합이다."},{"번호":3,"판정":"-","설명":"ㄱ, ㄴ은 모두 틀린 보기다."},{"번호":4,"판정":"-","설명":"ㄴ은 틀린 보기다."},{"번호":5,"판정":"-","설명":"ㄱ, ㄴ이 틀려 3개 모두 옳을 수 없다."}],"보기판정":[{"기호":"ㄱ","판정":"틀림","설명":"무허가·미등기 건물도 매수청구 대상이 된다(판례)."},{"기호":"ㄴ","판정":"틀림","설명":"해지통고로 종료된 경우 갱신거절 의사가 이미 들어 있으므로 갱신청구 없이 매수청구를 할 수 있다(94다34265)."},{"기호":"ㄷ","판정":"옳음","설명":"지상물매수청구권을 배제하는 임차인에게 불리한 약정은 효력이 없다(제652조, 제643조)."}],"개념":[{"종류":"비교","제목":"부속물매수청구권과 지상물매수청구권","왼쪽":{"이름":"부속물매수청구권(제646조)","항목":["대상: 건물 기타 공작물의 임차인","임대인의 동의를 얻어 부속한 물건, 임대인으로부터 매수한 물건","건물의 사용 편익을 위한 독립성 있는 물건","임대차 종료 시 행사","임차인의 채무불이행으로 해지된 경우 행사 불가(판례)"]},"오른쪽":{"이름":"지상물매수청구권(제643조·제283조)","항목":["대상: 건물 기타 공작물의 소유 등을 목적으로 한 토지임대차","기간 만료 시 지상시설이 현존할 것","갱신청구를 하고 임대인이 거절하면 행사. 기간 정함 없는 임대차의 해지통고 시는 갱신청구 불필요","무허가·미등기 건물도 대상","임차인의 차임연체 등 채무불이행으로 해지된 경우 행사 불가(판례)"]}},{"종류":"표","제목":"임차인의 권리 정리","머리":["권리","요건","근거"],"행":[["필요비 상환","지출 즉시 청구","제626조 제1항"],["유익비 상환","임대차 종료 시 가액 증가가 현존할 때","제626조 제2항"],["차임증감청구","공과부담 증감·경제사정 변동 시 장래에 대한 증감","제628조"],["해지통고(기간 약정 없음)","임대인 통고 시 6월, 임차인 통고 시 1월(토지·건물)","제635조"],["강행규정","제643조~제647조 등에 위반한 임차인에게 불리한 약정은 무효","제652조"]]}],"함정":"ㄱ에서 무허가는 허가를 받지 않아 보호할 가치가 없다고 보는 쪽이 흔한 오답이다. 매수청구는 건물의 사회·경제적 가치를 보전하는 제도라 등기·허가 여부를 묻지 않는다. ㄴ은 일반 기간 만료와 해지통고 종료를 구별하지 못하면 틀린다."},"36회-1차-072":{"한줄":"동의 있는 전대에서 합의해지로는 전차권이 소멸하지 않고(ㄱ), 임대차가 존속하는 동안은 임대인에게 차임 상당 손해가 없으므로(ㄴ) 틀린 것은 ㄱ, ㄴ이다.","근거":[{"법령":"민법","조문":"제631조","원문":"제631조(전차인의 권리의 확정) 임차인이 임대인의 동의를 얻어 임차물을 전대한 경우에는 임대인과 임차인의 합의로 계약을 종료한 때에도 전차인의 권리는 소멸하지 아니한다."},{"법령":"민법","조문":"제630조제1항","원문":"제630조(전대의 효과) ①임차인이 임대인의 동의를 얻어 임차물을 전대한 때에는 전차인은 직접 임대인에 대하여 의무를 부담한다. 이 경우에 전차인은 전대인에 대한 차임의 지급으로써 임대인에게 대항하지 못한다."},{"법령":"민법","조문":"제647조","원문":"제647조(전차인의 부속물매수청구권) ①건물 기타 공작물의 임차인이 적법하게 전대한 경우에 전차인이 그 사용의 편익을 위하여 임대인의 동의를 얻어 이에 부속한 물건이 있는 때에는 전대차의 종료시에 임대인에 대하여 그 부속물의 매수를 청구할 수 있다. ②임대인으로부터 매수하였거나 그 동의를 얻어 임차인으로부터 매수한 부속물에 대하여도 전항과 같다."},{"법령":"민법","조문":"제629조","원문":"제629조(임차권의 양도, 전대의 제한) ①임차인은 임대인의 동의없이 그 권리를 양도하거나 임차물을 전대하지 못한다. ②임차인이 전항의 규정에 위반한 때에는 임대인은 계약을 해지할 수 있다."},{"판례":"대법원 판례(동의 없는 전대와 손해배상)","요지":"임대인의 동의 없이 전대한 경우에도 임대차가 존속하는 동안에는 임대인이 전차인의 점유로 차임 상당의 손해를 입었다고 볼 수 없어 불법점유를 이유로 한 차임 상당 손해배상을 청구할 수 없다."}],"선지":[{"번호":1,"판정":"-","설명":"ㄱ은 틀린 보기다. 합의해지로 전차권이 소멸하지 않는다."},{"번호":2,"판정":"-","설명":"ㄷ은 옳은 보기라서 틀린 것을 고르는 문항의 답이 될 수 없다."},{"번호":3,"판정":"-","설명":"ㄱ, ㄴ이 틀린 보기이고 ㄷ은 옳다."},{"번호":4,"판정":"-","설명":"ㄷ이 옳은 보기라서 ㄴ, ㄷ을 묶을 수 없다."},{"번호":5,"판정":"-","설명":"ㄷ이 옳아서 3개 모두 틀릴 수 없다."}],"보기판정":[{"기호":"ㄱ","판정":"틀림","설명":"임대인의 동의를 얻은 전대에서는 합의로 임대차를 종료해도 전차권이 소멸하지 않는다(제631조)."},{"기호":"ㄴ","판정":"틀림","설명":"임대차가 존속하는 동안 임대인은 차임 상당의 손해를 입었다고 볼 수 없다(판례)."},{"기호":"ㄷ","판정":"옳음","설명":"임대인으로부터 매수한 부속물도 전차인이 전대차 종료 시 매수를 청구할 수 있다(제647조 제1항·제2항)."}],"개념":[{"종류":"비교","제목":"동의 있는 전대와 동의 없는 전대","왼쪽":{"이름":"임대인의 동의 있는 전대","항목":["전차인은 임대인에게 직접 의무 부담. 전대인에게 한 차임 지급으로 임대인에게 대항 불가(제630조 제1항)","임대인의 임차인에 대한 권리행사에 영향 없음(제630조 제2항)","임대인과 임차인이 합의해지해도 전차권 소멸 안 함(제631조)","임대차 해지통고 시 임대인은 전차인에게 통지해야 대항(제638조)","전차인도 부속물매수청구 가능(제647조)","임차인의 채무불이행으로 해지되면 전차권도 소멸(판례)"]},"오른쪽":{"이름":"동의 없는 전대","항목":["임차인이 임대인의 동의 없이 전대하지 못함(제629조 제1항)","임대인은 계약을 해지할 수 있음(제629조 제2항)","임대인과 전차인 사이에는 계약관계가 없음","임대차 존속 중 불법점유를 이유로 한 차임 상당 손해배상 불가(판례)"]}},{"종류":"표","제목":"전차인의 보호 규정","머리":["규정","내용","근거"],"행":[["전차권 존속","합의해지로도 소멸하지 않음","제631조"],["해지통고 통지","임대인이 전차인에게 사유를 통지해야 대항, 통지 후 6월(토지·건물) 경과 시 해지 효력","제638조"],["부속물매수청구","임대인 동의를 얻은 부속물, 임대인으로부터 매수한 부속물","제647조"],["강행규정","제631조·제638조·제647조에 위반한 전차인에게 불리한 약정 무효","제652조"]]}],"함정":"ㄱ은 합의해지로 임대차가 없어지면 전대차도 따라서 없어진다고 추측하기 쉽다. 제631조가 이를 막는다. ㄴ은 임대차가 끝난 뒤의 인도 지연과 구별해야 한다. 임대차가 존속하는 동안은 임대인이 차임을 받을 수 있어 손해가 없다."},"36회-1차-075":{"한줄":"임차인은 1년의 약정기간 만료를 주장해 보증금 반환을 청구할 수 있고, 묵시적 갱신 후에는 언제든 해지를 통지할 수 있으며, 갱신요구는 거절사유가 없으면 도달 시 갱신 효력이 생겨 ㄱ, ㄴ, ㄷ 모두 옳다.","근거":[{"법령":"주택임대차보호법","조문":"제4조제1항","원문":"제4조(임대차기간 등) ① 기간을 정하지 아니하거나 2년 미만으로 정한 임대차는 그 기간을 2년으로 본다. 다만, 임차인은 2년 미만으로 정한 기간이 유효함을 주장할 수 있다."},{"법령":"주택임대차보호법","조문":"제6조제1항·제2항","원문":"제6조(계약의 갱신) ① 임대인이 임대차기간이 끝나기 6개월 전부터 2개월 전까지의 기간에 임차인에게 갱신거절(更新拒絶)의 통지를 하지 아니하거나 계약조건을 변경하지 아니하면 갱신하지 아니한다는 뜻의 통지를 하지 아니한 경우에는 그 기간이 끝난 때에 전 임대차와 동일한 조건으로 다시 임대차한 것으로 본다. 임차인이 임대차기간이 끝나기 2개월 전까지 통지하지 아니한 경우에도 또한 같다. <개정 2020.6.9> ② 제1항의 경우 임대차의 존속기간은 2년으로 본다. <개정 2009.5.8>"},{"법령":"주택임대차보호법","조문":"제6조의2","원문":"제6조의2(묵시적 갱신의 경우 계약의 해지) ① 제6조제1항에 따라 계약이 갱신된 경우 같은 조 제2항에도 불구하고 임차인은 언제든지 임대인에게 계약해지(契約解止)를 통지할 수 있다. <개정 2009.5.8> ② 제1항에 따른 해지는 임대인이 그 통지를 받은 날부터 3개월이 지나면 그 효력이 발생한다."},{"법령":"주택임대차보호법","조문":"제6조의3제1항·제2항·제3항","원문":"제6조의3(계약갱신 요구 등) ① 제6조에도 불구하고 임대인은 임차인이 제6조제1항 전단의 기간 이내에 계약갱신을 요구할 경우 정당한 사유 없이 거절하지 못한다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 그러하지 아니하다. 1. 임차인이 2기의 차임액에 해당하는 금액에 이르도록 차임을 연체한 사실이 있는 경우 2. 임차인이 거짓이나 그 밖의 부정한 방법으로 임차한 경우 3. 서로 합의하여 임대인이 임차인에게 상당한 보상을 제공한 경우 4. 임차인이 임대인의 동의 없이 목적 주택의 전부 또는 일부를 전대(轉貸)한 경우 5. 임차인이 임차한 주택의 전부 또는 일부를 고의나 중대한 과실로 파손한 경우 6. 임차한 주택의 전부 또는 일부가 멸실되어 임대차의 목적을 달성하지 못할 경우 7. 임대인이 다음 각 목의 어느 하나에 해당하는 사유로 목적 주택의 전부 또는 대부분을 철거하거나 재건축하기 위하여 목적 주택의 점유를 회복할 필요가 있는 경우 가. 임대차계약 체결 당시 공사시기 및 소요기간 등을 포함한 철거 또는 재건축 계획을 임차인에게 구체적으로 고지하고 그 계획에 따르는 경우 나. 건물이 노후ㆍ훼손 또는 일부 멸실되는 등 안전사고의 우려가 있는 경우 다. 다른 법령에 따라 철거 또는 재건축이 이루어지는 경우 8. 임대인(임대인의 직계존속ㆍ직계비속을 포함한다)이 목적 주택에 실제 거주하려는 경우 9. 그 밖에 임차인이 임차인으로서의 의무를 현저히 위반하거나 임대차를 계속하기 어려운 중대한 사유가 있는 경우 ② 임차인은 제1항에 따른 계약갱신요구권을 1회에 한하여 행사할 수 있다. 이 경우 갱신되는 임대차의 존속기간은 2년으로 본다. ③ 갱신되는 임대차는 전 임대차와 동일한 조건으로 다시 계약된 것으로 본다. 다만, 차임과 보증금은 제7조의 범위에서 증감할 수 있다."},{"판례":"대법원 2024. 1. 11. 선고 2023다258672 판결","요지":"임차인이 계약갱신을 요구하면 임대인에게 갱신거절 사유가 없는 한 갱신요구가 임대인에게 도달한 때 갱신의 효력이 생긴다. 갱신된 임대차는 임차인이 언제든 해지를 통지할 수 있고 통지 후 3개월이 지나면 효력이 발생한다."}],"선지":[{"번호":1,"판정":"-","설명":"ㄱ만으로는 부족하다. ㄴ, ㄷ도 옳다."},{"번호":2,"판정":"-","설명":"ㄷ만으로는 부족하다. ㄱ, ㄴ도 옳다."},{"번호":3,"판정":"-","설명":"ㄱ, ㄴ만으로는 부족하다. ㄷ도 옳다."},{"번호":4,"판정":"-","설명":"ㄱ, ㄷ도 옳으므로 ㄴ, ㄷ만 고르면 모자란다."},{"번호":5,"판정":"-","설명":"ㄱ, ㄴ, ㄷ 모두 옳은 보기다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"임차인은 2년 미만으로 정한 기간이 유효함을 주장할 수 있다(제4조 제1항 단서)."},{"기호":"ㄴ","판정":"옳음","설명":"묵시적 갱신의 존속기간은 2년이며 임차인은 언제든 해지를 통지할 수 있다(제6조 제2항, 제6조의2)."},{"기호":"ㄷ","판정":"옳음","설명":"갱신요구가 도달하면 거절사유가 없는 한 그때 갱신의 효력이 생긴다(2023다258672)."}],"개념":[{"종류":"계산","제목":"사안의 기간 계산","단계":[{"설명":"약정 1년은 2년으로 본다(임차인은 1년의 유효를 주장 가능)","식":"제4조 제1항","값":"법정 존속기간 2년, 만료일 2025. 5. 31."},{"설명":"갱신요구 가능 기간: 만료 6개월 전부터 2개월 전까지","식":"제6조 제1항, 제6조의3 제1항","값":"약 2024. 11. 30. ~ 2025. 3. 31."},{"설명":"2025. 2. 15. 도달한 갱신요구","식":"위 기간에 포함","값":"적법한 갱신요구, 거절사유 없으면 도달 시 갱신 효력"}]},{"종류":"표","제목":"묵시적 갱신과 계약갱신요구권","머리":["구분","묵시적 갱신","계약갱신요구권"],"행":[["근거","제6조","제6조의3"],["성립","임대인이 6개월~2개월 전 통지를 하지 않고, 임차인이 2개월 전까지 통지하지 않음","임차인이 6개월~2개월 전에 갱신요구, 임대인은 거절사유 없으면 거절 불가"],["횟수","제한 없음","1회"],["갱신 후 기간","2년","2년"],["갱신 후 조건","전 임대차와 같은 조건","전 임대차와 같은 조건. 차임·보증금은 제7조 범위(20분의 1)에서 증감"],["임차인 해지","언제든 통지, 3개월 후 효력(제6조의2)","제6조의2 준용(제6조의3 제4항)"]]},{"종류":"흐름","제목":"주택임대차 만료 전 일정","단계":[{"이름":"만료 6개월 전","설명":"임차인 갱신요구·임대인 갱신거절 통지 가능 시작"},{"이름":"만료 2개월 전","설명":"갱신요구·갱신거절 통지의 마감. 임차인이 통지하지 않으면 묵시적 갱신 성립"},{"이름":"만료","설명":"갱신요구가 있으면 거절사유가 없는 한 동일 조건으로 2년 갱신"},{"이름":"갱신 후 해지","설명":"임차인이 통지하면 3개월 후 효력"}]}],"함정":"ㄱ에서 「2년으로 본다」를 임차인에게도 강제하는 것으로 읽으면 틀린다. 2년 간주는 임차인이 1년 기간의 유효를 주장하지 않을 때의 이야기이고, 주장하면 1년 만료로 보증금 반환을 청구할 수 있다. ㄷ을 임대인의 승낙이 있어야 갱신된다고 보는 것도 오답의 원인이다."},"36회-1차-080":{"한줄":"환산보증금 7억원이 부산의 기준 6억9천만원을 넘어 이 법의 적용범위 밖이므로 제2조 제3항이 열거한 규정, 곧 차임연체 해지권(제10조의8)만 적용된다.","근거":[{"법령":"상가건물 임대차보호법","조문":"제2조제1항·제3항","원문":"제2조(적용범위) ① 이 법은 상가건물(제3조제1항에 따른 사업자등록의 대상이 되는 건물을 말한다)의 임대차(임대차 목적물의 주된 부분을 영업용으로 사용하는 경우를 포함한다)에 대하여 적용한다. 다만, 제14조의2에 따른 상가건물임대차위원회의 심의를 거쳐 대통령령으로 정하는 보증금액을 초과하는 임대차에 대하여는 그러하지 아니하다. <개정 2020.7.31> ③ 제1항 단서에도 불구하고 제3조, 제10조제1항, 제2항, 제3항 본문, 제10조의2부터 제10조의9까지의 규정, 제11조의2 및 제19조는 제1항 단서에 따른 보증금액을 초과하는 임대차에 대하여도 적용한다. <신설 2013.8.13, 2015.5.13, 2020.9.29, 2022.1.4>"},{"법령":"상가건물 임대차보호법 시행령","조문":"제2조제1항·제3항","원문":"제2조(적용범위) ①「상가건물 임대차보호법」(이하 \"법\"이라 한다) 제2조제1항 단서에서 \"대통령령으로 정하는 보증금액\"이란 다음 각 호의 구분에 의한 금액을 말한다. <개정 2008.8.21, 2010.7.21, 2013.12.30, 2018.1.26, 2019.4.2> 1. 서울특별시 : 9억원 2. 「수도권정비계획법」에 따른 과밀억제권역(서울특별시는 제외한다) 및 부산광역시: 6억9천만원 3. 광역시(「수도권정비계획법」에 따른 과밀억제권역에 포함된 지역과 군지역, 부산광역시는 제외한다), 세종특별자치시, 파주시, 화성시, 안산시, 용인시, 김포시 및 광주시: 5억4천만원 4. 그 밖의 지역 : 3억7천만원 ③법 제2조제2항에서 \"대통령령으로 정하는 비율\"이라 함은 1분의 100을 말한다. <개정 2010.7.21>"},{"법령":"상가건물 임대차보호법","조문":"제10조의8","원문":"제10조의8(차임연체와 해지) 임차인의 차임연체액이 3기의 차임액에 달하는 때에는 임대인은 계약을 해지할 수 있다."},{"법령":"상가건물 임대차보호법","조문":"제5조제2항","원문":"제5조(보증금의 회수) ② 제3조제1항의 대항요건을 갖추고 관할 세무서장으로부터 임대차계약서상의 확정일자를 받은 임차인은 「민사집행법」에 따른 경매 또는 「국세징수법」에 따른 공매 시 임차건물(임대인 소유의 대지를 포함한다)의 환가대금에서 후순위권리자나 그 밖의 채권자보다 우선하여 보증금을 변제받을 권리가 있다."},{"법령":"상가건물 임대차보호법","조문":"제6조제1항","원문":"제6조(임차권등기명령) ① 임대차가 종료된 후 보증금이 반환되지 아니한 경우 임차인은 임차건물의 소재지를 관할하는 지방법원, 지방법원지원 또는 시ㆍ군법원에 임차권등기명령을 신청할 수 있다. <개정 2013.8.13>"}],"선지":[{"번호":1,"판정":"-","설명":"ㄱ만으로는 틀리다. 우선변제권(제5조 제2항)은 제2조 제3항에 없어 적용되지 않는다."},{"번호":2,"판정":"-","설명":"ㄷ만 적용된다. 제10조의8은 제2조 제3항이 적용한다고 열거한 규정이다."},{"번호":3,"판정":"-","설명":"ㄱ, ㄴ 모두 제2조 제3항에 없어 적용되지 않는다."},{"번호":4,"판정":"-","설명":"ㄴ(임차권등기명령, 제6조)은 적용되지 않는다."},{"번호":5,"판정":"-","설명":"ㄱ, ㄴ은 적용되지 않으므로 3개 모두 해당할 수 없다."}],"보기판정":[{"기호":"ㄱ","판정":"틀림","설명":"제5조 제2항의 우선변제권은 제2조 제3항에 열거되지 않아 적용되지 않는다."},{"기호":"ㄴ","판정":"틀림","설명":"제6조의 임차권등기명령은 제2조 제3항에 열거되지 않아 적용되지 않는다."},{"기호":"ㄷ","판정":"옳음","설명":"제10조의8은 제2조 제3항에 따라 기준을 초과한 임대차에도 적용된다."}],"개념":[{"종류":"계산","제목":"환산보증금 계산","단계":[{"설명":"환산보증금 = 보증금 + 월 차임 × 100","식":"시행령 제2조 제2항·제3항","값":"보증금 6억원 + 100만원 × 100"},{"설명":"월 차임 환산액","식":"100만원 × 100","값":"1억원"},{"설명":"환산보증금","식":"6억원 + 1억원","값":"7억원"},{"설명":"부산광역시 기준","식":"시행령 제2조 제1항 제2호","값":"6억9천만원"},{"설명":"비교","식":"7억원 > 6억9천만원","값":"법 제2조 제1항 단서에 따라 원칙적 적용 제외, 제2조 제3항의 규정만 적용"}]},{"종류":"표","제목":"지역별 환산보증금 기준(시행령 제2조 제1항)","머리":["지역","기준 금액"],"행":[["서울특별시","9억원"],["과밀억제권역(서울 제외) 및 부산광역시","6억9천만원"],["광역시(과밀억제권역·군지역·부산 제외), 세종, 파주, 화성, 안산, 용인, 김포, 광주","5억4천만원"],["그 밖의 지역","3억7천만원"]]},{"종류":"표","제목":"기준 초과 임대차에도 적용되는 규정(제2조 제3항)","머리":["규정","내용"],"행":[["제3조","대항력"],["제10조 제1항·제2항·제3항 본문","계약갱신요구권(10년 한도)"],["제10조의2","계약갱신 시 차임·보증금 증감청구 특례"],["제10조의3~제10조의7","권리금 정의, 회수기회 보호, 적용 제외, 표준권리금계약서, 평가기준 고시"],["제10조의8","차임연체 3기 시 임대인의 해지권"],["제10조의9","계약갱신요구 등에 관한 임시 특례"],["제11조의2","폐업으로 인한 임차인의 해지권"],["제19조","표준계약서"]]}],"함정":"사업자등록과 확정일자를 마쳤다는 사실에 끌려 ㄱ을 고르기 쉽다. 환산보증금이 기준을 넘으면 우선변제권(제5조)과 임차권등기명령(제6조)은 적용되지 않는다. 대항력(제3조)과 갱신요구, 권리금, 차임연체 해지는 기준을 넘어도 적용된다."},"36회-1차-077":{"한줄":"물품대금채무가 변제로 소멸해 대여금반환채무만 남았으므로 가등기담보법이 적용되고(ㄱ), 본등기 절차비용은 청산금에서 공제하지 않으며(ㄴ), 선의 제3자 취득으로 무효 본등기는 소급해 유효해지므로 ㄷ은 틀리다.","근거":[{"법령":"가등기담보 등에 관한 법률","조문":"제1조","원문":"제1조(목적) 이 법은 차용물(借用物)의 반환에 관하여 차주(借主)가 차용물을 갈음하여 다른 재산권을 이전할 것을 예약할 때 그 재산의 예약 당시 가액(價額)이 차용액(借用額)과 이에 붙인 이자를 합산한 액수를 초과하는 경우에 이에 따른 담보계약(擔保契約)과 그 담보의 목적으로 마친 가등기(假登記) 또는 소유권이전등기(所有權移轉登記)의 효력을 정함을 목적으로 한다."},{"법령":"가등기담보 등에 관한 법률","조문":"제3조제1항·제2항","원문":"제3조(담보권 실행의 통지와 청산기간) ① 채권자가 담보계약에 따른 담보권을 실행하여 그 담보목적부동산의 소유권을 취득하기 위하여는 그 채권(債權)의 변제기(辨濟期) 후에 제4조의 청산금(淸算金)의 평가액을 채무자등에게 통지하고, 그 통지가 채무자등에게 도달한 날부터 2개월(이하 \"청산기간\"이라 한다)이 지나야 한다. 이 경우 청산금이 없다고 인정되는 경우에는 그 뜻을 통지하여야 한다. ② 제1항에 따른 통지에는 통지 당시의 담보목적부동산의 평가액과 「민법」 제360조에 규정된 채권액을 밝혀야 한다. 이 경우 부동산이 둘 이상인 경우에는 각 부동산의 소유권이전에 의하여 소멸시키려는 채권과 그 비용을 밝혀야 한다."},{"법령":"가등기담보 등에 관한 법률","조문":"제4조제1항·제2항","원문":"제4조(청산금의 지급과 소유권의 취득) ① 채권자는 제3조제1항에 따른 통지 당시의 담보목적부동산의 가액에서 그 채권액을 뺀 금액(이하 \"청산금\"이라 한다)을 채무자등에게 지급하여야 한다. 이 경우 담보목적부동산에 선순위담보권(先順位擔保權) 등의 권리가 있을 때에는 그 채권액을 계산할 때에 선순위담보 등에 의하여 담보된 채권액을 포함한다. ② 채권자는 담보목적부동산에 관하여 이미 소유권이전등기를 마친 경우에는 청산기간이 지난 후 청산금을 채무자등에게 지급한 때에 담보목적부동산의 소유권을 취득하며, 담보가등기를 마친 경우에는 청산기간이 지나야 그 가등기에 따른 본등기(本登記)를 청구할 수 있다."},{"법령":"가등기담보 등에 관한 법률","조문":"제11조","원문":"제11조(채무자등의 말소청구권) 채무자등은 청산금채권을 변제받을 때까지 그 채무액(반환할 때까지의 이자와 손해금을 포함한다)을 채권자에게 지급하고 그 채권담보의 목적으로 마친 소유권이전등기의 말소를 청구할 수 있다. 다만, 그 채무의 변제기가 지난 때부터 10년이 지나거나 선의의 제삼자가 소유권을 취득한 경우에는 그러하지 아니하다."},{"판례":"대법원 2004. 4. 27. 선고 2003다29968 판결","요지":"차용금반환채무와 다른 원인의 채무를 함께 담보하려고 마친 가등기라도 후자의 채무가 변제 등으로 소멸하고 차용금반환채무의 전부 또는 일부만 남으면 그 가등기담보에 가등기담보법이 적용된다."},{"판례":"대법원 판례(청산금 산정)","요지":"청산금은 통지 당시 목적물 가액에서 채권액을 뺀 금액이고, 본등기를 위해 지출한 절차비용은 이를 청산금에서 공제하지 않는다."},{"판례":"대법원 판례(청산절차 없는 본등기)","요지":"청산절차를 거치지 않은 본등기는 무효이지만 선의의 제3자가 소유권을 취득하면 채무자는 말소를 청구할 수 없고, 그 본등기는 본등기를 한 때로 소급해 확정적으로 유효해진다."}],"선지":[{"번호":1,"판정":"-","설명":"ㄱ은 옳지만 ㄴ도 옳다."},{"번호":2,"판정":"-","설명":"ㄷ은 틀린 보기다. 제3자 취득 시점부터가 아니라 본등기 시점으로 소급해 유효하다."},{"번호":3,"판정":"-","설명":"ㄱ, ㄴ이 옳은 조합이다."},{"번호":4,"판정":"-","설명":"ㄷ이 틀려 ㄴ, ㄷ은 성립하지 않는다."},{"번호":5,"판정":"-","설명":"ㄷ이 틀려 3개 모두 옳을 수 없다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"물품대금채무가 변제로 소멸해 차용금반환채무만 남았고, 가액 2억원이 차용액과 이자의 합계를 넘으므로 법이 적용된다."},{"기호":"ㄴ","판정":"옳음","설명":"본등기 절차비용은 청산금에서 공제하지 않는다(판례)."},{"기호":"ㄷ","판정":"틀림","설명":"선의 제3자의 취득으로 본등기는 본등기를 한 시점으로 소급해 유효해진다. 제3자 취득 시점부터가 아니다(판례)."}],"개념":[{"종류":"계산","제목":"가등기담보법 적용 여부","단계":[{"설명":"이자 = 원금 × 이율 × 기간","식":"1억원 × 5% × 1년","값":"500만원"},{"설명":"차용액 + 이자","식":"1억원 + 500만원","값":"1억 500만원"},{"설명":"예약 당시 가액과 비교","식":"2억원 > 1억 500만원","값":"제1조 요건 충족"},{"설명":"물품대금채무 변제 후 남은 채무","식":"대여금반환채무만 존속","값":"가등기담보법 적용(2003다29968)"}]},{"종류":"흐름","제목":"담보권 실행(가등기담보법)","단계":[{"이름":"변제기 도래","설명":"채무를 이행하지 않음"},{"이름":"청산금 평가액 통지","설명":"변제기 후, 채무자 등에게 통지. 통지에 통지 당시 평가액과 채권액 명시(제3조)"},{"이름":"청산기간","설명":"통지가 도달한 날부터 2개월(제3조 제1항)"},{"이름":"청산금 지급","설명":"목적물 가액 - 채권액. 청산금 지급과 본등기·인도는 동시이행(제4조 제1항·제3항)"},{"이름":"본등기·소유권 취득","설명":"가등기는 청산기간이 지나야 본등기 청구, 이미 이전등기를 마친 경우 청산기간 후 청산금을 지급한 때 소유권 취득(제4조 제2항)"}]},{"종류":"표","제목":"채무자 등의 보호","머리":["내용","근거"],"행":[["불리한 특약은 무효(청산기간 후 제3자 권리를 침해하지 않는 특약은 예외)","제4조 제4항"],["청산금채권을 변제받을 때까지 채무액을 지급하고 소유권이전등기 말소 청구 가능. 변제기 후 10년 경과 또는 선의 제3자 소유권 취득 시 불가","제11조"],["담보가등기권리자는 선택에 따라 담보권 실행 또는 경매 청구, 경매에서는 저당권으로 봄","제12조 제1항"]]}],"함정":"ㄱ에서 담보채권 총액이 시가 2억원과 같아서 법 적용이 안 된다고 계산한 경우가 많다. 물품대금채무가 변제된 뒤에는 차용액과 이자만 비교한다. ㄷ은 「2025. 8. 1.부터」라는 시점 표현만 어긋났다. 유효해지는 시점은 제3자 취득 시가 아니라 본등기 시로 소급한다."},"36회-1차-076":{"한줄":"전유부분의 담보책임 존속기간은 구분소유자에게 인도한 날부터 기산하고 사용검사일은 공용부분의 기산일이므로 2번이 틀리다.","근거":[{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제9조의2제2항","원문":"제9조의2(담보책임의 존속기간) ② 제1항의 기간은 다음 각 호의 날부터 기산한다. <개정 2016.1.19> 1. 전유부분: 구분소유자에게 인도한 날 2. 공용부분: 「주택법」 제49조에 따른 사용검사일(집합건물 전부에 대하여 임시 사용승인을 받은 경우에는 그 임시 사용승인일을 말하고, 「주택법」 제49조제1항 단서에 따라 분할 사용검사나 동별 사용검사를 받은 경우에는 분할 사용검사일 또는 동별 사용검사일을 말한다) 또는 「건축법」 제22조에 따른 사용승인일"},{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제3조제1항","원문":"제3조(공용부분) ① 여러 개의 전유부분으로 통하는 복도, 계단, 그 밖에 구조상 구분소유자 전원 또는 일부의 공용(共用)에 제공되는 건물부분은 구분소유권의 목적으로 할 수 없다."},{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제17조","원문":"제17조(공용부분의 부담ㆍ수익) 각 공유자는 규약에 달리 정한 바가 없으면 그 지분의 비율에 따라 공용부분의 관리비용과 그 밖의 의무를 부담하며 공용부분에서 생기는 이익을 취득한다."},{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제24조제1항","원문":"제24조(관리인의 선임 등) ① 구분소유자가 10인 이상일 때에는 관리단을 대표하고 관리단의 사무를 집행할 관리인을 선임하여야 한다. <개정 2012.12.18>"},{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제20조제2항","원문":"제20조(전유부분과 대지사용권의 일체성) ② 구분소유자는 그가 가지는 전유부분과 분리하여 대지사용권을 처분할 수 없다. 다만, 규약으로써 달리 정한 경우에는 그러하지 아니하다."},{"판례":"대법원 판례(구조상 공용부분)","요지":"구조상 공용부분은 독립한 소유권의 객체가 아니므로 취득시효로 소유권을 취득할 수 없다."},{"판례":"대법원 판례(관리비 청구)","요지":"관리단은 관리비 징수에 관한 유효한 규약이 없어도 공용부분 관리비를 지분 비율에 따라 부담의무자인 구분소유자에게 청구할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"구조상 공용부분은 구분소유권의 목적이 될 수 없고(제3조 제1항) 취득시효 대상도 아니다."},{"번호":2,"판정":"틀림","설명":"전유부분은 구분소유자에게 인도한 날, 공용부분은 사용검사일(사용승인일)부터 기산한다(제9조의2 제2항)."},{"번호":3,"판정":"옳음","설명":"규약에 달리 정한 바가 없으면 지분 비율로 공용부분 관리비용을 부담한다(제17조). 관리단은 이를 청구할 수 있다(판례)."},{"번호":4,"판정":"옳음","설명":"구분소유자가 10인 이상이면 관리인을 선임해야 한다(제24조 제1항)."},{"번호":5,"판정":"옳음","설명":"규약으로 달리 정하지 않는 한 전유부분과 분리하여 대지사용권을 처분할 수 없다(제20조 제2항)."}],"개념":[{"종류":"표","제목":"담보책임 존속기간(제9조의2)","머리":["구분","내용"],"행":[["주요구조부·지반공사의 하자","10년"],["그 밖의 하자","하자의 중대성·내구연한 등을 고려해 5년의 범위에서 대통령령으로 정하는 기간"],["전유부분 기산일","구분소유자에게 인도한 날"],["공용부분 기산일","사용검사일(임시 사용승인일·분할·동별 사용검사일 포함) 또는 건축법상 사용승인일"],["멸실·훼손된 경우","멸실·훼손된 날부터 1년 내 행사"]]},{"종류":"표","제목":"관리인과 관리단","머리":["내용","근거"],"행":[["구분소유자 10인 이상이면 관리인 선임 의무","제24조 제1항"],["관리인은 구분소유자일 필요 없고 임기는 2년 범위에서 규약으로 정함","제24조 제2항"],["관리단집회의 결의로 선임·해임(규약으로 관리위원회 결의로 정할 수 있음)","제24조 제3항"],["부정행위 등이 있으면 각 구분소유자가 법원에 해임 청구","제24조 제5항"],["전유부분 50개 이상 건물의 관리인은 소관청에 신고(일부 제외)","제24조 제6항"]]}],"함정":"2번은 사용검사일 기준이 전체 담보책임에 통일되어 있다고 오해하게 만든다. 사용검사일은 공용부분, 인도일은 전유부분이다. 3번은 규약이 없다는 이유만으로 청구가 안 된다고 보는 오답이 많은데, 판례는 지분 비율에 따른 청구를 인정한다."},"36회-1차-079":{"한줄":"2자간 등기명의신탁은 약정과 등기가 모두 무효여서 소유권이 甲에게 그대로 있으므로 부당이득을 원인으로 한 이전등기가 아니라 소유권에 기한 말소(또는 진정명의회복)를 청구해야 한다.","근거":[{"법령":"부동산 실권리자명의 등기에 관한 법률","조문":"제4조","원문":"제4조(명의신탁약정의 효력) ① 명의신탁약정은 무효로 한다. ② 명의신탁약정에 따른 등기로 이루어진 부동산에 관한 물권변동은 무효로 한다. 다만, 부동산에 관한 물권을 취득하기 위한 계약에서 명의수탁자가 어느 한쪽 당사자가 되고 상대방 당사자는 명의신탁약정이 있다는 사실을 알지 못한 경우에는 그러하지 아니하다. ③ 제1항 및 제2항의 무효는 제3자에게 대항하지 못한다."},{"법령":"부동산 실권리자명의 등기에 관한 법률","조문":"제2조","원문":"제2조(정의) 이 법에서 사용하는 용어의 뜻은 다음과 같다. 1. \"명의신탁약정\"(名義信託約定)이란 부동산에 관한 소유권이나 그 밖의 물권(이하 \"부동산에 관한 물권\"이라 한다)을 보유한 자 또는 사실상 취득하거나 취득하려고 하는 자[이하 \"실권리자\"(實權利者)라 한다]가 타인과의 사이에서 대내적으로는 실권리자가 부동산에 관한 물권을 보유하거나 보유하기로 하고 그에 관한 등기(가등기를 포함한다. 이하 같다)는 그 타인의 명의로 하기로 하는 약정[위임ㆍ위탁매매의 형식에 의하거나 추인(追認)에 의한 경우를 포함한다]을 말한다. 다만, 다음 각 목의 경우는 제외한다. 가. 채무의 변제를 담보하기 위하여 채권자가 부동산에 관한 물권을 이전(移轉)받거나 가등기하는 경우 나. 부동산의 위치와 면적을 특정하여 2인 이상이 구분소유하기로 하는 약정을 하고 그 구분소유자의 공유로 등기하는 경우 다. 「신탁법」 또는 「자본시장과 금융투자업에 관한 법률」에 따른 신탁재산인 사실을 등기한 경우 2. \"명의신탁자\"(名義信託者)란 명의신탁약정에 따라 자신의 부동산에 관한 물권을 타인의 명의로 등기하게 하는 실권리자를 말한다. 3. \"명의수탁자\"(名義受託者)란 명의신탁약정에 따라 실권리자의 부동산에 관한 물권을 자신의 명의로 등기하는 자를 말한다. 4. \"실명등기\"(實名登記)란 법률 제4944호 부동산실권리자명의등기에관한법률 시행 전에 명의신탁약정에 따라 명의수탁자의 명의로 등기된 부동산에 관한 물권을 법률 제4944호 부동산실권리자명의등기에관한법률 시행일 이후 명의신탁자의 명의로 등기하는 것을 말한다."},{"법령":"부동산 실권리자명의 등기에 관한 법률","조문":"제8조","원문":"제8조(종중, 배우자 및 종교단체에 대한 특례) 다음 각 호의 어느 하나에 해당하는 경우로서 조세 포탈, 강제집행의 면탈(免脫) 또는 법령상 제한의 회피를 목적으로 하지 아니하는 경우에는 제4조부터 제7조까지 및 제12조제1항부터 제3항까지를 적용하지 아니한다. <개정 2013.7.12> 1. 종중(宗中)이 보유한 부동산에 관한 물권을 종중(종중과 그 대표자를 같이 표시하여 등기한 경우를 포함한다) 외의 자의 명의로 등기한 경우 2. 배우자 명의로 부동산에 관한 물권을 등기한 경우 3. 종교단체의 명의로 그 산하 조직이 보유한 부동산에 관한 물권을 등기한 경우"},{"판례":"대법원 판례(2자간 등기명의신탁)","요지":"명의신탁약정과 그에 따른 등기는 무효이므로 소유권은 신탁자에게 있다. 신탁자는 소유권에 기한 말소등기 또는 진정명의회복을 원인으로 한 이전등기를 청구할 수 있다. 수탁자가 제3자에게 처분하면 제3자는 소유권을 취득하고 신탁자는 소유권을 잃으며, 수탁자의 처분은 신탁자에 대한 불법행위가 될 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"소유권이 甲에게 있으므로 乙에게 소유권을 이전받을 부당이득 청구권이 생기지 않는다. 말소등기 또는 진정명의회복 이전등기를 청구한다(제4조 제1항·제2항)."},{"번호":2,"판정":"틀림","설명":"丙에게 양도한 때 제4조 제3항에 따라 丙이 소유권을 취득하고 甲은 소유권을 잃는다. 乙이 다시 취득해도 甲은 소유자가 아니다."},{"번호":3,"판정":"틀림","설명":"丁은 제4조 제3항의 제3자로서 선의·악의를 가리지 않고 소유권을 취득한다. 甲은 丁에게 반환을 청구할 수 없다."},{"번호":4,"판정":"틀림","설명":"乙의 처분으로 甲이 소유권을 잃게 되므로 불법행위가 성립할 수 있다(판례)."},{"번호":5,"판정":"틀림","설명":"매수 후 매도인 명의를 유지하기로 한 약정도 실권리자가 등기는 타인 명의로 하기로 하는 명의신탁약정(제2조 제1호)에 해당할 수 있다."}],"개념":[{"종류":"표","제목":"명의신탁 유형별 효력","머리":["유형","약정","등기·물권변동","소유권 귀속과 청구"],"행":[["2자간 등기명의신탁","무효(제4조 제1항)","무효(제4조 제2항)","신탁자 소유. 말소 또는 진정명의회복 청구. 제3자 보호(제4조 제3항)"],["3자간 등기명의신탁(중간생략형)","무효","무효","매도인 소유. 신탁자는 매도인에게 이전청구권을 갖고 매도인을 대위해 수탁자 명의 말소 청구"],["계약명의신탁(매도인 선의)","무효","유효(제4조 제2항 단서)","수탁자 소유. 신탁자는 수탁자에게 부당이득 반환 청구"],["계약명의신탁(매도인 악의)","무효","무효","매도인 소유"],["제3자 취득","-","-","무효로 대항하지 못함(제4조 제3항)"]]},{"종류":"표","제목":"명의신탁에 해당하지 않거나 특례가 있는 경우","머리":["경우","내용","근거"],"행":[["채무 담보 목적의 이전·가등기","명의신탁약정에서 제외","제2조 제1호 가목"],["구분소유적 공유","위치·면적을 특정한 구분소유 약정 + 공유 등기는 제외","제2조 제1호 나목"],["신탁법상 신탁재산 등기","제외","제2조 제1호 다목"],["종중·배우자·종교단체 특례","조세포탈·강제집행 면탈·법령상 제한 회피 목적이 아니면 제4조 등을 적용하지 않음","제8조"]]}],"함정":"1번이 틀린 문장처럼 읽혀 4번이나 5번을 고르기 쉽다. 신탁자는 이미 소유자라서 「이전받을」 청구가 아니라 소유권에 기한 말소를 청구한다. 5번은 대외관계에서 등기를 타인 명의로 두기로 하면 매도인 명의 유지형도 명의신탁약정이 될 수 있다는 점이 핵심이다."},"36회-2차-001":{"한줄":"소속공인중개사에는 개업공인중개사인 법인의 사원·임원으로서 공인중개사인 자도 포함되므로, 이들을 제외한다는 5번이 틀렸다.","근거":[{"법령":"공인중개사법","조문":"제2조제1호·제2호·제3호·제4호","원문":"1. \"중개\"라 함은 제3조에 따른 중개대상물에 대하여 거래당사자간의 매매ㆍ교환ㆍ임대차 그 밖의 권리의 득실변경에 관한 행위를 알선하는 것을 말한다.\n2. \"공인중개사\"라 함은 이 법에 의한 공인중개사자격을 취득한 자를 말한다.\n3. \"중개업\"이라 함은 다른 사람의 의뢰에 의하여 일정한 보수를 받고 중개를 업으로 행하는 것을 말한다.\n4. \"개업공인중개사\"라 함은 이 법에 의하여 중개사무소의 개설등록을 한 자를 말한다."},{"법령":"공인중개사법","조문":"제2조제5호","원문":"5. \"소속공인중개사\"라 함은 개업공인중개사에 소속된 공인중개사(개업공인중개사인 법인의 사원 또는 임원으로서 공인중개사인 자를 포함한다)로서 중개업무를 수행하거나 개업공인중개사의 중개업무를 보조하는 자를 말한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"중개는 제3조의 중개대상물에 대한 매매·교환·임대차 등 권리 득실변경의 알선이다(법 제2조제1호)."},{"번호":2,"판정":"옳음","설명":"이 법에 따라 자격을 취득한 사람이면 개설등록을 했는지와 상관없이 공인중개사다(법 제2조제2호)."},{"번호":3,"판정":"옳음","설명":"타인의 의뢰, 일정한 보수, 업(業) 세 요소를 모두 갖춘 중개가 중개업이다(법 제2조제3호)."},{"번호":4,"판정":"옳음","설명":"개업공인중개사는 자격이 아니라 개설등록을 기준으로 정한다(법 제2조제4호)."},{"번호":5,"판정":"틀림","설명":"법인의 사원·임원인 공인중개사는 소속공인중개사에 포함된다. 소속공인중개사는 중개업무를 수행하는 사람뿐 아니라 보조하는 사람도 포함한다(법 제2조제5호)."}],"개념":[{"종류":"표","제목":"중개 관련 여섯 용어의 기준","머리":["용어","기준","경계"],"행":[["공인중개사","이 법에 따른 자격 취득","개설등록 여부 무관"],["개업공인중개사","중개사무소 개설등록","법인의 임원인 공인중개사는 해당 없음(소속공인중개사)"],["소속공인중개사","개업공인중개사에 소속된 공인중개사","법인의 사원·임원인 공인중개사 포함, 중개업무 수행 또는 보조"],["중개보조원","공인중개사가 아닌 자로서 소속","현장안내·일반서무 등 단순 업무 보조"],["중개업","타인의 의뢰 + 일정한 보수 + 업","보수 없이 한 중개, 보수를 약속만 한 경우는 해당 없음(판례)"],["중개","제3조 중개대상물에 대한 권리 득실변경 알선","매매·교환·임대차 외 그 밖의 권리도 포함"]]},{"종류":"표","제목":"중개대상물의 범위","머리":["구분","중개대상물","중개대상물 아님"],"행":[["법 제3조 열거","토지, 건축물 그 밖의 토지의 정착물","-"],["영 제2조 열거","「입목에 관한 법률」에 따른 입목, 「공장 및 광업재단 저당법」에 따른 공장재단·광업재단","-"],["토지","지목과 관계없이 모두 해당","-"],["건축물","미등기·무허가 건물, 기둥·지붕·주벽을 갖춘 신축 중 건물","-"],["장래의 건물","동·호수가 특정되어 분양계약이 체결된 아파트 분양권","입주권, 대토권(특정 물건이 아니라 지위)"],["재산적 가치","-","영업시설·비품 등 유형물, 거래처·신용·권리금 등 무형 재산가치(판례)"]]}],"함정":"5번에서 \"법인의 사원·임원은 개업공인중개사 쪽\"이라고 떠올리기 쉽다. 법인 자체가 개설등록을 한 개업공인중개사이고, 그 사원·임원인 공인중개사는 소속공인중개사다."},"36회-2차-020":{"한줄":"인장 변경 신고(등록)는 법 제47조제1항이 열거한 수수료 납부 대상 여섯 가지에 들어 있지 않다.","근거":[{"법령":"공인중개사법","조문":"제47조제1항","원문":"① 다음 각 호의 어느 하나에 해당하는 자는 해당 지방자치단체의 조례로 정하는 바에 따라 수수료를 납부하여야 한다. 다만, 공인중개사자격시험을 제4조제2항의 규정에 따라 국토교통부장관이 시행하는 경우 제1호에 해당하는 자는 국토교통부장관이 결정ㆍ공고하는 수수료를 납부하여야 한다.\n1. 제4조에 따른 공인중개사자격시험에 응시하는 자\n2. 제5조제3항에 따라 공인중개사자격증의 재교부를 신청하는 자\n3. 제9조제1항에 따라 중개사무소의 개설등록을 신청하는 자\n4. 제11조제2항에 따라 중개사무소등록증의 재교부를 신청하는 자\n5. 제13조제3항에 따라 분사무소설치의 신고를 하는 자\n6. 제13조제5항에 따라 분사무소설치신고확인서의 재교부를 신청하는 자"}],"선지":[{"번호":1,"판정":"옳음","설명":"개설등록 신청자는 수수료를 낸다(법 제47조제1항제3호)."},{"번호":2,"판정":"옳음","설명":"등록증 재교부 신청자는 수수료를 낸다(제4호)."},{"번호":3,"판정":"옳음","설명":"분사무소설치 신고자는 수수료를 낸다(제5호)."},{"번호":4,"판정":"틀림","설명":"등록 인장의 변경 신고는 열거된 여섯 가지에 없으므로 수수료 대상이 아니다. 변경일부터 7일 이내에 등록하면 된다(규칙 제9조제2항)."},{"번호":5,"판정":"옳음","설명":"분사무소설치신고확인서 재교부 신청자는 수수료를 낸다(제6호)."}],"개념":[{"종류":"표","제목":"조례로 정한 수수료를 내는 여섯 경우","머리":["대상","근거","비고"],"행":[["공인중개사자격시험 응시","제1호","국토교통부장관 시행 시 장관이 결정·공고한 수수료"],["자격증 재교부 신청","제2호","자격증을 교부한 시·도지사에게 신청"],["중개사무소 개설등록 신청","제3호","등록관청에 신청"],["중개사무소등록증 재교부 신청","제4호","자격증 재교부 규정 준용(법 제11조제2항)"],["분사무소설치 신고","제5호","주된 사무소 관할 등록관청에 신고"],["분사무소설치신고확인서 재교부 신청","제6호","자격증 재교부 규정 준용(법 제13조제5항)"]]},{"종류":"흐름","제목":"중개사무소 개설등록 절차","단계":[{"이름":"신청","설명":"사무소를 두려는 곳의 시장·군수·구청장(등록관청)에 신청서와 실무교육 수료확인증 사본, 여권용 사진, 사무소 확보 증명서류를 낸다(규칙 제4조제1항). 이때 수수료를 낸다."},{"이름":"확인","설명":"등록관청이 자격증을 발급한 시·도지사에게 공인중개사 자격 확인을 요청하고, 법인 등기사항증명서와 건축물대장을 행정정보 공동이용으로 확인한다(규칙 제4조제1항)."},{"이름":"등록·통지","설명":"법인과 공인중개사로 종별을 나눠 등록하고 신청을 받은 날부터 7일 이내에 서면으로 통지한다(규칙 제4조제2항)."},{"이름":"등록증 교부","설명":"보증 설정 여부를 확인한 뒤 중개사무소등록증을 지체 없이 교부한다(규칙 제5조제1항)."},{"이름":"협회 통보","설명":"등록·행정처분·신고 사항을 매월 모아 다음 달 10일까지 한국공인중개사협회에 통보한다(규칙 제6조)."}]}],"함정":"고르기 쉬운 오답은 신고라서 수수료가 있을 것 같은 인장 변경이다. 수수료 대상은 신청·재교부 위주이고, 분사무소는 설치 신고와 확인서 재교부만 해당한다."},"36회-2차-009":{"한줄":"임신 또는 출산은 6개월 초과 휴업이 허용되는 부득이한 사유이므로 1번이 옳다.","근거":[{"법령":"공인중개사법","조문":"제21조제1항·제2항","원문":"① 개업공인중개사는 3개월을 초과하는 휴업(중개사무소의 개설등록 후 업무를 개시하지 아니하는 경우를 포함한다. 이하 같다), 폐업 또는 휴업한 중개업을 재개하고자 하는 때에는 등록관청에 그 사실을 신고하여야 한다. 휴업기간을 변경하고자 하는 때에도 또한 같다.\n② 제1항에 따른 휴업은 6개월을 초과할 수 없다. 다만, 질병으로 인한 요양등 대통령령으로 정하는 부득이한 사유가 있는 경우에는 그러하지 아니하다."},{"법령":"공인중개사법 시행령","조문":"제18조제1항·제4항·제6항","원문":"1. 3개월을 초과하여 휴업(법 제9조에 따른 중개사무소 개설등록 후 업무를 개시하지 않는 경우를 포함한다. 이하 이 조에서 같다)하려는 경우\n3. 3개월을 초과하여 휴업한 부동산중개업을 재개하려는 경우\n④ 관할 세무서장이 「부가가치세법 시행령」 제13조제5항에 따라 제1항의 신고서를 받아 해당 등록관청에 송부한 경우에는 제1항의 신고서가 제출된 것으로 본다.\n4. 임신 또는 출산"},{"법령":"공인중개사법 시행령","조문":"제18조제2항","원문":"② 법인인 개업공인중개사는 제1항에도 불구하고 법 제13조제3항에 따라 분사무소를 둔 경우에는 제1항에 따른 신고를 분사무소별로 할 수 있다."},{"법령":"공인중개사법","조문":"제20조제1항","원문":"다만, 중개사무소를 등록관청의 관할 지역 외의 지역으로 이전한 경우에는 이전 후의 중개사무소를 관할하는 시장ㆍ군수 또는 구청장(이하 이 조에서 \"이전후 등록관청\"이라 한다)에게 신고하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"출산은 영 제18조제6항제4호의 부득이한 사유라서 6개월을 넘겨 휴업할 수 있다(법 제21조제2항 단서)."},{"번호":2,"판정":"틀림","설명":"관할 밖으로 이전하면 이전 후 등록관청에 신고한다(법 제20조제1항 단서). 이전 전 등록관청이 아니다."},{"번호":3,"판정":"틀림","설명":"분사무소를 둔 법인은 휴업·폐업 신고를 분사무소별로 할 수 있다(영 제18조제2항)."},{"번호":4,"판정":"틀림","설명":"3개월 초과 휴업 후 재개 신고는 영 제18조제1항제3호이고, 등록증 첨부 대상은 제1호(휴업)·제2호(폐업)뿐이다. 재개 신고를 받은 등록관청은 반납받았던 등록증을 즉시 돌려준다(영 제18조제5항)."},{"번호":5,"판정":"틀림","설명":"세무서장이 폐업신고서를 받아 등록관청에 송부하면 등록관청에 신고서가 제출된 것으로 본다(영 제18조제4항)."}],"개념":[{"종류":"표","제목":"이전·휴업·폐업·재개 신고 비교","머리":["구분","시기","신고처","등록증"],"행":[["이전신고","이전한 날부터 10일 이내(사후)","등록관청, 관할 밖 이전은 이전 후 등록관청","첨부(규칙 제11조제1항)"],["3개월 초과 휴업","미리","등록관청","첨부"],["폐업","미리","등록관청","첨부"],["휴업한 중개업의 재개(3개월 초과 휴업 후)","미리","등록관청","첨부 없음, 반납받았던 등록증을 즉시 반환"],["휴업기간 변경","미리","등록관청","첨부 없음"],["미신고 제재","-","-","100만원 이하 과태료(법 제51조제3항제3호·제4호)"]]},{"종류":"흐름","제목":"관할 밖으로 중개사무소를 이전하는 경우","단계":[{"이름":"이전 후 신고","설명":"이전한 날부터 10일 이내에 이전 후 등록관청에 이전신고서, 등록증, 사무소 확보 증명서류를 낸다(법 제20조제1항, 규칙 제11조제1항)."},{"이름":"서류 송부 요청","설명":"이전 후 등록관청이 종전 등록관청에 관련 서류를 송부하여 달라고 요청한다(법 제20조제2항)."},{"이름":"서류 송부","설명":"종전 등록관청이 지체 없이 등록대장, 개설등록 신청서류, 최근 1년간 행정처분 서류를 보낸다(법 제20조제2항, 규칙 제11조제4항)."},{"이름":"등록증 재교부","설명":"이전 후 등록관청이 내용을 확인해 등록증을 재교부한다(규칙 제11조제2항)."},{"이름":"간판 철거·처분","설명":"이전신고를 한 개업공인중개사는 지체 없이 간판을 철거한다(법 제21조의2제1항). 이전신고 전에 생긴 사유의 행정처분은 이전 후 등록관청이 맡는다(법 제20조제3항)."}]}],"함정":"2번은 \"신고처는 원래 등록관청\"이라는 기억에서 나온 오답이다. 4번은 휴업·폐업 신고에 등록증을 붙이는 규정을 재개 신고에까지 넓힌 것이고, 5번은 세무서장 송부로 신고가 갈음된다는 규정을 뒤집은 것이다."},"36회-2차-006":{"한줄":"ㄱ과 ㄴ은 법 제13조제1항·제2항 그대로 옳고, ㄷ은 분사무소설치신고서를 주된 사무소 관할 등록관청에 낸다는 점에서 틀렸다.","근거":[{"법령":"공인중개사법","조문":"제13조제1항·제2항·제4항","원문":"①개업공인중개사는 그 등록관청의 관할 구역안에 중개사무소를 두되, 1개의 중개사무소만을 둘 수 있다.\n②개업공인중개사는 천막 그 밖에 이동이 용이한 임시 중개시설물을 설치하여서는 아니된다.\n④제3항에 따라 분사무소 설치신고를 받은 등록관청은 그 신고내용이 적합한 경우에는 국토교통부령으로 정하는 신고확인서를 교부하고 지체 없이 그 분사무소설치예정지역을 관할하는 시장ㆍ군수 또는 구청장에게 이를 통보하여야 한다."},{"법령":"공인중개사법 시행령","조문":"제15조제3항","원문":"③법 제13조제3항에 따라 분사무소의 설치신고를 하려는 자는 국토교통부령으로 정하는 분사무소설치신고서에 다음 각 호의 서류를 첨부하여 주된 사무소의 소재지를 관할하는 등록관청에 제출하여야 한다."}],"선지":[{"번호":1,"판정":"-","설명":"ㄴ(임시 중개시설물 금지)도 옳은 보기라서 ㄱ만 고르면 하나가 빠진다."},{"번호":2,"판정":"-","설명":"ㄷ은 분사무소 소재지가 아니라 주된 사무소 관할 등록관청에 신고하므로 옳은 보기가 아니다."},{"번호":3,"판정":"-","설명":"법 제13조제1항·제2항에 따라 ㄱ, ㄴ만 옳다."},{"번호":4,"판정":"-","설명":"ㄴ은 옳지만 ㄱ이 빠지고 틀린 ㄷ이 들어간 조합이다."},{"번호":5,"판정":"-","설명":"ㄷ(분사무소 소재지 관할 등록관청에 신고)이 틀려서 세 보기를 모두 고를 수 없다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"1등록 1사무소 원칙이다. 등록관청 관할 구역 안에 사무소를 1개만 둔다(법 제13조제1항)."},{"기호":"ㄴ","판정":"옳음","설명":"천막 같은 이동이 쉬운 임시 중개시설물은 설치할 수 없다(법 제13조제2항)."},{"기호":"ㄷ","판정":"틀림","설명":"분사무소설치신고서는 분사무소 소재지가 아니라 주된 사무소 소재지를 관할하는 등록관청에 낸다(영 제15조제3항). 등록관청이 분사무소 설치 예정지역의 시장·군수·구청장에게 통보한다(법 제13조제4항)."}],"개념":[{"종류":"흐름","제목":"분사무소 설치 절차","단계":[{"이름":"설치 요건","설명":"법인만 둘 수 있다. 주된 사무소가 있는 시·군·구를 제외하고 시·군·구마다 1개소를 넘을 수 없다(영 제15조제1항)."},{"이름":"책임자","설명":"공인중개사를 책임자로 둔다. 다른 법률에 따라 중개업을 하는 법인의 분사무소는 예외다(영 제15조제2항). 책임자는 신고일 전 1년 이내에 시·도지사가 실시하는 실무교육을 받아야 한다(법 제34조제1항)."},{"이름":"신고","설명":"주된 사무소 관할 등록관청에 분사무소설치신고서, 책임자 실무교육 수료확인증 사본, 보증 설정 증명서류, 사무소 확보 증명서류를 낸다(영 제15조제3항)."},{"이름":"확인·교부","설명":"등록관청이 책임자의 자격을 시·도지사에게 확인하고 법인 등기사항증명서를 확인한 뒤, 적합하면 신고확인서를 교부한다(영 제15조제3항, 법 제13조제4항)."},{"이름":"통보","설명":"등록관청이 분사무소 설치 예정지역 관할 시장·군수·구청장에게 지체 없이 통보한다(법 제13조제4항)."}]},{"종류":"표","제목":"사무소 설치 위반의 제재","머리":["위반","등록취소","형벌"],"행":[["둘 이상의 사무소(법 제13조제1항)","취소할 수 있음(법 제38조제2항제2호)","1년 이하 징역 또는 1천만원 이하 벌금(법 제49조제1항제4호)"],["임시 중개시설물 설치(법 제13조제2항)","취소할 수 있음(법 제38조제2항제3호)","1년 이하 징역 또는 1천만원 이하 벌금(법 제49조제1항제5호)"],["업무정지 중 공동사용(법 제13조제6항 단서)","공동사용 새로 시작 금지(영 제16조제2항)","-"],["중개 지역","제한 없음, 사무소 위치와 무관하게 전국 중개 가능","-"]]}],"함정":"ㄷ을 읽을 때 \"분사무소가 생기는 곳의 관청\"에 신고한다고 짐작하기 쉽다. 신고는 주된 사무소 관할 등록관청이고, 분사무소 지역 관청은 통보를 받는 쪽이다."},"36회-2차-007":{"한줄":"개업공인중개사가 표시·광고를 할 때 중개보조원에 관한 사항은 명시해서는 안 된다(법 제18조의2제1항).","근거":[{"법령":"공인중개사법","조문":"제18조의2제1항·제3항·제4항","원문":"① 개업공인중개사가 의뢰받은 중개대상물에 대하여 표시ㆍ광고(「표시ㆍ광고의 공정화에 관한 법률」 제2조에 따른 표시ㆍ광고를 말한다. 이하 같다)를 하려면 중개사무소, 개업공인중개사에 관한 사항으로서 대통령령으로 정하는 사항을 명시하여야 하며, 중개보조원에 관한 사항은 명시해서는 아니 된다.\n③ 개업공인중개사가 아닌 자는 중개대상물에 대한 표시ㆍ광고를 하여서는 아니 된다.\n④ 개업공인중개사는 중개대상물에 대하여 다음 각 호의 어느 하나에 해당하는 부당한 표시ㆍ광고를 하여서는 아니 된다.\n1. 중개대상물이 존재하지 않아서 실제로 거래를 할 수 없는 중개대상물에 대한 표시ㆍ광고"},{"법령":"공인중개사법","조문":"제18조제2항·제5항","원문":"②개업공인중개사가 아닌 자는 \"공인중개사사무소\", \"부동산중개\" 또는 이와 유사한 명칭을 사용하여서는 아니된다.\n⑤등록관청은 제1항부터 제3항까지의 규정을 위반한 사무소의 간판 등에 대하여 철거를 명할 수 있다. 이 경우 그 명령을 받은 자가 철거를 이행하지 아니하는 경우에는 「행정대집행법」에 의하여 대집행을 할 수 있다."},{"법령":"공인중개사법 시행령","조문":"제17조의2제1항·제4항제1호","원문":"1. 중개사무소의 명칭, 소재지, 연락처 및 등록번호\n2. 개업공인중개사의 성명(법인인 경우에는 대표자의 성명)\n1. 중개대상물이 존재하지만 실제로 중개의 대상이 될 수 없는 중개대상물에 대한 표시ㆍ광고"}],"선지":[{"번호":1,"판정":"옳음","설명":"비개업자는 \"부동산중개\"나 비슷한 명칭을 쓸 수 없다(법 제18조제2항)."},{"번호":2,"판정":"옳음","설명":"비개업자는 중개대상물 표시·광고를 할 수 없다(법 제18조의2제3항)."},{"번호":3,"판정":"옳음","설명":"존재하지만 중개의 대상이 될 수 없는 물건의 표시·광고는 부당한 표시·광고다(영 제17조의2제4항제1호, 법 제18조의2제4항제3호)."},{"번호":4,"판정":"옳음","설명":"성명 표기 위반 간판은 등록관청이 철거를 명할 수 있다(법 제18조제5항, 제3항)."},{"번호":5,"판정":"틀림","설명":"개업공인중개사 및 사무소에 관한 사항은 명시하되 중개보조원에 관한 사항은 명시해서는 안 된다(법 제18조의2제1항)."}],"개념":[{"종류":"표","제목":"표시·광고 명시사항","머리":["구분","명시할 사항","근거"],"행":[["모든 표시·광고","중개사무소의 명칭, 소재지, 연락처, 등록번호","영 제17조의2제1항제1호"],["모든 표시·광고","개업공인중개사 성명(법인은 대표자 성명)","영 제17조의2제1항제2호"],["모든 표시·광고","중개보조원에 관한 사항은 명시 금지","법 제18조의2제1항"],["인터넷 표시·광고(추가)","소재지, 면적, 가격, 중개대상물 종류, 거래 형태","영 제17조의2제2항제1호~제5호"],["인터넷 표시·광고(건축물 등 추가)","총 층수, 사용승인·사용검사·준공검사 등을 받은 날, 방향·방 개수·욕실 개수·입주가능일·주차대수·관리비","영 제17조의2제2항제6호"]]},{"종류":"표","제목":"명칭·표시·광고 위반의 제재","머리":["위반행위","제재","근거"],"행":[["비개업자의 \"공인중개사사무소\"·\"부동산중개\" 명칭 사용","1년 이하 징역 또는 1천만원 이하 벌금","법 제49조제1항제6호"],["비개업자의 중개대상물 표시·광고","1년 이하 징역 또는 1천만원 이하 벌금","법 제49조제1항제6호의2"],["명칭 문자 미사용, 옥외광고물 성명 미표기·거짓 표기","100만원 이하 과태료","법 제51조제3항제2호"],["명시사항을 지키지 않은 표시·광고","100만원 이하 과태료","법 제51조제3항제2호의2"],["부당한 표시·광고(존재하지 않는 물건, 허위·과장 등)","500만원 이하 과태료","법 제51조제2항제1호"],["법 제18조 위반 간판","등록관청의 철거 명령, 불이행 시 행정대집행","법 제18조제5항"]]}],"함정":"5번을 옳다고 읽기 쉽다. 사무소와 개업공인중개사 정보는 반드시 적고, 중개보조원 정보는 적어서는 안 된다. 3번은 \"존재하지 않는 물건\"(법 제18조의2제4항제1호)과 \"존재하지만 중개할 수 없는 물건\"(영 제17조의2제4항제1호)이 모두 부당 광고라는 점을 알면 옳은 선지로 처리된다."},"36회-2차-008":{"한줄":"상업용 건축물의 분양대행(ㄱ), 부동산의 이용·개발에 관한 상담(ㄴ), 상업용 건축물의 관리대행(ㄷ)이 모두 법인의 겸업 허용 업무다.","근거":[{"법령":"공인중개사법","조문":"제14조제1항","원문":"①법인인 개업공인중개사는 다른 법률에 규정된 경우를 제외하고는 중개업 및 다음 각 호에 규정된 업무와 제2항에 규정된 업무 외에 다른 업무를 함께 할 수 없다.\n1. 상업용 건축물 및 주택의 임대관리 등 부동산의 관리대행\n2. 부동산의 이용ㆍ개발 및 거래에 관한 상담\n3. 개업공인중개사를 대상으로 한 중개업의 경영기법 및 경영정보의 제공\n4. 상업용 건축물 및 주택의 분양대행\n5. 그 밖에 중개업에 부수되는 업무로서 대통령령으로 정하는 업무"},{"법령":"공인중개사법 시행령","조문":"제17조제2항","원문":"②법 제14조제1항제5호에서 \"대통령령이 정하는 업무\"라 함은 중개의뢰인의 의뢰에 따른 도배ㆍ이사업체의 소개 등 주거이전에 부수되는 용역의 알선을 말한다."}],"선지":[{"번호":1,"판정":"-","설명":"ㄴ 외에 분양대행(제4호)과 관리대행(제1호)도 겸업 업무라서 하나만 고르면 부족하다."},{"번호":2,"판정":"-","설명":"ㄷ의 관리대행도 제1호 겸업 업무라서 ㄱ, ㄴ만으로는 부족하다."},{"번호":3,"판정":"-","설명":"ㄴ의 상담도 제2호 겸업 업무라서 ㄱ, ㄷ만으로는 부족하다."},{"번호":4,"판정":"-","설명":"ㄱ의 분양대행도 제4호 겸업 업무라서 ㄴ, ㄷ만으로는 부족하다."},{"번호":5,"판정":"-","설명":"ㄱ, ㄴ, ㄷ 모두 법 제14조제1항 각 호의 업무다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"상업용 건축물 및 주택의 분양대행은 제4호 업무다."},{"기호":"ㄴ","판정":"옳음","설명":"부동산의 이용·개발 및 거래에 관한 상담은 제2호 업무다."},{"기호":"ㄷ","판정":"옳음","설명":"상업용 건축물 및 주택의 임대관리 등 관리대행은 제1호 업무다."}],"개념":[{"종류":"표","제목":"법인인 개업공인중개사가 중개업과 함께 할 수 있는 업무","머리":["번호","업무","근거"],"행":[["1","상업용 건축물 및 주택의 임대관리 등 부동산의 관리대행","법 제14조제1항제1호"],["2","부동산의 이용·개발 및 거래에 관한 상담","제2호"],["3","개업공인중개사를 대상으로 한 중개업의 경영기법·경영정보 제공","제3호"],["4","상업용 건축물 및 주택의 분양대행","제4호"],["5","도배·이사업체 소개 등 주거이전에 부수되는 용역의 알선","제5호, 영 제17조제2항"],["6","경매·공매 대상 부동산의 권리분석·취득 알선, 매수신청·입찰신청 대리","법 제14조제2항"]]},{"종류":"비교","제목":"법인과 법인이 아닌 개업공인중개사의 겸업","왼쪽":{"이름":"법인인 개업공인중개사","항목":["중개업과 법 제14조제1항·제2항 업무만 겸업 가능(다른 법률에 규정된 경우 제외)","설립 목적도 법 제14조 업무만 영위하는 것으로 한정(영 제13조제1항제2호나목)","그 밖의 업무를 겸하면 등록취소 가능(법 제38조제2항제4호)"]},"오른쪽":{"이름":"법인이 아닌 개업공인중개사","항목":["법 제14조제1항의 겸업 제한이 적용되지 않음","경매·공매 권리분석·취득 알선, 매수신청·입찰신청 대리는 가능(법 제14조제2항)","경매 매수신청 대리를 하려면 대법원규칙 요건을 갖춰 법원에 등록하고 감독을 받음(법 제14조제3항)"]}}],"함정":"분양대행과 관리대행을 \"중개업과 무관해 겸업 불가\"로 처리하면 오답이 된다. 법인의 겸업은 열거된 업무만 허용되고, 열거된 업무는 모두 해당 문항의 보기에 들어 있다."},"36회-2차-004":{"한줄":"인장등록은 개설등록 신청과 동시에 할 수 있을 뿐이고, 업무개시 전이면 되므로 \"동시에 하여야 한다\"는 1번이 틀렸다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"제9조제1항·제2항·제3항·제6항","원문":"①개업공인중개사 및 소속공인중개사는 법 제16조제1항의 규정에 따라 업무를 개시하기 전에 중개행위에 사용할 인장을 등록관청에 등록(전자문서에 의한 등록을 포함한다)하여야 한다.\n②제1항의 규정에 따라 등록한 인장을 변경한 경우에는 개업공인중개사 및 소속공인중개사는 변경일부터 7일 이내에 그 변경된 인장을 등록관청에 등록(전자문서에 의한 등록을 포함한다)하여야 한다.\n법인인 개업공인중개사의 경우에는 「상업등기규칙」에 따라 신고한 법인의 인장이어야 한다. 다만, 분사무소에서 사용할 인장의 경우에는 「상업등기규칙」 제35조제3항에 따라 법인의 대표자가 보증하는 인장을 등록할 수 있다.\n⑥ 제1항에 따른 인장의 등록은 다음 각 호의 신청이나 신고와 같이 할 수 있다.\n1. 제4조에 따른 중개사무소 개설등록신청\n2. 제8조에 따른 소속공인중개사ㆍ중개보조원에 대한 고용 신고"}],"선지":[{"번호":1,"판정":"틀림","설명":"개설등록 신청과 같이 할 수 있다는 것이지 같이 하여야 한다는 것이 아니다. 업무 개시 전까지 등록하면 된다(규칙 제9조제1항·제6항)."},{"번호":2,"판정":"옳음","설명":"소속공인중개사도 업무를 개시하기 전에 인장을 등록한다(규칙 제9조제1항)."},{"번호":3,"판정":"옳음","설명":"분사무소가 없는 법인은 상업등기규칙에 따라 신고한 법인의 인장을 등록한다(규칙 제9조제3항)."},{"번호":4,"판정":"옳음","설명":"분사무소 사용 인장은 법인 대표자가 보증하는 인장을 등록할 수 있다(규칙 제9조제3항 단서)."},{"번호":5,"판정":"옳음","설명":"등록한 인장을 변경하면 변경일부터 7일 이내에 등록한다(규칙 제9조제2항)."}],"개념":[{"종류":"표","제목":"인장등록 정리","머리":["항목","내용","근거"],"행":[["등록 의무자","개업공인중개사, 소속공인중개사(중개보조원은 의무 없음)","법 제16조제1항"],["등록 시기","업무를 개시하기 전","규칙 제9조제1항"],["병행 가능","개설등록 신청 또는 소속공인중개사·중개보조원 고용 신고와 같이 할 수 있음","규칙 제9조제6항"],["변경","변경일부터 7일 이내 등록","규칙 제9조제2항"],["크기·내용(개인)","가족관계등록부·주민등록표상 성명이 나타난 인장, 가로·세로 각 7밀리미터 이상 30밀리미터 이내","규칙 제9조제3항"],["법인","상업등기규칙에 따라 신고한 법인의 인장, 등록은 인감증명서 제출로 갈음","규칙 제9조제3항·제4항"],["분사무소","법인 대표자가 보증하는 인장 등록 가능","규칙 제9조제3항 단서"],["중개행위 시 사용","등록한 인장을 사용해야 함","법 제16조제2항"],["위반 제재","개업공인중개사 업무정지 가능(법 제39조제1항제2호), 소속공인중개사 자격정지 가능(법 제36조제1항제2호)","-"]]}],"함정":"\"신청과 동시에\"라는 표현에서 의무처럼 읽히는 게 함정이다. 같이 할 수 있는 선택 사항이고, 법정 기한은 업무 개시 전이다. 변경 등록 기한 7일을 이전신고 기한 10일과 섞어 5번을 의심하기도 한다."},"36회-2차-014":{"한줄":"거래정보사업자는 정보처리기사를 1명 이상 확보하면 되므로 ㄱ은 틀리고, 1년 이내 미운영 시 지정취소(ㄴ)와 공인중개사 자격증 사본 제출(ㄷ)은 옳다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"제15조제1항·제2항","원문":"①법 제24조제1항에 따라 부동산거래정보망을 설치ㆍ운영할 자로 지정받으려는 자는 별지 제16호서식의 거래정보사업자지정신청서에 다음 각 호의 서류를 첨부하여 국토교통부장관에게 제출하여야 한다.\n3. 정보처리기사 자격증 사본\n4. 공인중개사 자격증 사본\n②제1항에 따라 부동산거래정보망을 설치ㆍ운영할 자로 지정받으려는 자는 다음 각 호의 요건을 갖추어야 한다.\n1. 그 부동산거래정보망의 가입ㆍ이용신청을 한 개업공인중개사의 수가 5백명 이상이고 2개 이상의 특별시ㆍ광역시ㆍ도 및 특별자치도(이하 \"시ㆍ도\"라 한다)에서 각각 30인 이상의 개업공인중개사가 가입ㆍ이용신청을 하였을 것\n2. 정보처리기사 1명 이상을 확보할 것\n3. 공인중개사 1명 이상을 확보할 것"},{"법령":"공인중개사법","조문":"제24조제5항","원문":"⑤국토교통부장관은 거래정보사업자가 다음 각 호의 어느 하나에 해당하는 경우에는 그 지정을 취소할 수 있다.\n4. 정당한 사유 없이 지정받은 날부터 1년 이내에 부동산거래정보망을 설치ㆍ운영하지 아니한 경우"}],"선지":[{"번호":1,"판정":"-","설명":"ㄱ은 정보처리기사 2명 이상이라고 해서 틀렸고, 옳은 ㄴ·ㄷ이 빠진 조합이다."},{"번호":2,"판정":"-","설명":"ㄷ의 공인중개사 자격증 사본도 제출서류라서 ㄴ만으로는 부족하다."},{"번호":3,"판정":"-","설명":"ㄱ이 정보처리기사 2명 이상이라는 점에서 틀려, ㄱ이 든 조합은 맞지 않는다."},{"번호":4,"판정":"-","설명":"ㄴ(1년 이내 미운영 시 지정취소 가능), ㄷ(자격증 사본 제출)이 옳다."},{"번호":5,"판정":"-","설명":"ㄱ(정보처리기사 2명 이상)이 틀려 세 보기를 모두 고를 수 없다."}],"보기판정":[{"기호":"ㄱ","판정":"틀림","설명":"정보처리기사는 2명이 아니라 1명 이상 확보하면 된다(규칙 제15조제2항제2호)."},{"기호":"ㄴ","판정":"옳음","설명":"정당한 사유 없이 지정받은 날부터 1년 이내에 정보망을 설치·운영하지 않으면 국토교통부장관이 지정을 취소할 수 있다(법 제24조제5항제4호)."},{"기호":"ㄷ","판정":"옳음","설명":"지정신청서 첨부서류에 정보처리기사 자격증 사본과 공인중개사 자격증 사본이 모두 들어간다(규칙 제15조제1항제3호·제4호)."}],"개념":[{"종류":"표","제목":"거래정보사업자 지정 요건과 신청서류","머리":["구분","내용","근거"],"행":[["지정권자","국토교통부장관","법 제24조제1항"],["지정 대상","전기통신사업법상 부가통신사업자로서 요건을 갖춘 자","법 제24조제2항"],["개업공인중개사 가입·이용신청","500명 이상, 2개 이상 시·도에서 각각 30인 이상","규칙 제15조제2항제1호"],["전문 인력","정보처리기사 1명 이상, 공인중개사 1명 이상","규칙 제15조제2항제2호·제3호"],["설비","국토교통부장관이 정하는 용량·성능의 컴퓨터설비","규칙 제15조제2항제4호"],["신청서류","가입·이용신청서와 등록증 사본, 정보처리기사 자격증 사본, 공인중개사 자격증 사본, 컴퓨터 용량·성능 확인서류, 부가통신사업 신고 확인서류","규칙 제15조제1항"],["검토 기간","지정신청을 받은 날부터 30일 이내","규칙 제15조제3항"]]},{"종류":"흐름","제목":"거래정보사업자 지정에서 취소까지","단계":[{"이름":"지정 신청","설명":"지정신청서와 첨부서류를 국토교통부장관에게 낸다(규칙 제15조제1항)."},{"이름":"지정","설명":"신청을 받은 날부터 30일 이내에 검토하여 적합하면 지정하고 지정서를 교부한다(규칙 제15조제3항)."},{"이름":"운영규정 승인","설명":"지정받은 날부터 3개월 이내에 운영규정을 정하여 국토교통부장관의 승인을 얻는다. 변경할 때도 같다(법 제24조제3항)."},{"이름":"운영","설명":"개업공인중개사가 공개를 의뢰한 정보만 공개하고, 의뢰 내용과 다르게 공개하거나 개업공인중개사별로 차별 공개해서는 안 된다(법 제24조제4항)."},{"이름":"지정취소","설명":"거짓 지정, 운영규정 위반, 정보 공개 위반, 1년 내 미운영은 취소할 수 있고 이때 청문을 한다. 사망·해산 등으로 계속 운영이 불가능한 경우도 취소할 수 있다(법 제24조제5항·제6항)."}]}],"함정":"ㄱ은 숫자 하나를 바꾼 선지다. 정보처리기사와 공인중개사는 각각 1명 이상이다. ㄷ은 자격증 사본이 제출서류에 없다고 읽기 쉬운데, 공인중개사 자격증 사본이 포함된다."},"36회-2차-012":{"한줄":"일반중개계약서에는 중개대상물의 위치와 규모를 기재하므로, 의뢰인이 규모를 기재한 계약서의 작성을 요청할 수 있다는 3번이 옳다.","근거":[{"법령":"공인중개사법","조문":"제22조","원문":"제22조(일반중개계약) 중개의뢰인은 중개의뢰내용을 명확하게 하기 위하여 필요한 경우에는 개업공인중개사에게 다음 각 호의 사항을 기재한 일반중개계약서의 작성을 요청할 수 있다.\n1. 중개대상물의 위치 및 규모\n2. 거래예정가격\n3. 거래예정가격에 대하여 제32조에 따라 정한 중개보수\n4. 그 밖에 개업공인중개사와 중개의뢰인이 준수하여야 할 사항"},{"법령":"공인중개사법","조문":"제23조제3항","원문":"③개업공인중개사는 전속중개계약을 체결한 때에는 제24조에 따른 부동산거래정보망 또는 일간신문에 해당 중개대상물에 관한 정보를 공개하여야 한다. 다만, 중개의뢰인이 비공개를 요청한 경우에는 이를 공개하여서는 아니된다."},{"법령":"공인중개사법 시행령","조문":"제20조제1항·제2항제7호","원문":"①법 제23조제1항의 규정에 따른 전속중개계약의 유효기간은 3월로 한다. 다만, 당사자간에 다른 약정이 있는 경우에는 그 약정에 따른다.\n7. 중개대상물의 거래예정금액 및 공시지가. 다만, 임대차의 경우에는 공시지가를 공개하지 아니할 수 있다."},{"법령":"공인중개사법 시행규칙","조문":"제14조제2항","원문":"②법 제23조제2항에서 \"국토교통부령이 정하는 기간\"이라 함은 3년을 말한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"유효기간은 3개월이지만 당사자 간에 다른 약정이 있으면 그에 따른다(영 제20조제1항)."},{"번호":2,"판정":"틀림","설명":"전속중개계약서 보존 기간은 5년이 아니라 3년이다(규칙 제14조제2항)."},{"번호":3,"판정":"옳음","설명":"일반중개계약서 기재사항에 중개대상물의 위치 및 규모가 들어 있다(법 제22조제1호)."},{"번호":4,"판정":"틀림","설명":"임대차의 경우 공시지가는 공개하지 않을 수 있다(영 제20조제2항제7호 단서). 공개 의무가 없다."},{"번호":5,"판정":"틀림","설명":"중개의뢰인이 비공개를 요청하면 공개해서는 안 된다(법 제23조제3항 단서). 도배 상태는 공개 대상 정보지만 비공개 요청이 우선한다."}],"개념":[{"종류":"비교","제목":"일반중개계약과 전속중개계약","왼쪽":{"이름":"일반중개계약","항목":["의뢰인이 필요한 경우 일반중개계약서 작성을 요청할 수 있음(법 제22조)","기재사항: 위치·규모, 거래예정가격, 그에 대한 중개보수, 그 밖의 준수사항","표준서식 사용은 국토교통부장관이 권장(영 제19조)","정보 공개 의무 없음"]},"오른쪽":{"이름":"전속중개계약","항목":["특정 개업공인중개사에 한정해 중개하게 하는 계약(법 제23조제1항)","국토교통부령 서식(별지 제15호)에 의함, 계약서 3년 보존(법 제23조제2항, 규칙 제14조)","유효기간 3개월, 다른 약정이 있으면 그에 따름(영 제20조제1항)","부동산거래정보망 또는 일간신문에 정보 공개, 의뢰인이 비공개를 요청하면 공개 금지(법 제23조제3항)","서식 위반·미보존은 업무정지 가능(법 제39조제1항제3호), 정보 공개 위반은 등록취소 가능(법 제38조제2항제6호)"]}},{"종류":"표","제목":"전속중개계약 시 공개할 정보(영 제20조제2항)","머리":["번호","공개 정보","비고"],"행":[["1","종류, 소재지, 지목·면적, 건축물의 용도·구조·건축연도 등 특정 사항","-"],["2","벽면 및 도배의 상태","-"],["3","수도·전기·가스·소방·열공급·승강기 설비, 오수·폐수·쓰레기 처리시설 등의 상태","-"],["4","도로·대중교통과의 연계성, 시장·학교 등과의 근접성, 지형 등 입지조건, 일조·소음·진동 등 환경조건","-"],["5","소유권·전세권·저당권·지상권·임차권 등 권리관계","각 권리자의 주소·성명 등 인적 사항은 공개 금지"],["6","공법상의 이용제한 및 거래규제","-"],["7","거래예정금액 및 공시지가","임대차는 공시지가를 공개하지 않을 수 있음"]]}],"함정":"1번은 유효기간 3개월을 절대 기간으로 읽은 오답이고, 2번은 거래계약서·전속중개계약서의 보존 기간을 섞은 것이다. 거래계약서는 5년, 전속중개계약서는 3년이다."},"36회-2차-015":{"한줄":"매매업(ㄱ), 무등록 중개업자와의 거래(ㄴ), 시세에 부당한 영향을 주는 행위(ㄷ)가 모두 법 제33조제1항의 금지행위다.","근거":[{"법령":"공인중개사법","조문":"제33조제1항","원문":"① 개업공인중개사등은 다음 각 호의 행위를 하여서는 아니된다.\n1. 제3조에 따른 중개대상물의 매매를 업으로 하는 행위\n2. 제9조에 따른 중개사무소의 개설등록을 하지 아니하고 중개업을 영위하는 자인 사실을 알면서 그를 통하여 중개를 의뢰받거나 그에게 자기의 명의를 이용하게 하는 행위\n8. 부당한 이익을 얻거나 제3자에게 부당한 이익을 얻게 할 목적으로 거짓으로 거래가 완료된 것처럼 꾸미는 등 중개대상물의 시세에 부당한 영향을 주거나 줄 우려가 있는 행위"}],"선지":[{"번호":1,"판정":"-","설명":"ㄴ 외에 ㄱ(제1호)과 ㄷ(제8호)도 금지행위라서 하나만 고르면 부족하다."},{"번호":2,"판정":"-","설명":"ㄷ의 시세 교란 행위도 제8호 금지행위라서 ㄱ, ㄴ만으로는 부족하다."},{"번호":3,"판정":"-","설명":"ㄴ의 무등록 중개업자 이용도 제2호 금지행위라서 ㄱ, ㄷ만으로는 부족하다."},{"번호":4,"판정":"-","설명":"ㄱ의 매매업도 제1호 금지행위라서 ㄴ, ㄷ만으로는 부족하다."},{"번호":5,"판정":"-","설명":"ㄱ, ㄴ, ㄷ 모두 법 제33조제1항의 금지행위다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"중개대상물의 매매를 업으로 하는 행위는 제33조제1항제1호 금지행위다."},{"기호":"ㄴ","판정":"옳음","설명":"무등록 중개업자임을 알면서 그를 통해 중개를 의뢰받거나 그에게 명의를 이용하게 하는 행위는 제2호 금지행위다."},{"기호":"ㄷ","판정":"옳음","설명":"거짓 거래 완료 등으로 중개대상물의 시세에 부당한 영향을 주는 행위는 제8호 금지행위다."}],"개념":[{"종류":"표","제목":"금지행위(법 제33조제1항)와 형벌","머리":["호","금지행위","형벌"],"행":[["1","중개대상물의 매매를 업으로 하는 행위","1년 이하 징역 또는 1천만원 이하 벌금(법 제49조제1항제10호)"],["2","무등록 중개업자임을 알면서 중개를 의뢰받거나 명의를 이용하게 하는 행위","1년 이하 징역 또는 1천만원 이하 벌금"],["3","사례·증여 등 어떤 명목으로든 보수·실비를 초과해 금품을 받는 행위","1년 이하 징역 또는 1천만원 이하 벌금"],["4","거래상 중요사항에 관해 거짓된 언행으로 중개의뢰인의 판단을 그르치게 하는 행위","1년 이하 징역 또는 1천만원 이하 벌금"],["5","양도·알선이 금지된 부동산의 분양·임대 관련 증서 등의 매매·교환 중개 또는 그 매매업","3년 이하 징역 또는 3천만원 이하 벌금(법 제48조제3호)"],["6","중개의뢰인과 직접 거래하거나 거래당사자 쌍방을 대리하는 행위","3년 이하 징역 또는 3천만원 이하 벌금"],["7","등기하지 않은 부동산이나 전매 제한 부동산의 매매를 중개하는 등 투기를 조장하는 행위","3년 이하 징역 또는 3천만원 이하 벌금"],["8","거짓 거래 완료 등으로 중개대상물의 시세에 부당한 영향을 주거나 줄 우려가 있는 행위","3년 이하 징역 또는 3천만원 이하 벌금"],["9","단체를 구성해 특정 중개대상물의 중개를 제한하거나 구성원 외 공동중개를 제한하는 행위","3년 이하 징역 또는 3천만원 이하 벌금"]]},{"종류":"표","제목":"금지행위 관련 제재와 신고","머리":["주체","내용","근거"],"행":[["개업공인중개사","금지행위를 하면 등록취소 가능, 업무정지 가능","법 제38조제2항제9호, 제39조제1항제11호"],["소속공인중개사","금지행위를 하면 6개월 범위에서 자격정지 가능","법 제36조제1항제7호"],["누구든지(업무방해 금지)","시세에 부당한 영향을 줄 목적으로 개업공인중개사등의 업무를 방해하면 3년 이하 징역 또는 3천만원 이하 벌금","법 제33조제2항, 제48조제4호"],["신고센터","제33조제1항·제2항 위반행위는 부동산거래질서교란행위로 신고 가능","법 제47조의2제2항"],["포상금","제33조제1항제8호·제9호 위반행위 신고·고발 시 포상금 지급 가능","법 제46조제1항제5호"]]}],"함정":"ㄱ이 낯설어 보여도 매매업은 제1호에 그대로 있는 금지행위다. 중개업과 매매업은 서로 다른 업이라는 점이 이 규정의 전제다. 제1호~제4호는 1년 이하, 제5호~제9호는 3년 이하의 형벌이라는 구분도 같이 묻는다."},"36회-2차-011":{"한줄":"ㄱ·ㄴ은 영 제22조 그대로 옳고, 거래계약서 보존 기간은 3년이 아니라 5년이므로 ㄷ이 틀렸다.","근거":[{"법령":"공인중개사법 시행령","조문":"제22조","원문":"①법 제26조제1항의 규정에 따른 거래계약서에는 다음 각 호의 사항을 기재하여야 한다.\n3. 계약일\n8. 중개대상물확인ㆍ설명서 교부일자\n②법 제26조제1항에서 \"대통령령이 정하는 기간\"이라 함은 5년을 말한다.\n③국토교통부장관은 개업공인중개사가 작성하는 거래계약서의 표준이 되는 서식을 정하여 그 사용을 권장할 수 있다."},{"법령":"공인중개사법 시행령","조문":"제21조제4항","원문":"④ 법 제25조제3항 본문에서 \"대통령령이 정하는 기간\"이란 3년을 말한다."}],"선지":[{"번호":1,"판정":"-","설명":"ㄴ도 영 제22조제1항에 따라 옳은 보기라서 ㄱ만으로는 부족하다."},{"번호":2,"판정":"-","설명":"ㄷ은 보존 기간이 5년이라 틀렸고, 옳은 ㄱ이 빠진 조합이다."},{"번호":3,"판정":"-","설명":"ㄱ(표준서식 사용 권장), ㄴ(계약일·교부일자 기재)이 옳다."},{"번호":4,"판정":"-","설명":"ㄷ의 3년이 틀려서 ㄴ, ㄷ 조합은 맞지 않는다."},{"번호":5,"판정":"-","설명":"ㄷ의 3년이 틀려서 세 보기를 모두 고를 수 없다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"표준서식은 국토교통부장관이 정해 사용을 권장할 수 있을 뿐 강제하지 않는다(영 제22조제3항)."},{"기호":"ㄴ","판정":"옳음","설명":"계약일과 중개대상물확인·설명서 교부일자는 거래계약서 기재사항이다(영 제22조제1항제3호·제8호)."},{"기호":"ㄷ","판정":"틀림","설명":"거래계약서의 보존 기간은 5년이다(영 제22조제2항). 3년은 확인·설명서와 전속중개계약서의 보존 기간이다."}],"개념":[{"종류":"표","제목":"서류별 보존 기간과 서명·날인","머리":["서류","보존 기간","서명 및 날인","근거"],"행":[["중개대상물 확인·설명서","3년","개업공인중개사(법인은 대표자, 분사무소는 책임자) + 해당 중개행위를 한 소속공인중개사","법 제25조제3항·제4항, 영 제21조제4항"],["거래계약서","5년","확인·설명서와 같음(법 제25조제4항 준용)","법 제26조제1항·제2항, 영 제22조제2항"],["전속중개계약서","3년","-","법 제23조제2항, 규칙 제14조제2항"],["공인전자문서센터 보관 시","개업공인중개사의 보존 의무 없음","-","법 제25조제3항 단서, 제26조제1항 단서"]]},{"종류":"표","제목":"거래계약서 기재사항(영 제22조제1항)","머리":["번호","기재사항"],"행":[["1","거래당사자의 인적 사항"],["2","물건의 표시"],["3","계약일"],["4","거래금액·계약금액 및 그 지급일자 등 지급에 관한 사항"],["5","물건의 인도일시"],["6","권리이전의 내용"],["7","계약의 조건이나 기한이 있는 경우 그 조건 또는 기한"],["8","중개대상물확인·설명서 교부일자"],["9","그 밖의 약정내용"]]}],"함정":"ㄷ의 3년은 확인·설명서 보존 기간과 섞이기 쉬운 숫자다. 서류 이름만 바꿔 기간을 맞바꾼 선지가 자주 나오므로 거래계약서 5년, 확인·설명서 3년, 전속중개계약서 3년으로 구분해야 한다. 거래계약서에 거래금액을 거짓으로 적거나 서로 다른 둘 이상의 계약서를 작성하는 것은 금지된다(법 제26조제3항)."},"36회-2차-010":{"한줄":"아파트 임대차 중개에서는 관리비 금액과 산출내역도 확인·설명 사항이므로, 이를 설명 사항이 아니라고 한 4번이 틀렸다.","근거":[{"법령":"공인중개사법 시행령","조문":"제21조제1항","원문":"①법 제25조제1항에 따라 개업공인중개사가 확인ㆍ설명해야 하는 사항은 다음 각 호와 같다. 다만, 제3호의2 및 제10호부터 제12호까지의 사항은 주택 임대차 중개의 경우에만 적용한다.\n3. 거래예정금액ㆍ중개보수 및 실비의 금액과 그 산출내역\n3의2. 관리비 금액과 그 산출내역"},{"법령":"공인중개사법","조문":"제25조제1항·제3항","원문":"개업공인중개사는 중개를 의뢰받은 경우에는 중개가 완성되기 전에 다음 각 호의 사항을 확인하여\n③개업공인중개사는 중개가 완성되어 거래계약서를 작성하는 때에는 제1항에 따른 확인ㆍ설명사항을 대통령령으로 정하는 바에 따라 서면으로 작성하여 거래당사자에게 교부하고"}],"선지":[{"번호":1,"판정":"옳음","설명":"확인·설명은 중개가 완성되기 전에 한다(법 제25조제1항)."},{"번호":2,"판정":"옳음","설명":"거래계약서를 작성하는 때에 확인·설명서를 작성한다(법 제25조제3항)."},{"번호":3,"판정":"옳음","설명":"조사·확인 의무가 없는 사항이라도 의뢰인의 결정에 중요하면 그릇된 정보를 제공해서는 안 된다는 것이 판례다."},{"번호":4,"판정":"틀림","설명":"관리비 금액과 산출내역은 주택 임대차 중개에서 확인·설명해야 하는 사항이다(영 제21조제1항제3호의2 및 단서)."},{"번호":5,"판정":"옳음","설명":"의뢰인이 중개보수를 주지 않았다고 해서 확인·설명 의무와 위반 시 손해배상 의무가 당연히 없어지지는 않는다는 것이 판례다."}],"개념":[{"종류":"표","제목":"확인·설명 사항(영 제21조제1항)","머리":["번호","사항","적용"],"행":[["1","종류·소재지·지번·지목·면적·용도·구조·건축연도 등 기본 사항","모든 중개"],["2","소유권·전세권·저당권·지상권·임차권 등 권리관계","모든 중개"],["3","거래예정금액, 중개보수·실비의 금액과 산출내역","모든 중개"],["3의2","관리비 금액과 그 산출내역","주택 임대차 중개만"],["4","토지이용계획, 공법상 거래규제·이용제한","모든 중개"],["5","수도·전기·가스·소방·열공급·승강기·배수 등 시설물 상태","모든 중개"],["6","벽면·바닥면·도배 상태","모든 중개"],["7","일조·소음·진동 등 환경조건","모든 중개"],["8","도로·대중교통 연계성, 시장·학교 근접성 등 입지조건","모든 중개"],["9","권리를 취득함에 따라 부담할 조세의 종류와 세율","모든 중개"],["10","임대인의 정보 제시 의무, 보증금 중 일정액 보호(주택임대차보호법 제3조의7·제8조)","주택 임대차 중개만"],["11","전입세대확인서 열람·교부(주민등록법 제29조의2)","주택 임대차 중개만"],["12","민간임대주택의 임대보증금 보증(민간임대주택법 제49조)","민간임대주택인 주택 임대차 중개만"]]},{"종류":"표","제목":"확인·설명과 관련된 그 밖의 규정","머리":["규정","내용","근거"],"행":[["상태자료 요구","매도·임대의뢰인 등에게 중개대상물 상태에 관한 자료를 요구할 수 있음","법 제25조제2항"],["자료 요구 불응","불응한 사실을 의뢰인에게 설명하고 확인·설명서에 기재","영 제21조제2항"],["신분 확인","필요하면 중개의뢰인에게 신분을 확인할 수 있는 증표 제시를 요구할 수 있음","법 제25조의2"],["주택 임대차 설명","확정일자부여기관 정보제공 요청 가능, 임대인의 국세·지방세 체납 열람 신청 가능이라는 사항을 설명","법 제25조의3"]]}],"함정":"4번의 관리비는 \"아파트 관리비는 관리사무소가 정하니 중개사가 설명할 일이 아니다\"라는 생각에서 고르게 된다. 법령은 주택 임대차 중개에서 관리비 금액과 산출내역을 설명 사항으로 둔다. 매매 중개에는 이 항목이 적용되지 않는다.","개정":"관리비 금액과 산출내역은 영 제21조제1항제3호의2에 규정되어 있고 주택 임대차 중개에만 적용한다. 같은 항에는 2021.12.31과 2024.4.9 개정 이력이 붙어 있다."},"36회-2차-034":{"한줄":"요건을 갖춘 오피스텔의 중개보수는 매매·교환 1천분의 5, 임대차 등 1천분의 4 범위에서 쌍방에게 각각 받는다(규칙 제20조제4항제1호, 별표 2).","근거":[{"법령":"공인중개사법 시행규칙","조문":"제20조제4항","원문":"④법 제32조제4항에 따라 주택 외의 중개대상물에 대한 중개보수는 다음 각 호의 구분에 따른다.\n1. 「건축법 시행령」 별표 1 제14호나목2)에 따른 오피스텔(다음 각 목의 요건을 모두 갖춘 경우에 한정한다): 중개의뢰인 쌍방으로부터 각각 받되, 별표 2의 상한요율 이내에서 중개의뢰인과 개업공인중개사가 서로 협의하여 결정한다.\n가. 전용면적이 85제곱미터 이하일 것\n나. 상ㆍ하수도 시설이 갖추어진 전용입식 부엌, 전용수세식 화장실 및 목욕시설(전용수세식 화장실에 목욕시설을 갖춘 경우를 포함한다)을 갖출 것\n2. 제1호 외의 경우: 중개의뢰인 쌍방으로부터 각각 받되, 거래금액의 1천분의 9 이내에서 중개의뢰인과 개업공인중개사가 서로 협의하여 결정한다."}],"선지":[{"번호":1,"판정":"-","설명":"1천분의 4·3은 오피스텔 요율이 아니다. 오피스텔 요율은 매매·교환 1천분의 5, 임대차 등 1천분의 4다(별표 2)."},{"번호":2,"판정":"-","설명":"매매·교환 1천분의 5, 임대차 등 1천분의 4가 별표 2의 오피스텔 상한요율이다."},{"번호":3,"판정":"-","설명":"1천분의 6·5는 오피스텔 요율이 아니다."},{"번호":4,"판정":"-","설명":"1천분의 9는 요건을 못 갖춘 오피스텔·상가·토지 등 그 밖의 주택 외 중개대상물의 상한이다(규칙 제20조제4항제2호). 임대차 등 1천분의 8이라는 요율은 현행 규칙에 없다."},{"번호":5,"판정":"-","설명":"매매·임대차 모두 1천분의 9로 보는 것은 요건을 못 갖춘 경우의 일반 상한이다(규칙 제20조제4항제2호)."}],"개념":[{"종류":"표","제목":"중개대상물별 중개보수 규정","머리":["구분","정하는 곳","상한","비고"],"행":[["주택(부속토지 포함)","국토교통부령 범위 안에서 시·도 조례(법 제32조제4항)","규칙 별표 1의 구간별 요율과 한도액","쌍방에게 각각 받음"],["요건을 갖춘 오피스텔","국토교통부령(규칙 제20조제4항제1호)","매매·교환 1천분의 5, 임대차 등 1천분의 4","전용면적 85제곱미터 이하 + 전용입식 부엌, 전용수세식 화장실, 목욕시설"],["요건 못 갖춘 오피스텔, 상가, 토지 등","국토교통부령(규칙 제20조제4항제2호)","거래금액의 1천분의 9 이내","사무소 요율표에 자기 상한요율을 명시(규칙 제20조제7항)"],["주택과 주택 아닌 부분이 섞인 건축물","주택 면적 2분의 1 이상이면 주택 규정, 2분의 1 미만이면 주택 외 규정","-","규칙 제20조제6항"]]},{"종류":"표","제목":"주택 중개보수 상한요율(규칙 별표 1)","머리":["구분","거래금액","상한요율","한도액"],"행":[["매매·교환","5천만원 미만","1천분의 6","25만원"],["매매·교환","5천만원 이상 2억원 미만","1천분의 5","80만원"],["매매·교환","2억원 이상 9억원 미만","1천분의 4","-"],["매매·교환","9억원 이상 12억원 미만","1천분의 5","-"],["매매·교환","12억원 이상 15억원 미만","1천분의 6","-"],["매매·교환","15억원 이상","1천분의 7","-"],["임대차 등","5천만원 미만","1천분의 5","20만원"],["임대차 등","5천만원 이상 1억원 미만","1천분의 4","30만원"],["임대차 등","1억원 이상 6억원 미만","1천분의 3","-"],["임대차 등","6억원 이상 12억원 미만","1천분의 4","-"],["임대차 등","12억원 이상 15억원 미만","1천분의 5","-"],["임대차 등","15억원 이상","1천분의 6","-"]]}],"함정":"오피스텔 요건 두 가지(전용 85제곱미터 이하, 입식 부엌·화장실·목욕시설)를 모두 갖춰야 0.5%·0.4%가 적용된다. 하나라도 빠지면 1천분의 9가 상한이다. 주택 요율표의 숫자(0.4%, 0.3% 등)를 오피스텔에 끌어오면 1번처럼 틀린다.","개정":"규칙 제20조제4항은 2026.8.11 개정 이력이 붙어 있다. 오피스텔을 「건축법 시행령」 별표 1 제14호나목2)로 가리키며, 요율(매매·교환 1천분의 5, 임대차 등 1천분의 4)은 별표 2에 그대로 있다."},"36회-2차-013":{"한줄":"주택 외 중개대상물의 중개보수는 국토교통부령으로 정하며, 중개사무소 소재지 시·도 조례를 따르는 대상은 주택의 보수와 실비이므로 3번이 틀렸다.","근거":[{"법령":"공인중개사법","조문":"제32조제4항","원문":"④주택(부속토지를 포함한다. 이하 이 항에서 같다)의 중개에 대한 보수와 제2항에 따른 실비의 한도 등에 관하여 필요한 사항은 국토교통부령으로 정하는 범위 안에서 특별시ㆍ광역시ㆍ도 또는 특별자치도(이하 \"시ㆍ도\"라 한다)의 조례로 정하고, 주택 외의 중개대상물의 중개에 대한 보수는 국토교통부령으로 정한다."},{"법령":"공인중개사법 시행규칙","조문":"제20조제3항·제5항·제6항","원문":"③제1항 및 제2항의 경우에 중개대상물의 소재지와 중개사무소의 소재지가 다른 경우에는 개업공인중개사는 중개사무소의 소재지를 관할하는 시ㆍ도의 조례에서 정한 기준에 따라 중개보수 및 실비를 받아야 한다.\n3. 동일한 중개대상물에 대하여 동일 당사자간에 매매를 포함한 둘 이상의 거래가 동일 기회에 이루어지는 경우에는 매매계약에 관한 거래금액만을 적용한다.\n⑥중개대상물인 건축물 중 주택의 면적이 2분의 1이상인 경우에는 제1항의 규정을 적용하고, 주택의 면적이 2분의 1미만인 경우에는 제4항의 규정을 적용한다."},{"판례":"대법원 판례(아파트 분양권 매매의 중개보수)","요지":"분양권 매매를 중개한 경우 총 분양대금이 아니라 거래 당시 당사자 사이에 수수되는 대금, 즉 이미 낸 계약금·중도금에 프리미엄을 더한 금액을 거래금액으로 본다."}],"선지":[{"번호":1,"판정":"옳음","설명":"주택의 보수는 국토교통부령 범위 안에서 시·도 조례로 정한다(법 제32조제4항)."},{"번호":2,"판정":"옳음","설명":"주택 면적이 2분의 1 미만이면 주택 외 규정을 적용한다(규칙 제20조제6항)."},{"번호":3,"판정":"틀림","설명":"주택 외 중개대상물의 보수는 조례가 아니라 국토교통부령(규칙 제20조제4항)으로 정한다. 사무소 소재지 시·도 조례를 따르는 것은 주택의 보수와 실비다(규칙 제20조제3항)."},{"번호":4,"판정":"옳음","설명":"동일 당사자 간 동일 기회의 둘 이상 거래에 매매가 포함되면 매매계약의 거래금액만 적용한다(규칙 제20조제5항제3호)."},{"번호":5,"판정":"옳음","설명":"분양권 매매의 거래금액은 거래 당시 수수되는 대금(계약금·중도금·프리미엄)이라는 것이 판례다."}],"개념":[{"종류":"계산","제목":"월 차임이 있는 임대차의 중개보수(보증금 1,500만원, 월 차임 30만원, 주택)","단계":[{"설명":"월 차임 100배를 보증금에 합산(규칙 제20조제5항제1호 본문)","식":"1,500만원 + 30만원 × 100","값":"4,500만원"},{"설명":"합산액이 5천만원 미만이므로 100 대신 70을 곱해 다시 계산(같은 호 단서)","식":"1,500만원 + 30만원 × 70","값":"3,600만원"},{"설명":"5천만원 미만 임대차 요율 1천분의 5 적용(규칙 별표 1)","식":"3,600만원 × 5/1000","값":"18만원"},{"설명":"한도액 20만원 이내인지 확인","식":"18만원 ≤ 20만원","값":"18만원 이내에서 협의"}]},{"종류":"표","제목":"거래금액 계산과 보수 일반 규정","머리":["사항","내용","근거"],"행":[["교환계약","교환 대상 중개대상물 중 거래금액이 큰 물건의 가액","규칙 제20조제5항제2호"],["동일 기회 복수 거래","매매 거래금액만 적용(예: 매매 2억 5천만원 × 1천분의 4 = 100만원)","규칙 제20조제5항제3호"],["분양권 매매","계약금 + 중도금 + 프리미엄(총 분양대금 아님)","판례"],["중개보수를 받을 수 없는 경우","개업공인중개사의 고의·과실로 거래행위가 무효·취소·해제된 때","법 제32조제1항 단서"],["지급시기","약정에 따르고, 약정이 없으면 거래대금 지급이 완료된 날","영 제27조의2"],["실비","권리관계 확인 비용은 권리를 이전하려는 의뢰인에게, 계약금 등 반환채무이행 보장 비용은 권리를 취득하려는 의뢰인에게 영수증을 붙여 청구","규칙 제20조제2항"],["소재지가 다른 경우","주택의 보수·실비는 중개사무소 소재지 시·도 조례, 주택 외 보수는 국토교통부령","규칙 제20조제3항·제4항"],["한도 초과","어떤 명목으로든 초과해 금품을 받으면 금지행위","법 제33조제1항제3호"]]}],"함정":"3번을 옳게 읽고 5번을 틀렸다고 고르는 경우가 많다. 5번의 \"총 대금\"은 총 분양대금이 아니라 거래 당시 수수되는 대금을 뜻하는 판례 표현이라 옳은 문장이다. 3번은 소재지가 다를 때 조례를 따르는 규정(제20조제3항)이 제1항·제2항, 즉 주택 보수와 실비에만 걸린다는 점을 놓친 것이다."},"36회-2차-019":{"한줄":"책임준비금 적립비율은 공제료 수입액의 100분의 10 이상이다(영 제34조제3호).","근거":[{"법령":"공인중개사법 시행령","조문":"제34조제3호","원문":"3. 책임준비금의 적립비율 : 공제사고 발생률 및 공제금 지급액 등을 종합적으로 고려하여 정하되, 공제료 수입액의 100분의 10이상으로 정한다."},{"법령":"공인중개사법","조문":"제42조제2항ㆍ제3항","원문":"② 협회는 제1항에 따른 공제사업을 하고자 하는 때에는 공제규정을 제정하여 국토교통부장관의 승인을 얻어야 한다. 공제규정을 변경하고자 하는 때에도 또한 같다. ③ 제2항의 공제규정에는 대통령령으로 정하는 바에 따라 공제사업의 범위, 공제계약의 내용, 공제금, 공제료, 회계기준 및 책임준비금의 적립비율 등 공제사업의 운용에 관하여 필요한 사항을 정하여야 한다."},{"법령":"공인중개사법 시행령","조문":"제33조제2호","원문":"2. 공제사업의 부대업무로서 공제규정으로 정하는 사업"}],"선지":[{"번호":1,"판정":"옳음","설명":"공제사업을 하려는 협회는 공제규정을 제정하고 승인을 받아야 한다(법 제42조제2항)."},{"번호":2,"판정":"옳음","설명":"제정ㆍ변경 모두 국토교통부장관의 승인 대상이다(법 제42조제2항)."},{"번호":3,"판정":"옳음","설명":"부대업무로서 공제규정이 정하는 사업도 공제사업의 범위다(영 제33조제2호)."},{"번호":4,"판정":"옳음","설명":"범위, 계약 내용, 공제금, 공제료, 회계기준, 적립비율을 공제규정에 정한다(법 제42조제3항)."},{"번호":5,"판정":"틀림","설명":"적립비율의 하한은 100분의 10이다(영 제34조제3호)."}],"개념":[{"종류":"표","제목":"공제규정에 정할 사항","머리":["항목","내용","근거"],"행":[["공제계약의 내용","협회의 공제책임, 공제금, 공제료, 공제기간, 공제금 청구ㆍ지급절차, 구상ㆍ대위권, 계약 실효 등","영 제34조제1호"],["회계기준","공제사업을 손해배상기금과 복지기금으로 구분","영 제34조제2호"],["책임준비금 적립비율","공제료 수입액의 100분의 10 이상","영 제34조제3호"],["공제사업의 범위","공제기금 조성ㆍ공제금 지급, 부대업무","영 제33조"]]},{"종류":"표","제목":"공제사업 관련 승인과 공시","머리":["사항","내용","근거"],"행":[["공제규정 제정ㆍ변경","국토교통부장관 승인","법 제42조제2항"],["책임준비금 다른 용도 사용","국토교통부장관 승인","법 제42조제4항"],["회계 구분","다른 회계와 구분하여 별도 회계로 관리","법 제42조제4항"],["운용실적 공시","매 회계연도 종료 후 3개월 이내 일간신문 또는 협회보에 공시하고 협회 홈페이지에 게시","영 제35조"]]}],"함정":"적립비율의 숫자를 20으로 바꿔 놓은 문장이다. 나머지 네 선지는 승인권자와 공제규정 내용을 그대로 옮겼으므로, 숫자 한 곳만 확인하면 된다.","개정":"2026.2.27 개정으로 협회의 이름이 「한국공인중개사협회」로 정해졌다(법 제41조제1항). 공제규정 내용은 그대로다."},"36회-2차-017":{"한줄":"직접 거래(제33조제1항제6호), 거짓된 언행(제4호), 이중 계약서 작성(제36조제1항제6호)은 모두 자격정지 사유다.","근거":[{"법령":"공인중개사법","조문":"제36조제1항제6호ㆍ제7호","원문":"6. 제26조제3항의 규정을 위반하여 거래계약서에 거래금액 등 거래내용을 거짓으로 기재하거나 서로 다른 둘 이상의 거래계약서를 작성한 경우 7. 제33조제1항 각 호에 규정된 금지행위를 한 경우"},{"법령":"공인중개사법","조문":"제33조제1항제4호ㆍ제6호","원문":"4. 해당 중개대상물의 거래상의 중요사항에 관하여 거짓된 언행 그 밖의 방법으로 중개의뢰인의 판단을 그르치게 하는 행위 6. 중개의뢰인과 직접 거래를 하거나 거래당사자 쌍방을 대리하는 행위"},{"법령":"공인중개사법 시행규칙","조문":"별표 3","원문":"6. 법 제26조제3항의 규정을 위반하여 거래계약서에 거래금액 등 거래내용을 거짓으로 기재하거나 서로 다른 2 이상의 거래계약서를 작성한 경우 / 법 제36조제1항제6호 / 자격정지 6월"}],"선지":[{"번호":1,"판정":"-","설명":"ㄴ만으로는 부족하다. ㄱ과 ㄷ도 자격정지 사유다."},{"번호":2,"판정":"-","설명":"ㄱ, ㄴ만으로는 부족하다. ㄷ도 자격정지 사유다."},{"번호":3,"판정":"-","설명":"ㄱ, ㄷ만으로는 부족하다. ㄴ도 자격정지 사유다."},{"번호":4,"판정":"-","설명":"ㄴ, ㄷ만으로는 부족하다. ㄱ도 자격정지 사유다."},{"번호":5,"판정":"-","설명":"ㄱ, ㄴ, ㄷ 모두 자격정지 사유이므로 맞는 조합이다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"직접 거래는 제33조제1항제6호 금지행위이고, 금지행위 위반은 제36조제1항제7호에 따라 자격정지 사유다."},{"기호":"ㄴ","판정":"옳음","설명":"거짓된 언행은 제33조제1항제4호 금지행위이므로 제36조제1항제7호에 해당한다."},{"기호":"ㄷ","판정":"옳음","설명":"서로 다른 둘 이상의 거래계약서 작성은 제36조제1항제6호에 해당한다."}],"개념":[{"종류":"표","제목":"소속공인중개사 자격정지 기준 (시행규칙 별표 3)","머리":["위반행위","근거","자격정지"],"행":[["둘 이상의 중개사무소에 소속","법 제36조제1항제1호","6월"],["인장등록을 하지 않거나 등록하지 않은 인장 사용","제2호","3월"],["성실ㆍ정확한 확인ㆍ설명을 하지 않거나 근거자료를 제시하지 않음","제3호","3월"],["확인ㆍ설명서에 서명 및 날인을 하지 않음","제4호","3월"],["거래계약서에 서명 및 날인을 하지 않음","제5호","3월"],["거래계약서에 거래금액 등을 거짓 기재하거나 서로 다른 둘 이상의 계약서 작성","제6호","6월"],["제33조제1항 금지행위","제7호","6월"]]},{"종류":"비교","제목":"자격취소와 자격정지","왼쪽":{"이름":"자격취소 (법 제35조, 필요적)","항목":["시ㆍ도지사가 취소하여야 한다","부정한 방법으로 자격 취득","성명 사용 허락 또는 자격증 양도ㆍ대여","자격정지 기간 중 중개업무(소속공인중개사ㆍ중개보조원ㆍ법인 사원ㆍ임원이 되는 경우 포함)","직무 관련 금고 이상의 형 선고(집행유예 포함)","청문 실시"]},"오른쪽":{"이름":"자격정지 (법 제36조, 임의적)","항목":["시ㆍ도지사가 정지할 수 있다","소속공인중개사로서 업무를 수행하는 기간 중의 위반이 대상","정지 기간은 6개월의 범위 안","사유는 법 제36조제1항 각 호 7가지","등록관청은 사실을 알게 되면 지체 없이 시ㆍ도지사에 통보"]}}],"함정":"금지행위 아홉 가지가 모두 자격정지 사유다(제7호). 그래서 직접 거래와 거짓된 언행도 고르고, 이중 계약서 작성(제6호)까지 포함해야 한다. 하나라도 빼면 오답이 된다."},"36회-2차-016":{"한줄":"자격취소 사유가 되는 형은 금고 이상(집행유예 포함)이므로 벌금형은 해당하지 않는다.","근거":[{"법령":"공인중개사법","조문":"제35조제1항제2호~제4호","원문":"2. 제7조제1항의 규정을 위반하여 다른 사람에게 자기의 성명을 사용하여 중개업무를 하게 하거나 공인중개사자격증을 양도 또는 대여한 경우 3. 제36조에 따른 자격정지처분을 받고 그 자격정지기간 중에 중개업무를 행한 경우(다른 개업공인중개사의 소속공인중개사ㆍ중개보조원 또는 법인인 개업공인중개사의 사원ㆍ임원이 되는 경우를 포함한다) 4. 이 법 또는 공인중개사의 직무와 관련하여 「형법」 제114조, 제231조, 제234조, 제347조, 제355조 또는 제356조를 위반하여 금고 이상의 형(집행유예를 포함한다)을 선고받은 경우"}],"선지":[{"번호":1,"판정":"옳음","설명":"자격정지 기간 중 중개업무는 제35조제1항제3호 취소 사유다."},{"번호":2,"판정":"옳음","설명":"정지 기간 중 다른 개업공인중개사의 소속공인중개사가 되는 경우도 제3호 괄호에 포함된다."},{"번호":3,"판정":"옳음","설명":"정지 기간 중 법인인 개업공인중개사의 임원이 되는 경우도 제3호 괄호에 포함된다."},{"번호":4,"판정":"틀림","설명":"제4호는 금고 이상의 형을 요건으로 한다. 벌금형은 자격취소 사유가 아니다."},{"번호":5,"판정":"옳음","설명":"성명 사용을 허락한 경우는 제35조제1항제2호 취소 사유다."}],"개념":[{"종류":"표","제목":"공인중개사 자격취소 사유 (법 제35조제1항)","머리":["호","사유","비고"],"행":[["1","부정한 방법으로 공인중개사 자격 취득",""],["2","다른 사람에게 자기 성명을 사용하여 중개업무를 하게 하거나 자격증을 양도ㆍ대여","법 제7조제1항 위반"],["3","자격정지처분을 받고 정지 기간 중 중개업무를 행함","다른 개업공인중개사의 소속공인중개사ㆍ중개보조원, 법인의 사원ㆍ임원이 되는 경우 포함"],["4","이 법 또는 직무와 관련하여 형법 제114조, 제231조, 제234조, 제347조, 제355조, 제356조 위반으로 금고 이상의 형 선고","집행유예 포함"]]},{"종류":"흐름","제목":"자격취소 절차","단계":[{"이름":"취소 사유 확인","설명":"시ㆍ도지사가 제35조제1항 각 호 사유를 확인"},{"이름":"청문","설명":"자격을 취소하려면 시ㆍ도지사가 청문을 실시(법 제35조제2항)"},{"이름":"자격취소","설명":"시ㆍ도지사가 공인중개사 자격을 취소"},{"이름":"자격증 반납","설명":"취소된 자는 자격증을 시ㆍ도지사에게 반납. 분실 등으로 반납할 수 없으면 사유서 제출(법 제35조제3항ㆍ제4항)"}]}],"함정":"「형」이 나오면 모두 취소 사유로 고르기 쉽다. 요건은 금고 이상이고, 벌금형은 빠져 있다. 정지 기간 중에 소속공인중개사나 법인 임원이 되는 것은 중개업무를 직접 하지 않아도 취소 사유다."},"36회-2차-029":{"한줄":"계약 조건이 바뀌면 부동산등기법에 따른 등기신청 전에 변경신고를 한다(시행규칙 제3조제3항).","근거":[{"법령":"부동산 거래신고 등에 관한 법률 시행규칙","조문":"제3조제3항","원문":"③ 거래당사자 또는 개업공인중개사는 부동산 거래계약 신고 내용 중 다음 각 호의 어느 하나에 해당하는 사항이 변경된 경우에는 「부동산등기법」에 따른 부동산에 관한 등기신청 전에 신고관청에 신고 내용의 변경을 신고할 수 있다. … 4. 계약의 조건 또는 기한"},{"법령":"부동산 거래신고 등에 관한 법률 시행규칙","조문":"제2조제14항","원문":"⑭ 법 제25조에 따라 구축된 부동산 거래계약 관련 정보시스템(이하 \"부동산거래계약시스템\"이라 한다)을 통하여 부동산 거래계약을 체결한 경우에는 부동산 거래계약이 체결된 때에 제1항, 제2항 또는 제4항의 부동산거래계약 신고서를 제출한 것으로 본다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제3조제1항","원문":"1. 부동산의 매매계약 2. 「택지개발촉진법」, 「주택법」 등 대통령령으로 정하는 법률에 따른 부동산에 대한 공급계약 3. 다음 각 목의 어느 하나에 해당하는 지위의 매매계약"},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"별표 1 제1호 자목","원문":"자. 개업공인중개사가 거래계약서를 작성ㆍ교부한 경우에는 다음의 사항 1) 개업공인중개사의 인적사항 2) 개업공인중개사가 「공인중개사법」 제9조에 따라 개설등록한 중개사무소의 상호ㆍ전화번호 및 소재지"}],"선지":[{"번호":1,"판정":"옳음","설명":"거래신고 대상은 매매계약, 공급계약, 공급받는 지위 등의 매매계약뿐이다. 임대차계약은 포함되지 않는다(법 제3조제1항)."},{"번호":2,"판정":"옳음","설명":"신고관청은 부동산 소재지를 관할하는 시장ㆍ군수 또는 구청장이다(법 제3조제1항). 광역시 구 소재 토지는 구청장이다."},{"번호":3,"판정":"옳음","설명":"거래계약시스템으로 계약을 체결하면 체결 시점에 신고서를 낸 것으로 본다(규칙 제2조제14항)."},{"번호":4,"판정":"틀림","설명":"변경신고는 등기신청 전에 한다(규칙 제3조제3항제4호)."},{"번호":5,"판정":"옳음","설명":"개업공인중개사가 계약서를 작성ㆍ교부한 경우 그의 인적사항과 중개사무소 상호ㆍ전화번호ㆍ소재지가 신고사항이다(영 별표 1 제1호 자목)."}],"개념":[{"종류":"흐름","제목":"부동산 거래신고 절차","단계":[{"이름":"계약 체결","설명":"매매계약, 공급계약, 공급받는 지위의 매매계약 체결"},{"이름":"거래신고","설명":"계약 체결일부터 30일 이내. 거래당사자가 공동 신고하되, 개업공인중개사가 계약서를 작성ㆍ교부했으면 그가 신고(법 제3조제1항ㆍ제3항)"},{"이름":"신고필증 발급","설명":"신고관청이 내용을 확인한 후 지체 없이 발급. 매수인은 필증 발급 시 검인을 받은 것으로 봄(법 제3조제5항ㆍ제6항)"},{"이름":"정정ㆍ변경","설명":"정정은 잘못 기재된 사항에 대해 신청, 변경은 등기신청 전에 신고(규칙 제3조)"},{"이름":"해제등 신고","설명":"해제ㆍ무효ㆍ취소가 확정된 날부터 30일 이내 공동 신고(법 제3조의2제1항)"}]},{"종류":"표","제목":"신고 내용의 정정과 변경 (시행규칙 제3조)","머리":["구분","사유","시기"],"행":[["정정신청","거래당사자 주소ㆍ전화번호, 거래 지분 비율, 개업공인중개사 전화번호ㆍ상호ㆍ소재지, 건축물 종류, 지목ㆍ면적ㆍ지분ㆍ대지권비율이 잘못 기재된 경우","잘못 기재된 때"],["변경신고","거래 지분 비율, 거래 지분, 면적, 계약의 조건 또는 기한, 거래가격, 중도금ㆍ잔금 및 지급일, 공동매수인 일부 제외, 일부 부동산 제외, 위탁관리인 정보","등기신청 전"]]}],"함정":"「등기신청 전」과 「등기신청 후」만 바꾼 선지다. 정정은 잘못 적힌 사항, 변경은 신고 후 달라진 사항이고, 변경신고는 등기 전에 마쳐야 한다."},"36회-2차-025":{"한줄":"법인의 등기 현황은 법인 거래 신고사항이지만, 주택법에 따른 공급계약(법 제3조제1항제2호)은 그 대상에서 제외된다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"별표 1 제2호 가목","원문":"가. 법인의 현황에 관한 다음의 사항(거래당사자 중 국가등이 포함되어 있거나 거래계약이 법 제3조제1항제2호 또는 같은 항 제3호가목에 해당하는 경우는 제외한다) 1) 법인의 등기 현황 2) 법인과 거래상대방 간의 관계가 다음의 어느 하나에 해당하는지 여부"},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"별표 1 제1호 나목ㆍ마목ㆍ바목","원문":"나. 계약 체결일, 중도금 지급일 및 잔금 지급일 … 마. 실제 거래가격 바. 계약의 조건이나 기한이 있는 경우에는 그 조건 또는 기한"},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"제3조제3항제6호","원문":"③ 법 제3조제1항제2호에서 「택지개발촉진법」, 「주택법」 등 대통령령으로 정하는 법률이란 다음 각 호의 법률을 말한다. … 6. 「주택법」"}],"선지":[{"번호":1,"판정":"옳음","설명":"실제 거래가격은 모든 거래의 공통 신고사항이다(별표 1 제1호 마목)."},{"번호":2,"판정":"옳음","설명":"계약 체결일은 공통 신고사항이다(별표 1 제1호 나목)."},{"번호":3,"판정":"틀림","설명":"주택법에 따른 공급계약은 법 제3조제1항제2호에 해당하므로 법인 현황(등기 현황 등)은 신고하지 않는다(별표 1 제2호 가목 괄호)."},{"번호":4,"판정":"옳음","설명":"조건이나 기한이 있으면 신고한다(별표 1 제1호 바목)."},{"번호":5,"판정":"옳음","설명":"중도금 지급일과 잔금 지급일은 공통 신고사항이다(별표 1 제1호 나목)."}],"개념":[{"종류":"표","제목":"부동산 거래 신고사항 (시행령 별표 1)","머리":["구분","신고사항"],"행":[["공통","당사자 인적사항, 계약 체결일ㆍ중도금일ㆍ잔금일, 소재지ㆍ지번ㆍ지목ㆍ면적, 종류, 실제 거래가격, 조건ㆍ기한, 위탁관리인 인적사항(국내 주소 없는 매수인), 외국인 매수인의 체류자격, 개업공인중개사 인적사항"],["법인이 주택 거래","법인의 등기 현황, 법인과 거래상대방의 임원 관계. 국가등이 당사자이거나 공급계약ㆍ공급받는 지위(제3호가목)는 제외"],["법인이 주택 매수","주택 취득목적, 자금조달계획ㆍ지급방식(투기과열지구는 증명서류 첨부), 이용계획"],["법인 외의 자가 6억원 이상 주택 매수, 또는 투기과열지구ㆍ조정대상지역 주택 매수","자금조달계획ㆍ지급방식, 본인 입주 여부ㆍ입주 예정 시기 등 이용계획"],["허가구역 소재 주택 매수","자금조달계획(증명서류 첨부), 이용계획"],["토지 매수","수도권등 1억원 이상, 그 외 지역 6억원 이상이면 자금조달계획과 토지이용계획. 지분 매수는 수도권등 전부, 그 외 지역은 6억원 이상"]]},{"종류":"비교","제목":"법인 거래 중 법인 현황 신고 여부","왼쪽":{"이름":"법인 현황을 신고하는 경우","항목":["법인이 주택을 사고파는 일반 매매계약","법인 거래상대방의 임원 관계 확인이 필요한 거래"]},"오른쪽":{"이름":"법인 현황을 신고하지 않는 경우","항목":["거래당사자 중 국가등이 포함된 경우","법 제3조제1항제2호 공급계약(주택법ㆍ택지개발촉진법 등)","법 제3조제1항제3호가목 공급받는 자로 선정된 지위의 매매"]}}],"함정":"법인이 거래하면 법인의 등기 현황을 신고한다고 단정하면 3번을 고르지 못한다. 공급계약은 괄호 안 예외에 들어가 법인 현황 신고가 없다. 법인이 매수자이면 취득목적과 자금조달계획은 신고한다."},"36회-2차-039":{"한줄":"법인묘지의 설치ㆍ관리 허가는 묘지 설치ㆍ관리를 목적으로 민법에 따라 설립된 재단법인에 한정되므로 상법상 회사는 받을 수 없다.","근거":[{"법령":"장사 등에 관한 법률","조문":"제14조제5항","원문":"⑤ 시장등은 묘지의 설치ㆍ관리를 목적으로 「민법」에 따라 설립된 재단법인에 한정하여 법인묘지의 설치ㆍ관리를 허가할 수 있다."},{"법령":"장사 등에 관한 법률","조문":"제14조제4항","원문":"④ 가족묘지, 종중ㆍ문중묘지 또는 법인묘지를 설치ㆍ관리하려는 자는 보건복지부령으로 정하는 바에 따라 해당 묘지를 관할하는 시장등의 허가를 받아야 한다."},{"법령":"장사 등에 관한 법률","조문":"제18조제2항","원문":"② 개인묘지는 30제곱미터를 초과하여서는 아니 된다."},{"법령":"장사 등에 관한 법률","조문":"제8조제1항","원문":"① 매장을 한 자는 매장 후 30일 이내에 매장지를 관할하는 특별자치시장ㆍ특별자치도지사ㆍ시장ㆍ군수ㆍ구청장(이하 \"시장등\"이라 한다)에게 신고하여야 한다."},{"법령":"장사 등에 관한 법률 시행령","조문":"제25조제1호","원문":"법 제21조 단서에서 \"대통령령으로 정하는 경우\"란 다음 각 호의 어느 하나에 해당하는 경우를 말한다. 1. 70세 이상인 자의 묘지용으로 사용하기 위한 경우"}],"선지":[{"번호":1,"판정":"옳음","설명":"개인묘지 면적은 30제곱미터를 넘을 수 없다(법 제18조제2항)."},{"번호":2,"판정":"틀림","설명":"법인묘지는 민법상 재단법인만 허가받을 수 있다(법 제14조제5항)."},{"번호":3,"판정":"옳음","설명":"매장을 한 자는 묘지 종류와 관계없이 매장 후 30일 이내에 신고한다(법 제8조제1항)."},{"번호":4,"판정":"옳음","설명":"문중묘지는 허가 대상이다(법 제14조제4항)."},{"번호":5,"판정":"옳음","설명":"사설묘지 설치자도 매장될 자의 사망 전에는 매매할 수 없지만, 70세 이상인 자가 요청하는 경우는 예외다(법 제21조, 영 제25조제1호)."}],"개념":[{"종류":"표","제목":"사설묘지의 종류와 설치 절차","머리":["종류","설치 주체","절차","면적 제한"],"행":[["개인묘지","1기의 분묘 또는 배우자 관계였던 자의 분묘를 같은 구역에","설치 후 30일 이내 시장등에게 신고(법 제14조제2항)","30제곱미터 이하(법 제18조제2항)"],["가족묘지","민법상 친족관계였던 자의 분묘","시장등의 허가(법 제14조제4항)","가족당 1개소, 100제곱미터 이하(시행령 사설묘지 설치기준)"],["종중ㆍ문중묘지","종중이나 문중 구성원의 분묘","시장등의 허가","분묘 1기당 10제곱미터(합장 15제곱미터) 이내(법 제18조제1항)"],["법인묘지","민법상 재단법인이 불특정 다수인의 분묘를 설치","시장등의 허가","분묘 1기당 10제곱미터(합장 15제곱미터) 이내(법 제18조제1항)"]]},{"종류":"표","제목":"묘지 사전 매매 금지의 예외 (시행령 제25조)","머리":["호","예외 사유"],"행":[["1","70세 이상인 자의 묘지용으로 사용하기 위한 경우"],["2","뇌사자의 묘지용으로 사용하기 위한 경우"],["3","질병 등으로 6개월 이내에 사망이 예측되는 자의 묘지용(의사의 진단서 첨부)"],["4","합장을 하기 위한 경우(매장된 자의 배우자에 한정)"],["5","공설묘지의 수급을 위하여 지방자치단체의 조례로 정하는 경우"]]}],"함정":"「상법상 회사」도 허가받는다고 넓게 생각하기 쉽다. 법인묘지는 민법상 재단법인으로 한정된다. 개인묘지는 신고, 가족ㆍ종중ㆍ문중ㆍ법인묘지는 허가라는 구분도 같이 외운다."},"36회-2차-038":{"한줄":"임차인의 차임연체액이 3기의 차임액에 달하면 임대인은 계약을 해지할 수 있다(법 제10조의8).","근거":[{"법령":"상가건물 임대차보호법","조문":"제10조의8","원문":"임차인의 차임연체액이 3기의 차임액에 달하는 때에는 임대인은 계약을 해지할 수 있다."},{"법령":"상가건물 임대차보호법","조문":"제11조제2항","원문":"② 제1항에 따른 증액 청구는 임대차계약 또는 약정한 차임 등의 증액이 있은 후 1년 이내에는 하지 못한다."},{"법령":"상가건물 임대차보호법","조문":"제5조제1항","원문":"① 임차인이 임차건물에 대하여 보증금반환청구소송의 확정판결, 그 밖에 이에 준하는 집행권원에 의하여 경매를 신청하는 경우에는 「민사집행법」 제41조에도 불구하고 반대의무의 이행이나 이행의 제공을 집행개시의 요건으로 하지 아니한다."},{"법령":"상가건물 임대차보호법","조문":"제10조제2항","원문":"② 임차인의 계약갱신요구권은 최초의 임대차기간을 포함한 전체 임대차기간이 10년을 초과하지 아니하는 범위에서만 행사할 수 있다."},{"법령":"상가건물 임대차보호법","조문":"제11조의2제2항","원문":"② 제1항에 따른 해지는 임대인이 계약해지의 통고를 받은 날부터 3개월이 지나면 효력이 발생한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"증액 청구는 증액이 있은 후 1년 이내에는 하지 못한다(법 제11조제2항)."},{"번호":2,"판정":"틀림","설명":"확정판결에 의한 경매 신청은 반대의무 이행을 집행개시 요건으로 하지 않는다(법 제5조제1항)."},{"번호":3,"판정":"틀림","설명":"갱신요구권은 전체 임대차기간 10년을 넘지 않는 범위에서 행사한다(법 제10조제2항)."},{"번호":4,"판정":"옳음","설명":"3기의 차임액에 달하는 연체가 있으면 해지할 수 있다(법 제10조의8)."},{"번호":5,"판정":"틀림","설명":"폐업으로 인한 해지는 임대인이 통고를 받은 날부터 3개월이 지나면 효력이 발생한다(법 제11조의2제2항)."}],"개념":[{"종류":"비교","제목":"상가건물 임대차와 주택임대차의 갱신","왼쪽":{"이름":"상가건물 임대차보호법","항목":["갱신요구 시기: 기간 만료 6개월 전부터 1개월 전까지(법 제10조제1항)","전체 임대차기간 10년 범위(법 제10조제2항)","거절 사유: 3기의 차임액에 이르는 연체 등(법 제10조제1항제1호)","임대인이 기간 내 통지하지 않으면 전과 같은 조건으로 갱신, 존속기간 1년(법 제10조제4항)","임차인은 언제든 해지 통고, 임대인이 통고를 받은 날부터 3개월 후 효력(법 제10조제5항)"]},"오른쪽":{"이름":"주택임대차보호법","항목":["갱신요구 시기: 기간 만료 6개월 전부터 2개월 전까지(법 제6조의3제1항)","갱신요구권은 1회, 갱신 기간 2년(법 제6조의3제2항)","거절 사유: 2기의 차임액에 이르는 연체, 임대인 실거주 등(법 제6조의3제1항)","기간 정함이 없거나 2년 미만이면 2년으로 봄(법 제4조제1항)","임대인이 6개월~2개월 전 통지를 하지 않으면 전 임대차와 같은 조건으로 갱신(법 제6조제1항)"]}},{"종류":"표","제목":"차임ㆍ보증금 증액 제한","머리":["구분","증액 상한","간격 제한","근거"],"행":[["상가건물","청구 당시 차임ㆍ보증금의 100분의 5","증액이 있은 후 1년 이내 불가","법 제11조제1항ㆍ제2항, 영 제4조"],["주택","약정한 차임등의 20분의 1","증액이 있은 후 1년 이내 불가","법 제7조, 영 제8조제1항"]]}],"함정":"숫자 세 곳을 바꾼 선지가 많다. 상가 갱신요구 전체 기간은 10년, 폐업 해지는 통고 후 3개월, 증액은 1년 간격이다. 주택임대차의 갱신요구권 1회와 섞어 읽지 않는다."},"36회-2차-040":{"한줄":"대항력 없는 임차권은 경매로 임차주택이 경락되면 소멸한다(법 제3조의5). 갱신 거절 사유와 갱신요구 횟수는 ㄱ, ㄴ이 반대로 적혔다.","근거":[{"법령":"주택임대차보호법","조문":"제3조의5","원문":"임차권은 임차주택에 대하여 「민사집행법」에 따른 경매가 행하여진 경우에는 그 임차주택의 경락(競落)에 따라 소멸한다. 다만, 보증금이 모두 변제되지 아니한, 대항력이 있는 임차권은 그러하지 아니하다."},{"법령":"주택임대차보호법","조문":"제6조의3제1항제2호","원문":"2. 임차인이 거짓이나 그 밖의 부정한 방법으로 임차한 경우"},{"법령":"주택임대차보호법","조문":"제6조의3제2항","원문":"② 임차인은 제1항에 따른 계약갱신요구권을 1회에 한하여 행사할 수 있다. 이 경우 갱신되는 임대차의 존속기간은 2년으로 본다."}],"선지":[{"번호":1,"판정":"-","설명":"ㄱ은 틀린 보기다."},{"번호":2,"판정":"-","설명":"ㄷ만 옳으므로 맞는 조합이다."},{"번호":3,"판정":"-","설명":"ㄱ, ㄴ 모두 틀린 보기다."},{"번호":4,"판정":"-","설명":"ㄴ이 틀린 보기이므로 조합이 맞지 않는다."},{"번호":5,"판정":"-","설명":"ㄱ, ㄴ이 틀린 보기이므로 조합이 맞지 않는다."}],"보기판정":[{"기호":"ㄱ","판정":"틀림","설명":"거짓이나 부정한 방법으로 임차한 경우는 임대인이 갱신요구를 거절할 수 있는 사유다(법 제6조의3제1항제2호)."},{"기호":"ㄴ","판정":"틀림","설명":"갱신요구권은 1회에 한하여 행사하며, 갱신 기간은 2년이다(법 제6조의3제2항)."},{"기호":"ㄷ","판정":"옳음","설명":"대항력 없는 임차권은 경매로 경락되면 소멸한다. 소멸하지 않는 것은 보증금이 모두 변제되지 않은 대항력 있는 임차권이다(법 제3조의5)."}],"개념":[{"종류":"표","제목":"주택임대차 계약갱신요구권","머리":["항목","내용","근거"],"행":[["행사 기간","임대차기간 만료 6개월 전부터 2개월 전까지","법 제6조의3제1항, 제6조제1항"],["횟수와 기간","1회에 한하여, 갱신 존속기간 2년","법 제6조의3제2항"],["갱신 조건","전 임대차와 동일. 차임과 보증금은 법 제7조 범위에서 증감 가능","법 제6조의3제3항"],["거절 사유","2기의 차임액 연체, 거짓이나 부정한 방법으로 임차, 상당한 보상 합의, 무단 전대, 고의ㆍ중과실 파손, 멸실, 철거ㆍ재건축, 임대인 또는 직계존비속의 실거주, 중대한 의무 위반 등","법 제6조의3제1항"],["실거주 거절 후 제3자 임대","임대인이 손해배상 책임","법 제6조의3제5항ㆍ제6항"]]},{"종류":"비교","제목":"경매 시 임차권의 운명","왼쪽":{"이름":"대항력 없는 임차권","항목":["경매로 임차주택이 경락되면 소멸(법 제3조의5 본문)","매수인에게 임차권을 주장할 수 없다"]},"오른쪽":{"이름":"대항력 있는 임차권","항목":["보증금이 모두 변제되지 않았다면 소멸하지 않는다(법 제3조의5 단서)","대항요건: 주택의 인도와 주민등록. 전입신고한 다음 날부터 제삼자에 대해 효력(법 제3조제1항)"]}}],"함정":"거절 사유와 거절 불가를 거꾸로 읽으면 ㄱ을 고르게 된다. 거짓이나 부정한 방법으로 임차한 사실은 임대인이 갱신을 거절할 수 있는 사유다. 상가의 10년 범위와 달리 주택은 1회, 2년이다."},"36회-2차-037":{"한줄":"과징금 납부기한 연장 신청은 납부를 통지받은 날부터 30일 이내에 한다(법 제5조의2제2항).","근거":[{"법령":"부동산 실권리자명의 등기에 관한 법률","조문":"제5조의2제2항","원문":"② 과징금 납부의무자가 제1항에 따른 과징금 납부기한의 연장 또는 분할 납부를 신청하려는 경우에는 과징금 납부를 통지받은 날부터 30일 이내에 특별자치도지사ㆍ특별자치시장ㆍ시장ㆍ군수 또는 구청장에게 신청하여야 한다."},{"법령":"부동산 실권리자명의 등기에 관한 법률","조문":"제5조제1항ㆍ제4항","원문":"① 다음 각 호의 어느 하나에 해당하는 자에게는 해당 부동산 가액(價額)의 100분의 30에 해당하는 금액의 범위에서 과징금을 부과한다. 1. 제3조제1항을 위반한 명의신탁자 … ④ 제1항에 따른 과징금이 대통령령으로 정하는 금액을 초과하는 경우에는 그 초과하는 부분은 대통령령으로 정하는 바에 따라 물납(物納)할 수 있다."},{"법령":"부동산 실권리자명의 등기에 관한 법률","조문":"제6조제1항ㆍ제3항","원문":"① 제5조제1항제1호에 따른 과징금을 부과받은 자는 지체 없이 해당 부동산에 관한 물권을 자신의 명의로 등기하여야 한다. … ③ 이행강제금에 관하여는 제5조제4항부터 제7항까지의 규정을 준용한다."}],"선지":[{"번호":1,"판정":"-","설명":"ㄱ만으로는 틀린 조합이다. ㄱ이 틀린 보기다."},{"번호":2,"판정":"-","설명":"ㄷ만 옳으므로 맞는 조합이다."},{"번호":3,"판정":"-","설명":"ㄱ, ㄴ이 모두 틀린 보기다."},{"번호":4,"판정":"-","설명":"ㄴ이 틀린 보기이므로 조합이 맞지 않는다."},{"번호":5,"판정":"-","설명":"ㄱ, ㄴ이 틀린 보기이므로 조합이 맞지 않는다."}],"보기판정":[{"기호":"ㄱ","판정":"틀림","설명":"물납은 대통령령으로 정하는 금액을 초과하는 부분에 한해 할 수 있다. 전부를 물납할 수 없다(법 제5조제4항, 제6조제3항)."},{"기호":"ㄴ","판정":"틀림","설명":"과징금 부과대상은 명의신탁자다. 과징금을 부과받은 명의신탁자가 물권을 자기 명의로 등기해야 한다(법 제5조제1항제1호, 제6조제1항)."},{"기호":"ㄷ","판정":"옳음","설명":"연장 신청은 과징금 납부를 통지받은 날부터 30일 이내에 한다(법 제5조의2제2항)."}],"개념":[{"종류":"흐름","제목":"명의신탁 제재 절차","단계":[{"이름":"명의신탁 위반","설명":"명의신탁자가 실권리자명의 등기 의무(법 제3조제1항)를 위반"},{"이름":"과징금 부과","설명":"부동산 소재지 관할 시장ㆍ군수ㆍ구청장이 부동산 가액의 100분의 30 범위에서 부과. 소유권은 기준시가로 평가(법 제5조)"},{"이름":"기한 연장ㆍ분할 납부","설명":"재해, 사업 위기, 자금사정 곤란 등의 사유. 납부 통지를 받은 날부터 30일 이내 신청(법 제5조의2)"},{"이름":"실명등기","설명":"과징금을 부과받은 명의신탁자가 지체 없이 해당 부동산 물권을 자기 명의로 등기(법 제6조제1항)"},{"이름":"이행강제금","설명":"과징금 부과일부터 1년이 지난 때 부동산평가액의 100분의 10, 다시 1년이 지난 때 100분의 20(법 제6조제2항)"}]},{"종류":"표","제목":"과징금과 이행강제금","머리":["구분","대상","금액","물납"],"행":[["과징금","명의신탁자 등(법 제5조제1항)","부동산 가액의 100분의 30 범위","대통령령으로 정하는 금액 초과 부분만"],["이행강제금","과징금을 부과받고도 자기 명의로 등기하지 않은 자(법 제6조제1항)","1년 경과 시 부동산평가액의 100분의 10, 다시 1년 경과 시 100분의 20","과징금 규정 준용. 초과 부분만"]]}],"함정":"명의수탁자는 과징금 대상이 아니라는 점이 ㄴ의 핵심이다. 등기 의무를 지는 사람도 명의신탁자다. 물납은 기준 금액을 넘는 부분에만 허용되므로 전액 물납(ㄱ)은 틀린다."},"36회-2차-035":{"한줄":"확인ㆍ설명 사항을 적은 서면의 사본은 사건카드에 철하여 5년간 보존한다(규칙 제16조제2항).","근거":[{"법령":"공인중개사의 매수신청대리인 등록 등에 관한 규칙","조문":"제16조제2항","원문":"② 개업공인중개사는 위임계약을 체결한 경우 제1항의 확인ㆍ설명 사항을 서면으로 작성하여 서명날인한 후 위임인에게 교부하고, 그 사본을 사건카드에 철하여 5년간 보존하여야 한다."},{"법령":"공인중개사의 매수신청대리인 등록 등에 관한 규칙","조문":"제2조제5호","원문":"5. 「민사집행법」 제140조의 규정에 따른 공유자의 우선매수신고"},{"법령":"공인중개사의 매수신청대리인 등록 등에 관한 규칙","조문":"제5조제1호","원문":"공인중개사가 매수신청대리인으로 등록하기 위한 요건은 다음 각 호와 같다. 1. 개업공인중개사이거나 법인인 개업공인중개사일 것"},{"법령":"공인중개사의 매수신청대리인 등록 등에 관한 규칙","조문":"제6조제1호 / 제21조제1항제2호","원문":"제6조 1. 매수신청대리인 등록이 취소된 후 3년이 지나지 아니한 자. 단, 제21조제1항제2호에 의한 등록 취소는 제외한다. / 제21조제1항제2호 법 제21조 또는 이 규칙 제13조의2제1항의 규정에 따라 폐업신고를 한 경우"},{"법령":"공인중개사의 매수신청대리인 등록 등에 관한 규칙","조문":"제17조제3항","원문":"③ 개업공인중개사는 제1항의 규정에 따라 보수를 받은 경우 예규에서 정한 양식에 의한 영수증을 작성하여 서명날인한 후 위임인에게 교부하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"공유자의 우선매수신고는 대리권 범위에 들어 있다(규칙 제2조제5호)."},{"번호":2,"판정":"옳음","설명":"등록은 개업공인중개사만 할 수 있다(규칙 제5조제1호)."},{"번호":3,"판정":"틀림","설명":"보존 기간은 5년이다(규칙 제16조제2항)."},{"번호":4,"판정":"옳음","설명":"보수를 받으면 예규 양식의 영수증을 작성ㆍ서명날인하여 교부한다(규칙 제17조제3항)."},{"번호":5,"판정":"옳음","설명":"폐업신고에 따른 등록 취소는 3년 결격 기간에서 제외된다(규칙 제6조제1호 단서, 제21조제1항제2호)."}],"개념":[{"종류":"표","제목":"매수신청대리권의 범위 (규칙 제2조)","머리":["호","행위"],"행":[["1","매수신청 보증의 제공"],["2","입찰표의 작성 및 제출"],["3","차순위매수신고"],["4","매수신청 보증을 돌려 줄 것을 신청하는 행위"],["5","공유자의 우선매수신고"],["6","구 임대주택법에 따른 임차인의 임대주택 우선매수신고"],["7","우선매수신고에 따라 차순위매수신고인으로 보게 되는 경우 그 지위를 포기하는 행위"]]},{"종류":"표","제목":"매수신청대리인 등록과 보존 기간","머리":["항목","내용","근거"],"행":[["등록 주체","개업공인중개사 또는 법인인 개업공인중개사. 관할 지방법원장에게 등록","규칙 제4조, 제5조제1호"],["등록요건","부동산경매 실무교육 이수, 보증보험ㆍ공제 가입 또는 공탁","규칙 제5조제2호ㆍ제3호"],["결격","등록 취소 후 3년 미경과(폐업신고에 따른 취소는 제외) 등","규칙 제6조"],["사건카드 보존","5년","규칙 제15조제1항"],["확인ㆍ설명서 사본 보존","사건카드에 철하여 5년","규칙 제16조제2항"],["보수","예규 보수표 범위 안. 받으면 영수증 교부","규칙 제17조"]]}],"함정":"보존 기간 5년을 중개 관련 서류의 3년과 섞기 쉽다. 폐업신고로 등록이 취소된 경우에는 3년 결격이 적용되지 않는다는 예외도 선지로 나온다."},"36회-2차-036":{"한줄":"등기된 임차권이 저당권ㆍ압류채권ㆍ가압류채권에 대항할 수 없으면 매각으로 소멸한다(민사집행법 제91조제3항).","근거":[{"법령":"민사집행법","조문":"제91조제3항ㆍ제4항","원문":"③지상권ㆍ지역권ㆍ전세권 및 등기된 임차권은 저당권ㆍ압류채권ㆍ가압류채권에 대항할 수 없는 경우에는 매각으로 소멸된다. ④제3항의 경우 외의 지상권ㆍ지역권ㆍ전세권 및 등기된 임차권은 매수인이 인수한다. 다만, 그중 전세권의 경우에는 전세권자가 제88조에 따라 배당요구를 하면 매각으로 소멸된다."},{"법령":"공인중개사법","조문":"제14조제2항","원문":"② 개업공인중개사는 「민사집행법」에 의한 경매 및 「국세징수법」 그 밖의 법령에 의한 공매대상 부동산에 대한 권리분석 및 취득의 알선과 매수신청 또는 입찰신청의 대리를 할 수 있다."},{"법령":"민사집행법","조문":"제114조제2항","원문":"②차순위매수신고는 그 신고액이 최고가매수신고액에서 그 보증액을 뺀 금액을 넘는 때에만 할 수 있다."},{"법령":"민사집행법","조문":"제136조제1항","원문":"①법원은 매수인이 대금을 낸 뒤 6월 이내에 신청하면 채무자ㆍ소유자 또는 부동산 점유자에 대하여 부동산을 매수인에게 인도하도록 명할 수 있다."},{"법령":"민사집행법","조문":"제138조제4항","원문":"④재매각절차에서는 전의 매수인은 매수신청을 할 수 없으며 매수신청의 보증을 돌려 줄 것을 요구하지 못한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"대항할 수 없는 등기 임차권은 매각으로 소멸한다. 대항할 수 있는 등기 임차권만 매수인이 인수한다(민사집행법 제91조제3항ㆍ제4항)."},{"번호":2,"판정":"옳음","설명":"권리분석과 취득의 알선은 중개업자의 업무이고, 매수신청 대리를 하려면 등록이 필요하다(공인중개사법 제14조제2항)."},{"번호":3,"판정":"옳음","설명":"최고가매수신고액에서 보증액을 뺀 금액을 넘어야 차순위매수신고를 할 수 있다(민사집행법 제114조제2항)."},{"번호":4,"판정":"옳음","설명":"인도명령은 대금을 낸 뒤 6개월 이내에 신청한다(민사집행법 제136조제1항)."},{"번호":5,"판정":"옳음","설명":"재매각에서 전 매수인은 매수신청을 할 수 없고 보증 반환도 요구할 수 없다(민사집행법 제138조제4항)."}],"개념":[{"종류":"표","제목":"경매 매각과 부동산 위의 권리 (민사집행법 제91조)","머리":["권리","매각 후 처리"],"행":[["저당권","모두 소멸(제2항)"],["지상권ㆍ지역권ㆍ전세권ㆍ등기된 임차권","저당권ㆍ압류채권ㆍ가압류채권에 대항할 수 없으면 소멸(제3항)"],["위 권리 중 대항할 수 있는 것","매수인 인수. 전세권은 전세권자가 배당요구를 하면 소멸(제4항)"],["유치권","매수인이 유치권으로 담보하는 채권을 변제할 책임(제5항)"]]},{"종류":"표","제목":"경매 절차의 기한ㆍ요건","머리":["제도","내용","근거"],"행":[["차순위매수신고","신고액이 최고가매수신고액에서 보증액을 뺀 금액을 넘는 때에만 가능","제114조제2항"],["인도명령","매수인이 대금을 낸 뒤 6개월 이내 신청","제136조제1항"],["재매각","전 매수인은 매수신청 불가, 보증 반환 요구 불가","제138조제4항"],["재매각 취소","매수인이 재매각기일 3일 이전까지 대금, 지연이자, 절차비용을 지급하면 취소","제138조제3항"]]}],"함정":"등기된 임차권이라는 말에 무조건 인수된다고 외우면 1번이 맞아 보인다. 먼저 설정된 저당권ㆍ압류ㆍ가압류에 대항하지 못하는 등기 임차권은 소멸한다."},"36회-2차-044":{"한줄":"자연방재지구의 정의가 맞게 연결되어 있다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제31조제2항제4호나목","원문":"자연방재지구: 토지의 이용도가 낮은 해안변, 하천변, 급경사지 주변 등의 지역으로서 건축 제한 등을 통하여 재해 예방이 필요한 지구"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제30조제1항","원문":"가. 중심상업지역 : 도심ㆍ부도심의 상업기능 및 업무기능의 확충을 위하여 필요한 지역 나. 일반상업지역 : 일반적인 상업기능 및 업무기능을 담당하게 하기 위하여 필요한 지역 ... (2) 제2종일반주거지역 : 중층주택을 중심으로 편리한 주거환경을 조성하기 위하여 필요한 지역 (3) 제3종일반주거지역 : 중고층주택을 중심으로 편리한 주거환경을 조성하기 위하여 필요한 지역"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제31조제2항","원문":"1. 경관지구 가. 자연경관지구 : 산지ㆍ구릉지 등 자연경관을 보호하거나 유지하기 위하여 필요한 지구 ... 다. 특화경관지구 : 지역 내 주요 수계의 수변 또는 문화적 보존가치가 큰 건축물 주변의 경관 등 특별한 경관을 보호 또는 유지하거나 형성하기 위하여 필요한 지구 ... 5. 보호지구 ... 다. 생태계보호지구 : 야생동식물서식처 등 생태적으로 보존가치가 큰 지역의 보호와 보존을 위하여 필요한 지구 7. 취락지구 ... 나. 보호취락지구: 녹지지역ㆍ관리지역ㆍ농림지역 또는 자연환경보전지역 안의 취락을 농촌의 주거환경 보호와 주거기능 강화를 목적으로 정비하기 위한 지구"}],"선지":[{"번호":1,"판정":"틀림","설명":"도심ㆍ부도심의 상업기능ㆍ업무기능 확충은 중심상업지역이다. 일반상업지역은 일반적인 상업ㆍ업무기능을 담당한다(영 제30조제1항제2호가목ㆍ나목)."},{"번호":2,"판정":"틀림","설명":"중고층주택 중심은 제3종일반주거지역이다. 제2종은 중층주택 중심이다(영 제30조제1항제1호나목)."},{"번호":3,"판정":"틀림","설명":"야생동식물서식처 등 생태적 보존가치가 큰 지역의 보호는 생태계보호지구다. 보호취락지구는 취락을 농촌 주거환경 보호와 주거기능 강화를 목적으로 정비하는 지구다(영 제31조제2항제5호다목ㆍ제7호나목)."},{"번호":4,"판정":"틀림","설명":"산지ㆍ구릉지 등 자연경관 보호는 자연경관지구다. 특화경관지구는 수변이나 문화적 보존가치가 큰 건축물 주변 등 특별한 경관을 보호하는 지구다(영 제31조제2항제1호가목ㆍ다목)."},{"번호":5,"판정":"옳음","설명":"자연방재지구의 정의다(영 제31조제2항제4호나목)."}],"개념":[{"종류":"표","제목":"용도지역 세분 요건(영 제30조제1항)","머리":["지역","핵심 요건"],"행":[["제1종전용주거","단독주택 중심 양호한 주거환경 보호"],["제2종전용주거","공동주택 중심 양호한 주거환경 보호"],["제1종일반주거","저층주택 중심"],["제2종일반주거","중층주택 중심"],["제3종일반주거","중고층주택 중심"],["준주거","주거기능 위주, 일부 상업ㆍ업무기능 보완"],["중심상업","도심ㆍ부도심의 상업ㆍ업무기능 확충"],["일반상업","일반적인 상업ㆍ업무기능"],["근린상업","근린지역 일용품ㆍ서비스 공급"],["유통상업","도시 내ㆍ지역 간 유통기능 증진"]]},{"종류":"표","제목":"경관ㆍ방재ㆍ보호ㆍ취락지구의 세분(영 제31조제2항)","머리":["지구","세분","핵심 요건"],"행":[["경관지구","자연경관","산지ㆍ구릉지 등 자연경관 보호ㆍ유지"],["","시가지경관","주거지, 중심지 등 시가지 경관 보호ㆍ유지ㆍ형성"],["","특화경관","주요 수계의 수변, 문화적 보존가치 큰 건축물 주변 등"],["방재지구","시가지방재","건축물ㆍ인구 밀집 지역, 시설 개선 등으로 재해 예방"],["","자연방재","토지 이용도 낮은 해안변ㆍ하천변ㆍ급경사지 주변, 건축 제한 등으로 재해 예방"],["보호지구","역사문화환경보호","국가유산ㆍ전통사찰 등 보호"],["","중요시설물보호","항만ㆍ공항ㆍ공용시설ㆍ교정시설ㆍ군사시설 보호"],["","생태계보호","야생동식물서식처 등 생태적 보존가치 큰 지역"],["취락지구","자연취락","녹지ㆍ관리ㆍ농림ㆍ자연환경보전지역 안 취락 정비"],["","집단취락","개발제한구역 안 취락 정비"]]}],"함정":"정의 문장을 같은 계열의 이웃 지역ㆍ지구와 바꿔 놓은 선지들이다. 상업(중심↔일반), 일반주거(2종↔3종), 보호지구(생태계보호↔보호취락), 경관지구(자연↔특화) 쌍을 정의 문장으로 구분해 두어야 한다."},"36회-2차-051":{"한줄":"도지사는 광역도시계획과 관련되거나 특히 필요하다고 인정되면 관계 시장 또는 군수의 의견을 들어 직접 도시ㆍ군계획시설사업을 시행할 수 있다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제86조제4항","원문":"제1항부터 제3항까지의 규정에도 불구하고 국토교통부장관은 국가계획과 관련되거나 그 밖에 특히 필요하다고 인정되는 경우에는 관계 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수의 의견을 들어 직접 도시ㆍ군계획시설사업을 시행할 수 있으며, 도지사는 광역도시계획과 관련되거나 특히 필요하다고 인정되는 경우에는 관계 시장 또는 군수의 의견을 들어 직접 도시ㆍ군계획시설사업을 시행할 수 있다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제86조제7항","원문":"다음 각 호에 해당하지 아니하는 자가 제5항에 따라 도시ㆍ군계획시설사업의 시행자로 지정을 받으려면 도시ㆍ군계획시설사업의 대상인 토지(국공유지는 제외한다)의 소유 면적 및 토지 소유자의 동의 비율에 관하여 대통령령으로 정하는 요건을 갖추어야 한다. 1. 국가 또는 지방자치단체 2. 대통령령으로 정하는 공공기관 3. 그 밖에 대통령령으로 정하는 자"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제96조제3항제10호","원문":"「한국철도공사법」에 따른 한국철도공사"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제98조제3항","원문":"법 제89조제1항제3호에서 \"대통령령으로 정하는 자\"란 「지방공기업법」에 의한 지방공사 및 지방공단을 말한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제97조제1항","원문":"제30조제6항에 따라 도시ㆍ군관리계획결정을 고시한 경우에는 국공유지로서 도시ㆍ군계획시설사업에 필요한 토지는 그 도시ㆍ군관리계획으로 정하여진 목적 외의 목적으로 매각하거나 양도할 수 없다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제98조제1항","원문":"도시ㆍ군계획시설사업의 시행자(국토교통부장관, 시ㆍ도지사와 대도시 시장은 제외한다)는 도시ㆍ군계획시설사업의 공사를 마친 때에는 국토교통부령으로 정하는 바에 따라 공사완료보고서를 작성하여 시ㆍ도지사나 대도시 시장의 준공검사를 받아야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"광역도시계획과 관련되거나 특히 필요하면 도지사가 직접 시행할 수 있다(법 제86조제4항)."},{"번호":2,"판정":"틀림","설명":"한국철도공사는 영 제96조제3항의 공공기관이어서 토지 소유 면적ㆍ동의 비율 요건이 적용되지 않는다(법 제86조제7항제2호). 요건은 국공유지 제외 토지면적의 3분의 2 이상 소유와 토지 소유자 총수의 2분의 1 이상 동의다(영 제96조제2항)."},{"번호":3,"판정":"틀림","설명":"지방공사는 이행보증금 예치 제외 대상이다(법 제89조제1항 단서, 영 제98조제3항)."},{"번호":4,"판정":"틀림","설명":"결정 고시 후 국공유지는 정해진 목적 외의 목적으로 매각하거나 양도할 수 없다(법 제97조제1항)."},{"번호":5,"판정":"틀림","설명":"국토교통부장관, 시ㆍ도지사, 대도시 시장이 시행자이면 준공검사 대신 공사완료 공고를 한다(법 제98조제1항ㆍ제4항)."}],"개념":[{"종류":"표","제목":"도시ㆍ군계획시설사업 시행자(법 제86조)","머리":["구분","시행자","근거"],"행":[["원칙","관할 구역의 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장ㆍ군수","제1항"],["둘 이상 시ㆍ군에 걸침","관계 지자체장이 협의하여 정함. 불성립 시 같은 도면 도지사, 둘 이상 시ㆍ도면 국토교통부장관이 지정","제2항ㆍ제3항"],["국토교통부장관 직접","국가계획과 관련되거나 특히 필요한 경우, 관계 지자체장 의견 청취","제4항"],["도지사 직접","광역도시계획과 관련되거나 특히 필요한 경우, 관계 시장ㆍ군수 의견 청취","제4항"],["그 밖의 자","국토교통부장관, 시ㆍ도지사, 시장ㆍ군수로부터 지정","제5항"]]},{"종류":"표","제목":"지정 요건ㆍ면제ㆍ이행보증금ㆍ준공","머리":["항목","내용"],"행":[["지정 요건(영 제96조제2항)","국공유지 제외 토지면적의 3분의 2 이상 소유 + 토지 소유자 총수의 2분의 1 이상 동의"],["요건 면제(법 제86조제7항, 영 제96조제3항ㆍ제4항)","국가ㆍ지방자치단체, 한국토지주택공사ㆍ한국도로공사ㆍ한국철도공사 등 공공기관, 지방공사ㆍ지방공단 등"],["이행보증금 제외(법 제89조제1항, 영 제98조)","국가ㆍ지방자치단체, 영이 정한 공공기관(「공공기관의 운영에 관한 법률」 제5조제4항제1호ㆍ제2호나목), 지방공사ㆍ지방공단"],["실시계획 인가(영 제97조제2항)","국토교통부장관이 지정한 시행자는 국토교통부장관, 그 밖의 시행자는 시ㆍ도지사 또는 대도시 시장"],["준공(법 제98조)","시행자(국토교통부장관ㆍ시ㆍ도지사ㆍ대도시 시장 제외)는 시ㆍ도지사 또는 대도시 시장의 준공검사. 국토교통부장관ㆍ시ㆍ도지사ㆍ대도시 시장은 공사완료 공고"]]}],"함정":"선지 2는 지정 요건(3분의 2 소유)이 모든 시행자에게 적용된다고 보게 만든 것으로, 공공기관ㆍ지방공사 등은 면제된다. 선지 3의 지방공사 이행보증금 면제도 같은 구조다. 선지 5는 준공검사를 받는 시행자의 범위를 거꾸로 적었다."},"36회-2차-047":{"한줄":"다른 법령에 따른 건폐율ㆍ용적률 완화 내용을 반영하는 변경은 경미한 변경 면제 사유에서 빠져 있어 공동위원회 심의를 거친다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제25조제4항","원문":"지구단위계획 중 다음 각 호의 어느 하나에 해당하는 경우(다른 호에 저촉되지 않는 경우로 한정한다)에는 법 제30조제5항 단서에 따라 관계 행정기관의 장과의 협의, 국토교통부장관과의 협의 및 중앙도시계획위원회ㆍ지방도시계획위원회 또는 제2항에 따른 공동위원회의 심의를 거치지 않고 지구단위계획을 변경할 수 있다. 다만, 제14호에 해당하는 경우에는 공동위원회의 심의를 거쳐야 한다."},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제25조제4항제14호","원문":"「건축법」 등 다른 법령의 규정에 따른 건폐율 또는 용적률 완화 내용을 반영하기 위하여 지구단위계획을 변경하는 경우"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제25조제4항제3호ㆍ제4호","원문":"3. 획지(劃地: 구획된 한 단위의 토지를 말한다. 이하 같다) 면적의 30퍼센트 이내의 변경인 경우 4. 건축물높이의 20퍼센트 이내의 변경인 경우(층수변경이 수반되는 경우를 포함한다)"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제25조제4항제8호ㆍ제11호","원문":"8. 건축물의 배치ㆍ형태 또는 색채의 변경인 경우 11. 지구단위계획구역 면적의 10퍼센트(용도지역 변경을 포함하는 경우에는 5퍼센트를 말한다) 이내의 변경 및 동 변경지역안에서의 지구단위계획의 변경"}],"선지":[{"번호":1,"판정":"틀림","설명":"획지 면적 30퍼센트 이내의 변경은 심의 없이 변경할 수 있다. 25퍼센트는 이에 든다(영 제25조제4항제3호)."},{"번호":2,"판정":"틀림","설명":"건축물높이 20퍼센트 이내의 변경은 층수변경이 수반되어도 심의 없이 변경할 수 있다(영 제25조제4항제4호)."},{"번호":3,"판정":"틀림","설명":"건축물의 배치ㆍ형태 또는 색채의 변경은 심의 없이 변경할 수 있다(영 제25조제4항제8호)."},{"번호":4,"판정":"틀림","설명":"구역 면적 10퍼센트(용도지역 변경 포함 시 5퍼센트) 이내의 변경은 심의 없이 변경할 수 있다. 4퍼센트는 이에 든다(영 제25조제4항제11호)."},{"번호":5,"판정":"옳음","설명":"다른 법령에 따른 건폐율ㆍ용적률 완화 반영 변경은 단서에 따라 공동위원회 심의를 거친다(영 제25조제4항 단서, 제14호)."}],"개념":[{"종류":"표","제목":"지구단위계획 경미한 변경(심의 생략) 수치(영 제25조제4항)","머리":["대상","생략 가능 범위"],"행":[["가구면적","10퍼센트 이내"],["획지면적","30퍼센트 이내"],["건축물높이(층수변경 수반 포함)","20퍼센트 이내"],["건축선","1미터 이내"],["건축물 배치ㆍ형태ㆍ색채","변경 전부"],["지구단위계획구역 면적","10퍼센트 이내(용도지역 변경 포함 시 5퍼센트)"],["다른 법령의 건폐율ㆍ용적률 완화 반영","생략 불가: 공동위원회 심의"]]},{"종류":"표","제목":"공동위원회(법 제30조제3항 단서, 영 제25조제2항)","머리":["항목","내용"],"행":[["심의 대상","시ㆍ도지사가 결정하는 지구단위계획(구역 지정ㆍ변경 포함), 지구단위계획으로 대체하는 용도지구 폐지"],["구성","건축위원회와 도시계획위원회 위원 중에서 임명ㆍ위촉"],["위원 수","30명 이내"],["건축위원회 위원 비율","3분의 1 이상"],["시장ㆍ군수 결정","준용(법 제30조제7항): 시 또는 군에 두는 건축위원회와 시ㆍ군ㆍ구도시계획위원회"]]}],"함정":"경미 변경 수치는 가구 10, 획지 30, 높이 20, 건축선 1미터, 구역 면적 10(용도지역 변경 시 5)로 한 세트다. 선지 1~4는 모두 이 한도 안에 들고, 마지막 단서(제14호)만 심의 대상으로 남는다."},"36회-2차-054":{"한줄":"한국공항공사와 한국철도공사는 영이 정한 공공기관으로, 지방공사와 함께 법 제11조제5항의 제안 주체에 든다.","근거":[{"법령":"도시개발법","조문":"제11조제5항","원문":"제1항제2호부터 제4호까지의 규정에 해당하는 자, 도시개발구역의 토지 소유자(수용 또는 사용의 방식으로 제안하는 경우에는 도시개발구역의 국공유지를 제외한 토지면적의 3분의 2 이상을 사용할 수 있는 대통령령으로 정하는 권원을 가지고 2분의 1 이상을 소유한 자를 말한다) 또는 제1항제7호부터 제11호까지의 규정에 해당하는 자는 대통령령으로 정하는 바에 따라 특별자치도지사ㆍ시장ㆍ군수 또는 구청장에게 도시개발구역의 지정을 제안할 수 있다."},{"법령":"도시개발법","조문":"제11조제1항","원문":"2. 대통령령으로 정하는 공공기관 3. 대통령령으로 정하는 정부출연기관 4. 「지방공기업법」에 따라 설립된 지방공사"},{"법령":"도시개발법 시행령","조문":"제18조제1항","원문":"법 제11조제1항제2호에서 \"대통령령으로 정하는 공공기관\"이란 다음 각 호의 공공기관을 말한다. 6. 「한국철도공사법」에 따른 한국철도공사 8. 「한국공항공사법」에 따른 한국공항공사"}],"선지":[{"번호":1,"판정":"-","설명":"ㄴ과 ㄷ도 제안할 수 있어 ㄱ만으로는 부족하다."},{"번호":2,"판정":"-","설명":"ㄱ과 ㄴ도 제안할 수 있어 ㄷ만으로는 부족하다."},{"번호":3,"판정":"-","설명":"ㄷ(한국철도공사)이 빠졌다."},{"번호":4,"판정":"-","설명":"ㄱ(한국공항공사)이 빠졌다."},{"번호":5,"판정":"-","설명":"ㄱㆍㄴㆍㄷ 모두 제안할 수 있다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"한국공항공사는 영 제18조제1항제8호의 공공기관이어서 법 제11조제1항제2호에 해당하고 제안할 수 있다."},{"기호":"ㄴ","판정":"옳음","설명":"지방공사는 법 제11조제1항제4호에 해당하고 제안할 수 있다."},{"기호":"ㄷ","판정":"옳음","설명":"한국철도공사는 영 제18조제1항제6호의 공공기관이어서 제안할 수 있다."}],"개념":[{"종류":"표","제목":"도시개발사업 시행자와 구역 지정 제안 가능 여부(법 제11조제1항ㆍ제5항)","머리":["호","시행자","제안"],"행":[["1호","국가, 지방자치단체","열거 없음"],["2호","영이 정한 공공기관: 한국토지주택공사, 한국수자원공사, 한국농어촌공사, 한국관광공사, 한국철도공사, 혁신도시 매입공공기관, 한국공항공사(영 제18조제1항)","가능"],["3호","영이 정한 정부출연기관: 국가철도공단(역세권개발사업), 제주국제자유도시개발센터(제주특별자치도)(영 제18조제2항)","가능"],["4호","「지방공기업법」에 따른 지방공사","가능"],["5호","도시개발구역의 토지 소유자","가능(요건 있음)"],["6호","토지 소유자가 설립한 조합","열거 없음"],["7호~11호","과밀억제권역 이전 법인, 주택법 등록업자, 토목공사업 면허 등 능력자, 부동산개발업자, 부동산투자회사, 출자 설립 법인","가능"]]},{"종류":"표","제목":"제안의 동의ㆍ처리(법 제11조제6항ㆍ제7항, 영 제23조)","머리":["항목","내용"],"행":[["동의","토지 소유자와 7~11호 해당자: 대상 구역 토지면적의 3분의 2 이상에 해당하는 토지 소유자(지상권자 포함) 동의"],["동의 면제","1~4호가 영이 정한 비율(100분의 50)을 초과해 출자한 7~11호 해당자는 제외(영 제23조제5항)"],["수용ㆍ사용 방식 제안 시 토지 소유자","국공유지 제외 면적의 3분의 2 이상을 사용할 수 있는 권원(토지사용승낙서ㆍ매매계약서) + 2분의 1 이상 소유"],["제출처","특별자치도지사ㆍ시장ㆍ군수ㆍ구청장. 둘 이상 시ㆍ군ㆍ구에 걸치면 면적이 가장 큰 곳(영 제23조제2항)"],["수용 여부 통보","1개월 이내(영 제23조제3항)"],["비용","제안자와 협의해 전부 또는 일부 부담(법 제11조제7항)"]]}],"함정":"제안 주체는 법 제11조제1항 시행자 중 제2~4호와 제5호(토지 소유자), 제7~11호다. 제1호(국가ㆍ지방자치단체)와 제6호(조합)는 열거에서 빠져 있다."},"36회-2차-055":{"한줄":"설립 발기인 7명, 대의원회 설치 기준 50인, 설립등기 기한 30일이다.","근거":[{"법령":"도시개발법","조문":"제13조제1항","원문":"조합을 설립하려면 도시개발구역의 토지 소유자 7명 이상이 대통령령으로 정하는 사항을 포함한 정관을 작성하여 지정권자에게 조합 설립의 인가를 받아야 한다."},{"법령":"도시개발법 시행령","조문":"제36조제1항","원문":"의결권을 가진 조합원의 수가 50인 이상인 조합은 총회의 권한을 대행하게 하기 위하여 대의원회를 둘 수 있다."},{"법령":"도시개발법 시행령","조문":"제32조제1항","원문":"법 제13조에 따라 조합의 설립인가를 받은 조합의 대표자는 설립인가를 받은 날부터 30일 이내에 주된 사무소의 소재지에서 설립등기를 하여야 한다."}],"선지":[{"번호":1,"판정":"-","설명":"ㄷ이 14일이 아니라 30일이다."},{"번호":2,"판정":"-","설명":"ㄱ 7명, ㄴ 50인, ㄷ 30일이 모두 맞다."},{"번호":3,"판정":"-","설명":"ㄴ이 100인이 아니라 50인이고, ㄷ이 14일이 아니라 30일이다."},{"번호":4,"판정":"-","설명":"ㄱ이 10명이 아니라 7명이고, ㄷ이 14일이 아니라 30일이다."},{"번호":5,"판정":"-","설명":"ㄱ이 10명이 아니라 7명이고, ㄴ이 100인이 아니라 50인이다."}],"개념":[{"종류":"표","제목":"도시개발조합 숫자 정리","머리":["항목","숫자","근거"],"행":[["설립 발기","토지 소유자 7명 이상","법 제13조제1항"],["설립인가 동의","토지면적 3분의 2 이상 + 토지 소유자 총수 2분의 1 이상","법 제13조제3항"],["대의원회 설치","의결권을 가진 조합원 50인 이상이면 둘 수 있음","영 제36조제1항"],["대의원 수","의결권을 가진 조합원 총수의 100분의 10 이상","영 제36조제2항"],["설립등기","설립인가를 받은 날부터 30일 이내","영 제32조제1항"],["부과금 징수 위탁 시 조합이 지자체에 지급하는 금액","징수금액의 100분의 4","법 제16조제5항"]]},{"종류":"표","제목":"총회 의결사항(영 제35조)","머리":["호","의결사항"],"행":[["1","정관의 변경"],["2","개발계획 및 실시계획의 수립ㆍ변경"],["3","자금의 차입과 그 방법ㆍ이율ㆍ상환방법"],["4","조합의 수지예산"],["5","부과금의 금액 또는 징수방법"],["6","환지계획의 작성"],["7","환지예정지의 지정"],["8","체비지 등의 처분방법"],["9","조합임원의 선임"],["10","조합의 합병 또는 해산(청산금 징수ㆍ교부 완료 후 해산은 제외)"],["11","그 밖에 정관에서 정하는 사항"]]}],"함정":"숫자 세 개(7명, 50인, 30일)가 한 묶음이다. 오답 선지는 여기에 10명, 100인, 14일을 섞어 놓았다. 동의 요건의 3분의 2, 2분의 1과는 따로 외운다."},"36회-2차-065":{"한줄":"리모델링주택조합이 허가를 받으려면 단지 전체는 전체 75퍼센트와 각 동 50퍼센트, 동 리모델링은 그 동 75퍼센트의 동의가 필요하다.","근거":[{"법령":"주택법 시행령","조문":"별표 4 제1호나목","원문":"리모델링주택조합의 경우: 다음의 사항이 적혀 있는 결의서에 주택단지 전체를 리모델링하는 경우에는 주택단지 전체 구분소유자 및 의결권의 각 75퍼센트 이상의 동의와 각 동별 구분소유자 및 의결권의 각 50퍼센트 이상의 동의를 받아야 하며(리모델링을 하지 않는 별동의 건축물로 입주자 공유가 아닌 복리시설 등의 소유자는 권리변동이 없는 경우에 한정하여 동의비율 산정에서 제외한다), 동을 리모델링하는 경우에는 그 동의 구분소유자 및 의결권의 각 75퍼센트 이상의 동의를 받아야 한다. 1) 리모델링 설계의 개요 2) 공사비 3) 조합원의 비용분담 명세"},{"법령":"주택법","조문":"제66조제2항","원문":"② 제1항에도 불구하고 대통령령으로 정하는 기준 및 절차 등에 따라 리모델링 결의를 한 리모델링주택조합이나 소유자 전원의 동의를 받은 입주자대표회의(「공동주택관리법」 제2조제1항제8호에 따른 입주자대표회의를 말하며, 이하 \"입주자대표회의\"라 한다)가 시장ㆍ군수ㆍ구청장의 허가를 받아 리모델링을 할 수 있다."},{"법령":"주택법","조문":"제11조제3항","원문":"③ 제1항에 따라 주택을 리모델링하기 위하여 주택조합을 설립하려는 경우에는 다음 각 호의 구분에 따른 구분소유자(「집합건물의 소유 및 관리에 관한 법률」 제2조제2호에 따른 구분소유자를 말한다. 이하 같다)와 의결권(「집합건물의 소유 및 관리에 관한 법률」 제37조에 따른 의결권을 말한다. 이하 같다)의 결의를 증명하는 서류를 첨부하여 관할 시장ㆍ군수ㆍ구청장의 인가를 받아야 한다. 1. 주택단지 전체를 리모델링하고자 하는 경우에는 주택단지 전체의 구분소유자와 의결권의 각 3분의 2 이상의 결의 및 각 동의 구분소유자와 의결권의 각 과반수의 결의 2. 동을 리모델링하고자 하는 경우에는 그 동의 구분소유자 및 의결권의 각 3분의 2 이상의 결의"}],"선지":[{"번호":1,"판정":"-","설명":"ㄱ이 50이면 틀리다. 단지 전체 동의는 75퍼센트다(영 별표 4 제1호나목)."},{"번호":2,"판정":"-","설명":"ㄱ이 50, ㄴ이 75로 모두 틀리다."},{"번호":3,"판정":"-","설명":"ㄷ이 50이면 틀리다. 동 리모델링은 그 동의 75퍼센트다."},{"번호":4,"판정":"-","설명":"ㄱ 75, ㄴ 50, ㄷ 75가 별표 4의 기준과 일치한다."},{"번호":5,"판정":"-","설명":"ㄴ이 75, ㄷ이 50이어서 모두 틀리다."}],"개념":[{"종류":"표","제목":"리모델링 결의ㆍ동의 비율","머리":["구분","단지 전체","동 리모델링"],"행":[["주택조합 설립인가(법 제11조제3항)","전체 구분소유자ㆍ의결권 각 3분의 2 이상 + 각 동 구분소유자ㆍ의결권 각 과반수","그 동 구분소유자ㆍ의결권 각 3분의 2 이상"],["리모델링 허가: 리모델링주택조합(영 별표 4 제1호나목)","전체 각 75퍼센트 이상 + 각 동 각 50퍼센트 이상","그 동 각 75퍼센트 이상"],["리모델링 허가: 입주자대표회의(영 별표 4 제1호다목)","소유자 전원 동의","소유자 전원 동의"],["리모델링 허가: 입주자ㆍ사용자 또는 관리주체(영 별표 4 제1호가목)","입주자 전체 동의","입주자 전체 동의"]]},{"종류":"표","제목":"리모델링 허가 관련 기타 사항","머리":["항목","내용","근거"],"행":[["허가권자","시장ㆍ군수ㆍ구청장","법 제66조제1항"],["시공자 선정","경쟁입찰, 2회 이상 입찰하고도 입찰자 수가 미달하는 등 곤란한 경우 예외","법 제66조제4항, 영 제76조제1항"],["세대수 증가형 리모델링","대통령령 정하는 세대수(50세대) 이상 증가 시 시ㆍ군ㆍ구도시계획위원회 심의","법 제66조제6항, 영 제76조제2항"],["동의 철회","허가신청서를 제출하기 전까지 서면으로 가능","영 제75조제3항"],["사용검사","허가받아 공사를 마친 후 시장ㆍ군수ㆍ구청장의 사용검사","법 제66조제7항"]]}],"함정":"조합 설립인가의 결의 요건(3분의 2, 과반수)과 리모델링 허가의 동의 요건(75퍼센트, 50퍼센트)이 구조가 같아서 숫자만 바꿔 읽기 쉽다. 단지 전체는 ‘전체 큰 수 + 각 동 작은 수’, 동 리모델링은 ‘그 동 큰 수’로 외우면 ㄱ과 ㄷ이 같은 숫자라는 점을 잡을 수 있다."},"36회-2차-087":{"한줄":"청산금의 납부 및 지급이 완료되면 지적소관청이 하는 일은 청산금 조서 작성이 아니라 지체 없이 하는 축척변경의 확정공고다(영 제78조제1항).","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제83조제1항","원문":"① 축척변경에 관한 사항을 심의ㆍ의결하기 위하여 지적소관청에 축척변경위원회를 둔다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제79조제2항","원문":"② 위원장은 위원 중에서 지적소관청이 지명한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제75조제4항","원문":"④ 지적소관청은 청산금을 산정하였을 때에는 청산금 조서(축척변경 지번별 조서에 필지별 청산금 명세를 적은 것을 말한다)를 작성하고, 청산금이 결정되었다는 뜻을 제71조제2항의 방법에 따라 15일 이상 공고하여 일반인이 열람할 수 있게 하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제76조제1항","원문":"① 지적소관청은 제75조제4항에 따라 청산금의 결정을 공고한 날부터 20일 이내에 토지소유자에게 청산금의 납부고지 또는 수령통지를 하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제78조제1항","원문":"① 청산금의 납부 및 지급이 완료되었을 때에는 지적소관청은 지체 없이 축척변경의 확정공고를 하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제73조","원문":"지적소관청은 제72조제2항에 따라 축척변경에 관한 측량을 완료하였을 때에는 시행공고일 현재의 지적공부상의 면적과 측량 후의 면적을 비교하여 그 변동사항을 표시한 축척변경 지번별 조서를 작성하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"축척변경위원회는 지적소관청에 둔다(법 제83조제1항)."},{"번호":2,"판정":"옳음","설명":"위원장은 위원 중에서 지적소관청이 지명한다(영 제79조제2항)."},{"번호":3,"판정":"옳음","설명":"청산금 결정 공고일부터 20일 이내에 납부고지 또는 수령통지를 한다(영 제76조제1항)."},{"번호":4,"판정":"틀림","설명":"청산금 조서는 청산금을 산정했을 때 작성하며 공고도 그때 한다(영 제75조제4항). 납부·지급이 끝난 뒤에는 확정공고를 한다(영 제78조제1항)."},{"번호":5,"판정":"옳음","설명":"시행공고일 현재의 지적공부상 면적과 측량 후 면적을 비교한 축척변경 지번별 조서를 작성한다(영 제73조)."}],"개념":[{"종류":"흐름","제목":"축척변경 절차","단계":[{"이름":"신청 또는 직권","설명":"토지소유자의 신청 또는 지적소관청의 직권. 사유: 1필지 규모가 작아 소축척으로 정리 곤란, 한 지번부여지역에 축척이 다른 지적도 존재 등(법 제83조제2항)"},{"이름":"동의·의결·승인","설명":"시행지역 토지소유자 3분의 2 이상 동의 → 축척변경위원회 의결 → 시·도지사 또는 대도시 시장 승인"},{"이름":"시행공고","설명":"승인 후 지체 없이 20일 이상 공고. 소유자·점유자는 공고일부터 30일 이내에 점유 경계에 경계점표지 설치"},{"이름":"측량·지번별 조서","설명":"경계점표지를 기준으로 측량하고, 시행공고일 현재 면적과 측량 후 면적을 비교한 축척변경 지번별 조서 작성"},{"이름":"청산금 산정·공고","설명":"위원회 의결로 지번별 제곱미터당 금액 결정. 청산금 = 증감면적 × 제곱미터당 금액. 청산금 조서 작성 후 15일 이상 공고"},{"이름":"납부고지·수령통지","설명":"청산금 결정 공고일부터 20일 이내. 납부는 고지받은 날부터 6개월 이내, 지급은 통지한 날부터 6개월 이내. 이의신청은 받은 날부터 1개월 이내"},{"이름":"확정공고·등록","설명":"납부·지급 완료 후 지체 없이 확정공고하고 지적공부에 등록. 확정공고일에 토지의 이동이 있는 것으로 봄"}]},{"종류":"표","제목":"축척변경위원회","머리":["항목","내용"],"행":[["설치","지적소관청"],["구성","5명 이상 10명 이하, 위원의 2분의 1 이상을 토지소유자로 함. 소유자가 5명 이하면 전원 위촉"],["위원장","위원 중에서 지적소관청이 지명"],["위원","지역 사정에 정통한 소유자, 지적에 전문지식을 가진 사람 중에서 지적소관청이 위촉"],["회의","재적위원 과반수 출석으로 개의, 출석위원 과반수 찬성으로 의결. 회의 5일 전까지 서면 통지"],["심의·의결","시행계획, 제곱미터당 금액 결정과 청산금 산정, 청산금 이의신청, 그 밖에 지적소관청이 부치는 사항"],["승인 없이 하는 축척변경","합병하려는 토지가 축척이 다른 도면에 각각 등록된 경우, 도시개발사업 등 시행에서 제외된 토지 → 의결·승인 없이 가능, 면적만 새로 정함"]]}],"함정":"순서를 끝까지 따라가지 않으면 청산금 조서와 확정공고를 바꿔 놓는 선지에 걸린다. 청산금 조서는 산정 직후, 확정공고는 납부·지급 완료 후다. 숫자는 공고 20일 이상·15일 이상, 고지 20일, 납부·지급 6개월, 이의 1개월을 구분한다."},"36회-2차-091":{"한줄":"ㄱ~ㅁ은 모두 영 제82조제1항이 정한 직권 조사·측량 정정 사유(제1호·제2호·제7호·제4호·제5호)에 해당한다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제82조제1항","원문":"① 지적소관청이 법 제84조제2항에 따라 지적공부의 등록사항에 잘못이 있는지를 직권으로 조사ㆍ측량하여 정정할 수 있는 경우는 다음 각 호와 같다. <개정 2015.6.1, 2017.1.10>\n1. 제84조제2항에 따른 토지이동정리 결의서의 내용과 다르게 정리된 경우\n2. 지적도 및 임야도에 등록된 필지가 면적의 증감 없이 경계의 위치만 잘못된 경우\n4. 지적공부의 작성 또는 재작성 당시 잘못 정리된 경우\n5. 지적측량성과와 다르게 정리된 경우\n7. 지적공부의 등록사항이 잘못 입력된 경우"}],"선지":[{"번호":1,"판정":"-","설명":"ㄹ, ㅁ도 사유이므로 ㄱ, ㄴ, ㄷ만 고른 조합은 부족하다."},{"번호":2,"판정":"-","설명":"ㄷ(제7호)도 사유이므로 부족하다."},{"번호":3,"판정":"-","설명":"ㄴ(제2호)도 사유이므로 부족하다."},{"번호":4,"판정":"-","설명":"ㄱ(제1호)도 사유이므로 부족하다."},{"번호":5,"판정":"-","설명":"ㄱ~ㅁ이 모두 사유이므로 맞는 조합이다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"토지이동정리 결의서의 내용과 다르게 정리된 경우다(영 제82조제1항제1호)."},{"기호":"ㄴ","판정":"옳음","설명":"면적 증감 없이 경계 위치만 잘못된 경우다. 면적이 늘거나 줄면 이 사유가 아니다(영 제82조제1항제2호)."},{"기호":"ㄷ","판정":"옳음","설명":"등록사항을 잘못 입력한 경우다(영 제82조제1항제7호)."},{"기호":"ㄹ","판정":"옳음","설명":"작성 또는 재작성 당시 잘못 정리된 경우다(영 제82조제1항제4호)."},{"기호":"ㅁ","판정":"옳음","설명":"지적측량성과와 다르게 정리된 경우다(영 제82조제1항제5호)."}],"개념":[{"종류":"표","제목":"직권정정 사유(영 제82조제1항)","머리":["호","사유"],"행":[["1","토지이동정리 결의서의 내용과 다르게 정리된 경우"],["2","지적도·임야도에 등록된 필지가 면적 증감 없이 경계 위치만 잘못된 경우"],["3","1필지가 각각 다른 도면에 등록되어 면적은 일치하나 경계가 접합되지 않아 지상경계에 맞춰야 하는 경우"],["4","지적공부의 작성 또는 재작성 당시 잘못 정리된 경우"],["5","지적측량성과와 다르게 정리된 경우"],["6","법 제29조제10항에 따라 지적위원회 의결서 사본을 받아 정정하는 경우"],["7","지적공부의 등록사항이 잘못 입력된 경우"],["8","부동산등기법 제37조제2항에 따른 통지가 있는 경우(지적소관청의 착오로 잘못 합병한 경우만)"],["9","법률 제2801호 지적법개정법률 부칙 제3조에 따른 면적 환산이 잘못된 경우"]]},{"종류":"표","제목":"등록사항 정정의 절차·효과","머리":["항목","내용"],"행":[["신청과 직권","토지소유자는 정정을 신청할 수 있고(법 제84조제1항), 지적소관청은 직권으로 조사·측량하여 정정할 수 있다(제2항)"],["인접 토지 경계 변경","신청 정정으로 인접 토지의 경계가 변경되면 인접 토지소유자의 승낙서, 승낙하지 않으면 이에 대항할 수 있는 확정판결서 정본 제출(법 제84조제3항)"],["소유자 사항 정정","등기필증·등기완료통지서·등기사항증명서·등기전산정보자료에 따라 정정(법 제84조제4항)"],["정정 대상토지 관리","정정 서류와 측량성과도, 토지이동정리 결의서를 작성하고 대장 사유란에 \"등록사항정정 대상토지\"라고 적은 뒤 소유자에게 신청 통지(직권정정 사유면 통지 생략 가능). 열람·등본 때 그 부분은 흑백 반전 또는 붉은색(규칙 제94조)"],["측량 정지","경계나 면적 등 측량을 수반하는 표시가 잘못되면 정정 완료 때까지 지적측량을 정지시킬 수 있다. 정정을 위한 측량은 제외(영 제82조제3항)"]]}],"함정":"면적이 늘거나 줄면서 경계가 어긋난 경우는 ㄴ(면적 증감 없는 경계 위치 오류)이 아니라 소유자 신청 정정으로 간다. 다섯 보기 모두 호가 하나씩 대응하므로 하나라도 빼면 오답이다."},"36회-2차-085":{"한줄":"착수·변경·완료 신고 대상 토지개발사업 14종에 지적재조사사업은 들어 있지 않다(법 제86조제1항, 영 제83조제1항).","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제86조제1항","원문":"① 「도시개발법」에 따른 도시개발사업, 「농어촌정비법」에 따른 농어촌정비사업, 그 밖에 대통령령으로 정하는 토지개발사업의 시행자는 대통령령으로 정하는 바에 따라 그 사업의 착수ㆍ변경 및 완료 사실을 지적소관청에 신고하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제83조제1항제7호·제9호·제12호·제13호","원문":"7. 「관광진흥법」에 따른 관광단지 개발사업\n9. 「항만법」, 「신항만건설촉진법」에 따른 항만개발사업 및 「항만 재개발 및 주변지역 발전에 관한 법률」에 따른 항만재개발사업\n12. 「철도의 건설 및 철도시설 유지관리에 관한 법률」에 따른 고속철도, 일반철도 및 광역철도 건설사업\n13. 「도로법」에 따른 고속국도 및 일반국도 건설사업"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제83조제2항","원문":"② 법 제86조제1항에 따른 도시개발사업 등의 착수ㆍ변경 또는 완료 사실의 신고는 그 사유가 발생한 날부터 15일 이내에 하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"지적재조사사업은 신고 대상 토지개발사업 목록에 없다(영 제83조제1항)."},{"번호":2,"판정":"옳음","설명":"고속철도, 일반철도 및 광역철도 건설사업이 해당한다(영 제83조제1항제12호)."},{"번호":3,"판정":"옳음","설명":"고속국도 및 일반국도 건설사업이 해당한다(영 제83조제1항제13호)."},{"번호":4,"판정":"옳음","설명":"항만법에 따른 항만개발사업이 해당한다(영 제83조제1항제9호)."},{"번호":5,"판정":"옳음","설명":"관광진흥법에 따른 관광단지 개발사업이 해당한다(영 제83조제1항제7호)."}],"개념":[{"종류":"표","제목":"신고 대상 토지개발사업","머리":["구분","사업"],"행":[["법에 직접 규정","도시개발법에 따른 도시개발사업, 농어촌정비법에 따른 농어촌정비사업"],["영 제83조제1항 1~4호","주택법 주택건설사업, 택지개발촉진법 택지개발사업, 산업입지 및 개발에 관한 법률 산업단지개발사업, 도시 및 주거환경정비법 정비사업"],["5~8호","지역 개발 및 지원에 관한 법률 지역개발사업, 체육시설 설치를 위한 토지개발사업, 관광진흥법 관광단지 개발사업, 공유수면 관리 및 매립에 관한 법률 매립사업"],["9~11호","항만법·신항만건설촉진법 항만개발사업과 항만재개발사업, 공공주택 특별법 공공주택지구조성사업, 물류시설법·경제자유구역법 개발사업"],["12~14호","철도 건설사업(고속·일반·광역), 도로법 고속국도·일반국도 건설사업, 이와 유사하여 국토교통부장관이 고시하는 요건에 해당하는 사업"]]},{"종류":"표","제목":"도시개발사업 등 시행지역의 특례","머리":["항목","내용"],"행":[["신고","사업의 착수·변경·완료 사실을 사유 발생일부터 15일 이내에 지적소관청에 신고(영 제83조제2항)"],["토지의 이동 신청","사업과 관련한 토지의 이동은 사업시행자가 신청(법 제86조제2항)"],["환지를 수반하는 경우","사업완료 신고로 토지의 이동 신청을 갈음할 수 있고, 신고서에 갈음한다는 뜻을 적음(영 제83조제3항)"],["토지의 이동 시기","토지의 형질변경 등의 공사가 준공된 때에 이루어진 것으로 봄(법 제86조제3항)"],["소유자의 요청","착수·변경 신고가 된 토지의 소유자가 이동을 원하면 시행자에게 신청을 요청하고, 사업에 지장이 없으면 시행자가 신청(법 제86조제4항)"]]}],"함정":"신고 대상은 영 제83조제1항이 열거한 사업이다. 철도·도로·항만·관광단지 사업은 열거돼 있고, 지적재조사사업은 없다."},"36회-2차-104":{"한줄":"보기 ㄱ~ㄹ은 모두 규칙 제161조제1항이 정한 기록명령에 따른 등기를 할 수 없는 경우(제3호·제1호·제2호·제4호)다.","근거":[{"법령":"부동산등기규칙","조문":"제161조제1항·제2항","원문":"1. 권리이전등기의 기록명령이 있었으나, 그 기록명령에 따른 등기 전에 제3자 명의로 권리이전등기가 되어 있는 경우\n2. 지상권, 지역권, 전세권 또는 임차권의 설정등기의 기록명령이 있었으나, 그 기록명령에 따른 등기 전에 동일한 부분에 지상권, 전세권 또는 임차권의 설정등기가 되어 있는 경우\n3. 말소등기의 기록명령이 있었으나 그 기록명령에 따른 등기 전에 등기상 이해관계인이 발생한 경우\n4. 등기관이 기록명령에 따른 등기를 하기 위하여 신청인에게 첨부정보를 다시 등기소에 제공할 것을 명령하였으나 신청인이 이에 응하지 아니한 경우\n② 제1항과 같이 기록명령에 따른 등기를 할 수 없는 경우에는 그 뜻을 관할 지방법원과 이의신청인에게 통지하여야 한다."}],"선지":[{"번호":1,"판정":"-","설명":"ㄴ, ㄷ, ㄹ도 해당하므로 ㄱ만 고른 조합은 부족하다."},{"번호":2,"판정":"-","설명":"ㄱ, ㄹ도 해당하므로 부족하다."},{"번호":3,"판정":"-","설명":"ㄱ, ㄴ도 해당하므로 부족하다."},{"번호":4,"판정":"-","설명":"ㄷ도 해당하므로 부족하다."},{"번호":5,"판정":"-","설명":"ㄱ~ㄹ이 모두 해당하므로 맞는 조합이다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"말소등기 기록명령 뒤 등기 전에 등기상 이해관계인이 생긴 경우다. 지상권을 목적으로 한 저당권자가 이해관계인이다(규칙 제161조제1항제3호)."},{"기호":"ㄴ","판정":"옳음","설명":"권리이전등기의 기록명령 뒤 등기 전에 제3자 명의로 이전등기가 된 경우다(규칙 제161조제1항제1호)."},{"기호":"ㄷ","판정":"옳음","설명":"임차권설정등기 기록명령 뒤 등기 전에 동일한 부분에 임차권설정등기가 된 경우다(규칙 제161조제1항제2호)."},{"기호":"ㄹ","판정":"옳음","설명":"첨부정보 재제공 명령에 신청인이 응하지 않은 경우다(규칙 제161조제1항제4호)."}],"개념":[{"종류":"흐름","제목":"등기관 결정·처분에 대한 이의신청(법 제100조~제106조)","단계":[{"이름":"이의신청","설명":"결정·처분에 이의가 있는 자가 그 등기관이 속한 지방법원에 신청. 이의신청서는 결정·처분을 한 등기관이 속한 등기소에 제출"},{"이름":"등기관의 조치","설명":"이유 있다고 인정하면 해당 처분을 하고, 이유 없다고 인정하면 이의신청일부터 3일 이내에 의견을 붙여 관할 지방법원에 송부"},{"이름":"지방법원의 결정","설명":"이유를 붙여 결정. 이유 있으면 등기관에게 해당 처분을 명령(기록명령 등)하고 이의신청인과 등기상 이해관계인에게 통지"},{"이름":"항고","설명":"결정에 대해서는 비송사건절차법에 따라 항고"},{"이름":"부수 효과","설명":"이의에는 집행정지 효력이 없고, 새로운 사실이나 새로운 증거방법을 근거로 이의신청할 수 없다. 법원은 결정 전에 가등기 또는 이의가 있다는 뜻의 부기등기를 명령할 수 있다"}]},{"종류":"표","제목":"기록명령에 따른 등기를 할 수 없는 경우(규칙 제161조제1항)","머리":["호","경우"],"행":[["1","권리이전등기의 기록명령 뒤 그 등기 전에 제3자 명의로 권리이전등기가 된 경우"],["2","지상권·지역권·전세권·임차권 설정등기의 기록명령 뒤 그 등기 전에 동일한 부분에 같은 종류의 설정등기가 된 경우"],["3","말소등기의 기록명령 뒤 그 등기 전에 등기상 이해관계인이 생긴 경우"],["4","등기관이 첨부정보 재제공을 명령했는데 신청인이 응하지 않은 경우"],["통지","등기를 할 수 없으면 그 뜻을 관할 지방법원과 이의신청인에게 통지(제2항)"]]}],"함정":"기록명령이 있어도 명령 뒤 사정이 바뀌어 네 경우 중 하나에 해당하면 등기할 수 없고, 그 뜻을 관할 지방법원과 이의신청인에게 통지한다. 말소등기에서 이해관계인은 말소로 불이익을 입는 사람이며, 지상권 위의 저당권자가 그 예다."},"36회-2차-098":{"한줄":"ㄴ(분할금지 약정 변경등기는 공유자 전원 공동신청)과 ㄹ(처분제한 등기 시 직권보존)만 옳다. ㄱ은 보존등기에 등기원인을 기록하지 않고, ㄷ은 시장 확인 보존이 건물에만 허용된다.","근거":[{"법령":"부동산등기법","조문":"제64조","원문":"등기관이 소유권보존등기를 할 때에는 제48조제1항제4호에도 불구하고 등기원인과 그 연월일을 기록하지 아니한다."},{"법령":"부동산등기법","조문":"제65조","원문":"1. 토지대장, 임야대장 또는 건축물대장에 최초의 소유자로 등록되어 있는 자 또는 그 상속인, 그 밖의 포괄승계인\n2. 확정판결에 의하여 자기의 소유권을 증명하는 자\n3. 수용(收用)으로 인하여 소유권을 취득하였음을 증명하는 자\n4. 특별자치도지사, 시장, 군수 또는 구청장(자치구의 구청장을 말한다)의 확인에 의하여 자기의 소유권을 증명하는 자(건물의 경우로 한정한다)"},{"법령":"부동산등기법","조문":"제66조제1항","원문":"① 등기관이 미등기부동산에 대하여 법원의 촉탁에 따라 소유권의 처분제한의 등기를 할 때에는 직권으로 소유권보존등기를 하고, 처분제한의 등기를 명하는 법원의 재판에 따라 소유권의 등기를 한다는 뜻을 기록하여야 한다."},{"법령":"부동산등기법","조문":"제67조제2항","원문":"② 제1항 후단의 약정의 변경등기는 공유자 전원이 공동으로 신청하여야 한다."}],"선지":[{"번호":1,"판정":"-","설명":"ㄴ도 옳으므로 ㄹ만 고른 조합은 부족하다."},{"번호":2,"판정":"-","설명":"ㄱ, ㄷ은 틀린 보기다."},{"번호":3,"판정":"-","설명":"ㄴ, ㄹ이 옳은 보기이므로 맞는 조합이다."},{"번호":4,"판정":"-","설명":"ㄱ, ㄷ은 틀린 보기이고 ㄹ이 빠졌다."},{"번호":5,"판정":"-","설명":"ㄱ, ㄷ은 틀린 보기다."}],"보기판정":[{"기호":"ㄱ","판정":"틀림","설명":"소유권보존등기에는 등기원인과 그 연월일을 기록하지 않는다(법 제64조)."},{"기호":"ㄴ","판정":"옳음","설명":"분할금지 약정의 변경등기는 공유자 전원이 공동으로 신청한다(법 제67조제2항)."},{"기호":"ㄷ","판정":"틀림","설명":"시장·군수·구청장 등의 확인으로 소유권을 증명하는 보존등기는 건물에 한정된다. 토지는 해당하지 않는다(법 제65조제4호)."},{"기호":"ㄹ","판정":"옳음","설명":"미등기부동산에 법원의 촉탁으로 처분제한 등기를 할 때는 직권으로 소유권보존등기를 한다(법 제66조제1항)."}],"개념":[{"종류":"표","제목":"미등기 부동산의 소유권보존등기 신청인(법 제65조)","머리":["신청인","비고"],"행":[["대장에 최초의 소유자로 등록된 자 또는 그 상속인, 그 밖의 포괄승계인","토지·임야·건축물대장"],["확정판결에 의하여 자기의 소유권을 증명하는 자","토지·건물 모두"],["수용으로 소유권을 취득하였음을 증명하는 자","토지·건물 모두"],["특별자치도지사·시장·군수·구청장의 확인으로 소유권을 증명하는 자","건물에 한정"]]},{"종류":"표","제목":"소유권보존등기의 그 밖의 규칙","머리":["항목","내용"],"행":[["신청인","등기명의인으로 될 자 또는 등기명의인의 단독신청(법 제23조제2항)"],["등기사항","등기원인과 그 연월일은 기록하지 않음(법 제64조)"],["직권 보존","미등기부동산에 법원의 촉탁으로 처분제한 등기를 하면 직권으로 소유권보존등기 + 재판에 따라 소유권의 등기를 한다는 뜻 기록(법 제66조제1항)"],["건물의 직권 보존","사용승인을 받아야 할 건물이 사용승인을 받지 않았으면 그 사실을 표제부에 기록. 사용승인이 이루어지면 명의인이 1개월 이내에 그 기록의 말소등기 신청(법 제66조제2항·제3항)"],["소유권 일부이전","이전되는 지분을 기록하고, 분할금지 약정이 있으면 그 약정도 기록. 약정 변경등기는 공유자 전원 공동신청(법 제67조)"]]}],"함정":"소유권보존등기에는 등기원인과 연월일이 없다. 확인서에 의한 보존은 건물에만 인정되고 토지에는 인정되지 않는다. 처분제한 등기를 위한 직권보존은 법원의 촉탁이 있을 때다."},"36회-2차-106":{"한줄":"기한 후 신고에 따른 무신고가산세 감면은 지방자치단체의 장이 결정할 것을 미리 알고 기한후신고서를 제출한 경우를 제외하므로 ⑤가 틀린 진술이다.","근거":[{"법령":"지방세기본법","조문":"제57조제2항제2호","원문":"과세표준 신고서를 법정신고기한까지 제출하지 아니한 자가 법정신고기한이 지난 후 6개월 이내에 제51조에 따라 기한 후 신고를 한 경우(제53조에 따른 가산세만 해당하며, 지방자치단체의 장이 과세표준과 세액을 결정할 것을 미리 알고 기한후신고서를 제출한 경우는 제외한다)에는 다음 각 목의 구분에 따른 금액"},{"법령":"지방세기본법","조문":"제53조제2항","원문":"제1항에도 불구하고 사기나 그 밖의 부정한 행위로 법정신고기한까지 과세표준 신고를 하지 아니한 경우에는 무신고납부세액의 100분의 40에 상당하는 금액을 가산세로 부과한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"지방세를 감면해도 가산세는 감면대상에 넣지 않는다(지방세기본법 제52조제3항)."},{"번호":2,"판정":"옳음","설명":"부정행위로 무신고한 경우 무신고납부세액의 100분의 40이다. 일반 무신고는 100분의 20이다(제53조제1항ㆍ제2항)."},{"번호":3,"판정":"옳음","설명":"신고 당시 소유권 소송으로 상속재산이 확정되지 않아 과소신고한 경우에는 과소신고가산세를 부과하지 않는다(제54조제3항제1호)."},{"번호":4,"판정":"옳음","설명":"정당한 사유가 있으면 가산세를 부과하지 않으며(제57조제1항), 감면을 받으려는 자는 대통령령으로 정하는 바에 따라 신청한다(제57조제3항)."},{"번호":5,"판정":"틀림","설명":"기한 후 신고로 무신고가산세를 감면받으려면 자치단체장이 결정할 것을 미리 알기 전에 신고해야 한다. 미리 알고 낸 경우에는 감면하지 않는다(제57조제2항제2호). 1개월 이내 기한 후 신고의 감면율 100분의 50은 이 예외가 없을 때 적용한다."}],"개념":[{"종류":"표","제목":"무신고ㆍ과소신고가산세(지방세기본법 제53조ㆍ제54조)","머리":["구분","일반","부정행위"],"행":[["무신고가산세","무신고납부세액의 100분의 20","무신고납부세액의 100분의 40"],["과소신고ㆍ초과환급신고가산세","과소신고납부세액등의 100분의 10","부정과소신고납부세액등의 100분의 40 + 나머지 과소신고납부세액등의 100분의 10"],["가산세를 부과하지 않는 경우","신고 당시 소유권 소송으로 상속재산이 확정되지 않아 과소신고한 경우 등(제54조제3항)","-"],["감면대상","지방세를 감면해도 가산세는 감면대상에서 제외(제52조제3항)","-"]]},{"종류":"표","제목":"가산세 감면(지방세기본법 제57조제2항)","머리":["신고 종류","법정신고기한이 지난 후","감면액"],"행":[["수정신고(과소신고가산세만)","1개월 이내","가산세액의 100분의 90"],["수정신고(과소신고가산세만)","1개월 초과 3개월 이내","100분의 75"],["수정신고(과소신고가산세만)","3개월 초과 6개월 이내","100분의 50"],["수정신고(과소신고가산세만)","6개월 초과 1년 이내","100분의 30"],["수정신고(과소신고가산세만)","1년 초과 1년 6개월 이내","100분의 20"],["수정신고(과소신고가산세만)","1년 6개월 초과 2년 이내","100분의 10"],["기한 후 신고(무신고가산세만)","1개월 이내","100분의 50"],["기한 후 신고(무신고가산세만)","1개월 초과 3개월 이내","100분의 30"],["기한 후 신고(무신고가산세만)","3개월 초과 6개월 이내","100분의 20"]]}],"함정":"감면율 자체는 ⑤의 100분의 50이 맞는다. 다만 수정신고ㆍ기한 후 신고 감면은 둘 다 지방자치단체의 장이 경정ㆍ결정할 것을 미리 알고 낸 신고는 대상에서 빠진다. 수정신고 감면은 과소신고가산세에, 기한 후 신고 감면은 무신고가산세에만 붙는다."},"36회-2차-109":{"한줄":"다섯 진술 중 첫째ㆍ둘째ㆍ셋째ㆍ다섯째 ○가 틀리고 넷째 ○만 옳으므로 틀린 것은 4개다.","근거":[{"법령":"지방세법","조문":"제104조제3호","원문":"이 경우 토지와 건축물의 범위에서 주택은 제외한다."},{"법령":"지방세법","조문":"제107조제2항제1호","원문":"공부상의 소유자가 매매 등의 사유로 소유권이 변동되었는데도 신고하지 아니하여 사실상의 소유자를 알 수 없을 때에는 공부상 소유자"},{"법령":"지방세법","조문":"제107조제3항","원문":"재산세 과세기준일 현재 소유권의 귀속이 분명하지 아니하여 사실상의 소유자를 확인할 수 없는 경우에는 그 사용자가 재산세를 납부할 의무가 있다."},{"법령":"지방세법","조문":"제106조제3항","원문":"재산세의 과세대상 물건을 공부상 등재현황과 달리 이용함으로써 재산세 부담이 낮아지는 경우 등 대통령령으로 정하는 경우에는 공부상 등재현황에 따라 재산세를 부과한다."}],"선지":[{"번호":1,"판정":"-","설명":"틀린 진술이 4개이므로 1개는 오답이다."},{"번호":2,"판정":"-","설명":"틀린 진술이 4개이므로 2개는 오답이다."},{"번호":3,"판정":"-","설명":"틀린 진술이 4개이므로 3개는 오답이다."},{"번호":4,"판정":"-","설명":"첫째(주택 부속토지 포함), 둘째(공부상 소유자에게 부과하지 않음), 셋째(사용자 납세의무), 다섯째(건축물 3분 구분)가 틀려 4개다."},{"번호":5,"판정":"-","설명":"넷째 진술(공부상 현황에 따른 부과)이 옳으므로 5개 모두 틀린 것은 아니다."}],"보기판정":[{"기호":"○1","판정":"틀림","설명":"주택은 토지와 건축물의 범위에서 제외되므로 주택의 부속토지는 토지 과세대상에 포함되지 않는다(지방세법 제104조제3호)."},{"기호":"○2","판정":"틀림","설명":"공부상 소유자가 신고하지 않아 사실상 소유자를 알 수 없으면 공부상 소유자에게 부과한다(제107조제2항제1호)."},{"기호":"○3","판정":"틀림","설명":"소유권 귀속이 분명하지 않아 사실상 소유자를 확인할 수 없으면 사용자가 납세의무를 진다(제107조제3항)."},{"기호":"○4","판정":"옳음","설명":"재산세 부담이 낮아지도록 공부상 현황과 달리 이용하는 경우 등에는 공부상 등재현황에 따라 부과한다(제106조제3항 단서)."},{"기호":"○5","판정":"틀림","설명":"종합합산ㆍ별도합산ㆍ분리과세 구분은 토지에 적용한다. 건축물에는 이 구분이 없다(제106조제1항)."}],"개념":[{"종류":"표","제목":"재산세 납세의무자(지방세법 제107조)","머리":["구분","납세의무자"],"행":[["원칙","과세기준일(6월 1일) 현재 재산을 사실상 소유하고 있는 자"],["공유재산","지분권자(지분 표시가 없으면 균등)"],["주택의 건물과 부속토지 소유자가 다른 경우","산출세액을 건축물과 토지의 시가표준액 비율로 안분한 부분의 각 소유자"],["공부상 소유자가 소유권 변동을 신고하지 않아 사실상 소유자를 알 수 없는 경우","공부상 소유자"],["상속이 개시되었으나 상속등기가 이행되지 않고 사실상 소유자를 신고하지 않은 경우","행정안전부령으로 정하는 주된 상속자"],["공부상 개인 명의로 등재된 사실상 종중재산으로서 종중 소유를 신고하지 않은 경우","공부상 소유자"],["국가ㆍ지방자치단체와 연부로 매매계약을 체결하고 사용권을 무상으로 받은 경우","매수계약자"],["수탁자 명의로 등기ㆍ등록된 신탁재산","위탁자"],["환지방식 도시개발사업ㆍ재개발사업에서 체비지ㆍ보류지로 정한 경우","사업시행자"],["외국인 소유 항공기ㆍ선박을 임차하여 수입하는 경우","수입하는 자"],["파산선고 이후 파산종결 결정까지 파산재단에 속하는 재산","공부상 소유자"],["소유권 귀속이 분명하지 않아 사실상 소유자를 확인할 수 없는 경우","사용자"]]},{"종류":"표","제목":"토지의 재산세 과세대상 구분(지방세법 제106조제1항)","머리":["구분","대상 토지"],"행":[["종합합산과세대상","별도합산ㆍ분리과세대상을 제외한 토지"],["별도합산과세대상","공장용 건축물의 부속토지 등 대통령령으로 정하는 건축물의 부속토지"],["별도합산과세대상","차고용ㆍ보세창고용ㆍ시험연구검사용ㆍ물류단지시설용 토지 등 업무 또는 경제활동에 활용되는 토지"],["별도합산과세대상","철거ㆍ멸실된 건축물 또는 주택의 부속토지로서 대통령령으로 정하는 토지"],["분리과세대상","공장용지ㆍ전ㆍ답ㆍ과수원ㆍ목장용지, 산림 보호육성용 임야ㆍ종중 소유 임야"],["분리과세대상","골프장용 토지ㆍ고급오락장용 토지, 개발제한구역 지정 전 취득한 공장 부속토지"],["분리과세대상","국가ㆍ지방자치단체 지원 사업용, 기반시설용, 개발사업용 토지 등 대통령령으로 정하는 토지"],["건축물ㆍ주택","3분 구분이 없다(토지에만 적용)"]]}],"함정":"토지의 정의 앞부분만 읽으면 주택 부속토지가 토지로 보이지만, 정의 규정은 토지와 건축물의 범위에서 주택을 제외한다. 소유자를 알 수 없을 때의 납세의무자는 두 경우로 갈린다. 공부상 소유자가 신고를 안 한 경우는 공부상 소유자, 소유권 귀속이 불분명한 경우는 사용자다. 3분 구분은 토지에만 있다."},"36회-2차-113":{"한줄":"납부유예는 주택분 종합부동산세에만 있고 신청도 납부기한 만료 3일 전까지 해야 하므로, 토지분 납부유예를 만료일까지 신청하면 허가할 수 있다는 ④가 틀리다.","근거":[{"법령":"종합부동산세법","조문":"제20조의2제1항","원문":"관할세무서장은 다음 각 호의 요건을 모두 충족하는 납세의무자가 주택분 종합부동산세액의 납부유예를 그 납부기한 만료 3일 전까지 신청하는 경우 이를 허가할 수 있다."},{"법령":"종합부동산세법","조문":"제13조제2항","원문":"별도합산과세대상인 토지에 대한 종합부동산세의 과세표준은 납세의무자별로 해당 과세대상토지의 공시가격을 합산한 금액에서 80억원을 공제한 금액에 부동산 시장의 동향과 재정 여건 등을 고려하여 100분의 60부터 100분의 100까지의 범위에서 대통령령으로 정하는 공정시장가액비율을 곱한 금액으로 한다."},{"법령":"종합부동산세법","조문":"제16조제3항","원문":"제1항 및 제2항에도 불구하고 종합부동산세를 신고납부방식으로 납부하고자 하는 납세의무자는 종합부동산세의 과세표준과 세액을 해당 연도 12월 1일부터 12월 15일까지 대통령령으로 정하는 바에 따라 관할세무서장에게 신고하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"토지는 종합합산과세대상과 별도합산과세대상으로 나누어 과세한다(법 제11조). 분리과세대상은 종합부동산세 과세대상이 아니다."},{"번호":2,"판정":"옳음","설명":"별도합산 토지의 공제금액은 80억원이고 공정시장가액비율은 100분의 100이다(법 제13조제2항ㆍ제3항, 시행령 제2조의4제2항)."},{"번호":3,"판정":"옳음","설명":"신고납부를 택하면 12월 1일부터 12월 15일까지 신고하고, 이 경우 부과 결정은 없었던 것으로 본다(법 제16조제3항)."},{"번호":4,"판정":"틀림","설명":"납부유예는 주택분 종합부동산세액만 대상이고 신청기한은 납부기한 만료 3일 전까지다. 토지분은 납부유예 대상이 아니다(법 제20조의2제1항)."},{"번호":5,"판정":"옳음","설명":"주택분 납부유예 신청을 받으면 납부기한 만료일까지 허가 여부를 통지한다(법 제20조의2제2항)."}],"개념":[{"종류":"표","제목":"종합부동산세 공제금액과 공정시장가액비율","머리":["과세대상","공제금액","공정시장가액비율","근거"],"행":[["종합합산 토지","5억원","100분의 100","법 제13조제1항, 시행령 제2조의4제2항"],["별도합산 토지","80억원","100분의 100","법 제13조제2항, 시행령 제2조의4제2항"],["주택(일반)","9억원","100분의 60","법 제8조제1항제3호, 시행령 제2조의4제1항"],["주택(1세대 1주택자)","12억원","100분의 60","법 제8조제1항제1호"],["주택(최고세율 적용 법인 등)","0원","100분의 60","법 제8조제1항제2호"]]},{"종류":"흐름","제목":"종합부동산세 과세ㆍ납부 절차","단계":[{"이름":"과세기준일","설명":"재산세 과세기준일과 같은 6월 1일(종합부동산세법 제3조, 지방세법 제114조)"},{"이름":"합산배제 주택 신고","설명":"합산배제 주택 보유 납세의무자는 9월 16일~9월 30일 보유현황 신고(법 제8조제3항)"},{"이름":"부과ㆍ징수 또는 신고납부","설명":"12월 1일~12월 15일. 관할세무서장이 결정해 부과ㆍ징수하며 납부고지서는 납부기간 개시 5일 전까지 발급. 신고납부를 택하면 같은 기간에 신고(법 제16조)"},{"이름":"분납","설명":"납부할 세액이 250만원을 초과하면 납부기한이 지난 날부터 6개월 이내 분납(법 제20조). 250만원 초과 500만원 이하는 250만원을 뺀 금액, 500만원 초과는 50% 이하(시행령 제16조)"},{"이름":"납부유예(주택분만)","설명":"1세대 1주택자 등 요건 충족, 담보 제공, 납부기한 만료 3일 전까지 신청. 세무서장은 만료일까지 허가 여부 통지(법 제20조의2)"}]}],"함정":"주택분에만 있는 제도를 토지분에도 적용하는 선지가 나온다. 납부유예는 주택분 한정이고, 신청기한도 만료일이 아니라 만료 3일 전이다. 이 문항은 두 군데가 모두 어긋난다."},"36회-1차-008":{"한줄":"토지는 물리적 공급이 고정되어 있고 개발에 시간이 걸려 수급조절이 어렵다.","근거":[{"이론":"부동산시장의 특성","내용":"거래의 비공개성, 정보의 비대칭성, 수급조절의 곤란, 법·제도 규제, 국지성(부분시장), 상품의 이질성, 단기 비탄력적 공급."}],"선지":[{"번호":1,"판정":"틀림","설명":"수급조절이 어렵다. 공급이 비탄력적이고 개발에 시간이 걸린다."},{"번호":2,"판정":"옳음","설명":"토지이용 규제 등 법·제도 규제가 많다."},{"번호":3,"판정":"옳음","설명":"개별성 때문에 재화가 이질적이다."},{"번호":4,"판정":"옳음","설명":"거래가 비공개적이어서 정보가 불완전하고 비대칭적이다."},{"번호":5,"판정":"옳음","설명":"지역별·용도별로 시장이 나뉘는 국지성이 있다."}],"개념":[{"종류":"표","제목":"부동산시장의 특성","머리":["특성","원인·내용"],"행":[["수급조절 곤란","공급의 비탄력성, 건설 시차"],["정보 비대칭","거래의 비공개성, 개별성"],["국지성","부동성 → 부분시장으로 분화"],["이질성","개별성 → 표준화 곤란"],["법·제도 규제","토지이용 규제, 거래 규제"]]},{"종류":"표","제목":"효율적 시장의 세 형태","머리":["형태","반영된 정보","초과이윤 가능 여부"],"행":[["약성","과거의 정보","기술적 분석 무의미, 기본적 분석·내부정보로는 가능"],["준강성","과거 + 공표된 정보","기술적·기본적 분석 무의미, 내부정보로는 가능"],["강성","과거 + 공표 + 내부정보","어떤 정보로도 불가능"]]}],"함정":"수급조절이 어렵다는 점을 반대로 외운 경우 고른다. 토지는 단기 공급이 고정된다."},"36회-1차-032":{"한줄":"원금균등 연 원금 3,000만 원과 1회차 이자 2,700만 원에서 금리 3%를 얻고, 10회차 이자는 잔금 6억 3,000만 원의 3%인 1,890만 원이다.","근거":[{"이론":"원금균등분할상환","내용":"매기 원금상환액 = 대출액 ÷ 상환횟수. 이자 = 기초 잔금 × 금리. 원리금은 이자가 줄어드는 만큼 매기 감소한다."}],"선지":[{"번호":1,"판정":"-","설명":"1,710만 원은 잔금 5억 7,000만 원의 3%로, 12회차 이자다."},{"번호":2,"판정":"-","설명":"1,800만 원은 잔금 6억 원의 3%로, 11회차 이자다."},{"번호":3,"판정":"-","설명":"금리 3%, 10회차 이자 6억 3,000만 원 × 3% = 1,890만 원이다."},{"번호":4,"판정":"-","설명":"연 4%이면 1회차 원리금이 3,000 + 3,600 = 6,600만 원이 되어 조건과 맞지 않고, 2,450만 원은 어느 회차의 이자와도 맞지 않는다."},{"번호":5,"판정":"-","설명":"연 4%이면 1회차 원리금이 6,600만 원이라 조건과 맞지 않는다. 10회차 이자 2,520만 원은 4%를 가정할 때의 값이다."}],"개념":[{"종류":"계산","제목":"10회차 이자납부액 구하기","단계":[{"설명":"연간 원금상환액","식":"9억 ÷ 30","값":"3,000만원"},{"설명":"1회차 이자","식":"5,700 − 3,000","값":"2,700만원"},{"설명":"대출금리","식":"2,700 ÷ 90,000","값":"3%"},{"설명":"9회까지 상환한 원금","식":"3,000 × 9","값":"2억 7,000만원"},{"설명":"10회차 기초 잔금","식":"9억 − 2억 7,000만","값":"6억 3,000만원"},{"설명":"10회차 이자","식":"6억 3,000만 × 3%","값":"1,890만원"}]},{"종류":"표","제목":"상환방식 비교","머리":["구분","원리금균등","원금균등","만기일시"],"행":[["매기 원금","점차 증가","일정","만기에 전액"],["매기 이자","점차 감소","점차 감소","일정 (잔금이 그대로)"],["매기 원리금","일정","점차 감소","이자만 납부"],["초기 상환부담","원금균등보다 작음","가장 큼","이자만이라 가장 작음"],["총 이자","원금균등보다 많음","균등 방식 중 작음","가장 많음"]]}],"함정":"회차를 하나 틀리면 ①(12회차)·②(11회차) 값이 나온다. 10회차 이자는 9회까지 상환한 뒤의 잔금에 곱한다. 연 4%는 1회차 원리금 6,600만 원이 되어 조건에 어긋난다."},"36회-1차-049":{"한줄":"무권리자 처분의 추인은 무권대리 추인에 준해 계약 시로 소급하여 효력이 생긴다.","근거":[{"법령":"민법","조문":"제139조","원문":"무효인 법률행위는 추인하여도 그 효력이 생기지 아니한다. 그러나 당사자가 그 무효임을 알고 추인한 때에는 새로운 법률행위로 본다."},{"법령":"민법","조문":"제133조","원문":"추인은 다른 의사표시가 없는 때에는 계약시에 소급하여 그 효력이 생긴다. 그러나 제삼자의 권리를 해하지 못한다."},{"판례":"대법원 1999. 6. 17. 선고 98다40459 전원합의체 판결","요지":"토지거래허가구역 안의 허가 전 계약은 유동적 무효이고, 허가구역 지정이 해제되면 확정적으로 유효가 된다."}],"선지":[{"번호":1,"판정":"옳음","설명":"묵시적 추인도 가능하다."},{"번호":2,"판정":"옳음","설명":"무효 원인이 소멸한 후에 추인해야 새로운 법률행위로 효력이 있다."},{"번호":3,"판정":"옳음","설명":"무효인 법률행위에는 보호할 법률효과가 없다."},{"번호":4,"판정":"틀림","설명":"무권리자 처분의 추인은 소급한다. 무효행위 추인(비소급)과 구별한다."},{"번호":5,"판정":"옳음","설명":"지정 해제로 유동적 무효가 확정적 유효로 바뀐다."}],"개념":[{"종류":"표","제목":"무효를 살리는 길","머리":["구분","요건","효과","시점"],"행":[["일부무효(제137조)","무효 부분이 없어도 행위했을 것으로 인정","나머지 유효","-"],["무효행위 전환(제138조)","다른 법률행위의 요건 구비 + 당사자 의사","다른 법률행위로 유효","-"],["무효행위 추인(제139조)","무효임을 알고 추인","새로운 법률행위","추인한 때부터"],["무권대리·무권리자 처분 추인","본인·권리자의 추인","계약 시로 소급","소급"]]},{"종류":"표","제목":"무효와 취소 비교","머리":["구분","무효","취소"],"행":[["효력","처음부터 당연 무효","취소하면 처음부터 무효"],["주장권자","누구든지","취소권자만(제140조)"],["기간","제한 없음","추인할 수 있는 날부터 3년, 행위일부터 10년"],["추인","원칙 불가, 알고 추인 시 새 행위","추인하면 취소 불가"]]}],"함정":"4번을 비소급이라고 외운 무효행위 추인과 섞기 쉽다. 무권리자 처분 추인은 소급한다."},"36회-1차-065":{"한줄":"위험부담 규정은 임의규정이라 특약으로 달리 정할 수 있고, 쌍방 무책 불능에는 해제권이 없으며 수용보상금청구권은 이전청구의 대상일 뿐이다.","근거":[{"법령":"민법","조문":"제537조","원문":"제537조(채무자위험부담주의) 쌍무계약의 당사자 일방의 채무가 당사자쌍방의 책임없는 사유로 이행할 수 없게 된 때에는 채무자는 상대방의 이행을 청구하지 못한다."},{"법령":"민법","조문":"제546조","원문":"제546조(이행불능과 해제) 채무자의 책임있는 사유로 이행이 불능하게 된 때에는 채권자는 계약을 해제할 수 있다."},{"판례":"대법원 판례(대상청구)","요지":"이행불능을 가져온 사정으로 채무자가 대상을 취득한 경우 채권자는 그 대상의 이전을 청구할 수 있다. 쌍방 무책의 불능에서 채권자는 반대급부를 이행하고 채무자에게 보상금청구권의 양도 또는 보상금의 인도를 청구하는 것이지, 청구권이 당연히 채권자에게 귀속하지는 않는다."}],"선지":[{"번호":1,"판정":"-","설명":"옳은 것은 ㄱ뿐이다. 조합이 맞다."},{"번호":2,"판정":"-","설명":"ㄷ은 틀린 보기다. ㄱ이 빠져 있다."},{"번호":3,"판정":"-","설명":"ㄴ이 틀린 보기다."},{"번호":4,"판정":"-","설명":"ㄴ, ㄷ이 모두 틀린 보기다."},{"번호":5,"판정":"-","설명":"ㄴ, ㄷ이 포함되어 있어 틀린 조합이다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"제537조는 임의규정이다. 대가위험을 매수인이 지는 특약은 유효하다."},{"기호":"ㄴ","판정":"틀림","설명":"재결수용은 쌍방 무책 사유다. 제546조의 해제는 채무자의 책임 있는 불능을 요건으로 하므로 해제할 수 없다. 乙은 대금지급의무를 면한다(제537조)."},{"기호":"ㄷ","판정":"틀림","설명":"乙은 대금을 지급하고 대상(보상금청구권 또는 보상금)의 이전을 청구할 수 있을 뿐, 청구권 자체가 당연히 귀속하지는 않는다(판례)."}],"개념":[{"종류":"표","제목":"후발적 불능과 위험부담","머리":["귀책","계약 해제","반대급부 청구","근거"],"행":[["채무자 귀책","가능","채무불이행 책임(손해배상)","제546조"],["쌍방 무책","불가","채무자는 대금 청구 불가","제537조"],["채권자 귀책","채권자는 불가","채무자는 대금 청구 가능, 자기 채무 면한 이익 상환","제538조 제1항·제2항"]]},{"종류":"흐름","제목":"쌍방 무책 불능 시 처리","단계":[{"이름":"불능 발생","설명":"재결수용 등 쌍방 책임 없는 사유로 소유권 이전 불가"},{"이름":"대금 청구 불가","설명":"매도인은 대금청구를 못 하고 받은 중도금은 반환(제537조, 부당이득)"},{"이름":"대상청구","설명":"매수인이 반대급부를 이행하고 보상금청구권 이전 또는 보상금 인도를 청구"},{"이름":"특약","설명":"위험부담은 임의규정이라 매수인 부담으로 정하면 그대로 효력"}]}],"함정":"ㄷ을 맞다고 읽기 쉽다. 대금을 모두 냈으니 보상금청구권이 자기 것이 된다는 직관 때문이다. 판례는 이전을 청구할 수 있다는 것이고 청구권이 저절로 귀속하지는 않는다. ㄴ은 불능이 채무자 책임일 때만 제546조로 해제한다."},"36회-2차-002":{"한줄":"자격증의 양도·양수·대여는 금지되고 그 알선도 누구에게나 금지되므로 ㄱ·ㄴ만 옳다(법 제7조).","근거":[{"법령":"공인중개사법","조문":"제7조","원문":"제7조(자격증 대여 등의 금지)\n①공인중개사는 다른 사람에게 자기의 성명을 사용하여 중개업무를 하게 하거나 자기의 공인중개사자격증을 양도 또는 대여하여서는 아니된다.\n②누구든지 다른 사람의 공인중개사자격증을 양수하거나 대여받아 이를 사용하여서는 아니된다.\n③ 누구든지 제1항 및 제2항에서 금지한 행위를 알선하여서는 아니 된다."},{"법령":"공인중개사법","조문":"제49조 제1항 제1호 1의2.","원문":"①다음 각 호의 어느 하나에 해당하는 자는 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.\n1. 제7조제1항 또는 제2항을 위반하여 다른 사람에게 자기의 성명을 사용하여 중개업무를 하게 하거나 공인중개사자격증을 양도ㆍ대여한 자 또는 다른 사람의 공인중개사자격증을 양수ㆍ대여받은 자\n1의2. 제7조제3항을 위반하여 같은 조 제1항 및 제2항에서 금지한 행위를 알선한 자\n2. 제8조의 규정을 위반하여 공인중개사가 아닌 자로서 공인중개사 또는 이와 유사한 명칭을 사용한 자\n3. 제12조의 규정을 위반하여 이중으로 중개사무소의 개설등록을 하거나 둘 이상의 중개사무소에 소속된 자\n4. 제13조제1항의 규정을 위반하여 둘 이상의 중개사무소를 둔 자\n5. 제13조제2항의 규정을 위반하여 임시 중개시설물을 설치한 자\n5의2. 제15조제3항을 위반하여 중개보조원을 고용한 자\n6. 제18조제2항의 규정을 위반하여 개업공인중개사가 아닌 자로서 \"공인중개사사무소\", \"부동산중개\" 또는 이와 유사한 명칭을 사용한 자\n6의2. 제18조의2제3항을 위반하여 개업공인중개사가 아닌 자로서 중개업을  하기 위하여 중개대상물에 대한 표시ㆍ광고를 한 자\n7. 제19조제1항 또는 제2항을 위반하여 다른 사람에게 자기의 성명 또는 상호를 사용하여 중개업무를 하게 하거나 중개사무소등록증을 다른 사람에게 양도ㆍ대여한 자 또는 다른 사람의 성명ㆍ상호를 사용하여 중개업무를 하거나 중개사무소등록증을 양수ㆍ대여받은 자\n7의2. 제19조제3항을 위반하여 같은 조 제1항 및 제2항에서 금지한 행위를 알선한 자\n8. 제24조제4항의 규정을 위반하여 정보를 공개한 자\n9. 제29조제2항의 규정을 위반하여 업무상 비밀을 누설한 자\n10. 제33조제1항제1호부터 제4호까지의 규정을 위반한 자\n1. 제7조제1항 또는 제2항을 위반하여 다른 사람에게 자기의 성명을 사용하여 중개업무를 하게 하거나 공인중개사자격증을 양도ㆍ대여한 자 또는 다른 사람의 공인중개사자격증을 양수ㆍ대여받은 자\n1의2. 제7조제3항을 위반하여 같은 조 제1항 및 제2항에서 금지한 행위를 알선한 자"}],"선지":[{"번호":1,"판정":"-","설명":"ㄴ도 옳으므로 ㄱ만으로는 부족하다."},{"번호":2,"판정":"-","설명":"ㄱ, ㄴ이 옳다."},{"번호":3,"판정":"-","설명":"ㄷ이 틀려서 맞지 않다."},{"번호":4,"판정":"-","설명":"ㄱ이 빠지고 ㄷ이 들어갔다."},{"번호":5,"판정":"-","설명":"ㄷ이 틀려서 맞지 않다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"자격증 양도·대여는 금지다(법 제7조 제1항)."},{"기호":"ㄴ","판정":"옳음","설명":"남의 자격증을 양수하거나 대여받아 쓰는 것도 누구에게나 금지다(법 제7조 제2항)."},{"기호":"ㄷ","판정":"틀림","설명":"자격증 양도·대여의 알선은 금지다(법 제7조 제3항). 위반하면 1년 이하 징역 또는 1천만원 이하 벌금(법 제49조 제1항 제1호의2)."}],"개념":[{"종류":"표","제목":"자격증·등록증 대여 등 금지 비교","머리":["구분","금지 행위","금지 대상자","벌칙"],"행":[["공인중개사 자격증(법 제7조)","성명 사용 중개업무, 자격증 양도·대여, 양수·대여받아 사용, 알선","①②는 공인중개사 또는 누구든지, ③ 알선은 누구든지","1년 이하 징역 또는 1천만원 이하 벌금"],["중개사무소등록증(법 제19조)","성명·상호 사용 중개업무, 등록증 양도·대여, 양수·대여받아 사용, 알선","①은 개업공인중개사, ②③은 누구든지","1년 이하 징역 또는 1천만원 이하 벌금"],["행정처분","자격증: 성명 사용·양도·대여는 자격취소 사유","등록증: 성명·상호 사용, 양도·대여는 절대적 등록취소 사유","자격취소·등록취소 후 3년간 결격"]]},{"종류":"표","제목":"유사명칭 사용금지","머리":["구분","금지 명칭","벌칙"],"행":[["공인중개사가 아닌 자","공인중개사 또는 이와 유사한 명칭","1년 이하 징역 또는 1천만원 이하 벌금"],["개업공인중개사가 아닌 자","공인중개사사무소, 부동산중개 또는 이와 유사한 명칭","1년 이하 징역 또는 1천만원 이하 벌금"]]}],"함정":"ㄷ을 고르면 틀린다. 금지 대상이 ‘양도·대여’ 행위자뿐이라고 보기 쉬운데 2023년 신설된 제3항이 알선 자체를 금지한다.","개정":"2023.6.1 신설된 법 제7조 제3항이 자격증 양도·대여 알선을 금지한다(제49조 제1항 제1호의2)."},"36회-2차-003":{"한줄":"개업공인중개사는 다른 개업공인중개사의 소속공인중개사·중개보조원이 될 수 없다(법 제12조 제2항).","근거":[{"법령":"공인중개사법","조문":"제12조 제2항","원문":"②개업공인중개사등은 다른 개업공인중개사의 소속공인중개사ㆍ중개보조원 또는 개업공인중개사인 법인의 사원ㆍ임원이 될 수 없다."},{"법령":"공인중개사법","조문":"제9조 제2항","원문":"②공인중개사(소속공인중개사는 제외한다) 또는 법인이 아닌 자는 제1항에 따라 중개사무소의 개설등록을 신청할 수 없다."},{"법령":"공인중개사법 시행령","조문":"제13조 제1항 제2호 가목","원문":"①법 제9조제3항에 따른 중개사무소 개설등록의 기준은 다음 각 호와 같다. 다만, 다른 법률의 규정에 따라 부동산중개업을 할 수 있는 경우에는 다음 각 호의 기준을 적용하지 아니한다.\n1. 공인중개사가 중개사무소를 개설하고자 하는 경우\n가. 법 제34조제1항의 규정에 따른 실무교육을 받았을 것\n나. 건축물대장(「건축법」 제20조제5항에 따른 가설건축물대장은 제외한다. 이하 같다)에 기재된 건물(준공검사, 준공인가, 사용승인, 사용검사 등을 받은 건물로서 건축물대장에 기재되기 전의 건물을 포함한다. 이하 같다)에 중개사무소를 확보(소유ㆍ전세ㆍ임대차 또는 사용대차 등의 방법에 의하여 사용권을 확보하여야 한다)할 것\n2. 법인이 중개사무소를 개설하려는 경우\n가. 「상법」상 회사 또는 「협동조합 기본법」 제2조제1호에 따른 협동조합(같은 조 제3호에 따른 사회적협동조합은 제외한다)으로서 자본금이 5천만원 이상일 것\n나. 법 제14조에 규정된 업무만을 영위할 목적으로 설립된 법인일 것\n다. 대표자는 공인중개사이어야 하며, 대표자를 제외한 임원 또는 사원(합명회사 또는 합자회사의 무한책임사원을 말한다. 이하 이 조에서 같다)의 3분의 1 이상은 공인중개사일 것\n라. 대표자, 임원 또는 사원 전원 및 분사무소의 책임자(법 제13조제3항에 따라 분사무소를 설치하려는 경우에만 해당한다)가 법 제34조제1항에 따른 실무교육을 받았을 것\n마. 건축물대장에 기재된 건물에 중개사무소를 확보(소유ㆍ전세ㆍ임대차 또는 사용대차 등의 방법에 의하여 사용권을 확보하여야 한다)할 것\n2. 법인이 중개사무소를 개설하려는 경우\n가. 법 제34조제1항의 규정에 따른 실무교육을 받았을 것"},{"법령":"공인중개사법","조문":"제10조 제5호 제2항","원문":"5. 금고 이상의 형의 집행유예를 받고 그 유예기간이 만료된 날부터 2년이 지나지 아니한 자\n②제1항제1호부터 제11호까지의 어느 하나에 해당하는 자는 소속공인중개사 또는 중개보조원이 될 수 없다."}],"선지":[{"번호":1,"판정":"틀림","설명":"이중소속은 금지다. 개업공인중개사등은 다른 개업공인중개사의 소속공인중개사·중개보조원이 될 수 없다(법 제12조 제2항)."},{"번호":2,"판정":"옳음","설명":"피성년후견인은 결격사유다(법 제10조 제1항 제2호)."},{"번호":3,"판정":"옳음","설명":"공인중개사(소속공인중개사 제외)나 법인이 아니면 신청할 수 없다(법 제9조 제2항)."},{"번호":4,"판정":"옳음","설명":"법인의 자본금은 5천만원 이상이어야 한다(영 제13조 제1항 제2호 가목)."},{"번호":5,"판정":"옳음","설명":"집행유예 기간 만료 후 2년이 지나지 않은 자는 결격이고, 결격자는 소속공인중개사·중개보조원도 될 수 없다(법 제10조 제1항 제5호·제2항)."}],"개념":[{"종류":"표","제목":"형벌별 결격 기간","머리":["구분","결격 기간"],"행":[["금고 이상 실형","집행 종료·면제일부터 3년"],["금고 이상 집행유예","유예기간 + 만료일부터 2년"],["선고유예","결격 아님"],["이 법 위반 벌금 300만원 이상","선고 후 3년"],["이 법 위반 벌금 300만원 미만, 다른 법 위반 벌금","결격 아님"],["자격 취소","취소 후 3년"],["등록 취소(사망·해산·결격·등록기준 미달 제외)","취소 후 3년"]]},{"종류":"표","제목":"법인 개설등록 기준(영 제13조)","머리":["항목","기준"],"행":[["형태·자본금","상법상 회사 또는 협동조합(사회적협동조합 제외), 자본금 5천만원 이상"],["업무","법 제14조 업무만 영위할 목적으로 설립"],["대표자","공인중개사"],["임원·사원","대표자 제외 3분의 1 이상 공인중개사"],["실무교육","대표자·임원·사원 전원(분사무소 책임자 포함)"],["사무소","건축물대장 기재 건물에 사용권 확보"]]}],"함정":"개업공인중개사가 다른 곳의 ‘중개보조원’이 되는 것은 자격이 필요 없다고 생각해 맞는 문장으로 보기 쉽다. 이중소속 금지는 소속공인중개사·중개보조원·법인 임원 전부에 걸린다."},"36회-2차-026":{"한줄":"거짓 신고를 조장하거나 방조한 자는 500만원 이하의 과태료 대상이다(법 제28조제2항제3호). 징역ㆍ벌금 대상은 거짓으로 신고한 자 본인이다(법 제26조제1항).","근거":[{"법령":"부동산 거래신고 등에 관한 법률","조문":"제26조","원문":"제26조(벌칙)\n① 부당하게 재물이나 재산상 이득을 취득하거나 제3자로 하여금 이를 취득하게 할 목적으로 제4조제4호 또는 제5호를 위반하여 거짓으로 제3조 또는 제3조의2에 따라 신고한 자는 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다.\n② 제9조제1항에 따른 허가를 받지 아니하고 토지취득계약을 체결하거나 부정한 방법으로 허가를 받아 토지취득계약을 체결한 외국인등은 2년 이하의 징역 또는 2천만원 이하의 벌금에 처한다.\n③ 제11조제1항에 따른 허가 또는 변경허가를 받지 아니하고 토지거래계약을 체결하거나, 속임수나 그 밖의 부정한 방법으로 토지거래계약 허가를 받은 자는 2년 이하의 징역 또는 계약 체결 당시의 개별공시지가에 따른 해당 토지가격의 100분의 30에 해당하는 금액 이하의 벌금에 처한다.\n④ 제21조에 따른 허가 취소, 처분 또는 조치명령을 위반한 자는 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제28조 제2항","원문":"② 다음 각 호의 어느 하나에 해당하는 자에게는 500만원 이하의 과태료를 부과한다.\n1. 제3조제1항부터 제4항까지의 규정을 위반하여 같은 항에 따른 신고를 하지 아니한 자(공동신고를 거부한 자를 포함한다)\n1의2. 제3조의2제1항을 위반하여 같은 항에 따른 신고를 하지 아니한 자(공동신고를 거부한 자를 포함한다)\n2. 제4조제1호를 위반하여 개업공인중개사에게 제3조에 따른 신고를 하지 아니하게 하거나 거짓으로 신고하도록 요구한 자\n3. 제4조제3호를 위반하여 거짓으로 제3조에 따른 신고를 하는 행위를 조장하거나 방조한 자\n4. 제6조를 위반하여 거래대금 지급을 증명할 수 있는 자료 외의 자료를 제출하지 아니하거나 거짓으로 제출한 자"},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제4조 제3호","원문":"3. 거짓으로 제3조 또는 제3조의2에 따른 신고를 하는 행위를 조장하거나 방조하는 행위"}],"선지":[{"번호":1,"판정":"틀림","설명":"조장ㆍ방조(법 제4조제3호)는 징역ㆍ벌금이 아니라 500만원 이하의 과태료다(법 제28조제2항제3호). 부당이득 목적의 처벌은 제4조제4호ㆍ제5호의 거짓 신고 본인에게 적용된다(법 제26조제1항)."},{"번호":2,"판정":"옳음","설명":"허가 없이 토지취득계약을 체결한 외국인등은 2년 이하의 징역 또는 2천만원 이하의 벌금이다(법 제26조제2항)."},{"번호":3,"판정":"옳음","설명":"허가 없이 토지거래계약을 체결하면 2년 이하의 징역 또는 개별공시지가에 따른 토지가격의 100분의 30 이하 벌금이다(법 제26조제3항)."},{"번호":4,"판정":"옳음","설명":"속임수나 부정한 방법으로 허가를 받은 자도 같은 조 제3항의 처벌 대상이다."},{"번호":5,"판정":"옳음","설명":"법 제21조에 따른 허가 취소, 처분 또는 조치명령을 위반한 자는 1년 이하의 징역 또는 1천만원 이하의 벌금이다(법 제26조제4항)."}],"개념":[{"종류":"표","제목":"부동산 거래신고법 벌칙과 과태료","머리":["구분","대상 행위","근거"],"행":[["3년 이하 징역 또는 3천만원 이하 벌금","부당한 재산상 이득을 얻을 목적으로 거짓 거래신고ㆍ해제등 신고","법 제26조제1항"],["2년 이하 징역 또는 2천만원 이하 벌금","허가 없이 또는 부정한 방법으로 허가를 받아 토지취득계약을 체결한 외국인등","법 제26조제2항"],["2년 이하 징역 또는 토지가격 100분의 30 이하 벌금","허가 없이 토지거래계약 체결, 부정한 방법의 허가","법 제26조제3항"],["1년 이하 징역 또는 1천만원 이하 벌금","허가 취소, 처분 또는 조치명령 위반","법 제26조제4항"],["3천만원 이하 과태료","거짓 거래신고ㆍ해제등 신고(벌칙 대상이 아닌 경우), 거래대금 지급 증명자료 미제출ㆍ거짓 제출","법 제28조제1항"],["500만원 이하 과태료","신고 미이행(공동신고 거부 포함), 개업공인중개사에게 신고 안 하게 하거나 거짓 신고 요구, 거짓 신고 조장ㆍ방조","법 제28조제2항"],["취득가액 100분의 10 이하 과태료","거래신고를 거짓으로 한 자","법 제28조제3항"],["300만원 이하 과태료","외국인등의 취득 신고 위반(법 제8조제1항)","법 제28조제4항"],["100만원 이하 과태료","외국인등의 취득 신고(제8조제2항)ㆍ계속보유 신고 위반, 주택 임대차 신고 위반","법 제28조제5항"]]},{"종류":"표","제목":"신고포상금 (법 제25조의2, 시행령 제19조의2)","머리":["신고 대상","포상금","지급 요건"],"행":[["거짓 거래가격 신고, 거짓 거래신고ㆍ해제등 신고, 주택 임대차 계약금액 거짓 신고","부과되는 과태료의 100분의 20(거짓 거래가격 신고는 한도 1천만원)","신고관청이 적발하기 전에 신고하고 증거자료 제출, 과태료가 부과된 경우"],["허가 없이 토지거래계약 체결, 부정한 방법의 허가","50만원","허가관청 또는 수사기관이 적발하기 전에 신고ㆍ고발, 공소제기 또는 기소유예 결정"],["허가받은 목적대로 이용하지 않은 자","50만원","허가관청이 적발하기 전에 신고, 이행명령이 있는 경우"]]}],"함정":"조장이라는 말에서 처벌 수위를 높게 읽기 쉽다. 부당이득 목적을 붙여도 조장ㆍ방조는 과태료 500만원 이하다. 징역ㆍ벌금 문항에서는 허가 위반 계열(제26조제2항~제4항)과 부당이득 목적의 거짓 신고 본인(제26조제1항)만 고르면 된다."},"36회-2차-049":{"한줄":"신축이 금지된 공장ㆍ주택 등을 동물병원 같은 근린생활시설로 바꾸는 용도변경은 시가화조정구역에서 허가를 받아 할 수 있다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제81조제2항","원문":"시가화조정구역에서는 제56조와 제76조에도 불구하고 제1항에 따른 도시ㆍ군계획사업의 경우 외에는 다음 각 호의 어느 하나에 해당하는 행위에 한정하여 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수의 허가를 받아 그 행위를 할 수 있다. 1. 농업ㆍ임업 또는 어업용의 건축물 중 대통령령으로 정하는 종류와 규모의 건축물이나 그 밖의 시설을 건축하는 행위 2. 마을공동시설, 공익시설ㆍ공공시설, 광공업 등 주민의 생활을 영위하는 데에 필요한 행위로서 대통령령으로 정하는 행위 3. 입목의 벌채, 조림, 육림, 토석의 채취, 그 밖에 대통령령으로 정하는 경미한 행위"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제88조, 별표 24 제2호","원문":"법 제81조제2항의 규정에 의하여 시가화조정구역안에서 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수의 허가를 받아 할 수 있는 행위는 별표 24와 같다. 가. 주택 및 그 부속건축물의 건축으로서 다음의 1에 해당하는 행위 (1) 주택의 증축(기존주택의 면적을 포함하여 100제곱미터 이하에 해당하는 면적의 증축을 말한다) 사. 다음의 1에 해당하는 용도변경행위 (3) 공장ㆍ주택 등 시가화조정구역안에서의 신축이 금지된 시설의 용도를 근린생활시설(수퍼마켓ㆍ... 동물병원ㆍ... 등) 또는 종교시설로 변경하는 행위 아. 종교시설의 증축(새로운 대지조성은 허용되지 아니하며, ...)"}],"선지":[{"번호":1,"판정":"틀림","설명":"농업 등을 영위하는 자의 관리용건축물은 기존 관리용건축물 면적을 포함해 33제곱미터 이하여야 한다. 100제곱미터는 초과한다(영 별표 24 제1호바목)."},{"번호":2,"판정":"틀림","설명":"주택 증축은 기존 주택 면적을 포함해 100제곱미터 이하의 증축만 허용된다. 증축 면적 150제곱미터는 초과한다(영 별표 24 제2호가목(1))."},{"번호":3,"판정":"틀림","설명":"종교시설의 증축은 새로운 대지조성이 허용되지 않는다(영 별표 24 제2호아목)."},{"번호":4,"판정":"옳음","설명":"신축이 금지된 시설을 근린생활시설(동물병원 포함)이나 종교시설로 바꾸는 용도변경은 허가받아 할 수 있다(영 별표 24 제2호사목(3))."},{"번호":5,"판정":"틀림","설명":"기존 공장의 부대시설 설치는 새로운 대지조성이 허용되지 않고 기존 공장 부지 안에서만 할 수 있다(영 별표 24 제2호라목(2))."}],"개념":[{"종류":"표","제목":"시가화조정구역에서 허가받아 할 수 있는 행위(영 별표 24)","머리":["구분","행위","한도"],"행":[["농ㆍ임ㆍ어업용(제1호)","축사, 퇴비사, 잠실, 창고, 생산시설, 양어장","-"],["농ㆍ임ㆍ어업용(제1호)","관리용건축물","기존 면적 포함 33제곱미터 이하"],["주택(제2호가목)","주택의 증축","기존 면적 포함 100제곱미터 이하"],["주택(제2호가목)","부속건축물의 건축","기존 면적 포함 33제곱미터 이하"],["종교시설(제2호아목)","종교시설의 증축","지정 당시 연면적의 200퍼센트 이하, 새 대지조성 불가"],["용도변경(제2호사목)","신축이 금지된 시설을 근린생활시설 또는 종교시설로 변경","-"],["경미한 행위(제3호)","입목의 벌채, 조림, 육림, 토석 채취, 토지의 합병ㆍ분할 등","-"]]},{"종류":"비교","제목":"시가화조정구역의 사업과 행위","왼쪽":{"이름":"도시ㆍ군계획사업","항목":["국방상 또는 공익상 불가피한 사업만 시행(법 제81조제1항)","관계 중앙행정기관장의 요청으로 국토교통부장관이 지정 목적 달성에 지장이 없다고 인정(영 제87조)"]},"오른쪽":{"이름":"개인의 행위","항목":["시장ㆍ군수 등의 허가를 받아 별표 24의 행위만 가능(법 제81조제2항)","허가 전에 공공시설 관리자 등과 협의(법 제81조제3항)"]}}],"함정":"관리용건축물은 기존 면적을 포함해 33제곱미터 이하, 주택 증축은 기존 면적을 포함해 100제곱미터 이하가 한도다. 종교시설의 증축과 공장 부대시설의 설치는 새로운 대지조성을 수반하면 허용되지 않는다."},"36회-2차-063":{"한줄":"임시거주 조치 의무는 주거환경개선사업과 재개발사업의 철거 대상자에게 있고, 임시거주시설은 공사 완료일부터 30일 이내에 철거한다.","근거":[{"법령":"도시 및 주거환경정비법","조문":"제61조제1항","원문":"사업시행자는 주거환경개선사업 및 재개발사업의 시행으로 철거되는 주택의 소유자 또는 세입자에게 해당 정비구역 안과 밖에 위치한 임대주택 등의 시설에 임시로 거주하게 하거나 주택자금의 융자를 알선하는 등 임시거주에 상응하는 조치를 하여야 한다."},{"법령":"도시 및 주거환경정비법","조문":"제61조제4항","원문":"사업시행자는 정비사업의 공사를 완료한 때에는 완료한 날부터 30일 이내에 임시거주시설을 철거하고, 사용한 건축물이나 토지를 원상회복하여야 한다."}],"선지":[{"번호":1,"판정":"-","설명":"ㄱ은 재개발이다. 재건축은 임시거주 조치 의무 대상이 아니고, ㄴ도 30일이다(법 제61조제1항·제4항)."},{"번호":2,"판정":"-","설명":"ㄱ 재건축이 틀렸고 ㄴ 60일도 틀렸다(법 제61조제1항·제4항)."},{"번호":3,"판정":"-","설명":"ㄱ 재개발은 맞지만 ㄴ은 20일이 아니라 30일이다(법 제61조제4항)."},{"번호":4,"판정":"-","설명":"ㄱ 재개발, ㄴ 30일이 법 제61조제1항·제4항과 일치한다."},{"번호":5,"판정":"-","설명":"ㄱ 재개발은 맞지만 ㄴ은 60일이 아니라 30일이다(법 제61조제4항)."}],"개념":[{"종류":"표","제목":"임시거주시설·임시상가 한눈에","머리":["항목","내용","조문"],"행":[["조치 의무 대상","주거환경개선사업·재개발사업으로 철거되는 주택의 소유자·세입자(재건축 제외)","법 제61조제1항"],["조치 방법","구역 안팎의 임대주택 등에 임시 거주, 주택자금 융자 알선 등","법 제61조제1항"],["시설·토지 확보","국가·지방자치단체·공공단체·개인의 시설이나 토지를 일시 사용","법 제61조제2항"],["국가·지방자치단체의 사용신청 처리","영 제53조 사유가 없으면 거절 불가, 사용료·대부료 면제","법 제61조제3항"],["철거·원상회복","공사 완료일부터 30일 이내","법 제61조제4항"],["임시상가","재개발사업의 사업시행자가 이주 상가세입자용으로 설치할 수 있음","법 제61조제5항"],["비용 부담","시장·군수등이 아닌 사업시행자 사업의 임시거주시설 건설비를 시장·군수등이 일부 또는 전부 부담할 수 있음","법 제92조제2항"]]},{"종류":"흐름","제목":"임시거주시설 설치에서 철거까지","단계":[{"이름":"철거 대상자 확인","설명":"주거환경개선·재개발사업으로 철거되는 주택의 소유자와 세입자(법 제61조제1항)"},{"이름":"임시거주 조치","설명":"구역 안팎 임대주택 등에 거주시키거나 주택자금 융자 알선(법 제61조제1항)"},{"이름":"시설·토지 일시 사용","설명":"국가·지방자치단체는 제3자와 매매계약을 이미 체결했거나 사용계획이 확정된 경우 등 영 제53조 사유가 없으면 거절하지 못하고 사용료·대부료는 면제(법 제61조제3항, 영 제53조)"},{"이름":"공사 완료","설명":"정비사업의 공사를 마침"},{"이름":"철거·원상회복","설명":"완료한 날부터 30일 이내에 임시거주시설 철거, 사용한 건축물·토지 원상회복(법 제61조제4항)"}]}],"함정":"재건축을 ㄱ에 넣은 선지 1, 2는 법 제61조제1항에 재건축이 없어 탈락한다. ㄴ의 20일과 60일은 30일과 다르다. 조치 의무 대상은 주거환경개선사업과 재개발사업뿐이다."},"36회-2차-074":{"한줄":"사전결정에 따른 의제 사항을 협의하는 관계 행정기관의 장은 요청받은 날부터 10일이 아니라 15일 이내에 의견을 제출해야 한다.","근거":[{"법령":"건축법","조문":"제10조제7항","원문":"허가권자는 제6항 각 호의 어느 하나에 해당되는 내용이 포함된 사전결정을 하려면 미리 관계 행정기관의 장과 협의하여야 하며, 협의를 요청받은 관계 행정기관의 장은 요청받은 날부터 15일 이내에 의견을 제출하여야 한다."},{"법령":"건축법","조문":"제10조제9항","원문":"사전결정신청자는 제4항에 따른 사전결정을 통지받은 날부터 2년 이내에 제11조에 따른 건축허가를 신청하여야 하며, 이 기간에 건축허가를 신청하지 아니하면 사전결정의 효력이 상실된다."}],"선지":[{"번호":1,"판정":"옳음","설명":"허가 대상 건축물을 건축하려는 자는 허가 신청 전에 사전결정을 신청할 수 있다(법 제10조제1항제3호)."},{"번호":2,"판정":"옳음","설명":"건축위원회 심의와 교통영향평가서 검토를 동시에 신청할 수 있다(법 제10조제2항)."},{"번호":3,"판정":"옳음","설명":"소규모 환경영향평가 대상 사업이면 기후에너지환경부장관이나 지방환경관서의 장과 협의한다(법 제10조제3항)."},{"번호":4,"판정":"틀림","설명":"관계 행정기관의 장은 15일 이내에 의견을 제출하고, 기간 내 제출하지 않으면 협의가 이루어진 것으로 본다(법 제10조제7항·제8항)."},{"번호":5,"판정":"옳음","설명":"통지받은 날부터 2년 이내에 건축허가를 신청해야 하고, 그러지 않으면 사전결정의 효력이 상실된다(법 제10조제9항)."}],"개념":[{"종류":"흐름","제목":"사전결정에서 건축허가까지","단계":[{"이름":"사전결정 신청","설명":"허가 대상 건축물을 건축하려는 자가 허가 신청 전에 허가권자에게 신청. 건축 허용 여부, 건축 가능 규모, 허가 신청 시 고려할 사항(법 제10조제1항)"},{"이름":"동시 신청·협의","설명":"건축위원회 심의와 교통영향평가서 검토를 동시에 신청 가능. 소규모 환경영향평가 대상이면 기후에너지환경부장관 또는 지방환경관서의 장과 협의(법 제10조제2항·제3항)"},{"이름":"관계 행정기관 협의","설명":"의제되는 허가 내용이 있으면 미리 협의, 요청받은 날부터 15일 이내 의견 제출, 미제출 시 협의된 것으로 봄(법 제10조제7항·제8항)"},{"이름":"사전결정 통지","설명":"허가권자가 입지·규모·용도 등을 사전결정해 신청자에게 통지(법 제10조제4항)"},{"이름":"건축허가 신청","설명":"통지받은 날부터 2년 이내에 건축허가 신청. 넘기면 효력 상실(법 제10조제9항)"}]},{"종류":"표","제목":"사전결정 통지로 의제되는 허가(법 제10조제6항)","머리":["의제 대상","근거 법률"],"행":[["개발행위허가","국토의 계획 및 이용에 관한 법률 제56조"],["산지전용허가·신고, 산지일시사용허가·신고(보전산지는 도시지역만)","산지관리법 제14조·제15조·제15조의2"],["농지전용허가·신고·협의","농지법 제34조·제35조·제43조"],["하천점용허가","하천법 제33조"]]}],"함정":"협의 기간은 15일이고 10일이 아니다. 효력 상실 기준은 착공이 아니라 건축허가 신청이며 기간은 2년이다. 선지 3의 기후에너지환경부장관은 현행 명칭이라 맞는 문장이다.","개정":"소규모 환경영향평가 협의 상대 기관이 환경부장관에서 기후에너지환경부장관으로 바뀌었다(2025.10.1, 법 제10조제3항). 정답은 달라지지 않는다."},"36회-2차-069":{"한줄":"등록이 말소된 뒤 2년이 지나지 않은 자는 등록 결격이고, 거짓 등록은 필요적 말소 사유다.","근거":[{"법령":"주택법","조문":"제6조제5호","원문":"제8조에 따라 등록이 말소(제6조제1호 및 제2호에 해당하여 말소된 경우는 제외한다)된 후 2년이 지나지 아니한 자"},{"법령":"주택법","조문":"제4조제1항","원문":"연간 대통령령으로 정하는 호수(戶數) 이상의 주택건설사업을 시행하려는 자 … 는 국토교통부장관에게 등록하여야 한다. 다만, 다음 각 호의 사업주체의 경우에는 그러하지 아니하다. 1. 국가ㆍ지방자치단체 2. 한국토지주택공사 3. 지방공사 …"},{"법령":"주택법 시행령","조문":"제14조제1항","원문":"법 제4조제1항 각 호 외의 부분 본문에서 \"대통령령으로 정하는 호수\"란 다음 각 호의 구분에 따른 호수 또는 세대수를 말한다. 1. 단독주택의 경우: 20호 2. 공동주택의 경우: 20세대. 다만, 도시형 생활주택(제10조제2항제1호의 경우를 포함한다)은 30세대로 한다."},{"법령":"주택법 시행령","조문":"제15조제3항","원문":"등록사업자는 등록사항에 변경이 있으면 국토교통부령으로 정하는 바에 따라 변경 사유가 발생한 날부터 30일 이내에 국토교통부장관에게 신고하여야 한다."},{"법령":"주택법","조문":"제5조제2항","원문":"제11조에 따라 설립된 주택조합(세대수를 증가하지 아니하는 리모델링주택조합은 제외한다)이 그 구성원의 주택을 건설하는 경우에는 대통령령으로 정하는 바에 따라 등록사업자(지방자치단체ㆍ한국토지주택공사 및 지방공사를 포함한다)와 공동으로 사업을 시행할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"국가·지방자치단체·한국토지주택공사·지방공사는 등록 대상에서 빠진다(법 제4조제1항 단서)."},{"번호":2,"판정":"틀림","설명":"지방공사는 등록 제외 사업주체다(법 제4조제1항제3호). 도시형 생활주택의 등록 기준도 20세대가 아니라 30세대다(영 제14조제1항제2호 단서)."},{"번호":3,"판정":"틀림","설명":"변경신고는 변경 사유가 발생한 날부터 30일 이내다(영 제15조제3항)."},{"번호":4,"판정":"틀림","설명":"세대수를 증가하지 않는 리모델링주택조합은 공동사업주체 규정(법 제5조제2항)에서 제외되고, 그 외 조합의 공동시행도 '할 수 있다'이지 의무가 아니다."},{"번호":5,"판정":"옳음","설명":"거짓 등록은 말소 사유이고(법 제8조제1항제1호), 말소 후 2년이 지나지 않으면 등록할 수 없다(법 제6조제5호)."}],"개념":[{"종류":"표","제목":"주택건설사업 등의 등록","머리":["항목","내용","조문"],"행":[["등록 대상","연간 단독주택 20호, 공동주택 20세대(도시형 생활주택 30세대), 대지조성 1만㎡ 이상 시행","법 제4조제1항, 영 제14조"],["등록 제외","국가·지방자치단체, 한국토지주택공사, 지방공사, 주택건설 목적 공익법인, 공동사업 주택조합·고용자","법 제4조제1항 단서"],["등록 기준","자본금 3억원(개인은 자산평가액 6억원) 이상, 건축 분야 기술인 1명 이상, 사무실","영 제14조제3항"],["변경 신고","변경 사유 발생일부터 30일 이내","영 제15조제3항"],["결격사유","미성년자·피성년후견인·피한정후견인, 파산 미복권, 금고 이상 실형 집행 후 2년 미경과, 집행유예 중, 등록말소 후 2년 미경과, 이런 임원이 있는 법인","법 제6조"],["말소·영업정지","1년 이내 영업정지 또는 말소. 거짓 등록과 등록증 대여는 말소하여야 함","법 제8조제1항"]]},{"종류":"비교","제목":"공동사업주체(법 제5조)","왼쪽":{"이름":"공동시행 '할 수 있는' 경우","항목":["토지소유자 + 등록사업자","주택조합 + 등록사업자(지방자치단체·한국토지주택공사·지방공사 포함)","세대수를 증가하지 않는 리모델링주택조합은 이 규정에서 제외"]},"오른쪽":{"이름":"공동시행 '하여야 하는' 경우","항목":["고용자가 근로자의 주택을 건설하는 경우 등록사업자와 공동 시행","공동사업주체 간 업무·비용·책임 분담은 당사자 협약"]}}],"함정":"지방자치단체·지방공사는 규모와 관계없이 등록 대상에서 빠진다. 변경신고 기한은 30일이고 60일이 아니다. 공동시행이 의무인 쪽은 고용자뿐이고 토지소유자·주택조합은 할 수 있다."},"36회-2차-066":{"한줄":"토지임대부 분양주택의 분양가격은 토지는 임대하므로 택지비를 빼고 건축비만으로 구성한다.","근거":[{"법령":"주택법","조문":"제57조제3항","원문":"제1항의 분양가격은 택지비와 건축비로 구성(토지임대부 분양주택의 경우에는 건축비만 해당한다)되며, 구체적인 명세, 산정방식, 감정평가기관 선정방법 등은 국토교통부령으로 정한다."},{"법령":"주택법","조문":"제2조제9호","원문":"\"토지임대부 분양주택\"이란 토지의 소유권은 제15조에 따른 사업계획의 승인을 받아 토지임대부 분양주택 건설사업을 시행하는 자가 가지고, 건축물 및 복리시설(福利施設) 등에 대한 소유권[건축물의 전유부분(專有部分)에 대한 구분소유권은 이를 분양받은 자가 가지고, 건축물의 공용부분ㆍ부속건물 및 복리시설은 분양받은 자들이 공유한다]은 주택을 분양받은 자가 가지는 주택을 말한다."},{"법령":"주택법","조문":"제78조제1항","원문":"토지임대부 분양주택의 토지에 대한 임대차기간은 40년 이내로 한다. 이 경우 토지임대부 분양주택 소유자의 75퍼센트 이상이 계약갱신을 청구하는 경우 40년의 범위에서 이를 갱신할 수 있다."},{"법령":"주택법 시행령","조문":"제60조의2제1항제4호","원문":"토지임대부 분양주택의 경우: 5년"}],"선지":[{"번호":1,"판정":"틀림","설명":"토지임대부 분양주택의 거주의무기간은 5년이다(영 제60조의2제1항제4호)."},{"번호":2,"판정":"틀림","설명":"공용부분·부속건물·복리시설은 분양받은 자들이 공유한다. 건설사업 시행자는 토지 소유권만 가진다(법 제2조제9호)."},{"번호":3,"판정":"옳음","설명":"분양가격은 건축비만으로 구성한다(법 제57조제3항 괄호)."},{"번호":4,"판정":"틀림","설명":"토지임대부 분양주택은 최초 입주가능일에 입주해야 한다. '3년 이내'는 수도권 분양가상한제 적용주택의 입주기한이다(법 제57조의2제1항 본문 괄호)."},{"번호":5,"판정":"틀림","설명":"임대차기간은 40년 이내이고, 소유자 75퍼센트 이상이 청구하면 40년의 범위에서 갱신할 수 있다(법 제78조제1항)."}],"개념":[{"종류":"표","제목":"토지임대부 분양주택 한눈에","머리":["항목","내용","조문"],"행":[["소유 관계","토지는 건설사업 시행자 소유, 전유부분은 분양받은 자, 공용부분·부속건물·복리시설은 분양받은 자들의 공유","법 제2조제9호"],["분양가격","건축비만 해당(택지비 제외)","법 제57조제3항"],["임대차기간","40년 이내, 소유자 75퍼센트 이상 갱신 청구 시 40년 범위에서 갱신","법 제78조제1항"],["지상권","임대차계약을 체결하면 임대차기간 동안 구분소유권 목적의 지상권이 설정된 것으로 봄","법 제78조제2항"],["표준임대차계약서","국토교통부령 표준임대차계약서 사용","법 제78조제3항"],["승계","양수인·상속인이 임대차계약 승계","법 제78조제4항"],["토지임대료","조성원가 또는 감정가격 등 기준, 월별 임대료가 원칙(합의 시 선납·보증금 전환)","법 제78조제5항·제6항"],["입주기한","최초 입주가능일에 입주","법 제57조의2제1항"],["거주의무","거주의무기간 5년. 미이행 시 양도 불가, 부기등기","영 제60조의2제1항제4호, 법 제57조의2제2항·제5항"],["법 적용 순서","이 법에 없는 사항은 집합건물법, 민법 순으로 적용","법 제78조제8항"]]},{"종류":"비교","제목":"분양가격 구성","왼쪽":{"이름":"일반 분양가상한제 적용주택","항목":["택지비 + 건축비","공공택지: 택지 공급가격 + 택지 관련 비용","공공택지 외: 감정평가액 + 택지 관련 비용(매입가격 범위 예외 있음)"]},"오른쪽":{"이름":"토지임대부 분양주택","항목":["건축비만","토지는 임대하므로 택지비 제외","토지는 별도로 토지임대료를 납부"]}}],"함정":"거주의무기간은 5년이고 10년이 아니다. 입주기한 3년은 수도권 분양가상한제 적용주택의 규정이고 토지임대부 분양주택은 최초 입주가능일이다. 임대차기간은 40년 이내이고 공용부분 등은 분양받은 자들이 공유한다."},"36회-2차-086":{"한줄":"지적도·임야도의 토지이동이나 오류를 정비한 지적소관청은 그 내용을 연속지적도에 반영해야 한다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제90조의2제1항·제2항","원문":"① 국토교통부장관은 연속지적도의 관리 및 정비에 관한 정책을 수립ㆍ시행하여야 한다. ② 지적소관청은 지적도ㆍ임야도에 등록된 사항에 대하여 토지의 이동 또는 오류사항을 정비한 때에는 이를 연속지적도에 반영하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제90조의2제3항~제5항","원문":"③ 국토교통부장관은 제2항에 따른 지적소관청의 연속지적도 정비에 필요한 경비의 전부 또는 일부를 지원할 수 있다. ④ 국토교통부장관은 연속지적도를 체계적으로 관리하기 위하여 대통령령으로 정하는 바에 따라 연속지적도 정보관리체계를 구축ㆍ운영할 수 있다. ⑤ 국토교통부장관 또는 지적소관청은 제2항에 따른 연속지적도의 관리ㆍ정비 및 제4항에 따른 연속지적도 정보관리체계의 구축ㆍ운영에 관한 업무를 대통령령으로 정하는 법인, 단체 또는 기관에 위탁할 수 있다. 이 경우 위탁관리에 필요한 경비의 전부 또는 일부를 지원할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"연속지적도의 관리·정비 정책은 국토교통부장관이 수립·시행한다(법 제90조의2제1항)."},{"번호":2,"판정":"옳음","설명":"지적소관청은 토지의 이동이나 오류를 정비한 때 연속지적도에 반영해야 한다(법 제90조의2제2항)."},{"번호":3,"판정":"틀림","설명":"정비 경비를 지원하는 주체는 국토교통부장관이고, 지원은 의무가 아니라 할 수 있는 사항이다(법 제90조의2제3항)."},{"번호":4,"판정":"틀림","설명":"정보관리체계는 국토교통부장관이 구축·운영할 수 있다(법 제90조의2제4항). 시·도지사의 의무가 아니다."},{"번호":5,"판정":"틀림","설명":"관리·정비와 정보관리체계 운영 업무는 국토교통부장관 또는 지적소관청이 대통령령으로 정하는 법인·단체·기관에 위탁할 수 있다(법 제90조의2제5항). 특정 기관에 위탁하여야 한다고 정하지 않았다."}],"개념":[{"종류":"표","제목":"연속지적도 관리: 주체와 의무 정도","머리":["사항","주체","성격"],"행":[["관리·정비 정책 수립·시행","국토교통부장관","하여야 한다"],["지적도·임야도 정비 사항을 연속지적도에 반영","지적소관청","하여야 한다"],["지적소관청의 정비 경비 지원(전부 또는 일부)","국토교통부장관","할 수 있다"],["연속지적도 정보관리체계 구축·운영","국토교통부장관","할 수 있다"],["관리·정비 및 정보관리체계 운영 업무 위탁","국토교통부장관 또는 지적소관청","할 수 있다"]]},{"종류":"비교","제목":"지적도와 연속지적도","왼쪽":{"이름":"지적도","항목":["법 제2조제19호의 지적공부에 해당","지적측량 등으로 조사한 토지의 표시를 기록","소재, 지번, 지목, 경계를 등록","경계점좌표등록부 시행지역 도면에는 \"이 도면에 의하여 측량을 할 수 없음\"을 적음"]},"오른쪽":{"이름":"연속지적도","항목":["지적공부 열거(법 제2조제19호)에 들지 않음","지적측량 없이 전산화된 지적도·임야도 파일로 경계점들을 연결해 작성","측량에 활용할 수 없는 도면","지적전산자료에 포함(법 제76조제1항)"]}}],"함정":"선지 1, 3, 4, 5는 주체를 시·도지사나 지적소관청으로 바꾸고 재량 규정을 의무로 바꾼 문장이다. 정책 수립·경비 지원·정보관리체계는 국토교통부장관 몫이고, 지적소관청의 일은 정비 사항 반영이다."},"36회-2차-092":{"한줄":"중앙지적위원회는 현지조사 때 지적측량수행자에게 소속 지적기술자를 참여시키도록 요청할 수 있다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제29조제1항","원문":"① 토지소유자, 이해관계인 또는 지적측량수행자는 지적측량성과에 대하여 다툼이 있는 경우에는 대통령령으로 정하는 바에 따라 관할 시ㆍ도지사를 거쳐 지방지적위원회에 지적측량 적부심사를 청구할 수 있다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제28조제1항","원문":"① 다음 각 호의 사항을 심의ㆍ의결하기 위하여 국토교통부에 중앙지적위원회를 둔다. 1. 지적 관련 정책 개발 및 업무 개선 등에 관한 사항 2. 지적측량기술의 연구ㆍ개발 및 보급에 관한 사항 3. 제29조제6항에 따른 지적측량 적부심사(適否審査)에 대한 재심사(再審査) 4. 제39조에 따른 측량기술자 중 지적분야 측량기술자(이하 \"지적기술자\"라 한다)의 양성에 관한 사항 5. 제42조에 따른 지적기술자의 업무정지 처분 및 징계요구에 관한 사항"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제21조제5항","원문":"⑤ 위원장이 중앙지적위원회의 회의를 소집할 때에는 회의 일시ㆍ장소 및 심의 안건을 회의 5일 전까지 각 위원에게 서면으로 통지하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제22조","원문":"제21조제4항에 따라 중앙지적위원회가 현지조사를 하려는 경우에는 관계 공무원을 지정하여 지적측량 및 자료조사 등 현지조사를 하고 그 결과를 보고하게 할 수 있으며, 필요할 때에는 법 제24조제1항 각 호의 어느 하나에 해당하는 자(이하 \"지적측량수행자\"라 한다)에게 그 소속 측량기술자 중 지적분야 측량기술자(이하 \"지적기술자\"라 한다)를 참여시키도록 요청할 수 있다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제29조제8항","원문":"⑧ 제7항에 따라 중앙지적위원회로부터 의결서를 받은 국토교통부장관은 그 의결서를 관할 시ㆍ도지사에게 송부하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"적부심사는 관할 시·도지사를 거쳐 지방지적위원회에 청구한다(법 제29조제1항). 중앙지적위원회는 재심사를 맡는다."},{"번호":2,"판정":"틀림","설명":"중앙지적위원회 심의·의결사항은 지적 관련 정책 개발 및 업무 개선, 지적측량기술의 연구·개발 및 보급, 적부심사 재심사, 지적기술자 양성, 지적기술자의 업무정지 처분 및 징계요구다(법 제28조제1항). 지적재조사 기본계획은 들어 있지 않다."},{"번호":3,"판정":"틀림","설명":"회의 소집 통지는 회의 5일 전까지다(영 제21조제5항)."},{"번호":4,"판정":"옳음","설명":"현지조사를 하려면 관계 공무원을 지정하고, 필요하면 지적측량수행자에게 소속 지적기술자를 참여시키도록 요청할 수 있다(영 제22조)."},{"번호":5,"판정":"틀림","설명":"중앙지적위원회 의결서를 받은 국토교통부장관은 이를 관할 시·도지사에게 송부한다(법 제29조제8항). 지적소관청에 보내는 사람은 시·도지사다(제9항)."}],"개념":[{"종류":"흐름","제목":"지적측량 적부심사와 재심사","단계":[{"이름":"적부심사 청구","설명":"토지소유자·이해관계인·지적측량수행자가 지적측량성과에 다툼이 있을 때 시·도지사를 거쳐 지방지적위원회에 청구(법 제29조제1항)"},{"이름":"조사·회부","설명":"시·도지사가 30일 이내에 측량 경위와 성과, 토지이동·소유권 변동 연혁, 현황 실측도를 조사해 지방지적위원회에 회부(법 제29조제2항)"},{"이름":"심의·의결","설명":"회부받은 날부터 60일 이내, 부득이하면 의결로 30일 이내 한 번만 연장(법 제29조제3항)"},{"이름":"의결서 통지","설명":"의결서를 받은 시·도지사가 7일 이내에 청구인과 이해관계인에게 통지(법 제29조제5항)"},{"이름":"재심사 청구","설명":"불복하면 의결서를 받은 날부터 90일 이내에 국토교통부장관을 거쳐 중앙지적위원회에 청구(법 제29조제6항)"},{"이름":"정리","설명":"재심사 청구가 없거나 중앙위 의결이 있으면 지적소관청이 의결서 내용에 따라 지적공부 정정 또는 측량성과 수정(법 제29조제9항·제10항)"}]},{"종류":"표","제목":"중앙지적위원회 구성·회의","머리":["구분","내용","근거"],"행":[["구성","위원장·부위원장 포함 5명 이상 10명 이하","영 제20조제1항"],["위원장·부위원장","국토교통부 지적업무 담당 국장, 담당 과장","영 제20조제2항"],["위원 임기","위원장·부위원장 제외 위원은 2년","영 제20조제4항"],["개의·의결","재적위원 과반수 출석, 출석위원 과반수 찬성","영 제21조제3항"],["소집 통지","회의 5일 전까지 서면","영 제21조제5항"],["재심사 사안 관련 위원","그 안건의 심의·의결에 참석 불가","영 제21조제6항"]]}],"함정":"적부심사는 지방지적위원회가 먼저 맡고, 중앙지적위원회는 불복 재심사를 맡는다. 청구 경로가 시·도지사를 거치는 점은 같아 보여서 선지 1의 '중앙'만 바꿔 놓은 문장을 놓친다. 선지 3의 날짜 5일, 선지 5의 송부 대상도 자주 바뀐다."},"36회-2차-094":{"한줄":"합필등기는 소유권·지상권·전세권·임차권, 승역지 지역권, 모든 토지에 동일한 저당권·신탁등기만 있을 때 할 수 있으므로 ㄱ, ㄹ, ㅁ 이 가능하다.","근거":[{"법령":"부동산등기법","조문":"제37조제1항","원문":"합필(合筆)하려는 토지에 다음 각 호의 등기 외의 권리에 관한 등기가 있는 경우에는 합필의 등기를 할 수 없다. 1. 소유권ㆍ지상권ㆍ전세권ㆍ임차권 및 승역지(承役地: 편익제공지)에 하는 지역권의 등기 2. 합필하려는 모든 토지에 있는 등기원인 및 그 연월일과 접수번호가 동일한 저당권에 관한 등기 3. 합필하려는 모든 토지에 있는 제81조제1항 각 호의 등기사항이 동일한 신탁등기"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제66조제3항제5호","원문":"합병하려는 토지의 소유자별 공유지분이 다른 경우"}],"선지":[{"번호":1,"판정":"-","설명":"ㄱ 은 가능하나 ㄴ 은 불가능하다. 소유자별 공유지분이 다르면 지적 합병 단계에서 막힌다(공간정보법 시행령 제66조제3항제5호)."},{"번호":2,"판정":"-","설명":"ㄷ 은 불가능하다. 가등기담보권은 법 제37조제1항 각 호에 없다. ㅁ 은 가능하다."},{"번호":3,"판정":"-","설명":"ㄴ, ㄷ 이 불가능하다."},{"번호":4,"판정":"-","설명":"ㄱ(법 제37조제1항제1호 지상권), ㄹ(같은 호 승역지 지역권), ㅁ(같은 항 제2호) 모두 가능하다."},{"번호":5,"판정":"-","설명":"ㄴ, ㄷ 이 불가능하다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"지상권의 등기는 합필 제한 대상이 아니다(법 제37조제1항제1호)."},{"기호":"ㄴ","판정":"틀림","설명":"소유자별 공유지분이 다르면 지적소관청이 합병 신청을 받아주지 않는다(공간정보법 제80조제3항제3호, 시행령 제66조제3항제5호). 합병이 안 되므로 합필등기를 할 수 없다."},{"기호":"ㄷ","판정":"틀림","설명":"가등기담보권은 소유권·지상권·전세권·임차권·승역지 지역권·저당권·신탁 어디에도 속하지 않아 합필을 막는다(법 제37조제1항)."},{"기호":"ㄹ","판정":"옳음","설명":"승역지에 하는 지역권의 등기는 허용된다. 요역지에 하는 지역권은 이 목록에 없다(법 제37조제1항제1호)."},{"기호":"ㅁ","판정":"옳음","설명":"모든 토지에 원인·연월일·접수번호가 같은 저당권이면 허용된다(법 제37조제1항제2호)."}],"개념":[{"종류":"표","제목":"합필(합병)등기가 가능한 등기와 불가능한 등기","머리":["등기","합필 가능 여부","비고"],"행":[["소유권·지상권·전세권·임차권","가능","법 제37조제1항제1호"],["승역지에 하는 지역권","가능","요역지 지역권은 불가"],["모든 토지에 같은 저당권","가능","원인·연월일·접수번호 동일"],["모든 토지에 같은 신탁등기","가능","신탁원부 기록사항 동일"],["가등기담보권·가압류·가처분 등","불가","나머지 등기 전부"],["한쪽에만 있는 저당권","불가","모든 토지에 있어야 함"]]},{"종류":"흐름","제목":"토지 합병과 합필등기","단계":[{"이름":"합병 신청","설명":"토지소유자가 지적소관청에 신청. 소유자 다름·지목 다름·제한 등기 있음·공유지분 다름이면 신청 불가"},{"이름":"대장 합병 등록","설명":"지적소관청이 지적공부에 합병 등록"},{"이름":"합필등기 신청","설명":"소유권 등기명의인이 합병이 있는 때부터 1개월 이내 신청(법 제35조)"},{"이름":"등기관 심사","설명":"법 제37조제1항 위반이면 각하하고 지체 없이 지적소관청에 통지(법 제37조제2항)"}]}],"함정":"ㄴ 을 고르기 쉽다. 공유지분이 다른 사정은 등기부의 문제처럼 보이지만 지적소관청 단계에서 합병 신청이 막히므로 합필등기까지 가지 못한다. 지상권·승역지 지역권·같은 저당권은 가능하고 가등기담보권만 막힌다는 구분이 핵심이다."},"36회-2차-107":{"한줄":"채권자대위권으로 등기를 신청하려는 채권자는 납세의무자를 대위하여 부동산 등기의 등록면허세를 신고납부할 수 있다.","근거":[{"법령":"지방세법","조문":"제30조제5항","원문":"⑤ 채권자대위자는 납세의무자를 대위하여 부동산의 등기에 대한 등록면허세를 신고납부할 수 있다."},{"법령":"지방세법","조문":"제23조제1호라목","원문":"라. 제17조에 해당하는 물건의 등기 또는 등록"},{"법령":"지방세법","조문":"제17조제1항","원문":"① 취득가액이 50만원 이하일 때에는 취득세를 부과하지 아니한다."},{"법령":"지방세법","조문":"제25조제1항제1호","원문":"1. 부동산 등기: 부동산 소재지"},{"법령":"지방세법","조문":"제27조제1항","원문":"① 부동산, 선박, 항공기, 자동차 및 건설기계의 등록에 대한 등록면허세(이하 이 절에서 \"등록면허세\"라 한다)의 과세표준은 등록 당시의 가액으로 한다."},{"법령":"지방세법","조문":"제28조제1항","원문":"다만, 제1호부터 제5호까지 및 제5호의2의 규정에 따라 산출한 세액이 해당 각 호의 그 밖의 등기 또는 등록 세율보다 적을 때에는 그 밖의 등기 또는 등록 세율을 적용한다."},{"법령":"지방세법","조문":"제28조제1항제1호마목","원문":"마. 그 밖의 등기: 건당 6천원"}],"선지":[{"번호":1,"판정":"틀림","설명":"취득가액 50만원 이하는 취득세를 부과하지 않는 면세점이고, 그 물건의 소유권 이전등기는 등록면허세 과세대상이 된다. 납세의무가 있다(지방세법 제23조제1호라목, 제17조제1항)."},{"번호":2,"판정":"틀림","설명":"부동산 등기에 대한 등록면허세의 납세지는 부동산 소재지다(지방세법 제25조제1항제1호)."},{"번호":3,"판정":"틀림","설명":"과세표준은 등록 당시의 가액이다. 취득당시가액은 취득을 원인으로 하는 등록(제23조제1호 각 목)에서 쓴다(지방세법 제27조제1항·제3항)."},{"번호":4,"판정":"틀림","설명":"부동산 등기의 세액이 그 밖의 등기 세율보다 적으면 건당 6천원을 적용한다. 11만2천500원은 영리법인 설립·합병 등기의 최저세액이다(지방세법 제28조제1항)."},{"번호":5,"판정":"옳음","설명":"채권자대위자는 납세의무자를 대위하여 부동산 등기의 등록면허세를 신고납부할 수 있고, 지방자치단체의 장은 그 사실을 납세의무자에게 즉시 통보한다(지방세법 제30조제5항·제6항)."}],"개념":[{"종류":"표","제목":"부동산 등기 등록면허세 표준세율","머리":["등기","과세표준","세율"],"행":[["소유권 보존","부동산 가액","1천분의 8"],["소유권 이전(유상)","부동산 가액","1천분의 20(유상 주택은 주택 취득세율의 100분의 50)"],["소유권 이전(무상)","부동산 가액","1천분의 15"],["소유권 이전(상속)","부동산 가액","1천분의 8"],["지상권","부동산 가액","1천분의 2"],["저당권","채권금액","1천분의 2"],["지역권","요역지 가액","1천분의 2"],["전세권","전세금액","1천분의 2"],["임차권","월 임대차금액","1천분의 2"],["경매신청·가압류·가처분","채권금액","1천분의 2"],["그 밖의 등기","건당","6천원"]]},{"종류":"비교","제목":"취득세와 등록면허세(부동산)","왼쪽":{"이름":"취득세","항목":["납세의무자: 부동산등을 취득한 자","납세지: 부동산 소재지","과세표준: 취득당시가액","면세점: 취득가액 50만원 이하","신고·납부: 취득일부터 60일 등"]},"오른쪽":{"이름":"등록면허세(등록)","항목":["납세의무자: 등록을 하는 자","납세지: 부동산 소재지","과세표준: 등록 당시의 가액(신고가 없거나 시가표준액보다 적으면 시가표준액)","취득세 면세점 이하 물건의 등기에도 과세","신고·납부: 등록을 하기 전까지"]}}],"함정":"1번은 등록면허세에도 면세점이 있다고 보고 옳은 문장으로 처리하는 경우가 많다. 면세점은 취득세에 있고, 그 때문에 등기가 등록면허세로 넘어온다. 4번의 11만2천500원은 법인 설립 등기 숫자를 임차권에 끌어온 함정이다."},"36회-1차-009":{"한줄":"수요 증가와 공급 감소가 겹치면 가격은 반드시 오르고, 수요 증가폭이 공급 감소폭보다 작으면 균형량이 줄어든다.","근거":[{"이론":"수요·공급 동시 변화","내용":"기울기 절댓값이 1이면 수요 이동폭을 d, 공급 이동폭을 s라 할 때 수요 증가·공급 감소에서 가격 변화는 (d+s)/2로 항상 상승하고 수량 변화는 (d−s)/2다."}],"선지":[{"번호":1,"판정":"틀림","설명":"수요와 공급이 모두 증가하면 균형량은 증가한다. 수요 증가폭이 더 클 때 가격은 상승하나 균형량 감소가 아니다."},{"번호":2,"판정":"틀림","설명":"둘 다 감소하면 균형량이 감소한다. 수요 감소폭이 더 크면 가격은 하락한다."},{"번호":3,"판정":"옳음","설명":"수요 증가·공급 감소이면 가격은 상승하고, 수요 증가폭이 공급 감소폭보다 작으면 균형량은 감소한다."},{"번호":4,"판정":"틀림","설명":"수요 감소, 공급 증가이면 가격이 하락한다."},{"번호":5,"판정":"틀림","설명":"둘 다 증가하고 수요 증가폭이 더 작으면 가격은 하락하고 균형량은 증가한다."}],"개념":[{"종류":"계산","제목":"수요 증가·공급 감소의 수치 확인(기울기 절댓값 1)","단계":[{"설명":"처음 수요와 공급을 Qd = 100 − P, Qs = P로 놓는다","식":"100 − P = P","값":"P = 50, Q = 50"},{"설명":"수요 10 증가, 공급 20 감소(수요 증가폭 < 공급 감소폭)","식":"Qd = 110 − P,  Qs = P − 20","값":"새 식"},{"설명":"새 균형을 구한다","식":"110 − P = P − 20","값":"P = 65 (15 상승)"},{"설명":"균형량을 구한다","식":"Q = 65 − 20","값":"Q = 45 (5 감소)"}]},{"종류":"표","제목":"동시 변화 결과 정리","머리":["수요","공급","가격","균형량"],"행":[["증가","감소","상승","수요폭 < 공급폭이면 감소"],["감소","증가","하락","수요폭 < 공급폭이면 증가"],["증가","증가","수요폭 > 공급폭이면 상승","증가"],["감소","감소","수요폭 > 공급폭이면 하락","감소"]]}],"함정":"1번과 5번은 둘 다 증가하는데 균형량 감소를 고른 경우다. 같은 방향 변화에서는 균형량이 폭에 상관없이 확정된다."},"36회-1차-012":{"한줄":"탄력성 1.6 × 가격 하락률 5% = 8%이고, 수요곡선이 우하향이므로 가격이 내리면 수요량은 8% 증가한다.","근거":[{"이론":"수요의 가격탄력성","내용":"수요의 가격탄력성 = 수요량 변화율(%) ÷ 가격 변화율(%) (절댓값). 수요법칙에 따라 가격과 수요량은 반대 방향으로 움직인다."}],"선지":[{"번호":1,"판정":"-","설명":"4%는 1.6이 아닌 0.8을 곱해야 나오는 값이다."},{"번호":2,"판정":"-","설명":"수요량 하락은 가격 하락과 같은 방향이라 수요법칙에 어긋난다."},{"번호":3,"판정":"-","설명":"6%는 탄력성 1.2에 해당한다."},{"번호":4,"판정":"-","설명":"수요량 하락은 수요법칙에 어긋난다."},{"번호":5,"판정":"-","설명":"1.6 × 5% = 8%. 가격 하락에 수요량은 증가하므로 8% 증가."}],"개념":[{"종류":"계산","제목":"수요량 변화율 구하기","단계":[{"설명":"정의식에서 수요량 변화율을 정리한다","식":"수요량 변화율 = 탄력성 × 가격 변화율","값":"공식"},{"설명":"대입한다","식":"1.6 × 5%","값":"8%"},{"설명":"방향을 정한다(가격 하락 → 수요량 증가)","식":"가격 ↓, 수요량 ↑","값":"8% 증가"}]},{"종류":"표","제목":"가격탄력성의 값과 해석","머리":["탄력성","명칭","가격 5% 하락 시 수요량"],"행":[["0","완전비탄력","변화 없음"],["0.8","비탄력","4% 증가"],["1","단위탄력","5% 증가"],["1.6","탄력","8% 증가"],["∞","완전탄력","무한히 증가"]]}],"함정":"방향을 놓치면 8% 하락을 고르게 된다. 가격이 내리면 수요량은 늘어난다. 6%는 1.2를 곱한 값, 4%는 0.8을 곱한 값이다."},"36회-1차-053":{"한줄":"저당권은 점유를 이전하지 않는 담보물권이라 토지를 점유할 권리가 없다. 전세권과 지상권은 토지를 점유·사용하는 용익물권이다.","근거":[{"법령":"민법","조문":"제356조","원문":"저당권자는 채무자 또는 제삼자가 점유를 이전하지 아니하고 채무의 담보로 제공한 부동산에 대하여 다른 채권자보다 자기채권의 우선변제를 받을 권리가 있다."},{"법령":"민법","조문":"제303조제1항","원문":"①전세권자는 전세금을 지급하고 타인의 부동산을 점유하여 그 부동산의 용도에 좇아 사용ㆍ수익하며, 그 부동산 전부에 대하여 후순위권리자 기타 채권자보다 전세금의 우선변제를 받을 권리가 있다."},{"법령":"민법","조문":"제279조","원문":"지상권자는 타인의 토지에 건물 기타 공작물이나 수목을 소유하기 위하여 그 토지를 사용하는 권리가 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"ㄱ만 해당한다. 저당권은 점유 없이 우선변제권만 갖는다."},{"번호":2,"판정":"틀림","설명":"지상권은 토지를 사용하는 권리여서 점유할 권리가 인정된다(제279조)."},{"번호":3,"판정":"틀림","설명":"전세권은 부동산을 점유하여 사용·수익하는 권리다(제303조제1항)."},{"번호":4,"판정":"틀림","설명":"전세권과 지상권은 모두 점유할 권리가 인정된다."},{"번호":5,"판정":"틀림","설명":"ㄴ과 ㄷ은 점유할 권리가 인정되는 물권이다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"저당권은 점유 이전 없이 설정되므로 토지를 점유할 권리가 없다(제356조)."},{"기호":"ㄴ","판정":"틀림","설명":"전세권자는 부동산을 점유하여 사용·수익한다(제303조제1항)."},{"기호":"ㄷ","판정":"틀림","설명":"지상권자는 타인의 토지를 사용하는 권리가 있어 점유할 권리가 인정된다(제279조)."}],"개념":[{"종류":"표","제목":"물권별 점유권능","머리":["물권","종류","토지 점유 권능","근거"],"행":[["지상권","용익물권","있음","제279조"],["전세권","용익물권","있음","제303조제1항"],["지역권","용익물권","승역지를 점유하지 않고 이용만 함","제291조"],["저당권","담보물권","없음(점유를 이전하지 않음)","제356조"],["유치권","담보물권","있음(점유가 성립·존속 요건)","제320조"],["질권","담보물권","있음(동산 점유 이전이 효력요건)","제330조"]]}],"함정":"전세권이 담보물권의 성격도 갖는다는 이유로 점유권능이 없다고 보기 쉽다. 전세권은 점유를 수반하는 용익물권이다."},"36회-2차-033":{"한줄":"④ 임대차 확인사항에는 확정일자 부여현황, 국세ㆍ지방세 체납정보, 전입세대 확인서, 최우선변제금, 민간임대 등록 여부가 있다. 현장안내 중개보조원 신분고지는 세부 확인사항 ⑭다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"별지 제20호서식 Ⅰ. ④ 임대차 확인사항","원문":"확정일자 부여현황 정보 / 국세 및 지방세 체납정보 / 전입세대 확인서 / 최우선변제금 / 민간임대 등록여부"},{"법령":"공인중개사법 시행규칙","조문":"별지 제20호서식 Ⅱ. ⑭ 현장안내","원문":"현장안내자 [ ]개업공인중개사 [ ]소속공인중개사 [ ]중개보조원(신분고지 여부: [ ] 예 [ ] 아니오) [ ]해당 없음"},{"법령":"공인중개사법","조문":"제18조의4","원문":"중개보조원은 현장안내 등 중개업무를 보조하는 경우 중개의뢰인에게 본인이 중개보조원이라는 사실을 미리 알려야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄱ은 임대차 확인사항이나 ㄷ은 세부 확인사항(⑭)이다."},{"번호":2,"판정":"틀림","설명":"ㄴ과 ㄹ은 임대차 확인사항이지만 ㄱ이 빠졌다."},{"번호":3,"판정":"옳음","설명":"ㄱ, ㄴ, ㄹ이 ④ 임대차 확인사항에 해당한다."},{"번호":4,"판정":"틀림","설명":"ㄷ은 임대차 확인사항이 아니다."},{"번호":5,"판정":"틀림","설명":"ㄷ이 섞여 있다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"국세 및 지방세 체납정보는 ④ 임대차 확인사항의 항목이다. 임대인 자료 제출 또는 열람 동의로 갈음했는지 표시하고 임차인 권리를 설명한다."},{"기호":"ㄴ","판정":"옳음","설명":"민간임대 등록 여부(장기일반ㆍ공공지원 등 유형, 임대의무기간, 임대개시일, 임대보증금 보증 설명)는 ④ 임대차 확인사항이다."},{"기호":"ㄷ","판정":"틀림","설명":"현장안내자가 중개보조원이면 신분고지 여부를 표시하는 곳은 Ⅱ 세부 확인사항 ⑭다."},{"기호":"ㄹ","판정":"옳음","설명":"최우선변제금(소액임차인범위와 최우선변제금액)은 ④ 임대차 확인사항이다. 선순위 담보물권 설정 당시 기준으로 적는다."}],"개념":[{"종류":"표","제목":"확인ㆍ설명서[Ⅰ] ④ 임대차 확인사항의 항목과 표시 방법","머리":["항목","표시 방법"],"행":[["확정일자 부여현황 정보","임대인 자료 제출 또는 열람 동의, 임차인 권리 설명"],["국세 및 지방세 체납정보","임대인 자료 제출 또는 열람 동의, 임차인 권리 설명"],["전입세대 확인서","확인(서류 첨부) / 미확인(열람ㆍ교부 신청방법 설명) / 해당 없음"],["최우선변제금","소액임차인범위와 최우선변제금액, 선순위 담보물권 설정 당시 기준"],["민간임대 등록여부","등록 유형, 임대의무기간ㆍ임대개시일, 임대보증금 보증 설명 / 미등록"]]},{"종류":"표","제목":"확인ㆍ설명서[Ⅰ]에서 헷갈리는 항목의 위치","머리":["위치","항목"],"행":[["Ⅰ-② 권리관계","등기부 기재사항, 신탁등기 여부, 공동담보 여부, 계약갱신요구권 행사 여부(2026.8.11 개정으로 이동)"],["Ⅰ-④ 임대차 확인사항","확정일자 부여현황, 국세ㆍ지방세 체납정보, 전입세대 확인서, 최우선변제금, 민간임대 등록 여부"],["Ⅰ-⑥ 관리에 관한 사항","경비실, 관리주체, 관리비 금액ㆍ포함 비목ㆍ부과방식"],["Ⅱ-⑪ 내부ㆍ외부 시설물","수도, 전기, 가스, 소방(단독경보형 감지기), 난방, 승강기, 배수"],["Ⅱ-⑭ 현장안내","현장안내자, 중개보조원 신분고지 여부"]]}],"함정":"서식 개정 전 위치로 암기하면 흔들린다. 계약갱신요구권은 현재 ② 권리관계에 있고, ④에는 최우선변제금이 남아 있다. ㄷ의 신분고지는 어느 판이든 ⑭다.","개정":"별지 제20호서식이 2026.8.11 개정되어 '계약갱신요구권 행사 여부'가 ④ 임대차 확인사항에서 ② 권리관계로 옮겨졌다. 기출 보기 ㄹ을 현행 ④ 항목인 '최우선변제금'으로 교체했고, 정답 ③은 그대로다."},"36회-2차-021":{"한줄":"포상금 신청서는 등록관청에 내고, 지급은 검사의 공소제기 또는 기소유예 결정이 있어야 하며, 금액은 1건당 50만원이다. 보기 중 ㄷ만 맞다.","근거":[{"법령":"공인중개사법","조문":"제46조 제1항","원문":"①등록관청은 다음 각 호의 어느 하나에 해당하는 자를 등록관청, 수사기관이나 제47조의2에 따른 부동산거래질서교란행위 신고센터에 신고 또는 고발한 자에 대하여 대통령령으로 정하는 바에 따라 포상금을 지급할 수 있다.\n1. 제9조에 따른 중개사무소의 개설등록을 하지 아니하고 중개업을 한 자\n2. 거짓이나 그 밖의 부정한 방법으로 중개사무소의 개설등록을 한 자\n3. 중개사무소등록증 또는 공인중개사자격증을 다른 사람에게 양도ㆍ대여하거나 다른 사람으로부터 양수ㆍ대여받은 자\n4. 제18조의2제3항을 위반하여 표시ㆍ광고를 한 자\n5. 제33조제1항제8호 또는 제9호에 따른 행위를 한 자\n6. 제33조제2항을 위반하여 개업공인중개사등의 업무를 방해한 자"},{"법령":"공인중개사법 시행령","조문":"제36조의2 제1항 제2항 제3항","원문":"①법 제46조제1항의 규정에 따른 포상금은 1건당 50만원으로 한다.\n②제1항의 규정에 따른 포상금은 법 제46조제1항 각 호의 어느 하나에 해당하는 자가 행정기관에 의하여 발각되기 전에 등록관청이나 수사기관에 신고 또는 고발한 자에게 그 신고 또는 고발사건에 대하여 검사가 공소제기 또는 기소유예의 결정을 한 경우에 한하여 지급한다.\n③법 제46조제2항의 규정에 따라 포상금의 지급에 소요되는 비용 중 국고에서 보조할 수 있는 비율은 100분의 50이내로 한다."},{"법령":"공인중개사법 시행규칙","조문":"제28조 제1항 제2항","원문":"①영 제36조의2에 따른 포상금을 지급받으려는 자는 별지 제28호서식의 포상금지급신청서를 등록관청에 제출해야 한다.\n②제1항의 규정에 따라 포상금지급신청서를 제출받은 등록관청은 그 사건에 관한 수사기관의 처분내용을 조회한 후 포상금의 지급을 결정하고, 그 결정일부터 1월 이내에 포상금을 지급하여야 한다."}],"선지":[{"번호":1,"판정":"-","설명":"ㄱ은 틀린 설명이다. 맞는 ㄷ이 빠져 있어 정답 조합이 아니다."},{"번호":2,"판정":"-","설명":"ㄷ만 맞는 설명이므로 정답 조합이다."},{"번호":3,"판정":"-","설명":"ㄱ과 ㄴ은 둘 다 틀린 설명이다."},{"번호":4,"판정":"-","설명":"ㄴ은 틀린 설명이다. 기소유예 결정에도 지급하므로 ㄴ을 포함한 조합은 맞지 않다."},{"번호":5,"판정":"-","설명":"ㄱ과 ㄴ이 틀린 설명이라 세 개를 모두 고를 수 없다."}],"보기판정":[{"기호":"ㄱ","판정":"틀림","설명":"포상금지급신청서는 등록관청에 제출한다(시행규칙 제28조제1항). 국토교통부장관이 받는 것이 아니다."},{"기호":"ㄴ","판정":"틀림","설명":"검사가 공소제기 또는 기소유예의 결정을 한 경우에 지급한다(시행령 제36조의2제2항). 공소제기만 요건으로 적으면 틀리다."},{"기호":"ㄷ","판정":"옳음","설명":"포상금은 1건당 50만원이다(시행령 제36조의2제1항)."}],"개념":[{"종류":"표","제목":"포상금 지급 대상 (법 제46조제1항)","머리":["신고·고발 대상","근거"],"행":[["중개사무소 개설등록 없이 중개업을 한 자","제1호"],["거짓이나 그 밖의 부정한 방법으로 개설등록을 한 자","제2호"],["중개사무소등록증·공인중개사자격증을 양도·대여하거나 양수·대여받은 자","제3호"],["개업공인중개사가 아니면서 중개대상물을 표시·광고한 자","제4호 (법 제18조의2제3항)"],["거짓 거래완료로 시세에 부당한 영향을 주는 행위, 단체 구성으로 중개·공동중개를 제한하는 행위","제5호 (법 제33조제1항제8호·제9호)"],["시세에 영향을 줄 목적으로 개업공인중개사등의 업무를 방해한 자","제6호 (법 제33조제2항)"]]},{"종류":"흐름","제목":"포상금 지급 절차","단계":[{"이름":"신고·고발","설명":"행정기관에 발각되기 전에 등록관청·수사기관·신고센터에 신고 또는 고발한다."},{"이름":"검사의 처분","설명":"검사가 공소제기 또는 기소유예를 결정해야 지급 요건이 갖춰진다."},{"이름":"신청서 제출","설명":"포상금지급신청서를 등록관청에 낸다."},{"이름":"지급 결정","설명":"등록관청이 수사기관의 처분내용을 조회한 뒤 지급을 결정한다."},{"이름":"지급","설명":"결정일부터 1개월 이내에 1건당 50만원을 지급한다. 공동 신고는 균등 배분(합의가 있으면 그 방법), 같은 사건의 2건 이상 신고는 최초 신고자에게 지급한다."}]}],"함정":"신청서는 국토교통부장관이 아니라 등록관청에 낸다. 지급 요건에는 공소제기 외에 기소유예도 들어간다. 지급 주체는 등록관청이고, 국고 보조는 100분의 50 이내다."},"36회-2차-028":{"한줄":"자기 거주용 주택용지의 이용 의무기간은 취득일부터 2년이고, 이행강제금은 이용 의무기간이 지나면 부과할 수 없으며, 이미 부과된 이행강제금은 이행해도 징수한다. 보기 중 ㄷ만 맞다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"제14조 제2항","원문":"② 법 제17조제1항에서 \"대통령령으로 정하는 기간\"이란 다음 각 호의 구분에 따른 기간을 말한다.\n1. 법 제12조제1호가목부터 다목까지의 목적으로 허가를 받은 경우: 토지 취득일부터 2년\n2. 법 제12조제1호라목부터 바목까지의 목적으로 허가를 받은 경우: 토지 취득일부터 4년. 다만, 분양을 목적으로 허가를 받은 토지로서 개발에 착수한 후 토지 취득일부터 4년 이내에 분양을 완료한 경우에는 분양을 완료한 때에 4년이 지난 것으로 본다.\n3. 제10조제2항제1호에 따라 대체토지를 취득하기 위하여 허가를 받은 경우: 토지 취득일부터 2년\n4. 제10조제2항제2호에 따라 현상보존의 목적으로 토지를 취득하기 위하여 허가를 받은 경우: 토지 취득일부터 5년\n5. 제1호부터 제4호까지의 경우 외의 경우: 토지 취득일부터 5년"},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제18조 제3항 제4항 제5항","원문":"③ 시장ㆍ군수 또는 구청장은 최초의 이행명령이 있었던 날을 기준으로 1년에 한 번씩 그 이행명령이 이행될 때까지 반복하여 제2항에 따른 이행강제금을 부과ㆍ징수할 수 있다.\n④ 시장ㆍ군수 또는 구청장은 제17조제1항에 따른 이용 의무기간이 지난 후에는 이행강제금을 부과할 수 없다.\n⑤ 시장ㆍ군수 또는 구청장은 제1항에 따른 이행명령을 받은 자가 그 명령을 이행하는 경우에는 새로운 이행강제금의 부과를 즉시 중지하되, 명령을 이행하기 전에 이미 부과된 이행강제금은 징수하여야 한다."}],"선지":[{"번호":1,"판정":"-","설명":"ㄱ이 틀린 설명이라 이 조합은 정답이 아니다. 맞는 ㄷ이 빠져 있다."},{"번호":2,"판정":"-","설명":"ㄷ만 맞는 설명이므로 정답 조합이다."},{"번호":3,"판정":"-","설명":"ㄱ, ㄴ은 둘 다 틀린 설명이다."},{"번호":4,"판정":"-","설명":"ㄴ이 틀린 설명이라 ㄷ과 함께 고를 수 없다."},{"번호":5,"판정":"-","설명":"ㄱ, ㄴ이 틀린 설명이라 셋을 모두 고를 수 없다."}],"보기판정":[{"기호":"ㄱ","판정":"틀림","설명":"법 제12조제1호가목부터 다목까지(자기 거주용 주택용지 포함)의 목적으로 허가를 받은 경우 이용 의무기간은 토지 취득일부터 2년이다(시행령 제14조제2항제1호). 4년은 라목~바목 목적이다."},{"기호":"ㄴ","판정":"틀림","설명":"이행강제금은 이행명령이 이행될 때까지 1년에 한 번씩 반복 부과할 수 있으나(법 제18조제3항), 이용 의무기간이 지난 후에는 부과할 수 없다(법 제18조제4항)."},{"기호":"ㄷ","판정":"옳음","설명":"이행명령을 이행하면 새 이행강제금 부과를 즉시 중지하되, 명령을 이행하기 전에 이미 부과된 이행강제금은 징수하여야 한다(법 제18조제5항)."}],"개념":[{"종류":"표","제목":"토지 이용 의무기간 (시행령 제14조제2항)","머리":["허가 목적","이용 의무기간"],"행":[["자기의 거주용 주택용지, 주민 복지·편익시설 설치, 농업·축산업·임업·어업 경영 (법 제12조제1호 가목~다목)","토지 취득일부터 2년"],["수용 가능 사업 시행자의 사업, 지역 발전에 필요한 사업, 인접 지역 사업 시행자의 사업 (라목~바목)","토지 취득일부터 4년. 분양 목적으로 개발에 착수해 4년 안에 분양을 완료하면 완료한 때 4년이 지난 것으로 본다"],["대체토지 취득 목적 (시행령 제10조제2항제1호)","토지 취득일부터 2년"],["현상보존 목적 (시행령 제10조제2항제2호)","토지 취득일부터 5년"],["그 밖의 경우","토지 취득일부터 5년"]]},{"종류":"흐름","제목":"이용 의무 위반에서 이행강제금까지","단계":[{"이름":"이용 현황 조사","설명":"시장·군수·구청장이 허가받은 목적대로 이용하는지 조사한다 (법 제17조제2항)."},{"이름":"이행명령","설명":"문서로 하고 이행기간은 3개월 이내로 정한다 (시행령 제16조제1항)."},{"이름":"계고","설명":"이행기간 안에 이행하지 않으면 이행강제금을 부과·징수한다는 뜻을 미리 문서로 알린다 (시행령 제16조제5항)."},{"이름":"이행강제금 부과","설명":"취득가액의 100분의 10 범위의 금액을 문서로 부과한다. 최초 이행명령일을 기준으로 1년에 한 번씩 반복할 수 있다 (법 제18조제2항·제3항)."},{"이름":"부과 중단","설명":"이행명령을 이행하면 새 부과를 중지하지만 이미 부과된 금액은 징수한다. 이용 의무기간이 지나면 부과할 수 없다 (법 제18조제4항·제5항)."}]}],"함정":"이용 의무기간은 2년, 4년, 5년으로 갈리고 자기 거주용 주택용지는 가장 짧은 2년이다. 이행강제금은 반복 부과할 수 있지만 이용 의무기간이 지나면 부과하지 못한다."},"36회-2차-050":{"한줄":"계획관리지역에 지정된 산업·유통개발진흥지구의 건폐율은 40퍼센트가 아니라 60퍼센트 이하다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제84조제4항제2호","원문":"2. 개발진흥지구: 다음 각 목에서 정하는 비율 이하\n    가. 도시지역 외의 지역에 지정된 경우: 40퍼센트. 다만, 계획관리지역에 제31조제2항제8호나목에 따른 산업ㆍ유통개발진흥지구가 지정된 경우에는 60퍼센트로 한다.\n    나. 자연녹지지역에 지정된 경우: 30퍼센트"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제84조제4항제3호·제4호","원문":"3. 수산자원보호구역 : 40퍼센트 이하\n  4. 「자연공원법」에 따른 자연공원 : 60퍼센트 이하"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제84조제4항제6호","원문":"6. 공업지역에 있는 「산업입지 및 개발에 관한 법률」 제2조제8호가목부터 다목까지의 규정에 따른 국가산업단지ㆍ일반산업단지ㆍ도시첨단산업단지 및 같은 조 제12호에 따른 준산업단지: 80퍼센트 이하"}],"선지":[{"번호":1,"판정":"옳음","설명":"자연녹지지역에 지정된 개발진흥지구는 30퍼센트 이하다(영 제84조제4항제2호나목)."},{"번호":2,"판정":"옳음","설명":"수산자원보호구역은 40퍼센트 이하다(영 제84조제4항제3호)."},{"번호":3,"판정":"옳음","설명":"자연공원은 60퍼센트 이하다(영 제84조제4항제4호)."},{"번호":4,"판정":"틀림","설명":"계획관리지역의 산업·유통개발진흥지구는 60퍼센트 이하다. 40퍼센트는 도시지역 외 개발진흥지구의 일반 비율이고, 이 경우만 60퍼센트로 올라간다(영 제84조제4항제2호가목 단서)."},{"번호":5,"판정":"옳음","설명":"공업지역의 국가·일반·도시첨단산업단지와 준산업단지는 80퍼센트 이하다(영 제84조제4항제6호)."}],"개념":[{"종류":"표","제목":"용도지역별 건폐율과 용적률의 범위(영 제84조제1항, 제85조제1항)","머리":["용도지역","건폐율(이하)","용적률"],"행":[["제1종전용주거지역","50퍼센트","50퍼센트 이상 100퍼센트 이하"],["제2종전용주거지역","50퍼센트","50퍼센트 이상 150퍼센트 이하"],["제1종일반주거지역","60퍼센트","100퍼센트 이상 200퍼센트 이하"],["제2종일반주거지역","60퍼센트","100퍼센트 이상 250퍼센트 이하"],["제3종일반주거지역","50퍼센트","100퍼센트 이상 300퍼센트 이하"],["준주거지역","70퍼센트","200퍼센트 이상 500퍼센트 이하"],["중심상업지역","90퍼센트","200퍼센트 이상 1천500퍼센트 이하"],["일반상업지역","80퍼센트","200퍼센트 이상 1천300퍼센트 이하"],["근린상업지역","70퍼센트","200퍼센트 이상 900퍼센트 이하"],["유통상업지역","80퍼센트","200퍼센트 이상 1천100퍼센트 이하"],["전용공업지역","70퍼센트","150퍼센트 이상 300퍼센트 이하"],["일반공업지역","70퍼센트","150퍼센트 이상 350퍼센트 이하"],["준공업지역","70퍼센트","150퍼센트 이상 400퍼센트 이하"],["보전녹지지역","20퍼센트","50퍼센트 이상 80퍼센트 이하"],["생산녹지지역","20퍼센트","50퍼센트 이상 100퍼센트 이하"],["자연녹지지역","20퍼센트","50퍼센트 이상 100퍼센트 이하"],["보전관리지역","20퍼센트","50퍼센트 이상 80퍼센트 이하"],["생산관리지역","20퍼센트","50퍼센트 이상 80퍼센트 이하"],["계획관리지역","40퍼센트","50퍼센트 이상 100퍼센트 이하"],["농림지역","20퍼센트","50퍼센트 이상 80퍼센트 이하"],["자연환경보전지역","20퍼센트","50퍼센트 이상 80퍼센트 이하"]]},{"종류":"표","제목":"용도지역과 별도로 정한 건폐율(영 제84조제4항)","머리":["대상","건폐율(이하)"],"행":[["취락지구","60퍼센트(집단취락지구는 개발제한구역법령에 따름)"],["개발진흥지구 - 도시지역 외","40퍼센트(계획관리지역의 산업·유통개발진흥지구는 60퍼센트)"],["개발진흥지구 - 자연녹지지역","30퍼센트"],["수산자원보호구역","40퍼센트"],["자연공원","60퍼센트"],["농공단지","70퍼센트(기반시설이 충분하면 80퍼센트)"],["공업지역의 국가·일반·도시첨단산업단지, 준산업단지","80퍼센트"]]}],"함정":"40퍼센트라는 숫자가 계획관리지역의 일반 건폐율과 같아서 맞는 것처럼 보인다. 산업·유통개발진흥지구에 한해 계획관리지역이 60퍼센트로 올라간다."},"36회-2차-078":{"한줄":"컨테이너를 이용한 간이창고는 공장 대지에 설치하는 이동이 쉬운 것만 적용 제외다. 컨테이너 임시숙소는 건축법 적용 대상이다.","근거":[{"법령":"건축법","조문":"제3조제1항","원문":"① 다음 각 호의 어느 하나에 해당하는 건축물에는 이 법을 적용하지 아니한다.\n1. 「문화유산의 보존 및 활용에 관한 법률」에 따른 지정문화유산이나 임시지정문화유산 또는 「자연유산의 보존 및 활용에 관한 법률」에 따라 지정된 천연기념물등이나 임시지정천연기념물, 임시지정명승, 임시지정시ㆍ도자연유산, 임시자연유산자료\n2. 철도나 궤도의 선로 부지(敷地)에 있는 다음 각 목의 시설\n가. 운전보안시설\n나. 철도 선로의 위나 아래를 가로지르는 보행시설\n다. 플랫폼\n라. 해당 철도 또는 궤도사업용 급수(給水)ㆍ급탄(給炭) 및 급유(給油) 시설\n3. 고속도로 통행료 징수시설\n4. 컨테이너를 이용한 간이창고(「산업집적활성화 및 공장설립에 관한 법률」 제2조제1호에 따른 공장의 용도로만 사용되는 건축물의 대지에 설치하는 것으로서 이동이 쉬운 것만 해당된다)\n5. 「하천법」에 따른 하천구역 내의 수문조작실"}],"선지":[{"번호":1,"판정":"옳음","설명":"제3호. 고속도로 통행료 징수시설은 적용 제외다."},{"번호":2,"판정":"옳음","설명":"제2호다목. 철도·궤도의 선로 부지에 있는 플랫폼은 적용 제외다."},{"번호":3,"판정":"틀림","설명":"제4호의 컨테이너 건축물은 공장 용도 건축물의 대지에 설치하는 이동이 쉬운 간이창고만 적용 제외다. 임시숙소는 해당하지 않는다."},{"번호":4,"판정":"옳음","설명":"제5호. 하천구역 내 수문조작실은 적용 제외다."},{"번호":5,"판정":"옳음","설명":"제1호. 임시지정문화유산은 지정문화유산과 함께 적용 제외다."}],"개념":[{"종류":"표","제목":"건축법 적용 제외 건축물(법 제3조제1항)","머리":["호","적용 제외 건축물","주의"],"행":[["1","지정문화유산·임시지정문화유산, 천연기념물등·임시지정천연기념물·임시지정명승·임시지정시ㆍ도자연유산·임시자연유산자료","임시지정까지 포함"],["2","철도·궤도 선로 부지의 운전보안시설, 선로 위·아래를 가로지르는 보행시설, 플랫폼, 철도·궤도사업용 급수·급탄·급유 시설","선로 부지 안의 시설만"],["3","고속도로 통행료 징수시설",""],["4","컨테이너를 이용한 간이창고","공장 용도 건축물의 대지에 설치, 이동이 쉬운 것만"],["5","「하천법」에 따른 하천구역 내의 수문조작실",""]]},{"종류":"표","제목":"일부 규정만 적용하지 않는 지역(법 제3조제2항)","머리":["지역","적용하지 않는 규정"],"행":[["도시지역 및 지구단위계획구역 외의 지역으로서 동이나 읍이 아닌 지역","제44조~제47조(대지와 도로), 제51조(방화지구), 제57조(대지 분할 제한)"],["동·읍에 속하는 섬","인구 500명 이상인 경우만 동·읍으로 본다"]]}],"함정":"이름이 비슷한 '컨테이너 간이창고'와 '컨테이너 임시숙소'를 섞은 선지다. 제외되는 것은 공장 대지의 이동이 쉬운 간이창고뿐이다. 임시지정문화유산은 낯설어 보여도 제외 목록에 있다."},"36회-2차-079":{"한줄":"위탁경영이 허용되는 것은 ㄱ(농업법인 청산 중), ㄴ(징집), ㄷ(부상으로 3월 이상 치료)이다. 국외 여행은 3개월 이상이어야 하므로 국내 여행은 해당하지 않는다.","근거":[{"법령":"농지법","조문":"제9조","원문":"제9조(농지의 위탁경영) 농지 소유자는 다음 각 호의 어느 하나에 해당하는 경우 외에는 소유 농지를 위탁경영할 수 없다.\n1. 「병역법」에 따라 징집 또는 소집된 경우\n2. 3개월 이상 국외 여행 중인 경우\n3. 농업법인이 청산 중인 경우\n4. 질병, 취학, 선거에 따른 공직 취임, 그 밖에 대통령령으로 정하는 사유로 자경할 수 없는 경우\n5. 제17조에 따른 농지이용증진사업 시행계획에 따라 위탁경영하는 경우\n6. 농업인이 자기 노동력이 부족하여 농작업의 일부를 위탁하는 경우"},{"법령":"농지법 시행령","조문":"제8조제1항","원문":"①법 제9조제4호에서 \"그 밖에 대통령령으로 정하는 사유\"란 다음 각 호의 어느 하나에 해당하는 사유를 말한다.\n1. 부상으로 3월 이상의 치료가 필요한 경우\n2. 교도소ㆍ구치소 또는 보호감호시설에 수용 중인 경우\n3. 임신 중이거나 분만 후 6개월 미만인 경우"}],"선지":[{"번호":1,"판정":"-","설명":"ㄱ, ㄴ은 맞지만 ㄷ이 빠졌다."},{"번호":2,"판정":"-","설명":"ㄷ은 맞지만 ㄹ이 틀리고 ㄱ, ㄴ이 빠졌다."},{"번호":3,"판정":"-","설명":"ㄱ, ㄴ, ㄷ이 모두 맞고 ㄹ이 틀리다."},{"번호":4,"판정":"-","설명":"ㄹ이 틀리고 ㄱ이 빠졌다."},{"번호":5,"판정":"-","설명":"ㄹ이 틀려서 전부 맞는 조합이 아니다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"농업법인이 청산 중이면 위탁경영할 수 있다(법 제9조제3호)."},{"기호":"ㄴ","판정":"옳음","설명":"「병역법」에 따라 징집 또는 소집된 경우다(법 제9조제1호)."},{"기호":"ㄷ","판정":"옳음","설명":"부상으로 3월 이상의 치료가 필요한 경우다(영 제8조제1항제1호, 법 제9조제4호)."},{"기호":"ㄹ","판정":"틀림","설명":"위탁경영 사유는 3개월 이상 '국외' 여행 중인 경우다(법 제9조제2호). 국내 여행은 해당하지 않는다."}],"개념":[{"종류":"표","제목":"위탁경영이 가능한 경우(농지법 제9조, 영 제8조)","머리":["근거","사유"],"행":[["법 제9조제1호","「병역법」에 따라 징집 또는 소집된 경우"],["법 제9조제2호","3개월 이상 국외 여행 중인 경우"],["법 제9조제3호","농업법인이 청산 중인 경우"],["법 제9조제4호","질병, 취학, 선거에 따른 공직 취임, 그 밖에 대통령령으로 정하는 사유로 자경할 수 없는 경우"],["영 제8조제1항","부상으로 3월 이상 치료가 필요한 경우 / 교도소·구치소·보호감호시설 수용 중 / 임신 중이거나 분만 후 6개월 미만"],["법 제9조제5호","농지이용증진사업 시행계획에 따라 위탁경영하는 경우"],["법 제9조제6호","농업인이 자기 노동력이 부족하여 농작업의 일부를 위탁하는 경우"]]},{"종류":"표","제목":"자기 노동력이 부족한 경우(영 제8조제2항)","머리":["구분","기준"],"행":[["원칙","통상적인 농업경영관행에 따라 자기 또는 세대원의 노동력으로 해당 농지의 농작업 전부를 행할 수 없는 경우"],["요건 1","벼·과수·그 밖의 농작물의 재배작물별 주요 농작업의 3분의 1 이상을 자기 또는 세대원의 노동력으로 하는 경우"],["요건 2","자기의 농업경영에 관련된 해당 농작업에 1년 중 30일 이상 직접 종사하는 경우"]]}],"함정":"ㄹ은 국외 여행이 아니라 국내 여행이고 기간도 6개월이라 여행이라는 말에 끌린다. 법에 있는 것은 3개월 이상 '국외' 여행이다. ㄷ의 3월 이상 부상 치료는 법이 아니라 시행령 제8조제1항에 있어서 놓치기 쉽다."},"36회-2차-089":{"한줄":"적부심사청구는 시·도지사가 지방지적위원회에 회부하고, 위원회는 60일 이내에 의결하며, 시·도지사가 의결서를 받은 날부터 7일 이내에 통지한다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제29조제1항~제6항","원문":"제29조(지적측량의 적부심사 등)\n① 토지소유자, 이해관계인 또는 지적측량수행자는 지적측량성과에 대하여 다툼이 있는 경우에는 대통령령으로 정하는 바에 따라 관할 시ㆍ도지사를 거쳐 지방지적위원회에 지적측량 적부심사를 청구할 수 있다.\n② 제1항에 따른 지적측량 적부심사청구를 받은 시ㆍ도지사는 30일 이내에 다음 각 호의 사항을 조사하여 지방지적위원회에 회부하여야 한다.\n③ 제2항에 따라 지적측량 적부심사청구를 회부받은 지방지적위원회는 그 심사청구를 회부받은 날부터 60일 이내에 심의ㆍ의결하여야 한다. 다만, 부득이한 경우에는 그 심의기간을 해당 지적위원회의 의결을 거쳐 30일 이내에서 한 번만 연장할 수 있다.\n④ 지방지적위원회는 지적측량 적부심사를 의결하였으면 대통령령으로 정하는 바에 따라 의결서를 작성하여 시ㆍ도지사에게 송부하여야 한다.\n⑤ 시ㆍ도지사는 제4항에 따라 의결서를 받은 날부터 7일 이내에 지적측량 적부심사 청구인 및 이해관계인에게 그 의결서를 통지하여야 한다.\n⑥ 제5항에 따라 의결서를 받은 자가 지방지적위원회의 의결에 불복하는 경우에는 그 의결서를 받은 날부터 90일 이내에 국토교통부장관을 거쳐 중앙지적위원회에 재심사를 청구할 수 있다."}],"선지":[{"번호":1,"판정":"-","설명":"ㄱ·ㄴ·ㄷ은 맞지만 통지기한 ㄹ이 15일로 틀렸다. 7일이다(법 제29조제5항)."},{"번호":2,"판정":"-","설명":"심의기간 ㄴ이 90일이 아니라 60일이고, 통지 주체 ㄷ이 지적소관청이 아니라 시·도지사다."},{"번호":3,"판정":"-","설명":"ㄱ 시·도지사(법 제29조제2항), ㄴ 60일(제3항), ㄷ 시·도지사, ㄹ 7일(제5항)이다."},{"번호":4,"판정":"-","설명":"회부하는 자는 지적소관청이 아니라 시·도지사다. 적부심사는 시·도지사를 거쳐 청구한다."},{"번호":5,"판정":"-","설명":"ㄱ·ㄴ·ㄹ이 모두 틀렸다. 90일은 재심사 청구 기간이다(법 제29조제6항)."}],"개념":[{"종류":"흐름","제목":"지적측량 적부심사","단계":[{"이름":"청구","설명":"토지소유자·이해관계인·지적측량수행자가 관할 시·도지사를 거쳐 지방지적위원회에 청구한다."},{"이름":"조사·회부","설명":"시·도지사가 30일 이내에 지적측량 경위와 성과, 토지이동·소유권 변동 연혁, 주변 현황 실측도를 조사해 회부한다."},{"이름":"심의·의결","설명":"지방지적위원회가 회부받은 날부터 60일 이내에 의결한다. 부득이하면 위원회 의결을 거쳐 30일 이내에서 한 번만 연장한다."},{"이름":"의결서 송부·통지","설명":"위원회가 의결서를 시·도지사에게 송부하고, 시·도지사가 받은 날부터 7일 이내에 청구인과 이해관계인에게 통지한다."},{"이름":"재심사","설명":"불복하면 의결서를 받은 날부터 90일 이내에 국토교통부장관을 거쳐 중앙지적위원회에 청구한다."},{"이름":"정정","설명":"재심사를 청구하지 않으면 의결서 사본을 지적소관청에 보내고, 지적소관청이 등록사항을 정정하거나 측량성과를 수정한다."}]},{"종류":"표","제목":"적부심사 기간 모음","머리":["단계","기간","주체"],"행":[["조사·회부","청구를 받은 날부터 30일 이내","시·도지사"],["심의·의결","회부받은 날부터 60일 이내, 30일 이내 한 번 연장","지방지적위원회"],["의결서 통지","의결서를 받은 날부터 7일 이내","시·도지사"],["재심사 청구","의결서를 받은 날부터 90일 이내","청구인·이해관계인"]]}],"함정":"회부·통지 주체는 지적소관청이 아니라 시·도지사다. 7일, 30일, 60일, 90일이 한 조문에 몰려 있어 숫자를 서로 바꿔 쓴 선지가 나온다. 90일은 재심사 청구 기간에만 쓴다."},"36회-2차-095":{"한줄":"농지취득자격증명은 농지 소유권 취득의 요건이어서, 이를 발급받지 못한 채 등기를 마쳐도 소유권을 취득하지 못한다.","근거":[{"법령":"농지법","조문":"제8조제1항·제6항","원문":"제8조(농지취득자격증명의 발급)\n①농지를 취득하려는 자는 농지 소재지를 관할하는 시장(구를 두지 아니한 시의 시장을 말하며, 도농 복합 형태의 시는 농지 소재지가 동지역인 경우만을 말한다), 구청장(도농 복합 형태의 시의 구에서는 농지 소재지가 동지역인 경우만을 말한다), 읍장 또는 면장(이하 \"시ㆍ구ㆍ읍ㆍ면의 장\"이라 한다)에게서 농지취득자격증명을 발급받아야 한다. 다만, 다음 각 호의 어느 하나에 해당하면 농지취득자격증명을 발급받지 아니하고 농지를 취득할 수 있다.\n⑥제1항 본문과 제2항에 따라 농지취득자격증명을 발급받아 농지를 취득하는 자가 그 소유권에 관한 등기를 신청할 때에는 농지취득자격증명을 첨부하여야 한다."},{"법령":"부동산등기규칙","조문":"제43조제1항제7호","원문":"제43조(신청정보의 내용)\n① 등기를 신청하는 경우에는 다음 각 호의 사항을 신청정보의 내용으로 등기소에 제공하여야 한다.\n  7. 등기필정보. 다만, 공동신청 또는 승소한 등기의무자의 단독신청에 의하여 권리에 관한 등기를 신청하는 경우로 한정한다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제11조제1항","원문":"제11조(허가구역 내 토지거래에 대한 허가)\n① 허가구역에 있는 토지에 관한 소유권ㆍ지상권(소유권ㆍ지상권의 취득을 목적으로 하는 권리를 포함한다)을 이전하거나 설정(대가를 받고 이전하거나 설정하는 경우만 해당한다)하는 계약(예약을 포함한다. 이하 \"토지거래계약\"이라 한다)을 체결하려는 당사자는 공동으로 대통령령으로 정하는 바에 따라 시장ㆍ군수 또는 구청장의 허가를 받아야 한다. 허가받은 사항을 변경하려는 경우에도 또한 같다."}],"선지":[{"번호":1,"판정":"틀림","설명":"비영리법인의 설립허가는 법인 자체의 요건이다. 법인이 부동산을 취득하는 이전등기에 주무관청 허가서를 첨부하라는 규정은 없다."},{"번호":2,"판정":"틀림","설명":"학교법인이 기본재산을 처분하려면 관할청의 허가가 필요하고(사립학교법 제28조제1항), 처분에 따른 등기신청에는 그 허가를 증명하는 정보를 첨부한다(규칙 제46조제1항제2호)."},{"번호":3,"판정":"틀림","설명":"등기필정보는 공동신청 또는 승소한 등기의무자의 단독신청일 때 제공한다(규칙 제43조제1항제7호). 승소한 등기권리자의 단독신청에는 제공하지 않는다."},{"번호":4,"판정":"옳음","설명":"농지를 취득하려면 농지취득자격증명을 발급받아야 하고(농지법 제8조제1항), 이를 발급받아 취득한 자가 등기를 신청할 때 첨부한다(같은 조 제6항). 증명 없이 마친 이전등기로는 소유권을 취득하지 못한다."},{"번호":5,"판정":"틀림","설명":"허가는 허가구역 안의 토지에 대한 계약을 체결하려는 당사자가 받는 것이다(거래신고법 제11조제1항). 허가구역 지정 전에 체결한 계약의 이전등기에는 허가서 첨부를 요구하지 않는다."}],"개념":[{"종류":"표","제목":"등기신청 시 주요 제공정보","머리":["정보","제공 여부"],"행":[["등기필정보","공동신청, 승소한 등기의무자의 단독신청에 제공. 승소한 등기권리자의 단독신청에는 불요"],["농지취득자격증명","농지 소유권이전등기 신청 시 첨부(농지법 제8조제6항). 법령상 면제 사유는 예외"],["토지거래허가서","허가구역 안 토지 계약 후 이전등기 시 첨부. 지정 전 체결 계약은 불요"],["학교법인 기본재산 처분 허가","관할청의 허가를 증명하는 정보 첨부"],["법인 대표자 자격","법인 신청 시 대표자 자격을 증명하는 정보 첨부(규칙 제46조제1항제4호)"],["등기원인에 대한 제3자 허가·동의","허가·동의·승낙을 증명하는 정보 첨부(규칙 제46조제1항제2호)"]]}],"함정":"농지취득자격증명은 이전등기를 마쳤다고 해서 나중에 보충되는 서류가 아니다. 증명 없이 한 등기로는 소유권을 취득하지 못한다. 토지거래허가는 계약 체결 시점이 기준이다. 승소한 등기권리자와 승소한 등기의무자에서 등기필정보 제공 여부가 갈린다."},"36회-2차-093":{"한줄":"특정유증에 따른 소유권이전등기는 법에 단독신청 규정이 없어 원칙대로 공동신청한다.","근거":[{"법령":"부동산등기법","조문":"제23조","원문":"제23조(등기신청인)\n① 등기는 법률에 다른 규정이 없는 경우에는 등기권리자(登記權利者)와 등기의무자(登記義務者)가 공동으로 신청한다.\n② 소유권보존등기(所有權保存登記) 또는 소유권보존등기의 말소등기(抹消登記)는 등기명의인으로 될 자 또는 등기명의인이 단독으로 신청한다.\n③ 상속, 법인의 합병, 그 밖에 대법원규칙으로 정하는 포괄승계에 따른 등기는 등기권리자가 단독으로 신청한다.\n④ 등기절차의 이행 또는 인수를 명하는 판결에 의한 등기는 승소한 등기권리자 또는 등기의무자가 단독으로 신청하고, 공유물을 분할하는 판결에 의한 등기는 등기권리자 또는 등기의무자가 단독으로 신청한다.\n⑤ 부동산표시의 변경이나 경정(更正)의 등기는 소유권의 등기명의인이 단독으로 신청한다.\n⑥ 등기명의인표시의 변경이나 경정의 등기는 해당 권리의 등기명의인이 단독으로 신청한다.\n⑦ 신탁재산에 속하는 부동산의 신탁등기는 수탁자(受託者)가 단독으로 신청한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"포괄승계에 해당하지 않는 특정유증은 수증자(등기권리자)와 유증자의 상속인 등(등기의무자)이 공동으로 신청한다(법 제23조제1항)."},{"번호":2,"판정":"틀림","설명":"이행판결에 의한 등기는 승소한 등기권리자 또는 등기의무자가 단독으로 신청한다(법 제23조제4항)."},{"번호":3,"판정":"틀림","설명":"부동산표시의 변경이나 경정의 등기는 소유권의 등기명의인이 단독으로 신청한다(법 제23조제5항)."},{"번호":4,"판정":"틀림","설명":"소유권보존등기의 말소등기는 등기명의인이 단독으로 신청한다(법 제23조제2항)."},{"번호":5,"판정":"틀림","설명":"신탁재산에 속하는 부동산의 신탁등기는 수탁자가 단독으로 신청한다(법 제23조제7항)."}],"개념":[{"종류":"표","제목":"단독신청과 공동신청","머리":["구분","신청 방법","근거"],"행":[["원칙","등기권리자와 등기의무자 공동","법 제23조제1항"],["소유권보존등기·그 말소등기","등기명의인(될 자)이 단독","법 제23조제2항"],["상속·법인합병 등 포괄승계","등기권리자 단독","법 제23조제3항"],["이행·인수 판결, 공유물분할 판결","승소한 권리자·의무자 단독","법 제23조제4항"],["부동산표시의 변경·경정","소유권 등기명의인 단독","법 제23조제5항"],["등기명의인표시의 변경·경정","해당 권리의 등기명의인 단독","법 제23조제6항"],["신탁재산 신탁등기","수탁자 단독","법 제23조제7항"],["특정유증","공동신청","법 제23조제1항"]]},{"종류":"비교","제목":"포괄유증과 특정유증","왼쪽":{"이름":"포괄유증","항목":["수증자는 상속인과 같은 권리의무","등기신청은 공동신청"]},"오른쪽":{"이름":"특정유증","항목":["특정 재산을 지정하여 증여","등기원인은 유증, 공동신청"]}}],"함정":"이행판결, 표시변경, 보존말소, 신탁등기는 모두 법에 단독신청 규정이 있다. 유증은 상속과 달리 포괄승계 단독신청 규정(제23조제3항)에 들어가지 않는다. 포괄유증의 등기도 공동신청으로 처리한다."},"36회-2차-103":{"한줄":"지상권 설정청구권 가등기로 본등기를 하면 같은 부분의 지상권·지역권·전세권·임차권 설정등기만 직권말소한다. 토지임차권설정등기가 여기에 든다.","근거":[{"법령":"부동산등기규칙","조문":"제148조제1항","원문":"등기관이 지상권, 전세권 또는 임차권의 설정등기청구권보전 가등기에 의하여 지상권, 전세권 또는 임차권의 설정의 본등기를 한 경우 가등기 후 본등기 전에 마쳐진 다음 각 호의 등기(동일한 부분에 마쳐진 등기로 한정한다)는 법 제92조제1항에 따라 직권으로 말소한다.\n1. 지상권설정등기\n2. 지역권설정등기\n3. 전세권설정등기\n4. 임차권설정등기"},{"법령":"부동산등기규칙","조문":"제148조제2항","원문":"지상권, 전세권 또는 임차권의 설정등기청구권보전 가등기에 의하여 지상권, 전세권 또는 임차권의 설정의 본등기를 한 경우 가등기 후 본등기 전에 마쳐진 다음 각 호의 등기는 직권말소의 대상이 되지 아니한다.\n1. 소유권이전등기 및 소유권이전등기청구권보전 가등기\n2. 가압류 및 가처분 등 처분제한의 등기\n3. 체납처분으로 인한 압류등기\n4. 저당권설정등기"}],"선지":[{"번호":1,"판정":"틀림","설명":"저당권설정등기는 용익권 본등기와 양립하므로 직권말소 대상이 아니다(규칙 제148조제2항제4호)."},{"번호":2,"판정":"옳음","설명":"임차권설정등기는 같은 토지 전부에 마쳐진 지상권과 양립할 수 없는 용익권이라 직권말소한다(규칙 제148조제1항제4호)."},{"번호":3,"판정":"틀림","설명":"체납처분으로 인한 압류등기는 직권말소 대상이 아니다(규칙 제148조제2항제3호)."},{"번호":4,"판정":"틀림","설명":"가압류·가처분 등 처분제한의 등기는 남는다(규칙 제148조제2항제2호)."},{"번호":5,"판정":"틀림","설명":"소유권이전등기와 소유권이전등기청구권보전 가등기는 남는다(규칙 제148조제2항제1호)."}],"개념":[{"종류":"표","제목":"가등기 종류별 본등기 뒤 직권말소 범위","머리":["가등기의 종류","직권말소하는 것","직권말소하지 않는 것","근거"],"행":[["소유권이전청구권 가등기","가등기 뒤 본등기 전에 마쳐진 등기 중 예외를 뺀 전부","가등기상 권리 목적의 가압류·가처분, 가등기 전 가압류의 강제경매개시결정, 가등기 전 담보가등기·전세권·저당권의 임의경매개시결정, 대항력 있는 주택임차권등기등","규칙 제147조제1항"],["소유권이전청구권 가등기 중 체납처분 압류","직권말소대상통지 후 이의신청이 있으면 예규에 따라 결정","이의신청이 없는 경우의 처리는 예규에 따름","규칙 제147조제2항"],["지상권·전세권·임차권 설정청구권 가등기","동일한 부분의 지상권·지역권·전세권·임차권 설정등기, 대항력 없는 주택임차권등기등","소유권이전과 그 가등기, 가압류·가처분, 체납처분 압류, 저당권설정, 가등기 안 된 부분의 용익권","규칙 제148조제1·2항"],["저당권설정청구권 가등기","없음","가등기 후 본등기 전의 등기 전부","규칙 제148조제3항"]]},{"종류":"비교","제목":"소유권 가등기와 용익권 가등기의 본등기","왼쪽":{"이름":"소유권이전청구권 가등기","항목":["중간 등기를 거의 전부 직권말소","가압류·가처분은 가등기상 권리를 목적으로 한 것만 남는다","저당권설정등기는 말소 대상","규칙 제147조"]},"오른쪽":{"이름":"지상권·전세권·임차권 설정청구권 가등기","항목":["같은 부분의 용익권 설정등기만 말소","가압류·가처분 등 처분제한은 남는다","저당권설정등기는 남는다","규칙 제148조"]}}],"함정":"선지 1을 고르기 쉽다. 소유권이전청구권 가등기의 본등기에서는 중간의 저당권이 말소되지만, 용익권 가등기에서는 저당권이 남는다. 직권말소는 가등기로 보전하는 권리와 양립하지 못하는 같은 부분의 용익권에 한정된다."},"36회-2차-110":{"한줄":"옳은 것은 ㄴ뿐이다. 조작 설비·부대설비는 주체구조부와 한 몸이 되면 주체구조부 취득자가 함께 취득한 것으로 본다.","근거":[{"법령":"지방세법","조문":"제6조제1호","원문":"1. \"취득\"이란 매매, 교환, 상속, 증여, 기부, 법인에 대한 현물출자, 건축, 개수(改修), 공유수면의 매립, 간척에 의한 토지의 조성 등과 그 밖에 이와 유사한 취득으로서 원시취득(수용재결로 취득한 경우 등 과세대상이 이미 존재하는 상태에서 취득하는 경우는 제외한다), 승계취득 또는 유상ㆍ무상의 모든 취득을 말한다."},{"법령":"지방세법","조문":"제7조제3항","원문":"③ 건축물 중 조작(造作) 설비, 그 밖의 부대설비에 속하는 부분으로서 그 주체구조부(主體構造部)와 하나가 되어 건축물로서의 효용가치를 이루고 있는 것에 대하여는 주체구조부 취득자 외의 자가 가설(加設)한 경우에도 주체구조부의 취득자가 함께 취득한 것으로 본다."},{"법령":"지방세법","조문":"제7조제4항","원문":"④ 선박, 차량과 기계장비의 종류를 변경하거나 토지의 지목을 사실상 변경함으로써 그 가액이 증가한 경우에는 취득으로 본다. 이 경우 「도시개발법」에 따른 도시개발사업(환지방식만 해당한다)의 시행으로 토지의 지목이 사실상 변경된 때에는 그 환지계획에 따라 공급되는 환지는 조합원이, 체비지 또는 보류지는 사업시행자가 각각 취득한 것으로 본다."},{"법령":"지방세법","조문":"제7조제7항","원문":"⑦ 상속(피상속인이 상속인에게 한 유증 및 포괄유증과 신탁재산의 상속을 포함한다. 이하 이 장과 제3장에서 같다)으로 인하여 취득하는 경우에는 상속인 각자가 상속받는 취득물건(지분을 취득하는 경우에는 그 지분에 해당하는 취득물건을 말한다)을 취득한 것으로 본다. 이 경우 상속인의 납부의무에 관하여는 「지방세기본법」 제44조제1항 및 제5항을 준용한다."},{"법령":"지방세법","조문":"제7조제8항","원문":"⑧ 「주택법」 제11조에 따른 주택조합과 「도시 및 주거환경정비법」 제35조제3항 및 「빈집 및 소규모주택 정비에 관한 특례법」 제23조에 따른 재건축조합 및 소규모재건축조합(이하 이 장에서 \"주택조합등\"이라 한다)이 해당 조합원용으로 취득하는 조합주택용 부동산(공동주택과 부대시설ㆍ복리시설 및 그 부속토지를 말한다)은 그 조합원이 취득한 것으로 본다. 다만, 조합원에게 귀속되지 아니하는 부동산(이하 이 장에서 \"비조합원용 부동산\"이라 한다)은 제외한다."}],"선지":[{"번호":1,"판정":"-","설명":"ㄴ만 옳다. 보기 판정 참조."},{"번호":2,"판정":"-","설명":"ㄱ·ㅁ은 모두 틀린 보기다."},{"번호":3,"판정":"-","설명":"ㅁ이 틀려서 ㄴ, ㅁ 조합은 맞지 않는다."},{"번호":4,"판정":"-","설명":"ㄷ·ㄹ은 모두 틀린 보기다."},{"번호":5,"판정":"-","설명":"ㄷ·ㄹ·ㅁ은 모두 틀린 보기다."}],"보기판정":[{"기호":"ㄱ","판정":"틀림","설명":"취득에는 매매·교환·상속·증여·기부·현물출자·건축·개수 등이 모두 들어간다. 기부도 취득이다(지방세법 제6조제1호)."},{"기호":"ㄴ","판정":"옳음","설명":"조작 설비 등이 주체구조부와 하나가 되어 건축물의 효용가치를 이루면 가설한 자가 따로 있어도 주체구조부 취득자가 함께 취득한 것으로 본다(지방세법 제7조제3항)."},{"기호":"ㄷ","판정":"틀림","설명":"지목을 사실상 변경해 가액이 증가한 경우만 취득으로 본다. 감소한 경우는 해당하지 않는다(지방세법 제7조제4항)."},{"기호":"ㄹ","판정":"틀림","설명":"상속에는 피상속인이 상속인에게 한 유증과 포괄유증, 신탁재산의 상속이 포함된다. 상속인 각자가 지분만큼 취득한 것으로 본다(지방세법 제7조제7항)."},{"기호":"ㅁ","판정":"틀림","설명":"조합주택용 부동산은 공동주택과 부대시설·복리시설 및 부속토지를 말하고 조합원이 취득한 것으로 본다. 조합원에게 귀속되지 않는 비조합원용 부동산만 제외한다(지방세법 제7조제8항)."}],"개념":[{"종류":"표","제목":"취득세 취득 간주 규정(지방세법 제7조)","머리":["대상","취득자·효과","근거"],"행":[["등기·등록을 하지 않은 승계취득","사실상 취득하면 취득한 것, 양수인이 취득자","제7조제2항"],["건축물의 조작 설비·부대설비","주체구조부 취득자가 함께 취득","제7조제3항"],["토지 지목의 사실상 변경(가액 증가)","취득으로 봄. 가액 감소는 해당 없음","제7조제4항"],["과점주주가 된 경우","법인의 부동산등을 취득한 것으로 봄. 설립 시 주식 취득은 제외","제7조제5항"],["상속(유증·포괄유증·신탁재산의 상속 포함)","상속인 각자가 지분만큼 취득, 연대 납부","제7조제7항"],["주택조합등의 조합원용 부동산","조합원이 취득. 비조합원용은 제외","제7조제8항"],["배우자·직계존비속의 부동산등 취득","증여로 취득한 것으로 봄(경매·교환 등 예외)","제7조제11항"],["증여자의 채무를 인수하는 부담부증여","채무액 상당 부분은 유상취득","제7조제12항"]]},{"종류":"비교","제목":"주택조합등 취득 부동산의 취득자","왼쪽":{"이름":"조합원용 부동산","항목":["대상: 조합주택용 부동산(공동주택, 부대시설·복리시설, 그 부속토지)","취득자: 해당 조합원","주택조합등이 취득해도 조합원 취득으로 봄"]},"오른쪽":{"이름":"비조합원용 부동산","항목":["대상: 조합원에게 귀속되지 않는 부동산","취득자: 주택조합등","조합원 취득 간주 규정이 적용되지 않음"]}}],"함정":"ㄱ은 취득을 유상취득으로 좁혀 읽게 만든 보기다. 취득의 정의에는 기부와 증여 같은 무상취득이 들어간다. ㄷ은 가액이 증가한 경우만 취득으로 보는데 감소까지 넣었다. ㄹ은 유증이 상속에 들어가는 규정을 반대로 썼다. ㅁ은 조합원용 부동산의 범위에 부대시설·복리시설이 들어간다는 점을 뒤집은 보기다. ㄴ이 옳다는 것만 잡고 ㅁ까지 옳다고 읽으면 3번으로 간다."},"36회-2차-108":{"한줄":"수탁자의 물적납세의무는 신탁 설정일 이후에 법정기일이 도래하는 재산세에 대한 것이고, 설정일 전에 도래한 재산세는 대상이 아니다.","근거":[{"법령":"지방세법","조문":"제117조","원문":"제117조(물납) 지방자치단체의 장은 재산세의 납부세액이 1천만원을 초과하는 경우에는 납세의무자의 신청을 받아 해당 지방자치단체의 관할구역에 있는 부동산에 대하여만 대통령령으로 정하는 바에 따라 물납을 허가할 수 있다."},{"법령":"지방세법","조문":"제118조","원문":"제118조(분할납부) 지방자치단체의 장은 재산세의 납부세액이 250만원을 초과하는 경우에는 대통령령으로 정하는 바에 따라 납부할 세액의 일부를 납부기한이 지난 날부터 3개월 이내에 분할납부하게 할 수 있다."},{"법령":"지방세법","조문":"제118조의2제1항","원문":"① 지방자치단체의 장은 다음 각 호의 요건을 모두 충족하는 납세의무자가 제111조의2에 따른 1세대 1주택(제4조제1항에 따른 시가표준액이 9억원을 초과하는 주택을 포함한다)의 재산세액(해당 재산세를 징수하기 위하여 함께 부과하는 지방세를 포함하며, 이하 이 조에서 \"주택 재산세\"라 한다)의 납부유예를 그 납부기한 만료 3일 전까지 신청하는 경우 이를 허가할 수 있다. 이 경우 납부유예를 신청한 납세의무자는 그 유예할 주택 재산세에 상당하는 담보를 제공하여야 한다."},{"법령":"지방세법","조문":"제119조","원문":"제119조(소액 징수면제) 고지서 1장당 재산세로 징수할 세액이 2천원 미만인 경우에는 해당 재산세를 징수하지 아니한다."},{"법령":"지방세법","조문":"제119조의2제1항","원문":"① 신탁재산의 위탁자가 다음 각 호의 어느 하나에 해당하는 재산세ㆍ납부지연가산세 또는 체납처분비(이하 이 조에서 \"재산세등\"이라 한다)를 체납한 경우로서 그 위탁자의 다른 재산에 대하여 체납처분을 하여도 징수할 금액에 미치지 못할 때에는 해당 신탁재산의 수탁자는 그 신탁재산(해당 신탁재산의 관리, 처분, 운용 또는 개발 등을 통하여 수탁자가 얻은 재산으로서 「신탁법」 제27조에 따라 신탁재산에 속하는 재산을 포함한다. 이하 제5항 및 제6항에서 같다)으로써 위탁자의 재산세등을 납부할 의무가 있다. 1. 신탁 설정일 이후에 「지방세기본법」 제71조제1항에 따른 법정기일이 도래하는 재산세 또는 납부지연가산세(재산세에 대한 납부지연가산세으로 한정한다)으로서 해당 신탁재산과 관련하여 발생한 것. 다만, 제113조제1항제1호 및 제2호에 따라 신탁재산과 다른 토지를 합산하여 과세하는 경우에는 신탁재산과 관련하여 발생한 재산세 등을 제4조에 따른 신탁재산과 다른 토지의 시가표준액 비율로 안분계산한 부분 중 신탁재산 부분에 한정한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"납부세액이 1천만원을 초과하면 신청에 따라 물납을 허가할 수 있고, 해당 지방자치단체 관할구역의 부동산에 한한다(지방세법 제117조)."},{"번호":2,"판정":"옳음","설명":"납부세액이 250만원을 초과하면 납부기한이 지난 날부터 3개월 이내에 나누어 내게 할 수 있다(지방세법 제118조)."},{"번호":3,"판정":"옳음","설명":"납부유예를 신청한 납세의무자는 유예할 주택 재산세에 상당하는 담보를 제공해야 한다(지방세법 제118조의2제1항)."},{"번호":4,"판정":"옳음","설명":"고지서 1장당 재산세액이 2천원 미만이면 징수하지 않는다(지방세법 제119조)."},{"번호":5,"판정":"틀림","설명":"수탁자가 신탁재산으로 납부할 의무는 위탁자가 체납하고 위탁자의 다른 재산에 체납처분을 해도 부족한 경우, 신탁 설정일 이후에 법정기일이 도래하는 해당 신탁재산 관련 재산세에 한한다(지방세법 제119조의2제1항제1호)."}],"개념":[{"종류":"표","제목":"재산세 납부·징수 관련 수치(지방세법 제117조~제122조)","머리":["제도","요건·한도","근거"],"행":[["물납","납부세액 1천만원 초과, 납세의무자 신청, 관할구역 안 부동산에 한함","제117조"],["분할납부","납부세액 250만원 초과, 납부기한이 지난 날부터 3개월 이내","제118조"],["납부유예","1세대 1주택자 등 요건 충족, 납부기한 만료 3일 전까지 신청, 담보 제공","제118조의2"],["소액 징수면제","고지서 1장당 재산세 2천원 미만","제119조"],["세부담 상한","직전 연도 상당액의 100분의 150(주택은 적용 제외)","제122조"],["수탁자 물적납세의무","위탁자 체납 + 위탁자 다른 재산으로 부족 + 신탁 설정일 이후 법정기일 도래분","제119조의2"]]},{"종류":"흐름","제목":"주택 재산세 납부유예 절차(지방세법 제118조의2)","단계":[{"이름":"신청","설명":"납부기한 만료 3일 전까지 신청하고 유예할 재산세에 상당하는 담보를 제공한다. 과세기준일 현재 1세대 1주택 소유자, 만 60세 이상 또는 5년 이상 보유, 직전 과세기간 총급여액 7천만원 이하 또는 종합소득금액 6천만원 이하, 납부세액 100만원 초과, 지방세·국세 체납 없음."},{"이름":"허가 여부 통지","설명":"지방자치단체의 장이 납부기한 만료일까지 납세의무자에게 허가 여부를 통지한다."},{"이름":"유예 기간","설명":"허가한 날부터 징수할 세액의 고지일까지 납부지연가산세를 부과하지 않는다."},{"이름":"허가 취소","설명":"주택 양도·증여, 사망으로 상속 개시, 1세대 1주택 요건 상실, 담보 보전 명령 불응, 징수 곤란, 유예세액을 납부하려는 경우에는 취소해야 하고 납세의무자에게 즉시 통지한다."},{"이름":"징수","설명":"유예받은 세액과 이자상당가산액을 징수한다. 상속인은 상속으로 받은 재산의 한도에서 납부한다."}]}],"함정":"5번은 신탁 설정일 전과 후를 바꾼 선지다. 신탁 설정 전에 이미 법정기일이 지난 위탁자의 재산세까지 신탁재산이 떠안지는 않는다. 위탁자 체납과 다른 재산 부족이라는 요건도 같이 따라붙는다. 1번 물납과 2번 분할납부는 1천만원과 250만원을 바꿔 쓰는 숫자 함정으로 자주 나온다."},"36회-1차-020":{"한줄":"옳은 것은 ㄱ(취득세는 지방세로 재정수요 충족)과 ㄹ(탄력성이 작은 쪽이 조세를 더 부담)이다.","근거":[{"이론":"조세의 귀착","내용":"조세 부담은 가격에 덜 탄력적인 쪽이 더 크게 진다. 공급이 수요보다 비탄력적이면 공급자 부담이 더 크다."},{"이론":"거래세와 경제적 순손실","내용":"거래세를 부과하면 거래량이 줄어 총잉여가 감소하고 경제적 순손실(자중손실)이 생긴다."},{"이론":"동결효과","내용":"양도소득세가 강화되면 매도를 미루어 매물이 감소하고 부동산가격은 상승한다."},{"이론":"헨리 조지","내용":"토지 공급이 고정되어 토지세는 임차인에게 전가되지 않고 지주가 부담한다. 이를 근거로 토지단일세를 주장했다."}],"선지":[{"번호":1,"판정":"-","설명":"ㄴ이 틀리므로 조합이 맞지 않는다."},{"번호":2,"판정":"-","설명":"ㄱ과 ㄹ이 옳은 조합이다."},{"번호":3,"판정":"-","설명":"ㄴ, ㄷ, ㅁ이 모두 틀리므로 조합이 맞지 않는다."},{"번호":4,"판정":"-","설명":"ㄴ과 ㅁ이 틀리므로 조합이 맞지 않는다."},{"번호":5,"판정":"-","설명":"ㄷ과 ㅁ이 틀리므로 조합이 맞지 않는다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"취득세는 지방세로, 지방자치단체의 재정수요를 충족시킨다."},{"기호":"ㄴ","판정":"틀림","설명":"거래세를 부과하면 거래량이 줄어 총잉여가 감소하고 경제적 순손실이 발생한다."},{"기호":"ㄷ","판정":"틀림","설명":"동결효과로 매물이 줄어 부동산가격은 상승한다."},{"기호":"ㄹ","판정":"옳음","설명":"공급이 수요보다 비탄력적이면 공급자가 조세를 더 많이 부담한다."},{"기호":"ㅁ","판정":"틀림","설명":"헨리 조지는 토지세가 전가되지 않고 지주가 부담한다는 점을 근거로 토지단일세를 주장했다."}],"개념":[{"종류":"표","제목":"부동산 관련 조세 분류","머리":["단계","국세","지방세"],"행":[["취득","상속세, 증여세, 인지세","취득세, 등록면허세"],["보유","종합부동산세","재산세, 지방교육세"],["처분","양도소득세","지방소득세(양도소득분)"]]},{"종류":"비교","제목":"조세 귀착","왼쪽":{"이름":"수요가 비탄력적(공급이 탄력적)","항목":["수요자의 조세부담이 더 큼","예: 필수 주거용 부동산"]},"오른쪽":{"이름":"공급이 비탄력적(수요가 탄력적)","항목":["공급자의 조세부담이 더 큼","예: 토지 — 완전비탄력이면 전부 공급자(지주) 부담"]}}],"함정":"동결효과를 가격 하락으로 읽기 쉽다. 매물이 줄어 가격은 오른다. 거래세 부과로 총잉여가 늘어난다는 보기도 틀리다."},"36회-1차-026":{"한줄":"체계적 위험은 시장 전체에 영향을 주는 위험이라 분산투자로 제거할 수 없다.","근거":[{"이론":"체계적 위험과 비체계적 위험","내용":"체계적 위험(인플레이션·경기변동·금리)은 분산투자로 제거할 수 없고, 비체계적 위험(개별 자산 고유 위험)은 분산투자로 줄일 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"체계적 위험은 모든 자산에 공통으로 작용해 분산투자로 제거되지 않는다."},{"번호":2,"판정":"틀림","설명":"서로 아무 관계가 없으면 상관계수는 0이다. 1은 완전히 같은 방향으로 움직이는 경우다."},{"번호":3,"판정":"틀림","설명":"효용이 같은 조합을 이은 선은 무차별곡선이다. 효율적 투자선은 같은 위험에서 기대수익률이 최대인 점들을 이은 선이다."},{"번호":4,"판정":"틀림","설명":"같은 방향으로 움직이면 위험감소효과가 작다. 반대 방향으로 움직일수록 위험감소효과가 크다."},{"번호":5,"판정":"틀림","설명":"분산·표준편차는 수익이 아니라 위험을 측정하는 전통적인 방법이다."}],"개념":[{"종류":"비교","제목":"체계적 위험과 비체계적 위험","왼쪽":{"이름":"체계적 위험(시장위험)","항목":["경기변동·인플레이션·금리 변화","모든 자산에 공통","분산투자로 제거 불가"]},"오른쪽":{"이름":"비체계적 위험(고유위험)","항목":["개별 부동산의 입지·관리·임차인 문제","자산마다 다름","분산투자로 감소 가능"]}},{"종류":"표","제목":"포트폴리오이론 용어","머리":["용어","뜻"],"행":[["무차별곡선","투자자에게 효용이 같은 수익-위험 조합을 이은 곡선"],["효율적 전선(투자선)","같은 위험에서 최대 수익률을 주는 포트폴리오들의 집합"],["최적 포트폴리오","무차별곡선과 효율적 전선이 접하는 점"],["분산·표준편차","수익률의 흩어진 정도, 위험의 척도"]]}],"함정":"무차별곡선과 효율적 전선의 정의를 서로 바꿔 놓은 선지가 나온다. 분산·표준편차는 수익이 아니라 위험의 척도다."},"36회-1차-031":{"한줄":"DTI 기준 총 대출한도 1억 4,000만원이 LTV 기준 한도 2억 4,000만원보다 작으므로 총 한도는 1억 4,000만원이고, 기존 대출 5,000만원을 빼면 추가대출 최대금액은 9,000만원이다.","근거":[{"이론":"LTV·DTI에 의한 대출한도","내용":"LTV 한도 = 담보가치 × LTV, DTI 한도(대출금액) = 연소득 × DTI ÷ 저당상수. 두 기준을 모두 충족해야 하므로 작은 쪽이 총 한도이고, 기존 대출을 뺀 금액이 추가대출 한도다."}],"선지":[{"번호":1,"판정":"-","설명":"7,000만원 × 40% = 2,800만원은 연간 원리금 상환 한도다. 저당상수로 나누기 전의 값이라 대출금액이 아니다."},{"번호":2,"판정":"-","설명":"총 한도 min(2억 4,000만원, 1억 4,000만원) = 1억 4,000만원에서 기존 대출 5,000만원을 뺀 9,000만원이다."},{"번호":3,"판정":"-","설명":"DTI 기준 총 한도이며 기존 대출 5,000만원을 빼지 않았다."},{"번호":4,"판정":"-","설명":"LTV 기준 추가대출액(2억 4,000만원 − 5,000만원)이다. DTI 기준을 반영하지 않았다."},{"번호":5,"판정":"-","설명":"LTV 기준 총 한도이며 DTI도 기존 대출도 반영하지 않았다."}],"개념":[{"종류":"계산","제목":"추가대출 최대금액","단계":[{"설명":"DTI 기준 연간 원리금 한도","식":"연소득 × DTI = 7,000만원 × 40%","값":"2,800만원"},{"설명":"DTI 기준 총 대출한도","식":"연간 원리금 한도 ÷ 저당상수 = 2,800만원 ÷ 0.2","값":"1억 4,000만원"},{"설명":"LTV 기준 총 대출한도","식":"담보가치 × LTV = 4억원 × 60%","값":"2억 4,000만원"},{"설명":"총 대출한도","식":"두 기준을 모두 충족 → 작은 값","값":"1억 4,000만원"},{"설명":"추가대출 최대금액","식":"총 한도 − 기존 대출 = 1억 4,000만원 − 5,000만원","값":"9,000만원"}]},{"종류":"표","제목":"LTV·DTI·DSR 비교","머리":["구분","계산식","높을수록","과열기 정책 방향"],"행":[["LTV(담보인정비율)","대출금액 ÷ 담보가치","대출 가능액이 커지고 자기자본 비율은 낮아짐","낮춰서 대출 억제"],["DTI(총부채상환비율)","해당 주택담보대출 연간 원리금 ÷ 연소득 (기타 대출은 이자만 합산)","연소득 대비 상환 부담이 커짐","낮춰서 대출 억제"],["DSR(총부채원리금상환비율)","모든 대출의 연간 원리금 ÷ 연소득","전체 부채 상환 부담이 커짐","낮춰서 대출 억제"],["침체기 정책 방향","LTV·DTI를 높여 대출 확대","주택 수요 증가","-"]]}],"함정":"저당상수를 곱해야 하는지 나눠야 하는지 헷갈리면 ①을 고르게 된다. 연간 원리금 한도를 대출금액으로 바꿀 때는 저당상수로 나눈다. 둘 중 작은 값을 쓰지 않고 LTV 한도만 보면 ④·⑤가 나온다."},"36회-2차-005":{"한줄":"ㄱ과 ㄷ은 맞고, ㄴ은 완료일부터 15일 이내가 수시 모니터링의 기한이라 틀려서 4번이다.","근거":[{"법령":"공인중개사법 시행령","조문":"제17조의3제1항제1호","원문":"국토교통부장관은 법 제18조의3제4항에 따라 다음 각 호의 어느 하나에 해당하는 기관에 같은 조 제1항에 따른 모니터링 업무를 위탁할 수 있다. 1. 「공공기관의 운영에 관한 법률」 제4조에 따른 공공기관"},{"법령":"공인중개사법 시행규칙","조문":"제10조의3제3항","원문":"모니터링 기관은 제1항에 따라 업무를 수행한 경우 해당 업무에 따른 결과보고서를 다음 각 호의 구분에 따른 기한까지 국토교통부장관에게 제출해야 한다. 1. 기본 모니터링 업무: 매 분기의 마지막 날부터 30일 이내 2. 수시 모니터링 업무: 해당 모니터링 업무를 완료한 날부터 15일 이내"},{"법령":"공인중개사법 시행규칙","조문":"제10조의3제4항","원문":"국토교통부장관은 제3항에 따라 제출받은 결과보고서를 시ㆍ도지사 및 등록관청 등에 통보하고 필요한 조사 및 조치를 요구할 수 있다."}],"선지":[{"번호":1,"판정":"-","설명":"ㄴ만으로는 부족하다. ㄴ이 틀렸다."},{"번호":2,"판정":"-","설명":"ㄷ만 고르면 ㄱ이 빠진다."},{"번호":3,"판정":"-","설명":"ㄴ이 틀렸으므로 포함할 수 없다."},{"번호":4,"판정":"-","설명":"ㄱ, ㄷ이 옳은 조합이다."},{"번호":5,"판정":"-","설명":"ㄴ이 틀렸으므로 3개 전부는 아니다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"공공기관은 위탁 가능 기관이다(영 제17조의3제1항제1호)."},{"기호":"ㄴ","판정":"틀림","설명":"기본 모니터링은 매 분기 마지막 날부터 30일 이내다. 완료일부터 15일 이내는 수시 모니터링이다(칙 제10조의3제3항)."},{"기호":"ㄷ","판정":"옳음","설명":"칙 제10조의3제4항."}],"개념":[{"종류":"표","제목":"기본 모니터링과 수시 모니터링","머리":["구분","기본 모니터링","수시 모니터링"],"행":[["실시","기본계획서에 따라 분기별","위반 의심 등 국토교통부장관이 필요하다고 판단할 때"],["계획서 제출","다음 연도 기본계획서를 매년 12월 31일까지","기간·내용·방법 등을 담은 계획서 제출"],["결과보고서 기한","매 분기의 마지막 날부터 30일 이내","업무 완료일부터 15일 이내"],["근거","칙 제10조의3제1항제1호·제2항제1호·제3항제1호","칙 제10조의3제1항제2호·제2항제2호·제3항제2호"]]},{"종류":"흐름","제목":"모니터링 결과 처리","단계":[{"이름":"모니터링 실시","설명":"국토교통부장관이 인터넷 표시·광고의 법 제18조의2 준수 여부를 점검, 업무는 위탁 가능(법 제18조의3제1항·제4항)"},{"이름":"결과보고서 제출","설명":"모니터링 기관이 국토교통부장관에게 제출(기본 분기 말일부터 30일, 수시 완료일부터 15일)"},{"이름":"통보·조치 요구","설명":"국토교통부장관이 시·도지사·등록관청 등에 통보하고 조사·조치 요구(칙 제10조의3제4항)"},{"이름":"결과 회신","설명":"시·도지사·등록관청 등이 조사·조치를 완료한 날부터 10일 이내에 국토교통부장관에게 통보(칙 제10조의3제5항)"}]}],"함정":"15일과 30일을 서로 바꿔 놓은 선지가 반복된다. 분기 단위로 도는 기본 모니터링이 30일, 건별로 도는 수시 모니터링이 15일이다."},"36회-2차-022":{"한줄":"신고센터 업무는 한국부동산원에 위탁하므로 ㄴ이 틀리고, ㄱ과 ㄷ이 옳아 3번이다.","근거":[{"법령":"공인중개사법","조문":"제47조의2제1항","원문":"국토교통부장관은 부동산 시장의 건전한 거래질서를 조성하기 위하여 부동산거래질서교란행위 신고센터(이하 이 조에서 \"신고센터\"라 한다)를 설치ㆍ운영할 수 있다."},{"법령":"공인중개사법","조문":"제47조의2제2항 본문","원문":"누구든지 부동산중개업 및 부동산 시장의 건전한 거래질서를 해치는 다음 각 호의 어느 하나에 해당하는 행위(이하 \"부동산거래질서교란행위\"라 한다)를 발견하는 경우 그 사실을 신고센터에 신고할 수 있다."},{"법령":"공인중개사법 시행령","조문":"제37조제7항","원문":"국토교통부장관은 법 제47조의2제4항에 따라 같은 조 제3항에 따른 신고센터의 업무를 「한국부동산원법」에 따른 한국부동산원(이하 \"한국부동산원\"이라 한다)에 위탁한다."}],"선지":[{"번호":1,"판정":"-","설명":"ㄷ이 빠졌다."},{"번호":2,"판정":"-","설명":"ㄴ은 틀린 보기다."},{"번호":3,"판정":"-","설명":"ㄱ, ㄷ이 옳은 조합이다."},{"번호":4,"판정":"-","설명":"ㄴ이 틀렸다."},{"번호":5,"판정":"-","설명":"ㄴ이 틀렸다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"법 제47조의2제1항."},{"기호":"ㄴ","판정":"틀림","설명":"위탁 기관은 한국부동산원이다(영 제37조제7항)."},{"기호":"ㄷ","판정":"옳음","설명":"누구든지 신고할 수 있다(법 제47조의2제2항)."}],"개념":[{"종류":"흐름","제목":"신고센터 처리 절차","단계":[{"이름":"신고","설명":"누구든지 신고인·피신고인 인적사항, 발생일시·장소·내용, 증거자료 등을 서면(전자문서 포함)으로 제출(영 제37조제1항)"},{"이름":"보완 요청","설명":"보완이 필요하면 기간을 정해 신고인에게 요청(영 제37조제2항)"},{"이름":"조사·조치 요구","설명":"시·도지사 및 등록관청 등에 요구. 명백한 거짓 등은 국토교통부장관 승인을 받아 종결 가능(영 제37조제3항)"},{"이름":"결과 통보","설명":"시·도지사·등록관청 등은 완료한 날부터 10일 이내 신고센터에 통보, 신고센터는 신고인에게 처리결과 통보(영 제37조제4항·제5항)"},{"이름":"월간 보고","설명":"신고센터는 매월 10일까지 직전 달의 접수·처리 결과를 국토교통부장관에게 제출(영 제37조제6항)"}]},{"종류":"표","제목":"부동산거래질서교란행위(법 제47조의2제2항)","머리":["호","위반 대상 조문"],"행":[["제1호","법 제7조~제9조, 제18조의4, 제33조제2항 위반(자격증 대여, 유사명칭, 무등록 중개업, 중개보조원 고지의무, 업무방해 등)"],["제2호","법 제48조제2호 해당 행위(거짓·부정한 방법으로 개설등록)"],["제3호","개업공인중개사가 제12조제1항, 제13조제1항·제2항, 제14조제1항, 제15조제3항, 제17조, 제18조, 제19조, 제25조제1항, 제25조의3, 제26조제3항을 위반"],["제4호","개업공인중개사등이 제12조제2항, 제29조제2항, 제33조제1항 위반"],["제5호","「부동산 거래신고 등에 관한 법률」 제3조, 제3조의2, 제4조 위반"]]}],"함정":"위탁 기관을 모르면 ㄴ이 그럴듯하다. 자격시험·교육 위탁 기관(공기업·준정부기관·협회 등)과 신고센터 위탁 기관(한국부동산원)을 섞지 않는다.","개정":"신고센터는 법 제47조의2(개정 2023.6.1)에 따라 운영되며 신고 대상 행위가 같은 항 각 호로 열거된다."},"36회-2차-027":{"한줄":"신고관청은 조사 결과를 시·도지사에게 보고하고, 시·도지사가 국토교통부장관에게 보고한다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률","조문":"제5조","원문":"③ 신고관청은 제2항에 따른 검증 결과를 해당 부동산의 소재지를 관할하는 세무관서의 장에게 통보하여야 하며, 통보받은 세무관서의 장은 해당 신고 내용을 국세 또는 지방세 부과를 위한 과세자료로 활용할 수 있다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제6조","원문":"① 신고관청은 제3조, 제3조의2 또는 제8조에 따라 신고 받은 내용이 누락되어 있거나 정확하지 아니하다고 판단하는 경우에는 국토교통부령으로 정하는 바에 따라 신고인에게 신고 내용을 보완하게 하거나 신고한 내용의 사실 여부를 확인하기 위하여 소속 공무원으로 하여금 거래당사자 또는 개업공인중개사에게 거래계약서, 거래대금 지급을 증명할 수 있는 자료 등 관련 자료의 제출을 요구하는 등 필요한 조치를 취할 수 있다.\n② 제1항에 따라 신고 내용을 조사(이하 이 조에서 \"신고내용조사\"라 한다)한 경우 신고관청은 조사 결과를 특별시장, 광역시장, 특별자치시장, 도지사, 특별자치도지사(이하 \"시ㆍ도지사\"라 한다)에게 보고하여야 하며, 시ㆍ도지사는 이를 국토교통부령으로 정하는 바에 따라 국토교통부장관에게 보고하여야 한다.\n③ 제1항에도 불구하고 국토교통부장관은 제3조, 제3조의2 또는 제8조에 따라 신고 받은 내용의 확인을 위하여 필요한 때에는 신고내용조사를 직접 또는 신고관청과 공동으로 실시할 수 있다.\n④ 국토교통부장관 및 신고관청은 제1항 및 제3항에 따른 신고내용조사를 위하여 국세ㆍ지방세에 관한 자료, 소득ㆍ재산에 관한 자료 등 대통령령으로 정하는 자료를 관계 행정기관의 장에게 요청할 수 있다. 이 경우 요청을 받은 관계 행정기관의 장은 정당한 사유가 없으면 그 요청에 따라야 한다."},{"법령":"부동산 거래신고 등에 관한 법률 시행규칙","조문":"제6조","원문":"① 국토교통부장관 또는 신고관청(이하 \"조사기관\"이라 한다)은 법 제6조제1항 또는 제3항에 따라 신고 내용을 조사하기 위하여 거래당사자 또는 개업공인중개사에게 다음 각 호의 자료를 제출하도록 요구할 수 있다.\n1. 거래계약서 사본\n2. 거래대금의 지급을 확인할 수 있는 입금표 또는 통장 사본"},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"별표 2 제5호","원문":"「공인중개사법」 제35조, 제36조, 제38조 및 제39조에 따른 공인중개사의 자격취소, 자격정지, 등록취소 및 업무정지에 관한 자료"}],"선지":[{"번호":1,"판정":"옳음","설명":"신고관청은 검증 결과를 관할 세무관서의 장에게 통보하고, 통보받은 세무관서의 장은 과세자료로 활용할 수 있다(법 제5조제3항)."},{"번호":2,"판정":"옳음","설명":"국세·지방세, 소득·재산 자료 등 대통령령으로 정하는 자료를 관계 행정기관의 장에게 요청할 수 있고(법 제6조제4항), 공인중개사법에 따른 자격취소·자격정지·등록취소·업무정지 자료가 포함된다(시행령 별표 2 제5호)."},{"번호":3,"판정":"옳음","설명":"국토교통부장관은 직접 또는 신고관청과 공동으로 신고내용조사를 할 수 있다(법 제6조제3항)."},{"번호":4,"판정":"틀림","설명":"신고관청은 조사 결과를 시·도지사에게 보고하고, 시·도지사가 국토교통부장관에게 보고한다(법 제6조제2항). 시·도지사가 월 1회 취합하여 보고한다(시행규칙 제6조제4항)."},{"번호":5,"판정":"옳음","설명":"거래계약서 사본, 입금표 또는 통장 사본 등의 제출을 요구할 수 있다(시행규칙 제6조제1항제1호·제2호)."}],"개념":[{"종류":"흐름","제목":"신고내용 검증·조사 체계","단계":[{"이름":"검증","설명":"신고관청이 국토교통부장관의 거래가격 검증체계로 신고가격의 적정성을 검증(법 제5조제2항)"},{"이름":"통보","설명":"검증 결과를 해당 부동산 소재지 관할 세무관서의 장에게 통보, 과세자료로 활용(같은 조 제3항)"},{"이름":"조사","설명":"누락·부정확 신고 시 보완 요구 또는 자료 제출 요구(법 제6조제1항). 국토교통부장관은 직접 또는 공동 조사 가능(같은 조 제3항)"},{"이름":"보고","설명":"신고관청 → 시·도지사 → 국토교통부장관(같은 조 제2항). 시·도지사는 월 1회 보고(시행규칙 제6조제4항)"},{"이름":"후속 조치","설명":"법 위반이 있으면 수사기관 고발 또는 관계 행정기관 통보(같은 조 제5항)"}]},{"종류":"표","제목":"자료제출 요구 대상(시행규칙 제6조제1항)","머리":["호","자료"],"행":[["1","거래계약서 사본"],["2","거래대금의 지급을 확인할 수 있는 입금표 또는 통장 사본"],["3","매수인이 대출, 정기예금 등 만기수령·해약, 주식·채권 등 처분을 하였음을 증명할 자료"],["4","매도인이 받은 거래대금을 예금 외의 용도로 지출한 경우 이를 증명할 자료"],["5","그 밖에 사실 확인에 필요한 자료"]]}],"함정":"보고 경로는 신고관청, 시·도지사, 국토교통부장관 순이다. 군수·구청장이 국토교통부장관에게 바로 보고한다는 문장이 틀린 선지이다. 자료제출 요구는 요구사유·자료범위·제출기한을 적은 서면으로 한다(시행규칙 제6조제2항)."},"36회-2차-030":{"한줄":"단독으로 주택 임대차 계약을 신고하려는 사람도 신분증명서를 신고관청에 보여줘야 한다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"제4조의3","원문":"① 법 제6조의2제1항 본문에서 \"대통령령으로 정하는 금액을 초과하는 임대차 계약\"이란 보증금이 6천만원을 초과하거나 월 차임이 30만원을 초과하는 주택 임대차 계약(계약을 갱신하는 경우로서 보증금 및 차임의 증감 없이 임대차 기간만 연장하는 계약은 제외한다)을 말한다.\n② 법 제6조의2제2항에서 \"대통령령으로 정하는 지역\"이란 특별자치시ㆍ특별자치도ㆍ시ㆍ군(광역시 및 경기도의 관할구역에 있는 군으로 한정한다)ㆍ구(자치구를 말한다)를 말한다."},{"법령":"부동산 거래신고 등에 관한 법률 시행규칙","조문":"제6조의2","원문":"⑤ 임대차계약당사자 중 일방이 신고를 거부해 법 제6조의2제3항에 따라 단독으로 주택 임대차 계약을 신고하려는 임대차계약당사자는 임대차 신고서에 서명 또는 날인한 후 제3항 각 호에 따른 서류 등과 단독신고사유서를 첨부해 신고관청에 제출해야 한다. 이 경우 신고관청은 단독신고 사유에 해당하는지를 확인해야 한다.\n⑥ 제2항부터 제5항까지의 규정에 따라 신고하려는 자는 신분증명서를 신고관청에 보여줘야 한다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제6조의3","원문":"① 임대차계약당사자는 제6조의2에 따라 신고한 후 해당 주택 임대차 계약의 보증금, 차임 등 임대차 가격이 변경되거나 임대차 계약이 해제된 때에는 변경 또는 해제가 확정된 날부터 30일 이내에 해당 신고관청에 공동으로 신고하여야 한다. 다만, 임대차계약당사자 중 일방이 국가등인 경우에는 국가등이 신고하여야 한다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제6조의5","원문":"① 제6조의2에도 불구하고 임차인이 「주민등록법」에 따라 전입신고를 하는 경우 이 법에 따른 주택 임대차 계약의 신고를 한 것으로 본다.\n③ 제6조의2, 제6조의3에 따른 신고의 접수를 완료한 때에는 「주택임대차보호법」 제3조의6제1항에 따른 확정일자를 부여한 것으로 본다(임대차계약서가 제출된 경우로 한정한다). 이 경우 신고관청은 「주택임대차보호법」 제3조의6제2항에 따라 확정일자부를 작성하거나 「주택임대차보호법」 제3조의6의 확정일자부여기관에 신고 사실을 통보하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"신고 지역은 특별자치시·특별자치도·시·군(광역시와 경기도 관할구역의 군에 한정)·구이다. 경상북도의 군은 해당하지 않는다(시행령 제4조의3제2항)."},{"번호":2,"판정":"틀림","설명":"보증금·차임의 증감 없이 임대차 기간만 연장하는 갱신계약은 신고 대상에서 제외된다(시행령 제4조의3제1항)."},{"번호":3,"판정":"옳음","설명":"공동신고, 단독신고, 국가등 신고 모두 신분증명서를 보여줘야 한다(시행규칙 제6조의2제5항·제6항)."},{"번호":4,"판정":"틀림","설명":"보증금·차임 등 임대차 가격이 변경되면 변경이 확정된 날부터 30일 이내에 공동으로 변경신고를 해야 한다. 감액도 같다(법 제6조의3제1항)."},{"번호":5,"판정":"틀림","설명":"반대이다. 임차인이 「주민등록법」에 따라 전입신고를 하면 주택 임대차 계약의 신고를 한 것으로 본다(법 제6조의5제1항)."}],"개념":[{"종류":"표","제목":"주택 임대차 계약 신고 요건","머리":["항목","내용","근거"],"행":[["대상 금액","보증금 6천만원 초과 또는 월 차임 30만원 초과","시행령 제4조의3제1항"],["제외","보증금·차임 증감 없이 기간만 연장하는 갱신계약","같은 항"],["대상 지역","특별자치시·특별자치도·시·군(광역시·경기도 관할 군만)·구","같은 조 제2항"],["기한·장소","계약체결일부터 30일 이내 주택 소재지 관할 신고관청","법 제6조의2제1항"],["변경·해제","확정일부터 30일 이내 공동 신고","법 제6조의3제1항"],["의제","전입신고 시 임대차 신고 의제, 신고 접수 완료 시 확정일자 부여 의제(계약서 제출 시)","법 제6조의5제1항·제3항"],["과태료","신고 불이행·거짓 신고 100만원 이하","법 제28조제5항제3호"]]},{"종류":"비교","제목":"임대차 신고와 확정일자","왼쪽":{"이름":"신고 접수 완료","항목":["임대차계약서가 제출된 경우","확정일자를 부여한 것으로 봄","신고관청이 확정일자부 작성 또는 통보"]},"오른쪽":{"이름":"전입신고","항목":["임차인이 주민등록법에 따라 한 경우","주택 임대차 계약의 신고를 한 것으로 봄","주민등록 대항요건도 별도로 충족"]}}],"함정":"신고 지역을 광역시와 경기도 군까지만 잡는 점을 놓치기 쉽다. 의제 방향(전입신고 → 임대차 신고)이 뒤집힌 5번도 단골이다."},"36회-2차-045":{"한줄":"가스관과 하수도관은 공동구협의회의 심의를 거쳐 수용할 수 있는 시설이고, 나머지는 반드시 수용해야 하는 시설이다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"영 제35조의3","원문":"공동구가 설치된 경우에는 법 제44조제3항에 따라 제1호부터 제6호까지의 시설을 공동구에 수용하여야 하며, 제7호 및 제8호의 시설은 법 제44조의2제4항에 따른 공동구협의회의 심의를 거쳐 수용할 수 있다. 1. 전선로\n2. 통신선로\n3. 수도관\n4. 열수송관\n5. 중수도관\n6. 쓰레기수송관\n7. 가스관\n8. 하수도관, 그 밖의 시설"},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"법 제44조제3항","원문":"③ 공동구가 설치된 경우에는 대통령령으로 정하는 바에 따라 공동구에 수용하여야 할 시설이 모두 수용되도록 하여야 한다."}],"선지":[{"번호":1,"판정":"-","설명":"ㄹ(쓰레기수송관)은 반드시 수용해야 하는 시설이다. 협의회 심의 대상이 아니다."},{"번호":2,"판정":"-","설명":"ㄴ(하수도관)과 ㄷ(가스관)이 협의회 심의를 거쳐 수용하는 시설이다(영 제35조의3 제7호·제8호)."},{"번호":3,"판정":"-","설명":"ㄱ(열수송관), ㄹ(쓰레기수송관), ㅁ(중수도관)은 모두 의무 수용 시설이다."},{"번호":4,"판정":"-","설명":"ㄱ(열수송관)과 ㅁ(중수도관)은 의무 수용 시설이므로 심의 대상에 넣을 수 없다."},{"번호":5,"판정":"-","설명":"다섯 시설 가운데 심의 대상은 가스관과 하수도관 둘뿐이다."}],"보기판정":[{"기호":"ㄱ","판정":"틀림","설명":"열수송관은 의무 수용 시설이다(영 제35조의3 제4호)."},{"기호":"ㄴ","판정":"옳음","설명":"하수도관은 공동구협의회 심의를 거쳐 수용한다(영 제35조의3 제8호)."},{"기호":"ㄷ","판정":"옳음","설명":"가스관은 공동구협의회 심의를 거쳐 수용한다(영 제35조의3 제7호)."},{"기호":"ㄹ","판정":"틀림","설명":"쓰레기수송관은 의무 수용 시설이다(영 제35조의3 제6호)."},{"기호":"ㅁ","판정":"틀림","설명":"중수도관은 의무 수용 시설이다(영 제35조의3 제5호)."}],"개념":[{"종류":"표","제목":"공동구 수용 시설(영 제35조의3)","머리":["구분","시설"],"행":[["반드시 수용(제1호~제6호)","전선로, 통신선로, 수도관, 열수송관, 중수도관, 쓰레기수송관"],["공동구협의회 심의를 거쳐 수용(제7호·제8호)","가스관, 하수도관, 그 밖의 시설"],["수용 의무의 근거","공동구가 설치된 경우 수용할 시설이 모두 수용되도록 한다(법 제44조③)"]]},{"종류":"표","제목":"공동구 설치(법 제44조, 영 제35조의2)","머리":["항목","내용"],"행":[["설치 의무자","개발사업을 시행하는 사업시행자"],["대상 지역","도시개발구역, 택지개발지구, 경제자유구역, 정비구역, 공공주택지구, 도청이전신도시"],["규모","200만㎡ 초과(영 제35조의2①)"],["비용 부담","공동구 점용예정자와 사업시행자(법 제44조⑤)"],["점용예정자 부담액","해당 시설을 개별적으로 매설할 때 필요한 비용(영 제38조②)"]]}],"함정":"가스관을 전선·수도관 같은 기반 설비로 보고 의무 수용으로 고르기 쉽다. 의무 수용 목록은 전선로, 통신선로, 수도관, 열수송관, 중수도관, 쓰레기수송관이고, 가스관과 하수도관은 협의회 심의 대상이다."},"36회-2차-059":{"한줄":"기본계획의 타당성을 5년마다 검토하는 사람은 국토교통부장관이 아니라 기본계획의 수립권자이다.","근거":[{"법령":"도시 및 주거환경정비법","조문":"법 제4조제1항·제2항","원문":"① 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사 또는 시장은 관할 구역에 대하여 도시ㆍ주거환경정비기본계획(이하 \"기본계획\"이라 한다)을 10년 단위로 수립하여야 한다. 다만, 도지사가 대도시가 아닌 시로서 기본계획을 수립할 필요가 없다고 인정하는 시에 대하여는 기본계획을 수립하지 아니할 수 있다.\n② 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사 또는 시장(이하 \"기본계획의 수립권자\"라 한다)은 기본계획에 대하여 5년마다 타당성을 검토하여 그 결과를 기본계획에 반영하여야 한다."},{"법령":"도시 및 주거환경정비법","조문":"법 제5조제1항제11호","원문":"11. 건폐율ㆍ용적률 등에 관한 건축물의 밀도계획"},{"법령":"도시 및 주거환경정비법","조문":"법 제6조제3항","원문":"③ 제1항 및 제2항에도 불구하고 대통령령으로 정하는 경미한 사항을 변경하는 경우에는 주민공람과 지방의회의 의견청취 절차를 거치지 아니할 수 있다."},{"법령":"도시 및 주거환경정비법 시행령","조문":"영 제6조제4항","원문":"④ 법 제6조제3항 및 제7조제1항 단서에서 \"대통령령으로 정하는 경미한 사항을 변경하는 경우\"란 각각 다음 각 호의 경우를 말한다.\n2. 정비사업의 계획기간을 단축하는 경우\n3. 공동이용시설에 대한 설치계획을 변경하는 경우"}],"선지":[{"번호":1,"판정":"틀림","설명":"5년마다 타당성을 검토하는 주체는 특별시장·광역시장·특별자치시장·특별자치도지사·시장(기본계획의 수립권자)이다(법 제4조제2항)."},{"번호":2,"판정":"옳음","설명":"도지사는 대도시가 아닌 시로서 기본계획을 수립할 필요가 없다고 인정하는 시에 대해 수립하지 않게 할 수 있다(법 제4조제1항 단서)."},{"번호":3,"판정":"옳음","설명":"기본계획에는 건폐율·용적률 등에 관한 건축물의 밀도계획이 포함된다(법 제5조제1항제11호)."},{"번호":4,"판정":"옳음","설명":"정비사업의 계획기간을 단축하는 변경은 경미한 사항이어서 주민공람과 지방의회 의견청취를 거치지 않을 수 있다(법 제6조제3항, 영 제6조제4항제2호)."},{"번호":5,"판정":"옳음","설명":"공동이용시설 설치계획의 변경도 경미한 사항이다(영 제6조제4항제3호)."}],"개념":[{"종류":"흐름","제목":"도시·주거환경정비기본계획 수립 절차","단계":[{"이름":"수립","설명":"특별시장·광역시장·특별자치시장·특별자치도지사·시장이 10년 단위로 수립(법 제4조①). 5년마다 타당성 검토(제4조②)"},{"이름":"주민공람·의견청취","설명":"14일 이상 주민공람, 지방의회 의견은 통지일부터 60일 이내(법 제6조)"},{"이름":"협의·심의","설명":"관계 행정기관 협의 후 지방도시계획위원회 심의(법 제7조①)"},{"이름":"도지사 승인","설명":"대도시가 아닌 시의 시장은 도지사 승인(법 제7조②)"},{"이름":"고시·보고","설명":"공보에 고시하고 일반이 열람. 국토교통부장관에게 보고(법 제7조③④)"}]},{"종류":"표","제목":"주민공람·의견청취를 생략하는 경미한 변경(영 제6조제4항)","머리":["호","내용"],"행":[["1호","정비기반시설 규모 확대, 또는 면적 10% 미만 축소"],["2호","정비사업의 계획기간 단축"],["3호","공동이용시설 설치계획 변경"],["4호","사회복지시설·주민문화시설 설치계획 변경"],["5호","정비예정구역 면적을 20% 미만 범위에서 변경"],["6호","단계별 정비사업 추진계획 변경"],["7호","건폐율·용적률을 각 20% 미만 범위에서 변경"]]}],"함정":"선지 1은 5년마다 타당성을 검토하는 주체를 국토교통부장관으로 적었다. 법에서 검토 주체는 기본계획의 수립권자이다. 경미한 변경 항목은 영 제6조제4항에 열거되어 있다."},"36회-2차-070":{"한줄":"국가 또는 한국토지주택공사가 사업주체인 경우에는 국토교통부장관의 사용검사를 받는다.","근거":[{"법령":"주택법","조문":"제49조제1항","원문":"① 사업주체는 제15조에 따른 사업계획승인을 받아 시행하는 주택건설사업 또는 대지조성사업을 완료한 경우에는 주택 또는 대지에 대하여 국토교통부령으로 정하는 바에 따라 시장ㆍ군수ㆍ구청장(국가 또는 한국토지주택공사가 사업주체인 경우와 대통령령으로 정하는 경우에는 국토교통부장관을 말한다. 이하 이 조에서 같다)의 사용검사를 받아야 한다. 다만, 제15조제3항에 따라 사업계획을 승인받은 경우에는 완공된 주택에 대하여 공구별로 사용검사(이하 \"분할 사용검사\"라 한다)를 받을 수 있고, 사업계획승인 조건의 미이행 등 대통령령으로 정하는 사유가 있는 경우에는 공사가 완료된 주택에 대하여 동별로 사용검사(이하 \"동별 사용검사\"라 한다)를 받을 수 있다."},{"법령":"주택법","조문":"제49조제3항","원문":"③ 제1항에도 불구하고 다음 각 호의 구분에 따라 해당 주택의 시공을 보증한 자, 해당 주택의 시공자 또는 입주예정자는 대통령령으로 정하는 바에 따라 사용검사를 받을 수 있다.\n1. 사업주체가 파산 등으로 사용검사를 받을 수 없는 경우에는 해당 주택의 시공을 보증한 자 또는 입주예정자\n2. 사업주체가 정당한 이유 없이 사용검사를 위한 절차를 이행하지 아니하는 경우에는 해당 주택의 시공을 보증한 자, 해당 주택의 시공자 또는 입주예정자. 이 경우 사용검사권자는 사업주체가 사용검사를 받지 아니하는 정당한 이유를 밝히지 못하면 사용검사를 거부하거나 지연할 수 없다."},{"법령":"주택법","조문":"제49조제4항","원문":"④ 사업주체 또는 입주예정자는 제1항에 따른 사용검사를 받은 후가 아니면 주택 또는 대지를 사용하게 하거나 이를 사용할 수 없다. 다만, 대통령령으로 정하는 경우로서 사용검사권자의 임시 사용승인을 받은 경우에는 그러하지 아니하다."},{"법령":"주택법 시행령","조문":"제54조제4항","원문":"④ 제3항에 따른 사용검사는 신청일부터 15일 이내에 하여야 한다."},{"법령":"주택법 시행령","조문":"제56조","원문":"제56조(임시 사용승인)\n① 법 제49조제4항 단서에서 \"대통령령으로 정하는 경우\"란 다음 각 호의 구분에 따른 경우를 말한다.\n1. 주택건설사업의 경우: 건축물의 동별로 공사가 완료된 경우\n2. 대지조성사업의 경우: 구획별로 공사가 완료된 경우\n② 법 제49조제4항 단서에 따른 임시 사용승인을 받으려는 자는 국토교통부령으로 정하는 바에 따라 사용검사권자에게 임시 사용승인을 신청하여야 한다.\n③ 사용검사권자는 제2항에 따른 신청을 받은 때에는 임시 사용승인대상인 주택 또는 대지가 사업계획의 내용에 적합하고 사용에 지장이 없는 경우에만 임시사용을 승인할 수 있다. 이 경우 임시 사용승인의 대상이 공동주택인 경우에는 세대별로 임시 사용승인을 할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"국가 또는 한국토지주택공사가 사업주체인 경우의 사용검사권자는 국토교통부장관이다(법 제49조제1항)."},{"번호":2,"판정":"옳음","설명":"사업주체가 파산 등으로 사용검사를 받을 수 없으면 시공보증자 또는 입주예정자가 받을 수 있다(법 제49조제3항제1호)."},{"번호":3,"판정":"옳음","설명":"사용검사는 신청일부터 15일 이내에 한다(영 제54조제4항)."},{"번호":4,"판정":"옳음","설명":"대지조성사업은 구획별로 공사가 완료된 경우 임시 사용승인을 받아 사용검사 전에 사용할 수 있다(법 제49조제4항 단서, 영 제56조제1항제2호)."},{"번호":5,"판정":"옳음","설명":"임시 사용승인 대상이 공동주택이면 세대별로 승인할 수 있다(영 제56조제3항 후단)."}],"개념":[{"종류":"흐름","제목":"사용검사 절차","단계":[{"이름":"사용검사 신청","설명":"사업계획승인을 받아 시행한 주택건설·대지조성사업을 완료하면 시장·군수·구청장에게 사용검사를 받는다. 국가·한국토지주택공사가 사업주체인 경우 등은 국토교통부장관이다(법 제49조제1항)."},{"이름":"분할·동별 사용검사","설명":"공구별로 사업계획을 승인받은 경우 공구별로, 승인 조건 미이행 등 영 제54조제2항 사유가 있으면 동별로 받을 수 있다(법 제49조제1항 단서)."},{"이름":"검사","설명":"신청일부터 15일 이내에 사업계획 적합 여부와 사용검사 전 조치해야 하는 하자의 조치 완료 여부를 확인한다(영 제54조제3항·제4항)."},{"이름":"관계 기관 협의","설명":"의제된 인허가의 사용승인·준공검사를 위해 관계 행정기관의 장과 협의하며, 협의 요청을 받은 기관은 10일 이내에 의견을 제시한다(법 제49조제2항, 영 제54조제5항)."},{"이름":"사용","설명":"사용검사를 받은 후에야 주택·대지를 사용하게 하거나 사용할 수 있다. 임시 사용승인을 받으면 예외다(법 제49조제4항)."}]},{"종류":"표","제목":"임시 사용승인과 대행 사용검사","머리":["구분","내용"],"행":[["임시 사용승인(주택건설)","건축물의 동별로 공사가 완료된 경우(영 제56조제1항제1호)"],["임시 사용승인(대지조성)","구획별로 공사가 완료된 경우(영 제56조제1항제2호)"],["임시 사용승인 요건","사업계획 내용에 적합하고 사용에 지장이 없는 경우에만 가능, 공동주택은 세대별 승인 가능(영 제56조제3항)"],["대행 사용검사(제3항제1호)","사업주체가 파산 등으로 받을 수 없으면 시공보증자 또는 입주예정자"],["대행 사용검사(제3항제2호)","사업주체가 정당한 이유 없이 절차를 이행하지 않으면 시공보증자, 시공자 또는 입주예정자"],["시공보증자의 사용검사(영 제55조제1항)","시공보증자가 잔여공사를 시공하고 사용검사를 받음. 시공보증자가 없거나 시공이 불가능하면 입주예정자대표회의가 시공자를 정함"]]}],"함정":"사용검사권자는 시장·군수·구청장이 원칙이고, 국가와 한국토지주택공사가 사업주체이면 국토교통부장관이다. 지방공사나 지방자치단체는 이 예외에 들지 않는다.","개정":"법 제49조제5항(입주예정자 과반수가 요청하면 사용검사 전에 현장점검)은 2026.2.3 신설되었다. 요청에 따르지 않은 사업주체는 1천만원 이하의 과태료 대상이다(법 제106조제2항제5호의2)."},"36회-2차-082":{"한줄":"박물관·미술관 같은 문화시설과 그에 접속된 정원·부속시설물의 부지는 지목이 대(垈)다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제58조제8호","원문":"대: 가. 영구적 건축물 중 주거ㆍ사무실ㆍ점포와 박물관ㆍ극장ㆍ미술관 등 문화시설과 이에 접속된 정원 및 부속시설물의 부지 / 나. 「국토의 계획 및 이용에 관한 법률」 등 관계 법령에 따른 택지조성공사가 준공된 토지"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제58조제22호","원문":"공원: 일반 공중의 보건ㆍ휴양 및 정서생활에 이용하기 위한 시설을 갖춘 토지로서 「국토의 계획 및 이용에 관한 법률」에 따라 공원 또는 녹지로 결정ㆍ고시된 토지"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제58조제26호","원문":"사적지: 국가유산으로 지정된 역사적인 유적ㆍ고적ㆍ기념물 등을 보존하기 위하여 구획된 토지. 다만, 학교용지ㆍ공원ㆍ종교용지 등 다른 지목으로 된 토지에 있는 유적ㆍ고적ㆍ기념물 등을 보호하기 위하여 구획된 토지는 제외한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"문화시설과 접속된 정원·부속시설물 부지는 대에 속한다(영 제58조제8호가목)."},{"번호":2,"판정":"틀림","설명":"공원은 보건·휴양·정서생활 시설을 갖춘 토지 중 국토계획법상 공원 또는 녹지로 결정·고시된 것이다(영 제58조제22호). 문화시설 부지는 이에 해당하지 않는다."},{"번호":3,"판정":"틀림","설명":"사적지는 국가유산으로 지정된 유적·고적·기념물을 보존하려고 구획한 토지다(영 제58조제26호). 박물관·미술관 부지와 관계없다."},{"번호":4,"판정":"틀림","설명":"유원지는 수영장·유선장·낚시터·어린이놀이터·동물원·식물원·민속촌·경마장·야영장 같은 위락·휴양 시설의 토지다(영 제58조제24호)."},{"번호":5,"판정":"틀림","설명":"학교용지는 학교의 교사와 이에 접속된 체육장 등 부속시설물의 부지다(영 제58조제10호)."}],"개념":[{"종류":"표","제목":"건축물 부지를 가르는 지목","머리":["지목","해당 부지","주의"],"행":[["대","주거ㆍ사무실ㆍ점포, 박물관ㆍ극장ㆍ미술관 등 문화시설과 접속 정원ㆍ부속시설물, 택지조성공사 준공 토지","과수원ㆍ목장용지ㆍ묘지 안의 주거용(관리용) 건축물 부지도 대"],["공장용지","제조업 공장시설물, 공장부지 조성공사 준공 토지, 같은 구역의 의료시설 등 부속시설물","공장 안 급유ㆍ송유시설은 주유소용지에서 제외"],["학교용지","학교 교사와 접속 체육장 등 부속시설물","-"],["종교용지","교회ㆍ사찰ㆍ향교 등 건축물과 접속 부속시설물","-"],["창고용지","독립 설치된 보관시설물과 접속 부속시설물","-"],["사적지","국가유산으로 지정된 유적ㆍ고적ㆍ기념물 보존 구획 토지","학교용지ㆍ공원ㆍ종교용지 안의 유적 구획 토지는 제외"]]},{"종류":"표","제목":"지목 부호: 첫 글자와 다른 네 가지","머리":["지목","부호","비고"],"행":[["공장용지","장","공원(공)과 구별"],["주차장","차","주유소용지(주)와 구별"],["하천","천","-"],["유원지","원","유지(유)와 구별"],["그 밖의 지목","첫 글자","학교용지 학, 창고용지 창, 주유소용지 주 등"]]}],"함정":"정원이 딸려 있다는 이유로 2번 공원을 고르기 쉽다. 공원은 국토계획법에 따라 공원·녹지로 결정·고시된 토지여야 하고, 문화시설의 부속 정원은 대의 일부다."},"36회-2차-083":{"한줄":"부동산종합공부의 등록사항은 법이 다섯 가지로 정해 두었고 토지적성평가 확인서는 그 안에 없다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제76조의3","원문":"지적소관청은 부동산종합공부에 다음 각 호의 사항을 등록하여야 한다. 1. 토지의 표시와 소유자에 관한 사항: 이 법에 따른 지적공부의 내용 2. 건축물의 표시와 소유자에 관한 사항(토지에 건축물이 있는 경우만 해당한다): 「건축법」 제38조에 따른 건축물대장의 내용 3. 토지의 이용 및 규제에 관한 사항: 「토지이용규제 기본법」 제10조에 따른 토지이용계획확인서의 내용 4. 부동산의 가격에 관한 사항: 「부동산 가격공시에 관한 법률」 제10조에 따른 개별공시지가, 같은 법 제16조, 제17조 및 제18조에 따른 개별주택가격 및 공동주택가격 공시내용 5. 그 밖에 부동산의 효율적 이용과 부동산과 관련된 정보의 종합적 관리ㆍ운영을 위하여 필요한 사항으로서 대통령령으로 정하는 사항"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제62조의2","원문":"법 제76조의3제5호에서 “대통령령으로 정하는 사항”이란 「부동산등기법」 제48조에 따른 부동산의 권리에 관한 사항을 말한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제76조의2제2항·제3항","원문":"지적소관청은 부동산종합공부를 영구히 보존하여야 하며, 부동산종합공부의 멸실 또는 훼손에 대비하여 이를 별도로 복제하여 관리하는 정보관리체계를 구축하여야 한다. / 제76조의3 각 호의 등록사항을 관리하는 기관의 장은 지적소관청에 상시적으로 관련 정보를 제공하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제76조의4제1항","원문":"부동산종합공부를 열람하거나 부동산종합공부 기록사항의 전부 또는 일부에 관한 증명서(이하 “부동산종합증명서”라 한다)를 발급받으려는 자는 지적소관청이나 읍ㆍ면ㆍ동의 장에게 신청할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"등록사항은 지적공부, 건축물대장, 토지이용계획확인서, 개별공시지가ㆍ개별주택가격ㆍ공동주택가격, 부동산등기법 제48조의 권리 사항이다(법 제76조의3, 영 제62조의2). 토지적성평가 확인서는 없다."},{"번호":2,"판정":"옳음","설명":"영구 보존과 별도 복제 관리 정보관리체계 구축은 지적소관청의 의무다(법 제76조의2제2항)."},{"번호":3,"판정":"옳음","설명":"등록사항 관리기관의 장은 지적소관청에 상시적으로 정보를 제공한다(법 제76조의2제3항)."},{"번호":4,"판정":"옳음","설명":"지적소관청이 부동산의 효율적 이용과 정보의 종합적 관리ㆍ운영을 위해 관리ㆍ운영한다(법 제76조의2제1항)."},{"번호":5,"판정":"옳음","설명":"열람과 증명서 발급은 지적소관청이나 읍ㆍ면ㆍ동의 장에게 신청한다(법 제76조의4제1항)."}],"개념":[{"종류":"표","제목":"부동산종합공부 등록사항","머리":["구분","등록 내용","근거"],"행":[["토지의 표시와 소유자","지적공부의 내용","법 제76조의3제1호"],["건축물의 표시와 소유자(건축물이 있는 경우만)","건축물대장의 내용","법 제76조의3제2호"],["토지의 이용 및 규제","토지이용계획확인서의 내용","법 제76조의3제3호"],["부동산의 가격","개별공시지가, 개별주택가격, 공동주택가격 공시내용","법 제76조의3제4호"],["부동산의 권리","부동산등기법 제48조에 따른 권리에 관한 사항","법 제76조의3제5호, 영 제62조의2"]]},{"종류":"표","제목":"부동산종합공부 관리 규정","머리":["항목","내용","근거"],"행":[["관리자","지적소관청이 관리ㆍ운영","법 제76조의2제1항"],["보존","영구 보존, 멸실ㆍ훼손에 대비한 별도 복제 관리 정보관리체계 구축","법 제76조의2제2항"],["정보 제공","등록사항 관리기관의 장은 상시적으로 제공","법 제76조의2제3항"],["자료 제출 요구","정확한 등록ㆍ관리를 위해 필요하면 관리기관의 장에게 요구, 요구받은 기관은 특별한 사유가 없으면 제공","법 제76조의2제4항"],["열람ㆍ증명서 발급","지적소관청이나 읍ㆍ면ㆍ동의 장에게 신청","법 제76조의4제1항"],["등록사항 정정","법 제84조(등록사항의 정정) 준용","법 제76조의5"],["불일치 등록사항","지적소관청이 확인ㆍ관리, 관리기관에 통지해 정정 요청 가능","영 제62조의3"]]}],"함정":"3번의 「제공하여야」와 4항의 「요구할 수 있다」는 서로 다른 조항이다. 관리기관은 상시 제공이 의무이고, 지적소관청의 자료 제출 요구는 필요할 때 하는 재량이다. 5번은 시장ㆍ군수가 아닌 읍ㆍ면ㆍ동의 장도 발급처에 들어간다."},"36회-2차-096":{"한줄":"민법상 조합은 등기 명의인이 될 수 없어 조합원 전원 명의의 합유등기로 한다.","근거":[{"법령":"부동산등기법","조문":"제26조제1항","원문":"종중(宗中), 문중(門中), 그 밖에 대표자나 관리인이 있는 법인 아닌 사단(社團)이나 재단(財團)에 속하는 부동산의 등기에 관하여는 그 사단이나 재단을 등기권리자 또는 등기의무자로 한다."},{"법령":"부동산등기법","조문":"제48조제4항","원문":"제1항제5호의 권리자가 2인 이상인 경우에는 권리자별 지분을 기록하여야 하고 등기할 권리가 합유(合有)인 때에는 그 뜻을 기록하여야 한다."},{"법령":"부동산등기법","조문":"제27조","원문":"등기원인이 발생한 후에 등기권리자 또는 등기의무자에 대하여 상속이나 그 밖의 포괄승계가 있는 경우에는 상속인이나 그 밖의 포괄승계인이 그 등기를 신청할 수 있다."},{"법령":"부동산등기규칙","조문":"제52조제7호","원문":"법 제29조제2호에서 “사건이 등기할 것이 아닌 경우”란 다음 각 호의 어느 하나에 해당하는 경우를 말한다. … 7. 공동상속인 중 일부가 자신의 상속지분만에 대한 상속등기를 신청한 경우"},{"법령":"부동산등기법","조문":"제23조제1항","원문":"등기는 법률에 다른 규정이 없는 경우에는 등기권리자(登記權利者)와 등기의무자(登記義務者)가 공동으로 신청한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"상속지분 일부만의 상속등기 신청은 각하 사유다(규칙 제52조제7호)."},{"번호":2,"판정":"틀림","설명":"단체 명의로 등기할 수 있는 것은 대표자나 관리인이 있는 법인 아닌 사단ㆍ재단이다(법 제26조). 조합은 이에 해당하지 않아 조합원 전원 명의로 합유라는 뜻을 함께 신청ㆍ기록한다(법 제48조제4항, 규칙 제105조제2항)."},{"번호":3,"판정":"옳음","설명":"등기원인 발생 후 권리자에게 상속이 있으면 상속인이 그 등기를 신청한다(법 제27조)."},{"번호":4,"판정":"옳음","설명":"단독신청을 허용하는 규정에 소유권 포기가 없다. 포기에 따른 이전등기는 공동신청 원칙(법 제23조제1항)이 적용된다."},{"번호":5,"판정":"옳음","설명":"변경등기는 권리의 동일성이 유지되는 범위에서만 한다. 층ㆍ방위ㆍ면적이 모두 달라지면 동일한 전세권으로 볼 수 없어 새 설정등기를 한다는 것이 등기실무의 태도다."}],"개념":[{"종류":"표","제목":"단독신청 사유 정리","머리":["사유","단독 신청인","근거"],"행":[["소유권보존등기와 그 말소등기","등기명의인으로 될 자 또는 등기명의인","법 제23조제2항"],["상속, 법인합병 등 포괄승계","등기권리자","법 제23조제3항"],["이행ㆍ인수를 명하는 판결","승소한 등기권리자 또는 등기의무자","법 제23조제4항"],["공유물분할 판결","등기권리자 또는 등기의무자","법 제23조제4항"],["부동산표시의 변경ㆍ경정","소유권의 등기명의인","법 제23조제5항"],["등기명의인표시의 변경ㆍ경정","해당 권리의 등기명의인","법 제23조제6항"],["신탁등기","수탁자","법 제23조제7항"],["수용으로 인한 소유권이전","등기권리자","법 제99조제1항"],["가등기","가등기권리자 (의무자 승낙 또는 가처분명령이 있을 때)","법 제89조"],["가등기 말소","가등기명의인","법 제93조제1항"]]},{"종류":"표","제목":"사건이 등기할 것이 아닌 경우 (각하 사유)","머리":["유형","예"],"행":[["등기능력 없는 물건ㆍ권리","등기할 수 없는 대상에 대한 신청"],["법령 근거 없는 특약","법령에 근거가 없는 특약사항의 등기"],["분리처분 금지 위반","구분건물의 전유부분과 대지사용권을 분리해 처분하는 등기"],["농지의 전세권 설정","농지를 전세권 목적으로 하는 등기"],["저당권의 분리 양도","피담보채권과 분리한 양도, 다른 채권의 담보"],["일부지분 보존등기","일부지분에 대한 소유권보존등기"],["일부 상속인의 자기 지분 상속등기","공동상속인 중 일부가 자기 지분만 신청"],["촉탁 대상 등기를 신청","관공서 또는 법원의 촉탁으로 해야 할 등기를 신청"],["이중 보존","이미 보존등기된 부동산에 다시 보존등기 신청"]]}],"함정":"3번의 「상속인이 등기를 신청」과 1번의 「일부 상속인이 자기 지분만 신청」은 서로 다른 장면이다. 포괄승계인은 피상속인의 지위를 이어 신청하는 것이고, 지분 일부만 상속등기를 하는 것은 규칙 제52조제7호가 각하한다. 2번은 법인 아닌 사단ㆍ재단 규정(법 제26조)을 조합에 잘못 끌어다 쓴 선지다."},"36회-2차-101":{"한줄":"공유자는 자기 지분만 소유권이전등기를 신청할 수 있다.","근거":[{"법령":"부동산등기법","조문":"제67조제1항","원문":"등기관이 소유권의 일부에 관한 이전등기를 할 때에는 이전되는 지분을 기록하여야 한다. 이 경우 등기원인에 「민법」 제268조제1항 단서의 약정이 있을 때에는 그 약정에 관한 사항도 기록하여야 한다."},{"법령":"부동산등기규칙","조문":"제123조","원문":"소유권의 일부에 대한 이전등기를 신청하는 경우에는 이전되는 지분을 신청정보의 내용으로 등기소에 제공하여야 한다."},{"법령":"부동산등기규칙","조문":"제67조제1항","원문":"전자신청은 당사자가 직접 하거나 자격자대리인이 당사자를 대리하여 한다. 다만, 법인 아닌 사단이나 재단은 전자신청을 할 수 없으며, 외국인의 경우에는 다음 각 호의 어느 하나에 해당하는 요건을 갖추어야 한다. 1. 「출입국관리법」 제31조에 따른 외국인등록 2. 「재외동포의 출입국과 법적 지위에 관한 법률」 제6조, 제7조에 따른 국내거소신고"},{"법령":"부동산등기규칙","조문":"제60조제3항","원문":"제1항에 따라 인감증명을 제출하여야 하는 자가 국가 또는 지방자치단체인 경우에는 인감증명을 제출할 필요가 없다."},{"법령":"부동산등기규칙","조문":"제52조제10호","원문":"그 밖에 신청취지 자체에 의하여 법률상 허용될 수 없음이 명백한 등기를 신청한 경우"}],"선지":[{"번호":1,"판정":"옳음","설명":"법인 아닌 사단ㆍ재단은 전자신청을 할 수 없다(규칙 제67조제1항 본문 단서)."},{"번호":2,"판정":"틀림","설명":"소유권 일부(지분)의 이전등기는 이전되는 지분을 신청정보로 제공해 신청한다(법 제67조제1항, 규칙 제123조). 자기 지분만 이전하는 신청이 가능하다."},{"번호":3,"판정":"옳음","설명":"지상권은 토지 전부를 사용하는 권리라 공유지분만을 목적으로 하는 설정등기는 법률상 허용될 수 없음이 명백한 신청이다(규칙 제52조제10호)."},{"번호":4,"판정":"옳음","설명":"외국인은 외국인등록이나 국내거소신고를 갖추어야 전자신청을 할 수 있다(규칙 제67조제1항제1호ㆍ제2호)."},{"번호":5,"판정":"옳음","설명":"국가 또는 지방자치단체는 인감증명을 제출하지 않는다(규칙 제60조제3항)."}],"개념":[{"종류":"비교","제목":"방문신청과 전자신청","왼쪽":{"이름":"방문신청","항목":["신청인 또는 대리인이 등기소에 출석해 서면 제출 (법 제24조제1항제1호)","대리인이 변호사ㆍ법무사이면 사무원을 출석시켜 제출 가능","인감증명 제출 (규칙 제60조)","출석하지 않으면 각하 (법 제29조제4호)","도면은 전자문서로 작성해 송신이 원칙 (규칙 제63조)"]},"오른쪽":{"이름":"전자신청","항목":["전산정보처리조직(애플리케이션 포함)으로 신청정보와 첨부정보 송신 (법 제24조제1항제2호)","당사자가 직접 하거나 자격자대리인이 대리 (규칙 제67조제1항)","법인 아닌 사단ㆍ재단은 불가, 외국인은 외국인등록 또는 국내거소신고 필요","사용자등록 선행, 유효기간 3년 (규칙 제68조, 제69조)","사용자등록번호ㆍ등기필정보를 제공하지 않으면 송신 불가 (규칙 제67조제2항)"]}},{"종류":"표","제목":"인감증명을 제출하는 경우 (방문신청)","머리":["제출 사유","제출자","근거"],"행":[["소유권 등기명의인이 등기의무자로 신청","등기의무자","규칙 제60조제1항제1호"],["소유권 가등기명의인이 가등기 말소 신청","가등기명의인","규칙 제60조제1항제2호"],["소유권 외 권리 명의인이 등기필정보 없이 신청(법 제51조)","등기의무자","규칙 제60조제1항제3호"],["토지합필등기 확인서 첨부","토지소유자들","규칙 제60조제1항제4호"],["토지분필등기 권리자 확인서 첨부","권리자","규칙 제60조제1항제5호"],["협의분할 상속등기","상속인 전원","규칙 제60조제1항제6호"],["제3자의 동의 또는 승낙서 첨부","제3자","규칙 제60조제1항제7호"],["예외","국가ㆍ지방자치단체는 제출하지 않음","규칙 제60조제3항"],["유효기간","발행일부터 3개월 이내","규칙 제62조"]]}],"함정":"1번과 4번은 전자신청 자격을 묻는 선지로 규칙 제67조제1항 하나에서 나온다. 3번의 지분 위 지상권은 소유권 지분 이전과 다르게 설정이 막힌다. 소유권은 지분 단위로 이전할 수 있지만, 지상권 같은 용익권은 지분만을 목적으로 설정할 수 없다."},"36회-2차-117":{"한줄":"소유기간 5년 이상인 토지의 비사업용 토지 기간기준은 직전 5년 중 2년 초과, 직전 3년 중 1년 초과, 소유기간의 100분의 40 초과다.","근거":[{"법령":"소득세법","조문":"제104조의3제1항","원문":"① 제104조제1항제8호에서 \"비사업용 토지\"란 해당 토지를 소유하는 기간 중 대통령령으로 정하는 기간 동안 다음 각 호의 어느 하나에 해당하는 토지를 말한다."},{"법령":"소득세법 시행령","조문":"제168조의6제1호","원문":"법 제104조의3제1항 각 호 외의 부분에서 \"대통령령으로 정하는 기간\"이란 다음 각 호의 어느 하나에 해당하는 기간을 말한다. 이 경우 기간의 계산은 일수로 한다.\n  1. 토지의 소유기간이 5년 이상인 경우에는 다음 각 목의 모두에 해당하는 기간\n    가. 양도일 직전 5년 중 2년을 초과하는 기간\n    나. 양도일 직전 3년 중 1년을 초과하는 기간\n    다. 토지의 소유기간의 100분의 40에 상당하는 기간을 초과하는 기간"}],"선지":[{"번호":1,"판정":"-","설명":"ㄱ 2, ㄴ 1은 맞고 ㄷ이 30이어서 틀리다. 소유기간의 100분의 40이다."},{"번호":2,"판정":"-","설명":"ㄱ 2, ㄴ 1, ㄷ 40이 시행령 제168조의6제1호 가목·나목·다목이다."},{"번호":3,"판정":"-","설명":"ㄱ 3, ㄴ 2, ㄷ 30은 세 칸 모두 틀리다."},{"번호":4,"판정":"-","설명":"ㄷ 40은 맞지만 ㄱ은 3년이 아니라 2년, ㄴ은 2년이 아니라 1년이다."},{"번호":5,"판정":"-","설명":"ㄷ 40은 맞지만 ㄱ은 4년이 아니라 2년, ㄴ은 2년이 아니라 1년이다."}],"개념":[{"종류":"표","제목":"비사업용 토지의 기간기준(소득세법 시행령 제168조의6)","머리":["토지 소유기간","가","나","다"],"행":[["5년 이상","양도일 직전 5년 중 2년 초과","양도일 직전 3년 중 1년 초과","소유기간의 100분의 40 초과"],["3년 이상 5년 미만","소유기간 − 3년 초과","양도일 직전 3년 중 1년 초과","소유기간의 100분의 40 초과"],["3년 미만","소유기간 − 2년 초과(소유기간 2년 미만이면 가목 적용 안 함)","소유기간의 100분의 40 초과","-"],["공통","각 목을 모두 충족하는 기간이어야 하고, 기간은 일수로 계산","-","-"]]},{"종류":"계산","제목":"소유기간 10년 토지의 기간기준 판정(예시)","단계":[{"설명":"가목: 양도일 직전 5년 중 비사업용 사용기간이 2년을 넘는지 본다(비사업용 3년이라 가정)","식":"3년 > 2년","값":"충족"},{"설명":"나목: 양도일 직전 3년 중 비사업용 사용기간이 1년을 넘는지 본다(비사업용 2년이라 가정)","식":"2년 > 1년","값":"충족"},{"설명":"다목: 소유기간 10년의 100분의 40를 구하고, 전체 비사업용 사용기간(4.5년이라 가정)과 비교한다","식":"10년 × 40% = 4년, 4.5년 > 4년","값":"충족"},{"설명":"세 목을 모두 충족하므로 그 기간 동안 비사업용 토지에 해당한다","식":"가 · 나 · 다 모두 충족","값":"비사업용 토지"}]}],"함정":"소유기간 5년 이상 구간의 숫자는 2·1·40이다. 3·2는 3년 미만과 3년 이상 5년 미만 구간의 숫자와 섞이기 쉽고, 30은 어느 구간에도 없다."},"36회-2차-116":{"한줄":"ㄱ은 사업장 소재지 납세지 지정 규정에, ㄹ은 주거용 외 부동산임대업 결손금 불공제 규정에 맞고, 국외 소재 주택 임대소득은 과세되며 광업재단 대여도 부동산임대업이다.","근거":[{"법령":"소득세법","조문":"제9조제1항제1호","원문":"① 국세청장 또는 관할 지방국세청장은 다음 각 호의 어느 하나에 해당하는 경우에는 제6조부터 제8조까지의 규정에도 불구하고 대통령령으로 정하는 바에 따라 납세지를 따로 지정할 수 있다.\n  1. 사업소득이 있는 거주자가 사업장 소재지를 납세지로 신청한 경우"},{"법령":"소득세법","조문":"제12조제2호나목","원문":"다음 각 호의 소득에 대해서는 소득세를 과세하지 아니한다.\n  2. 사업소득 중 다음 각 목의 어느 하나에 해당하는 소득\n    나. 1개의 주택을 소유하는 자의 주택임대소득(제99조에 따른 기준시가가 12억원을 초과하는 주택 및 국외에 소재하는 주택의 임대소득은 제외한다) 또는 해당 과세기간에 대통령령으로 정하는 총수입금액의 합계액이 2천만원 이하인 자의 주택임대소득(2018년 12월 31일 이전에 끝나는 과세기간까지 발생하는 소득으로 한정한다). 이 경우 주택 수의 계산 및 주택임대소득의 산정 등 필요한 사항은 대통령령으로 정한다."},{"법령":"소득세법","조문":"제45조제2항","원문":"② 제1항에도 불구하고 다음 각 호의 어느 하나에 해당하는 사업(이하 \"부동산임대업\"이라 한다)에서 발생한 결손금은 종합소득 과세표준을 계산할 때 공제하지 아니한다. 다만, 주거용 건물 임대업의 경우에는 그러하지 아니하다.\n  1. 부동산 또는 부동산상의 권리를 대여하는 사업\n  2. 공장재단 또는 광업재단을 대여하는 사업\n  3. 채굴에 관한 권리를 대여하는 사업으로서 대통령령으로 정하는 사업"},{"법령":"소득세법","조문":"제45조제3항제2호","원문":"③ 부동산임대업에서 발생한 결손금과 제1항 및 제2항 단서에 따라 공제하고 남은 결손금(이하 \"이월결손금\"이라 한다)은 해당 이월결손금이 발생한 과세기간의 종료일부터 15년 이내에 끝나는 과세기간의 소득금액을 계산할 때 먼저 발생한 과세기간의 이월결손금부터 순서대로 다음 각 호의 구분에 따라 공제한다. 다만, 「국세기본법」 제26조의2에 따른 국세부과의 제척기간이 지난 후에 그 제척기간 이전 과세기간의 이월결손금이 확인된 경우 그 이월결손금은 공제하지 아니한다.\n  2. 부동산임대업에서 발생한 이월결손금은 부동산임대업의 소득금액에서 공제한다."}],"선지":[{"번호":1,"판정":"-","설명":"ㄱ은 옳고 ㄴ이 틀려서 맞는 조합이 아니다."},{"번호":2,"판정":"-","설명":"옳은 것은 ㄱ과 ㄹ이다."},{"번호":3,"판정":"-","설명":"ㄴ과 ㄷ이 모두 틀렸다."},{"번호":4,"판정":"-","설명":"ㄷ이 틀려서 맞는 조합이 아니다."},{"번호":5,"판정":"-","설명":"ㄴ과 ㄷ이 틀렸다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"사업소득이 있는 거주자가 사업장 소재지를 납세지로 신청하면 국세청장 또는 관할지방국세청장이 납세지를 따로 지정할 수 있다(소득세법 제9조제1항제1호). 거주자의 원칙적 납세지는 주소지다(제6조제1항)."},{"기호":"ㄴ","판정":"틀림","설명":"1개 주택 소유자의 주택임대소득은 비과세이지만 기준시가 12억원을 초과하는 주택과 국외에 소재하는 주택의 임대소득은 제외한다. 국외 주택 1개의 임대소득은 과세된다(제12조제2호나목)."},{"기호":"ㄷ","판정":"틀림","설명":"부동산임대업에는 부동산·부동산상의 권리 대여 외에 공장재단 또는 광업재단을 대여하는 사업과 채굴에 관한 권리를 대여하는 사업이 들어간다(제45조제2항제2호·제3호)."},{"기호":"ㄹ","판정":"옳음","설명":"주거용 건물 임대업을 제외한 부동산임대업의 결손금은 종합소득 과세표준 계산에서 공제하지 않는다(제45조제2항). 이월결손금은 15년 이내 부동산임대업의 소득금액에서 공제한다(같은 조 제3항제2호)."}],"개념":[{"종류":"표","제목":"주택임대소득의 과세(소득세법 제12조·제25조, 시행령 제53조·제8조의2)","머리":["소유 주택","임대료(월세)","보증금 간주임대료","비고"],"행":[["국내 1주택(기준시가 12억원 이하)","비과세","해당 없음","제12조제2호나목"],["1주택이라도 기준시가 12억원 초과 또는 국외 소재","과세","해당 없음","제12조제2호나목"],["2주택","과세","기준시가 12억원 이하 주택을 빼고 센 2주택이 되고 보증금 합계가 12억원을 초과할 때","제25조제1항제2호, 시행령 제53조제1항"],["3주택 이상","과세","보증금 합계가 3억원을 초과할 때","제25조제1항제1호"],["소형주택","-","주거전용 40㎡ 이하이면서 기준시가 2억원 이하인 주택은 2026년 12월 31일까지 주택 수에 넣지 않음","제25조제1항 본문"],["주택 수 계산","-","본인과 배우자 합산, 공동소유는 지분이 가장 큰 사람 소유로 계산","시행령 제8조의2제3항"]]},{"종류":"비교","제목":"부동산임대업 결손금의 공제(소득세법 제45조)","왼쪽":{"이름":"주거용 건물 임대업을 제외한 부동산임대업","항목":["그 과세기간의 종합소득 과세표준 계산에서 결손금 공제 안 함(제2항)","이월결손금은 발생 과세기간 종료일부터 15년 이내 부동산임대업 소득금액에서만 공제(제3항제2호)","부동산·부동산상 권리 대여, 공장재단·광업재단 대여, 채굴에 관한 권리 대여 사업 포함"]},"오른쪽":{"이름":"주거용 건물 임대업","항목":["결손금을 그 과세기간의 근로소득금액·연금소득금액·기타소득금액·이자소득금액·배당소득금액에서 순서대로 공제(제1항, 제2항 단서)","공제하고 남은 이월결손금도 15년 이내 다른 소득금액에서 공제(제3항제1호)"]}}],"함정":"ㄴ은 '국외에 소재하는 주택'이 비과세 제외 대상이라는 점을 놓치기 쉽고, ㄷ은 광업재단 대여도 부동산임대업에 들어간다. 주거용 건물 임대업의 결손금만 다른 소득에서 공제된다.","개정":"2주택 소유자의 간주임대료 기준금액 12억원은 시행령 제53조제1항에 있고 <신설 2025.2.28> 표시가 붙어 있다."},"36회-1차-010":{"한줄":"공급함수는 공급량과 그 결정 요인 사이의 관계를 나타낸 함수다.","근거":[{"이론":"수요·공급의 기본 개념","내용":"수요곡선은 한계편익곡선, 공급곡선은 한계비용곡선이다. 수요량은 주어진 가격에서 구입하고자 하는 최대수량이다. 가격 변화로 인한 수요량 변화는 곡선상 이동이고, 가격 이외 요인 변화로 인한 수요 변화는 곡선 자체의 이동이다."}],"선지":[{"번호":1,"판정":"틀림","설명":"수요곡선은 소비자의 한계편익을 나타내는 한계편익곡선이다. 한계비용곡선은 공급곡선이다."},{"번호":2,"판정":"틀림","설명":"수요량은 주어진 가격에서 수요자가 구입하려는 최대수량이다."},{"번호":3,"판정":"틀림","설명":"수요량의 변화는 가격 변화에 따른 수요곡선상 이동이다. 수요곡선 자체의 이동은 수요의 변화다."},{"번호":4,"판정":"틀림","설명":"공급곡선은 공급자의 한계비용을 나타내는 한계비용곡선이다."},{"번호":5,"판정":"옳음","설명":"공급함수는 Qs=f(가격, 생산요소 가격, 기술 등)처럼 공급량과 공급량에 영향을 주는 요인의 관계를 나타낸다."}],"개념":[{"종류":"비교","제목":"수요량의 변화와 수요의 변화","왼쪽":{"이름":"수요량의 변화","항목":["원인: 해당 부동산 가격 변화","수요곡선상의 점 이동","가격 상승 시 수요량 감소"]},"오른쪽":{"이름":"수요의 변화","항목":["원인: 가격 이외 요인(소득·인구·선호·대체재 가격·금리·기대 등)","수요곡선 자체의 좌우 이동","공급도 같은 방식: 공급량 변화는 곡선상 이동, 공급 변화는 곡선 이동"]}},{"종류":"표","제목":"수요곡선과 공급곡선의 경제적 의미","머리":["구분","나타내는 것","기울기","수량의 의미"],"행":[["수요곡선","한계편익","우하향","주어진 가격에서 구입하려는 최대수량"],["공급곡선","한계비용","우상향","주어진 가격에서 공급하려는 최대수량"],["수요함수","수요량과 결정 요인(가격·소득·대체재 가격 등)의 관계","-","-"],["공급함수","공급량과 결정 요인(가격·생산요소 가격·기술 등)의 관계","-","-"]]}],"함정":"한계편익과 한계비용의 짝을 바꾸거나 최대·최소를 바꾼 선지가 반복해서 나온다. 수요량과 수요도 이름이 비슷해 섞어 쓴다. 곡선 자체가 움직이는 것은 수요(공급)의 변화다."},"36회-1차-057":{"한줄":"제187조의 판결은 형성판결만 뜻하므로 이행판결로는 등기 없이 물권변동이 일어나지 않는다.","근거":[{"법령":"민법","조문":"제187조","원문":"상속, 공용징수, 판결, 경매 기타 법률의 규정에 의한 부동산에 관한 물권의 취득은 등기를 요하지 아니한다. 그러나 등기를 하지 아니하면 이를 처분하지 못한다."},{"이론":"건물의 신축","내용":"건물을 신축한 사람은 건물이 완성된 때 보존등기 없이 소유권을 원시취득한다."},{"판례":"대법원 판례(판결과 물권변동)","요지":"제187조의 판결은 형성판결을 말하고, 이행판결이나 확인판결은 포함하지 않는다. 공유물분할판결이 확정되면 등기 없이 물권이 변동한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"상속은 제187조에 따라 등기 없이 소유권을 취득한다."},{"번호":2,"판정":"옳음","설명":"재결수용은 공용징수로서 제187조에 해당한다."},{"번호":3,"판정":"틀림","설명":"이행판결이 확정되어도 승소자는 판결에 따라 등기를 마쳐야 소유권을 취득한다."},{"번호":4,"판정":"옳음","설명":"건물은 신축으로 완성된 때 등기 없이 원시취득한다."},{"번호":5,"판정":"옳음","설명":"공매는 경매와 같이 매각대금을 완납한 때 등기 없이 소유권을 취득한다."}],"개념":[{"종류":"표","제목":"판결의 종류와 물권변동","머리":["판결 종류","물권변동 시기","예"],"행":[["형성판결","판결 확정 시 등기 없이 변동","공유물분할판결"],["이행판결","판결에 따라 등기를 마쳐야 변동","소유권이전등기절차 이행을 명한 판결"],["확인판결","변동을 일으키지 않음","소유권확인판결"],["이행판결 확정 후","승소자가 단독으로 등기를 신청","부동산등기법상 판결에 의한 등기"]]},{"종류":"표","제목":"등기가 필요한 경우와 불필요한 경우","머리":["구분","사례","등기"],"행":[["불필요","상속, 재결수용, 경매·공매, 건물 신축, 형성판결","제187조 본문"],["필요","매매·증여·교환 등 법률행위로 인한 변동","제186조"],["필요","점유취득시효 완성에 따른 소유권 취득","제245조제1항, 등기해야 취득"],["필요","등기 없이 취득한 부동산의 처분","제187조 단서"]]}],"함정":"제187조의 판결은 형성판결뿐이고 이행판결·확인판결은 해당하지 않는다. 점유취득시효가 완성되어도 등기를 마쳐야 소유권을 취득하므로 제187조의 사유와 구별한다."},"36회-1차-064":{"한줄":"채무자의 승낙 없이 유치물 일부를 대여해도 소멸을 청구할 수 있는 범위는 대여한 그 유치물에 한정되고, 유치물 전부에 대한 소멸 청구는 인정되지 않는다.","근거":[{"법령":"민법","조문":"제324조제2·3항","원문":"제324조(유치권자의 선관의무) ②유치권자는 채무자의 승낙없이 유치물의 사용, 대여 또는 담보제공을 하지 못한다. 그러나 유치물의 보존에 필요한 사용은 그러하지 아니하다. ③유치권자가 전2항의 규정에 위반한 때에는 채무자는 유치권의 소멸을 청구할 수 있다."},{"법령":"민법","조문":"제321조","원문":"제321조(유치권의 불가분성) 유치권자는 채권전부의 변제를 받을 때까지 유치물전부에 대하여 그 권리를 행사할 수 있다."},{"판례":"대법원 판례(복수 유치물 중 일부의 대여)","요지":"유치권자가 복수의 유치물 중 일부를 채무자 승낙 없이 대여한 경우 소멸청구의 대상은 대여한 유치물이고, 나머지 유치물의 유치권은 그대로 남는다."},{"법령":"민법","조문":"제204조제1·3항","원문":"제204조(점유의 회수) ①점유자가 점유의 침탈을 당한 때에는 그 물건의 반환 및 손해의 배상을 청구할 수 있다. ③제1항의 청구권은 침탈을 당한 날로부터 1년내에 행사하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"유치권 소멸에 따른 손해배상청구권은 점유회수청구(제204조 제1항)와 별개의 채권이다. 침탈일부터 1년 안에 행사하라는 제한(제204조 제3항)은 점유회수의 소에 붙는 기간이다."},{"번호":2,"판정":"옳음","설명":"유치권은 점유가 있어야 유지되는데, 유치권자가 보관을 맡긴 경우 그 수탁자의 점유로 유치권자의 점유가 이어진다. 소유자의 반환청구를 거부할 수 있다."},{"번호":3,"판정":"옳음","설명":"지상물매수청구권은 전세권이 소멸한 뒤 행사해야 비로소 생기는 청구권이다. 소멸 전에는 변제기에 있는 채권이 없어 유치권이 성립하지 않는다(제320조 제1항)."},{"번호":4,"판정":"옳음","설명":"유치권은 불가분이어서 유치물 각 부분이 채권 전부를 담보한다(제321조)."},{"번호":5,"판정":"틀림","설명":"소멸청구는 제324조 제2항을 위반한 대여 대상 유치물에 한정된다. 나머지 유치물은 불가분성(제321조)에 따라 여전히 채권 전부를 담보하므로 전부에 대한 소멸 청구는 틀리다(제324조 제3항)."}],"개념":[{"종류":"표","제목":"유치권의 성립요건과 소멸","머리":["구분","내용","근거"],"행":[["목적물","타인의 물건 또는 유가증권(동산·부동산)","제320조 제1항"],["견련성","그 물건에 관하여 생긴 채권","제320조 제1항"],["변제기","채권이 변제기에 있을 것","제320조 제1항"],["점유","적법한 점유(불법행위로 시작한 점유는 제외)","제320조 제2항"],["배제특약","당사자 사이 유치권 포기 특약은 유효","판례"],["소멸","점유 상실, 채무자의 소멸청구(선관의무·무단 사용·대여·담보제공 위반), 상당한 담보 제공","제324조 제3항, 제327조, 제328조"]]},{"종류":"비교","제목":"유치권과 저당권","왼쪽":{"이름":"유치권","항목":["법정담보물권, 요건 충족 시 당연 성립","등기 불요, 점유 필요·상실 시 소멸","우선변제권 없음(경매권만 있음)","물상대위 없음","경매로 소멸하지 않고 인도 거절 가능"]},"오른쪽":{"이름":"저당권","항목":["약정담보물권, 설정계약+등기","점유를 넘기지 않음","우선변제권 있음","물상대위 있음(제370조, 제342조)","경매로 소멸"]}}],"함정":"선지 1을 틀렸다고 보기 쉽다. 1년 제한은 점유회수청구에만 걸리고 유치권 소멸에 따른 손해배상청구에는 걸리지 않는다. 선지 5는 불가분성(제321조)을 소멸청구에도 그대로 적용해 전부 소멸로 오해하기 쉽다."},"36회-1차-078":{"한줄":"시효완성 후 등기 전에 명의신탁 해지로 소유권을 이전받은 甲은 시효완성 후의 새 소유자여서, 丙은 특별한 사정이 없으면 甲에게 취득시효를 주장하지 못한다.","근거":[{"법령":"부동산 실권리자명의 등기에 관한 법률","조문":"제8조","원문":"제8조(종중, 배우자 및 종교단체에 대한 특례) 다음 각 호의 어느 하나에 해당하는 경우로서 조세 포탈, 강제집행의 면탈(免脫) 또는 법령상 제한의 회피를 목적으로 하지 아니하는 경우에는 제4조부터 제7조까지 및 제12조제1항부터 제3항까지를 적용하지 아니한다. 1. 종중(宗中)이 보유한 부동산에 관한 물권을 종중(종중과 그 대표자를 같이 표시하여 등기한 경우를 포함한다) 외의 자의 명의로 등기한 경우 2. 배우자 명의로 부동산에 관한 물권을 등기한 경우 3. 종교단체의 명의로 그 산하 조직이 보유한 부동산에 관한 물권을 등기한 경우"},{"법령":"부동산 실권리자명의 등기에 관한 법률","조문":"제4조","원문":"제4조(명의신탁약정의 효력) ① 명의신탁약정은 무효로 한다. ② 명의신탁약정에 따른 등기로 이루어진 부동산에 관한 물권변동은 무효로 한다. 다만, 부동산에 관한 물권을 취득하기 위한 계약에서 명의수탁자가 어느 한쪽 당사자가 되고 상대방 당사자는 명의신탁약정이 있다는 사실을 알지 못한 경우에는 그러하지 아니하다. ③ 제1항 및 제2항의 무효는 제3자에게 대항하지 못한다."},{"판례":"대법원 판례(취득시효 완성 후 소유자 변경)","요지":"점유취득시효가 완성된 뒤 등기를 하기 전에 소유권을 취득한 제3자에게는 특별한 사정이 없으면 시효취득을 주장하지 못한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"배우자 사이의 명의신탁은 조세포탈 등의 목적이 없으면 제4조의 무효 규정이 적용되지 않아 약정이 유효하다(제8조 제2호). 신탁자가 사망해도 약정은 상속인과 수탁자 사이에 존속한다."},{"번호":2,"판정":"옳음","설명":"유효한 명의신탁에서 신탁자는 대내적으로 소유자여서 신탁자가 부동산을 매도하는 계약은 타인 권리의 매매가 아니라는 것이 판례이다."},{"번호":3,"판정":"옳음","설명":"대외적으로는 수탁자 乙이 소유자이므로 신탁자 甲은 제3자 丙에게 직접 소유권을 주장하지 못한다."},{"번호":4,"판정":"옳음","설명":"유효한 명의신탁이므로 신탁자는 해지를 원인으로 수탁자에게 소유권이전등기를 청구할 수 있다."},{"번호":5,"판정":"틀림","설명":"시효 완성 당시 소유자는 대외적 소유자 乙이다. 완성 후 등기 전에 소유권을 이전받은 甲에게 丙은 시효취득을 주장하지 못한다."}],"개념":[{"종류":"표","제목":"명의신탁 유형별 효력","머리":["유형","약정","물권변동","부동산 소유자"],"행":[["2자간 등기명의신탁","무효","무효","신탁자"],["3자간 등기명의신탁(중간생략)","무효","수탁자 명의 등기 무효","매도인"],["계약명의신탁(매도인 선의)","무효","유효(제4조 제2항 단서)","수탁자"],["계약명의신탁(매도인 악의)","무효","무효","매도인"],["종중·배우자·종교단체 특례(조세포탈 등 목적 없음)","유효","유효","수탁자(대외), 신탁자(대내)"]]},{"종류":"비교","제목":"무효인 명의신탁과 특례의 명의신탁","왼쪽":{"이름":"무효인 명의신탁","항목":["약정 무효(제4조 제1항)","등기 물권변동 무효(제4조 제2항)","무효는 제3자에게 대항 못함(제4조 제3항)","신탁자에 대한 과징금·벌칙"]},"오른쪽":{"이름":"특례(제8조)","항목":["종중·배우자·종교단체","조세 포탈·강제집행 면탈·법령상 제한 회피 목적이 없어야 함","제4조~제7조 미적용","약정·등기 모두 유효, 대외적 소유자는 수탁자"]}}],"함정":"문제의 전제인 유효한 명의신탁은 제8조 특례를 뜻한다. 무효인 명의신탁의 법리(신탁자 소유, 부당이득 반환)를 적용하면 안 된다. 선지 5는 취득시효 완성 시점과 소유권 이전 시점의 선후를 따져야 한다."},"36회-2차-023":{"한줄":"설명의 근거자료를 제시하지 않은 개업공인중개사는 500만원 이하 과태료 대상이다(법 제51조제2항제1호의6).","근거":[{"법령":"공인중개사법","조문":"제51조제2항제1호의6","원문":"② 다음 각 호의 어느 하나에 해당하는 자에게는 500만원 이하의 과태료를 부과한다.\n1의6. 제25조제1항을 위반하여 성실ㆍ정확하게 중개대상물의 확인ㆍ설명을 하지 아니하거나 설명의 근거자료를 제시하지 아니한 자"},{"법령":"공인중개사법","조문":"제49조제1항제1호·제2호·제6호의2","원문":"①다음 각 호의 어느 하나에 해당하는 자는 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.\n1. 제7조제1항 또는 제2항을 위반하여 다른 사람에게 자기의 성명을 사용하여 중개업무를 하게 하거나 공인중개사자격증을 양도ㆍ대여한 자 또는 다른 사람의 공인중개사자격증을 양수ㆍ대여받은 자\n2. 제8조의 규정을 위반하여 공인중개사가 아닌 자로서 공인중개사 또는 이와 유사한 명칭을 사용한 자\n6의2. 제18조의2제3항을 위반하여 개업공인중개사가 아닌 자로서 중개업을  하기 위하여 중개대상물에 대한 표시ㆍ광고를 한 자"},{"법령":"공인중개사법","조문":"제48조제1호","원문":"다음 각 호의 어느 하나에 해당하는 자는 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다.\n1. 제9조에 따른 중개사무소의 개설등록을 하지 아니하고 중개업을 한 자"}],"선지":[{"번호":1,"판정":"틀림","설명":"자격증을 대여받은 자는 1년 이하 징역 또는 1천만원 이하 벌금이다(법 제49조제1항제1호)."},{"번호":2,"판정":"틀림","설명":"무등록 중개업은 3년 이하 징역 또는 3천만원 이하 벌금이다(법 제48조제1호)."},{"번호":3,"판정":"틀림","설명":"유사명칭 사용은 1년 이하 징역 또는 1천만원 이하 벌금이다(법 제49조제1항제2호)."},{"번호":4,"판정":"틀림","설명":"개업공인중개사가 아닌 자의 중개대상물 표시·광고는 1년 이하 징역 또는 1천만원 이하 벌금이다(법 제49조제1항제6호의2)."},{"번호":5,"판정":"옳음","설명":"성실·정확한 확인·설명을 하지 않거나 근거자료를 제시하지 않으면 500만원 이하 과태료다(법 제51조제2항제1호의6)."}],"개념":[{"종류":"표","제목":"과태료 부과권자와 대상(법 제51조제5항)","머리":["부과권자","대표 대상","금액 구간"],"행":[["국토교통부장관","거래정보사업자의 운영규정 위반·감독명령 불응, 협회의 공시 누락·개선명령 불이행·검사 거부, 정보통신서비스 제공자의 자료 제출·조치 불이행","500만원 이하"],["시·도지사","연수교육 미이수(제51조제2항제5호의2), 자격증 미반납·사유서 미제출(제51조제3항제6호)","500만원 이하 / 100만원 이하"],["등록관청","부당한 표시·광고, 확인·설명 불성실·근거자료 미제시, 중개보조원 고지의무 위반","500만원 이하"],["등록관청","등록증 미게시, 명칭 문자 미사용, 이전·휴업·폐업 신고 누락, 손해배상책임 미설명, 등록증 미반납","100만원 이하"]]},{"종류":"비교","제목":"형벌이냐 과태료냐","왼쪽":{"이름":"형벌 대상","항목":["개업공인중개사가 아닌 자의 중개대상물 표시·광고","거짓 언행으로 중개의뢰인의 판단을 그르침","초과 보수 수수","자격증 대여·양수"]},"오른쪽":{"이름":"과태료 대상","항목":["개업공인중개사의 존재하지 않는 매물 표시·광고 등 부당한 표시·광고","확인·설명 불성실, 근거자료 미제시","광고에 명시사항을 누락한 표시·광고(100만원 이하)","연수교육 미이수"]}}],"함정":"같은 확인·설명 의무 위반이라도 소속공인중개사는 자격정지, 개업공인중개사는 과태료·업무정지로 처분이 갈린다. 광고도 개업공인중개사가 아닌 자가 하면 형벌, 개업공인중개사가 위반하면 과태료다."},"36회-2차-048":{"한줄":"체육시설법상 사업계획의 승인은 도시혁신계획으로 따로 정할 수 있는 사항으로 열거돼 있지 않다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제83조의3제1항","원문":"① 도시혁신구역에 대하여는 다음 각 호의 법률 규정에도 불구하고 도시혁신계획으로 따로 정할 수 있다. 2. 「주차장법」 제19조에 따른 부설주차장의 설치 3. 「문화예술진흥법」 제9조에 따른 건축물에 대한 미술작품의 설치 5. 「도시공원 및 녹지 등에 관한 법률」 제14조에 따른 도시공원 또는 녹지 확보기준 6. 「학교용지 확보 등에 관한 특례법」 제3조에 따른 학교용지의 조성ㆍ개발 기준"}],"선지":[{"번호":1,"판정":"옳음","설명":"도시공원 또는 녹지 확보기준(「도시공원 및 녹지 등에 관한 법률」 제14조)은 도시혁신계획으로 따로 정할 수 있다(법 제83조의3제1항제5호)."},{"번호":2,"판정":"옳음","설명":"건축물에 대한 미술작품 설치(「문화예술진흥법」 제9조)는 도시혁신계획으로 따로 정할 수 있다(법 제83조의3제1항제3호)."},{"번호":3,"판정":"옳음","설명":"부설주차장 설치(「주차장법」 제19조)는 도시혁신계획으로 따로 정할 수 있다(법 제83조의3제1항제2호)."},{"번호":4,"판정":"옳음","설명":"학교용지 조성·개발 기준(「학교용지 확보 등에 관한 특례법」 제3조)은 도시혁신계획으로 따로 정할 수 있다(법 제83조의3제1항제6호)."},{"번호":5,"판정":"틀림","설명":"「체육시설의 설치·이용에 관한 법률」에 따른 사업계획 승인은 제83조의3제1항 각 호에 없다. 따로 정할 수 있는 사항이 아니다."}],"개념":[{"종류":"표","제목":"도시혁신구역에서 도시혁신계획으로 따로 정할 수 있는 법률 규정","머리":["호","법률 규정","내용"],"행":[["1","주택법 제35조","주택의 배치, 부대시설·복리시설의 설치기준 및 대지조성기준"],["2","주차장법 제19조","부설주차장의 설치"],["3","문화예술진흥법 제9조","건축물에 대한 미술작품의 설치"],["4","건축법 제43조","공개 공지 등의 확보"],["5","도시공원 및 녹지 등에 관한 법률 제14조","도시공원 또는 녹지 확보기준"],["6","학교용지 확보 등에 관한 특례법 제3조","학교용지의 조성·개발 기준"]]},{"종류":"표","제목":"도시혁신구역·복합용도구역·도시·군계획시설입체복합구역","머리":["구분","도시혁신구역","복합용도구역","입체복합구역"],"행":[["조문","제40조의3","제40조의4","제40조의5"],["지정권자","공간재구조화계획 결정권자","공간재구조화계획 결정권자","도시·군관리계획 결정권자"],["지정 대상","도심·부도심 또는 생활권 중심지역, 주요 기반시설과 연계한 거점 지역 등","산업구조 변화로 복합적 토지이용이 필요한 지역, 노후 건축물 밀집 지역 등","도시·군계획시설 준공 후 10년 경과 시설 개량·정비 필요 등"],["계획","도시혁신계획","복합용도계획","건축제한·건폐율·용적률·높이를 대통령령 범위에서 따로 정함"],["특별건축구역","지정된 것으로 봄(제83조의3제2항)","도시혁신구역 규정 준용(제83조의4)","-"],["밀도 한도","-","-","건폐율·용적률 용도지역별 최대한도의 200퍼센트 이하(제40조의5제3항)"]]}],"함정":"완화 대상은 법 제83조의3제1항의 여섯 가지이다. 주택법 제35조와 건축법 제43조도 여기에 들어 있고, 사업계획 승인 같은 인허가 절차는 열거돼 있지 않다.","개정":"제40조의2가 2024.2.6. 삭제됐고, 입지규제최소구역을 대신해 도시혁신구역(제40조의3)과 복합용도구역(제40조의4)이 규정돼 있다."},"36회-2차-057":{"한줄":"환지를 정하지 않은 종전 토지의 권리는 환지처분이 공고된 날이 끝나는 때에 소멸하고 등기 완료와는 무관하다.","근거":[{"법령":"도시개발법","조문":"제42조제1항","원문":"① 환지 계획에서 정하여진 환지는 그 환지처분이 공고된 날의 다음 날부터 종전의 토지로 보며, 환지 계획에서 환지를 정하지 아니한 종전의 토지에 있던 권리는 그 환지처분이 공고된 날이 끝나는 때에 소멸한다."},{"법령":"도시개발법 시행규칙","조문":"제26조제3항제3호","원문":"③ 법 제28조제1항제6호에서 \"국토교통부령으로 정하는 사항\"이란 다음 각 호의 사항을 말한다. 3. 건축 계획(입체 환지를 시행하는 경우로 한정한다)"},{"법령":"도시개발법 시행규칙","조문":"제26조제4항제1호","원문":"평균부담률 = [총사업비/(권리가액의 합계 + 체비지 평가액의 합계)] × 100"},{"법령":"도시개발법","조문":"제31조제1항","원문":"① 시행자는 토지 면적의 규모를 조정할 특별한 필요가 있으면 면적이 작은 토지는 과소(過小) 토지가 되지 아니하도록 면적을 늘려 환지를 정하거나 환지 대상에서 제외할 수 있고, 면적이 넓은 토지는 그 면적을 줄여서 환지를 정할 수 있다."},{"법령":"도시개발법 시행규칙","조문":"제27조제2항제1호","원문":"② 환지의 방식은 다음 각 호와 같이 구분한다. 1. 평면 환지: 환지 전 토지에 대한 권리를 도시개발사업으로 조성되는 토지에 이전하는 방식"}],"선지":[{"번호":1,"판정":"옳음","설명":"입체 환지를 시행하는 경우 환지 계획에 건축 계획이 포함된다(시행규칙 제26조제3항제3호, 법 제28조제1항)."},{"번호":2,"판정":"옳음","설명":"평가식 환지 설계의 평균부담률은 총사업비를 권리가액 합계와 체비지 평가액 합계의 합으로 나눈 값에 100을 곱한다(시행규칙 제26조제4항제1호)."},{"번호":3,"판정":"틀림","설명":"환지를 정하지 않은 종전 토지의 권리는 환지처분이 공고된 날이 끝나는 때에 소멸한다. 소유권이전등기와는 관계가 없다(법 제42조제1항)."},{"번호":4,"판정":"옳음","설명":"면적이 작은 토지는 과소 토지가 되지 않도록 면적을 늘려 환지를 정하거나 환지 대상에서 제외할 수 있다(법 제31조제1항)."},{"번호":5,"판정":"옳음","설명":"평면 환지는 환지 전 토지에 대한 권리를 조성되는 토지에 이전하는 방식이다(시행규칙 제27조제2항제1호)."}],"개념":[{"종류":"흐름","제목":"환지 방식 사업 절차","단계":[{"이름":"환지 계획 작성","설명":"환지 설계, 환지 명세, 청산 대상 토지 명세, 체비지·보류지 명세 등(법 제28조제1항)"},{"이름":"계획 인가","설명":"행정청이 아닌 시행자는 특별자치도지사·시장·군수·구청장의 인가(법 제29조제1항)"},{"이름":"공람·의견","설명":"토지 소유자·임차권자등에게 알리고 공람, 공람 종료일부터 60일 이내 반영 여부 통보(법 제29조제3항·제6항)"},{"이름":"환지 예정지 지정","설명":"지정의 효력 발생일부터 환지처분 공고일까지 환지 예정지에서 종전과 같은 권리 행사(법 제35조, 제36조제1항)"},{"이름":"공사 완료 공고·공람","설명":"공사를 끝낸 뒤 공고하고 관계 서류 공람(법 제40조제1항)"},{"이름":"준공검사·환지처분","설명":"준공검사를 받은 뒤 대통령령으로 정한 기간에 환지처분, 토지 소유자에게 알리고 공고(법 제40조제4항·제5항)"},{"이름":"효과·등기","설명":"공고일이 끝나는 때 권리 소멸, 다음 날 청산금 확정, 공고 후 14일 이내 등기 촉탁·신청(법 제42조, 제43조제1항)"}]},{"종류":"비교","제목":"평면 환지와 입체 환지","왼쪽":{"이름":"평면 환지","항목":["환지 전 토지에 대한 권리를 조성되는 토지에 이전(시행규칙 제27조제2항제1호)","위치는 환지 전 토지의 용도, 보유 기간, 위치, 권리가액, 청산금 규모 등을 고려(같은 조 제4항제1호)"]},"오른쪽":{"이름":"입체 환지","항목":["환지 전 토지나 건축물(무허가 제외)에 대한 권리를 건설되는 구분건축물에 이전(시행규칙 제27조제2항제2호)","토지 소유자 등의 신청에 따라 위치 결정, 같은 신청이 둘 이상이면 보유 기간·거주 기간·권리가액 등 고려(같은 조 제4항제2호)","신청 기간은 통지한 날부터 30일 이상 60일 이하(법 제32조제4항)"]}}],"함정":"효과가 생기는 시점은 환지처분 공고일이다. 환지를 정하지 않은 종전 토지의 권리는 그날이 끝나는 때 소멸하고, 환지는 다음 날부터 종전의 토지로 본다. 등기는 공고 후 14일 이내에 촉탁·신청하는 별개 절차이다."},"36회-2차-064":{"한줄":"대의원회는 총회 권한을 대행하지 못하는 사항 외에는 대행할 수 있고, 사업완료로 인한 조합 해산은 대행 불가 사항에서 빠진다.","근거":[{"법령":"도시 및 주거환경정비법","조문":"제46조제4항","원문":"④ 대의원회는 총회의 의결사항 중 대통령령으로 정하는 사항 외에는 총회의 권한을 대행할 수 있다."},{"법령":"도시 및 주거환경정비법 시행령","조문":"제43조제10호","원문":"10. 제42조제1항제1호에 따른 조합의 합병 또는 해산에 관한 사항. 다만, 사업완료로 인한 해산의 경우는 제외한다."},{"법령":"도시 및 주거환경정비법","조문":"제40조제3항","원문":"③ 조합이 정관을 변경하려는 경우에는 제35조제2항부터 제5항까지의 규정에도 불구하고 총회를 개최하여 조합원 과반수의 찬성으로 시장ㆍ군수등의 인가를 받아야 한다. 다만, 제1항제2호ㆍ제3호ㆍ제4호ㆍ제8호ㆍ제13호 또는 제16호의 경우에는 조합원 3분의 2 이상의 찬성으로 한다."},{"법령":"도시 및 주거환경정비법","조문":"제41조제1항 후단","원문":"① 조합은 조합원으로서 정비구역에 위치한 건축물 또는 토지(재건축사업의 경우에는 건축물과 그 부속토지를 말한다. 이하 이 항에서 같다)를 소유한 자[하나의 건축물 또는 토지의 소유권을 다른 사람과 공유한 경우에는 가장 많은 지분을 소유(2인 이상의 공유자가 가장 많은 지분을 소유한 경우를 포함한다)한 경우로 한정한다] 중 다음 각 호의 어느 하나의 요건을 갖춘 조합장 1명과 이사, 감사를 임원으로 둔다. 이 경우 조합장은 선임일부터 제74조제1항에 따른 관리처분계획인가를 받을 때까지는 해당 정비구역에서 거주(영업을 하는 자의 경우 영업을 말한다. 이하 이 조 및 제43조에서 같다)하여야 한다."},{"법령":"도시 및 주거환경정비법","조문":"제45조제5항제3호","원문":"3. 법인인 토지등소유자가 대리인을 지정하는 경우. 이 경우 법인의 대리인은 조합임원 또는 대의원으로 선임될 수 있다."},{"법령":"도시 및 주거환경정비법 시행령","조문":"제41조제4항","원문":"④ 전문조합관리인의 임기는 3년으로 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"정비사업비의 부담 시기 및 절차는 정관 기재사항 제13호이고, 이를 변경하는 정관 변경은 조합원 3분의 2 이상 찬성이 필요하다(법 제40조제1항제13호, 제3항 단서). 과반수로는 부족하다."},{"번호":2,"판정":"틀림","설명":"법인인 토지등소유자가 지정한 대리인은 조합임원 또는 대의원으로 선임될 수 있다(법 제45조제5항제3호)."},{"번호":3,"판정":"틀림","설명":"조합장의 거주 의무는 선임일부터 관리처분계획인가를 받을 때까지다(법 제41조제1항). 준공인가까지가 아니다."},{"번호":4,"판정":"틀림","설명":"전문조합관리인의 임기는 3년으로 정해져 있다(영 제41조제4항). 시·도 조례로 따로 정하지 않는다."},{"번호":5,"판정":"옳음","설명":"조합의 합병 또는 해산은 대의원회가 대행할 수 없으나, 사업완료로 인한 해산은 제외한다(영 제43조제10호 단서). 사업완료 해산은 대의원회가 총회 권한을 대행한다."}],"개념":[{"종류":"표","제목":"조합 기구별 기준","머리":["구분","기준","근거"],"행":[["조합임원","조합장 1명, 이사 3명 이상, 감사 1명 이상 3명 이하. 토지등소유자 100인 초과 시 이사 5명 이상","법 제41조제1항, 영 제40조"],["조합장 요건","정비구역 건축물·토지 5년 이상 소유, 또는 선임 직전 3년 중 1년 이상 거주","법 제41조제1항"],["조합장 거주의무","선임일부터 관리처분계획인가를 받을 때까지 정비구역에 거주(영업 포함)","법 제41조제1항"],["임기","3년 이하의 범위에서 정관으로 정하고 연임 가능","법 제41조제4항"],["전문조합관리인","임기 3년. 임원 업무를 대행하며 시장·군수등이 선정","법 제41조제5항, 영 제41조제4항"],["대의원회","조합원 100명 이상이면 둔다. 조합원의 10분의 1 이상으로 구성","법 제46조제1항·제2항"],["대의원 자격","조합장이 아닌 조합임원은 대의원이 될 수 없다","법 제46조제3항"]]},{"종류":"표","제목":"대의원회가 총회 권한을 대행할 수 없는 사항(영 제43조)","머리":["호","대행 불가 사항"],"행":[["1","정관의 변경(경미한 변경은 총회 의결사항으로 정한 경우로 한정)"],["2","자금의 차입과 그 방법·이자율 및 상환방법"],["3","예산으로 정한 사항 외에 조합원에게 부담이 되는 계약"],["4","시공자·설계자·감정평가법인등의 선정 및 변경"],["5","정비사업전문관리업자의 선정 및 변경"],["6","조합임원의 선임·해임, 대의원의 선임·해임(임기 중 궐위된 자의 보궐선임은 가능, 조합장은 제외)"],["7","사업시행계획서의 작성 및 변경(경미한 변경 제외)"],["8","관리처분계획의 수립 및 변경(경미한 변경 제외)"],["9","총회에 상정하여야 하는 사항"],["10","조합의 합병 또는 해산(사업완료로 인한 해산은 대행 가능)"],["11","건설되는 건축물의 설계 개요의 변경"],["12","정비사업비의 변경"]]}],"함정":"정관 변경은 과반수 찬성이 원칙이지만 조합원 자격, 제명·탈퇴, 정비구역 위치·면적, 조합의 비용부담·회계, 정비사업비 부담 시기·절차, 시공자·설계자 선정 및 계약서 내용(제2·3·4·8·13·16호)은 3분의 2 이상이다. 조합장 거주 기간은 관리처분계획인가까지이고 준공인가까지가 아니다. 대의원회가 대행하지 못하는 해산에서 사업완료로 인한 해산은 빠진다."},"36회-2차-073":{"한줄":"도지사 승인 대상 용도는 공동주택, 일반음식점, 일반업무시설, 숙박시설, 위락시설이며 공장은 들어 있지 않다.","근거":[{"법령":"건축법","조문":"법 제11조제2항제2호","원문":"② 시장ㆍ군수는 제1항에 따라 다음 각 호의 어느 하나에 해당하는 건축물의 건축을 허가하려면 미리 건축계획서와 국토교통부령으로 정하는 건축물의 용도, 규모 및 형태가 표시된 기본설계도서를 첨부하여 도지사의 승인을 받아야 한다.\n2. 자연환경이나 수질을 보호하기 위하여 도지사가 지정ㆍ공고한 구역에 건축하는 3층 이상 또는 연면적의 합계가 1천제곱미터 이상인 건축물로서 위락시설과 숙박시설 등 대통령령으로 정하는 용도에 해당하는 건축물"},{"법령":"건축법 시행령","조문":"영 제8조제3항","원문":"③ 법 제11조제2항제2호에서 \"위락시설과 숙박시설 등 대통령령으로 정하는 용도에 해당하는 건축물\"이란 다음 각 호의 건축물을 말한다.\n1. 공동주택\n2. 제2종 근린생활시설(일반음식점만 해당한다)\n3. 업무시설(일반업무시설만 해당한다)\n4. 숙박시설\n5. 위락시설"}],"선지":[{"번호":1,"판정":"틀림","설명":"공장은 영 제8조제3항 각 호에 없다. 승인 대상 용도가 아니다."},{"번호":2,"판정":"옳음","설명":"공동주택은 영 제8조제3항제1호의 승인 대상 용도다."},{"번호":3,"판정":"옳음","설명":"위락시설은 영 제8조제3항제5호의 승인 대상 용도다."},{"번호":4,"판정":"옳음","설명":"숙박시설은 영 제8조제3항제4호의 승인 대상 용도다."},{"번호":5,"판정":"옳음","설명":"제2종 근린생활시설은 일반음식점만 대상이다(영 제8조제3항제2호). 일반음식점은 승인 대상 용도에 든다."}],"개념":[{"종류":"표","제목":"건축허가권자와 승인권자(법 제11조, 영 제8조)","머리":["구분","대상","비고"],"행":[["시장·군수·구청장 허가","일반 건축물의 건축·대수선","법 제11조제1항 본문"],["특별시장·광역시장 허가","특별시·광역시에 건축하는 21층 이상 또는 연면적 합계 10만제곱미터 이상 건축물","공장, 창고 제외(영 제8조제1항 단서)"],["도지사 승인(시장·군수가 허가하려는 경우)","21층 이상 또는 연면적 합계 10만제곱미터 이상 건축물","도 조례로 정하는 건축물은 제외(법 제11조제2항제1호)"],["도지사 승인","자연환경·수질 보호를 위해 도지사가 지정·공고한 구역의 3층 이상 또는 연면적 합계 1천제곱미터 이상 건축물로서 공동주택, 일반음식점, 일반업무시설, 숙박시설, 위락시설","법 제11조제2항제2호, 영 제8조제3항"],["도지사 승인","주거환경·교육환경 보호를 위해 도지사가 지정·공고한 구역의 위락시설·숙박시설","법 제11조제2항제3호"]]}],"함정":"승인 대상 용도에는 공장이 없고 일반음식점은 있다. 제2종 근린생활시설 전체가 아니라 일반음식점만, 업무시설도 일반업무시설만 해당한다. 법 조문은 「3층 이상 또는 연면적 합계 1천제곱미터 이상」이다."},"36회-2차-071":{"한줄":"주택상환사채의 납입금은 택지의 구입·조성, 주택건설자재의 구입, 건설공사비 충당 등에 쓸 수 있다.","근거":[{"법령":"주택법 시행령","조문":"영 제87조제1항","원문":"① 주택상환사채의 납입금은 다음 각 호의 용도로만 사용할 수 있다.\n1. 택지의 구입 및 조성\n2. 주택건설자재의 구입\n3. 건설공사비에의 충당\n4. 그 밖에 주택상환을 위하여 필요한 비용으로서 국토교통부장관의 승인을 받은 비용에의 충당"},{"법령":"주택법","조문":"법 제81조제2항","원문":"② 주택상환사채는 기명증권(記名證券)으로 하고, 사채권자의 명의변경은 취득자의 성명과 주소를 사채원부에 기록하는 방법으로 하며, 취득자의 성명을 채권에 기록하지 아니하면 사채발행자 및 제3자에게 대항할 수 없다."},{"법령":"주택법","조문":"법 제82조","원문":"제82조(주택상환사채의 효력) 제8조에 따라 등록사업자의 등록이 말소된 경우에도 등록사업자가 발행한 주택상환사채의 효력에는 영향을 미치지 아니한다."},{"법령":"주택법 시행령","조문":"영 제84조제2항","원문":"② 등록사업자가 발행할 수 있는 주택상환사채의 규모는 최근 3년간의 연평균 주택건설 호수 이내로 한다."},{"법령":"주택법 시행령","조문":"영 제86조제1항","원문":"① 주택상환사채의 상환기간은 3년을 초과할 수 없다."}],"선지":[{"번호":1,"판정":"옳음","설명":"납입금은 택지의 구입 및 조성, 주택건설자재의 구입, 건설공사비 충당, 장관이 승인한 비용에 한해 쓸 수 있다(영 제87조제1항제2호)."},{"번호":2,"판정":"틀림","설명":"주택상환사채는 기명증권으로 한다(법 제81조제2항). 명의변경은 사채원부 기록으로 한다."},{"번호":3,"판정":"틀림","설명":"등록사업자의 등록이 말소되어도 발행한 주택상환사채의 효력에는 영향이 없다(법 제82조)."},{"번호":4,"판정":"틀림","설명":"등록사업자의 발행 규모는 최근 3년간 연평균 주택건설 호수 이내다(영 제84조제2항)."},{"번호":5,"판정":"틀림","설명":"상환기간은 3년을 초과할 수 없다(영 제86조제1항)."}],"개념":[{"종류":"표","제목":"주택상환사채 요약(법 제80조~제83조, 영 제83조~제87조)","머리":["항목","내용"],"행":[["발행자","한국토지주택공사, 등록사업자"],["등록사업자 요건","법인으로서 자본금 5억원 이상, 건설업 등록, 최근 3년간 연평균 주택건설 실적 300호 이상, 금융기관 또는 주택도시보증공사의 보증"],["발행 승인","주택상환사채발행계획을 수립해 국토교통부장관의 승인"],["발행 규모","등록사업자는 최근 3년간 연평균 주택건설 호수 이내"],["증권 형태","기명증권. 명의변경은 취득자의 성명·주소를 사채원부에 기록"],["상환기간","3년 초과 불가. 발행일부터 주택 공급계약 체결일까지"],["양도·해약","양도하거나 중도에 해약 불가. 해외이주 등 국토교통부령이 정한 부득이한 사유는 예외"],["납입금 용도","택지 구입·조성, 주택건설자재 구입, 건설공사비 충당, 장관 승인 비용"],["등록 말소","등록이 말소되어도 주택상환사채의 효력에 영향 없음"]]},{"종류":"흐름","제목":"주택상환사채 발행 절차","단계":[{"이름":"발행계획 수립·승인 신청","설명":"발행계획서에 택지 권리 증명서류, 금융기관 또는 주택도시보증공사의 보증서를 첨부해 국토교통부장관에게 제출한다. 발행대행계약서와 납입금 관리계약서는 모집공고 전까지 제출할 수 있다(영 제85조제1항)."},{"이름":"승인·통보","설명":"국토교통부장관이 승인하고 발행 대상지역 관할 시·도지사에게 통보한다(영 제85조제3항)."},{"이름":"모집공고","설명":"모집 전에 모집공고안을 작성해 국토교통부장관에게 제출한다(영 제85조제4항)."},{"이름":"발행·납입금 관리","설명":"액면 또는 할인 방법으로 발행하고 주택상환사채대장을 갖춘다. 납입금은 보증기관과 협의한 금융기관이 관리한다(영 제83조, 제87조제2항)."},{"이름":"상환","설명":"발행조건에 따라 주택을 건설해 사채권자에게 상환한다(법 제81조제1항)."}]}],"함정":"상환기간(3년), 발행 규모의 기준 기간(3년), 증권 형태(기명증권)가 선지에서 바뀌어 나온다. 등록이 말소되어도 사채의 효력은 유지된다."},"36회-2차-067":{"한줄":"사업주체가 품질점검단의 점검에 따르지 않거나 기피·방해하면 2천만원 이하의 과태료 대상이다.","근거":[{"법령":"주택법","조문":"법 제48조의3제3항","원문":"③ 사업주체는 제2항에 따른 품질점검단의 점검에 협조하여야 하며 이에 따르지 아니하거나 기피 또는 방해해서는 아니 된다."},{"법령":"주택법","조문":"법 제106조제1항제2호","원문":"① 다음 각 호의 어느 하나에 해당하는 자에게는 2천만원 이하의 과태료를 부과한다.\n2. 제48조의3제3항을 위반하여 점검에 따르지 아니하거나 기피 또는 방해한 자"},{"법령":"주택법","조문":"법 제48조의3제1항·제5항","원문":"① 시ㆍ도지사는 제48조의2에 따른 사전방문을 실시하고 제49조제1항에 따른 사용검사를 신청하기 전에 공동주택의 품질을 점검하여 사업계획의 내용에 적합한 공동주택이 건설되도록 할 목적으로 주택 관련 분야 등의 전문가로 구성된 공동주택 품질점검단(이하 \"품질점검단\"이라 한다)을 설치ㆍ운영할 수 있다. 이 경우 시ㆍ도지사는 품질점검단의 설치ㆍ운영에 관한 사항을 조례로 정하는 바에 따라 대도시 시장에게 위임할 수 있다.\n⑤ 사용검사권자는 제2항에 따라 제출받은 점검결과를 제49조제1항에 따른 사용검사가 있은 날부터 2년 이상 보관하여야 하며, 입주자(입주예정자를 포함한다)가 관련 자료의 공개를 요구하는 경우에는 이를 공개하여야 한다."},{"법령":"주택법 시행규칙","조문":"규칙 제20조의4제5항","원문":"⑤ 품질점검단은 품질점검을 실시한 후 점검 종료일부터 5일 이내에 점검결과를 시ㆍ도지사와 사용검사권자에게 제출해야 한다."},{"법령":"주택법 시행령","조문":"영 제53조의4제1항제8호","원문":"8. 공무원으로서 공동주택 관련 지도ㆍ감독 및 인ㆍ허가 업무 등에 종사한 경력이 5년 이상인 사람"}],"선지":[{"번호":1,"판정":"틀림","설명":"품질점검단은 시·도지사가 설치·운영한다. 시·도지사는 조례로 대도시 시장에게 위임할 수 있다(법 제48조의3제1항)."},{"번호":2,"판정":"옳음","설명":"점검에 따르지 않거나 기피 또는 방해한 사업주체에게는 2천만원 이하의 과태료를 부과한다(법 제106조제1항제2호, 제48조의3제3항)."},{"번호":3,"판정":"틀림","설명":"품질점검단은 점검 종료일부터 5일 이내에 결과를 시·도지사와 사용검사권자에게 제출한다(규칙 제20조의4제5항)."},{"번호":4,"판정":"틀림","설명":"사용검사권자는 점검결과를 사용검사가 있은 날부터 2년 이상 보관한다(법 제48조의3제5항)."},{"번호":5,"판정":"틀림","설명":"공무원 출신 위원은 공동주택 관련 지도·감독 및 인·허가 업무 등에 종사한 경력이 5년 이상이어야 한다(영 제53조의4제1항제8호)."}],"개념":[{"종류":"표","제목":"공동주택 품질점검단 요약","머리":["항목","내용","근거"],"행":[["설치·운영","시·도지사. 조례로 대도시 시장에게 위임 가능","법 제48조의3제1항"],["점검 대상","공동주택 중 등록사업자 등이 건설하는 300세대 이상. 시·도지사가 필요하다고 인정하면 조례로 300세대 미만도 가능","영 제53조의5제1항"],["점검 사항","공용부분, 일부 세대의 전유부분(3세대 이상 선정), 사용검사권자가 자문 요청한 현장조사 사항","영 제53조의5제2항, 규칙 제20조의4제4항"],["결과 제출","점검 종료일부터 5일 이내에 시·도지사와 사용검사권자에게","규칙 제20조의4제5항"],["결과 보관","사용검사가 있은 날부터 2년 이상. 입주자가 요구하면 공개","법 제48조의3제5항"],["위원 임기","공무원이 아닌 위원은 2년, 두 차례만 연임","영 제53조의4제2항"],["사업주체 협조 위반","점검에 따르지 않거나 기피·방해: 2천만원 이하 과태료. 조치명령 불이행: 1천만원 이하 과태료","법 제106조"]]},{"종류":"흐름","제목":"품질점검부터 조치명령까지","단계":[{"이름":"점검 요청","설명":"사업주체의 사전방문계획을 받은 사용검사권자가 대상 공동주택이면 지체 없이 시·도지사에게 품질점검을 요청한다(규칙 제20조의4제1항)."},{"이름":"점검계획 통보","설명":"시·도지사는 점검 시작일 7일 전까지 사용검사권자와 사업주체에게 통보한다(규칙 제20조의4제3항)."},{"이름":"점검 실시","설명":"사전방문기간 종료일부터 10일 이내에 점검한다(규칙 제20조의4제2항)."},{"이름":"결과 제출","설명":"점검 종료일부터 5일 이내에 제출한다(규칙 제20조의4제5항)."},{"이름":"사업주체 의견","설명":"사용검사권자가 점검결과를 사업주체에 즉시 통보하고, 사업주체는 통보일부터 5일 이내에 의견을 낼 수 있다(영 제53조의6제1항·제2항)."},{"이름":"조치명령","설명":"하자로 판단하면 의견 제출일부터 5일 이내에 보수·보강 등을 명한다(영 제53조의6제3항)."}]}],"함정":"설치 주체는 시장·군수·구청장이 아니라 시·도지사다. 결과 제출 5일, 결과 보관 2년, 공무원 경력 5년이 선지에서 3일, 3년, 4년으로 바뀌어 나온다. 과태료는 점검 기피·방해에 부과하고 상한은 2천만원이다."},"36회-2차-080":{"한줄":"성토 면적 1천제곱미터 이하, 성토 높이 50센티미터 이내이면 농지개량행위 신고를 하지 않아도 된다.","근거":[{"법령":"농지법 시행령","조문":"영 제59조의2","원문":"제59조의2(신고를 하지 않아도 되는 경미한 행위) 법 제41조의3제1항제4호에서 \"대통령령으로 정하는 경미한 행위\"란 다음 각 호의 어느 하나에 해당하는 행위를 말한다. 다만, 다음 각 호의 범위에서 시ㆍ군ㆍ자치구의 조례로 따로 정하는 경우에는 그에 따른다.\n1. 면적(성토가 이루어지는 해당 필지의 총면적을 말한다) 1천제곱미터 이하인 농지에 대한 성토\n2. 면적(절토가 이루어지는 해당 필지의 총면적을 말한다) 1천제곱미터 이하인 농지에 대한 절토\n3. 높이(성토가 이루어지는 해당 필지에서 최근 1년간 성토한 높이를 합산한 것을 말한다) 50센티미터 이내의 성토\n4. 깊이(절토가 이루어지는 해당 필지에서 최근 1년간 절토한 깊이를 합산한 것을 말한다) 50센티미터 이내의 절토"},{"법령":"농지법","조문":"법 제41조의3제1항","원문":"① 농지를 개량하려는 자 중 성토 또는 절토를 하려는 자는 농림축산식품부령으로 정하는 바에 따라 시장ㆍ군수 또는 자치구구청장에게 신고하여야 하며, 신고한 사항을 변경하려는 경우에도 또한 같다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 그러하지 아니하다.\n4. 대통령령으로 정하는 경미한 행위인 경우"}],"선지":[{"번호":1,"판정":"-","설명":"ㄱ은 1천제곱미터, ㄴ은 50센티미터다. 영 제59조의2제1호·제3호와 일치하는 조합이다."},{"번호":2,"판정":"-","설명":"ㄱ 1천제곱미터는 맞으나 ㄴ이 60센티미터가 아니라 50센티미터다(영 제59조의2제3호)."},{"번호":3,"판정":"-","설명":"ㄱ이 3천제곱미터가 아니라 1천제곱미터다(영 제59조의2제1호). ㄴ 50센티미터만 맞다."},{"번호":4,"판정":"-","설명":"ㄱ이 3천제곱미터가 아니라 1천제곱미터이고 ㄴ이 60센티미터가 아니라 50센티미터다. 둘 다 틀렸다."},{"번호":5,"판정":"-","설명":"ㄱ이 3천제곱미터가 아니라 1천제곱미터이고 ㄴ이 70센티미터가 아니라 50센티미터다. 둘 다 틀렸다."}],"개념":[{"종류":"비교","제목":"신고하지 않아도 되는 경미한 행위(영 제59조의2)","왼쪽":{"이름":"성토","항목":["면적: 성토가 이루어지는 해당 필지의 총면적 1천제곱미터 이하","높이: 해당 필지에서 최근 1년간 성토한 높이를 합산해 50센티미터 이내"]},"오른쪽":{"이름":"절토","항목":["면적: 절토가 이루어지는 해당 필지의 총면적 1천제곱미터 이하","깊이: 해당 필지에서 최근 1년간 절토한 깊이를 합산해 50센티미터 이내"]}},{"종류":"표","제목":"농지개량행위 신고 제도(법 제41조의3 등)","머리":["항목","내용","근거"],"행":[["신고 대상","농지를 개량하려는 자 중 성토 또는 절토를 하려는 자. 변경할 때도 신고","법 제41조의3제1항"],["신고 면제","개발행위허가를 받은 경우, 국가·지방자치단체의 공익사업, 재해복구·재난수습 응급조치, 경미한 행위","법 제41조의3제1항 각 호"],["신고 서류","사업계획서, 소유권 또는 사용권 입증서류, 농지개량 기준에 적합한 흙임을 증명하는 서류(성토의 경우)","규칙 제52조의3제1항"],["수리","내용을 검토해 이 법에 적합하면 신고를 수리","법 제41조의3제2항"],["위반 시 원상회복","신고 없이 성토·절토하면 원상회복명령, 불이행 시 대집행","법 제42조"],["위반 시 벌칙","3년 이하의 징역 또는 3천만원 이하의 벌금(신고·변경신고 위반, 농지개량 기준 위반)","법 제60조제4호·제5호"]]}],"함정":"면적 기준은 1천제곱미터, 높이·깊이 기준은 50센티미터다. 성토와 절토는 같은 숫자를 쓴다. 높이는 필지에서 최근 1년간 합산한 값이다. 시·군·자치구 조례로 달리 정할 수 있으나 이 문항은 조례를 고려하지 않는다."},"36회-2차-084":{"한줄":"축척 600분의 1 지역은 면적을 0.1m² 단위로 정하고, 0.05m²를 넘는 끝수는 올리므로 928.651m²는 928.7m²다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제60조제1항제2호","원문":"2. 지적도의 축척이 600분의 1인 지역과 경계점좌표등록부에 등록하는 지역의 토지 면적은 제1호에도 불구하고 제곱미터 이하 한 자리 단위로 하되, 0.1제곱미터 미만의 끝수가 있는 경우 0.05제곱미터 미만일 때에는 버리고 0.05제곱미터를 초과할 때에는 올리며, 0.05제곱미터일 때에는 구하려는 끝자리의 숫자가 0 또는 짝수이면 버리고 홀수이면 올린다. 다만, 1필지의 면적이 0.1제곱미터 미만일 때에는 0.1제곱미터로 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제60조제1항제1호","원문":"1. 토지의 면적에 1제곱미터 미만의 끝수가 있는 경우 0.5제곱미터 미만일 때에는 버리고 0.5제곱미터를 초과하는 때에는 올리며, 0.5제곱미터일 때에는 구하려는 끝자리의 숫자가 0 또는 짝수이면 버리고 홀수이면 올린다. 다만, 1필지의 면적이 1제곱미터 미만일 때에는 1제곱미터로 한다."}],"선지":[{"번호":1,"판정":"-","설명":"소수점 이하를 모두 버린 값이다. 이 지역의 등록 단위는 0.1m²다."},{"번호":2,"판정":"-","설명":"끝수 0.051m²를 버린 값이다. 0.05m²를 초과하므로 올려야 한다."},{"번호":3,"판정":"-","설명":"소수 둘째 자리까지 쓴 값이다. 등록 면적은 소수 한 자리다."},{"번호":4,"판정":"-","설명":"0.1m² 미만 끝수 0.051m²가 0.05m²를 초과하여 올린 값이다."},{"번호":5,"판정":"-","설명":"1m² 단위로 올린 값이다. 일반 지역의 처리 방법이고 600분의 1 지역에는 쓰지 않는다."}],"개념":[{"종류":"표","제목":"면적 단위와 끝수 처리 (영 제60조제1항)","머리":["지역","등록 단위","끝수 처리","최소 면적"],"행":[["일반 지역","1m²","0.5m² 미만 버림, 0.5m² 초과 올림, 0.5m²는 앞자리가 0 또는 짝수면 버림, 홀수면 올림","1m² 미만이면 1m²"],["축척 600분의 1 지역","0.1m²","0.05m² 미만 버림, 0.05m² 초과 올림, 0.05m²는 앞자리가 0 또는 짝수면 버림, 홀수면 올림","0.1m² 미만이면 0.1m²"],["경계점좌표등록부 시행 지역","0.1m²","600분의 1 지역과 같다","0.1m² 미만이면 0.1m²"],["방위각ㆍ종횡선 수치ㆍ거리 계산","구하려는 끝자리","다음 숫자가 5 미만이면 버림, 5 초과면 올림, 5이면 앞자리가 0 또는 짝수면 버림, 홀수면 올림","-"]]},{"종류":"계산","제목":"928.651m²의 끝수 처리","단계":[{"설명":"적용 규정 선택","식":"600분의 1 지역 → 0.1m² 단위","값":"영 제60조제1항제2호"},{"설명":"0.1m² 미만 끝수 구하기","식":"928.651 − 928.6","값":"0.051m²"},{"설명":"끝수와 0.05m² 비교","식":"0.051 > 0.05","값":"올림"},{"설명":"등록 면적","식":"928.6 + 0.1","값":"928.7m²"}]}],"함정":"일반 지역의 1m² 단위 규칙을 적용하면 929m²(⑤)가 나온다. 축척 600분의 1이라는 조건에서 0.1m² 단위 규칙으로 갈아타야 한다. 끝수 0.051은 0.05를 넘으므로 928.6(②)에서 멈추면 안 된다."},"36회-2차-099":{"한줄":"승역지에 지역권설정의 등기를 할 때 기록하는 사항은 법 제48조제1항제1호~제4호와 제70조 각 호이고, 권리자(지역권자)는 포함되지 않는다.","근거":[{"법령":"부동산등기법","조문":"제70조","원문":"제70조(지역권의 등기사항) 등기관이 승역지의 등기기록에 지역권설정의 등기를 할 때에는 제48조제1항제1호부터 제4호까지에서 규정한 사항 외에 다음 각 호의 사항을 기록하여야 한다. 다만, 제4호는 등기원인에 그 약정이 있는 경우에만 기록한다.\n  1. 지역권설정의 목적\n  2. 범위\n  3. 요역지\n  4. 「민법」 제292조제1항 단서, 제297조제1항 단서 또는 제298조의 약정\n  5. 승역지의 일부에 지역권설정의 등기를 할 때에는 그 부분을 표시한 도면의 번호"},{"법령":"부동산등기법","조문":"제48조제1항","원문":"① 등기관이 갑구 또는 을구에 권리에 관한 등기를 할 때에는 다음 각 호의 사항을 기록하여야 한다.\n  1. 순위번호\n  2. 등기목적\n  3. 접수연월일 및 접수번호\n  4. 등기원인 및 그 연월일\n  5. 권리자"},{"법령":"부동산등기법","조문":"제71조제1항","원문":"① 등기관이 승역지에 지역권설정의 등기를 하였을 때에는 직권으로 요역지의 등기기록에 다음 각 호의 사항을 기록하여야 한다.\n  1. 순위번호\n  2. 등기목적\n  3. 승역지\n  4. 지역권설정의 목적\n  5. 범위\n  6. 등기연월일"}],"선지":[{"번호":1,"판정":"-","설명":"범위는 승역지에 기록할 사항이다(법 제70조제2호)."},{"번호":2,"판정":"-","설명":"요역지는 승역지에 기록할 사항이다(법 제70조제3호)."},{"번호":3,"판정":"-","설명":"법 제70조는 제48조제1항 중 제1호~제4호만 끌어오고 제5호 권리자는 제외한다. 승역지에는 지역권자를 기록하지 않는다."},{"번호":4,"판정":"-","설명":"지역권설정의 목적은 승역지에 기록할 사항이다(법 제70조제1호)."},{"번호":5,"판정":"-","설명":"등기원인 및 그 연월일은 제48조제1항제4호에 따라 기록한다."}],"개념":[{"종류":"비교","제목":"승역지와 요역지의 지역권 기록사항","왼쪽":{"이름":"승역지 등기기록 (설정등기, 법 제70조)","항목":["순위번호, 등기목적, 접수연월일ㆍ접수번호, 등기원인 및 그 연월일 (제48조제1항제1호~제4호)","지역권설정의 목적","범위","요역지","민법 제292조제1항 단서, 제297조제1항 단서, 제298조의 약정(그 약정이 있는 경우에만)","승역지 일부이면 그 부분을 표시한 도면의 번호"]},"오른쪽":{"이름":"요역지 등기기록 (직권, 법 제71조)","항목":["순위번호","등기목적","승역지","지역권설정의 목적","범위","등기연월일","승역지에 지역권 변경ㆍ말소의 등기를 하면 직권으로 요역지에 변경ㆍ말소의 등기"]}},{"종류":"표","제목":"용익권ㆍ담보권의 등기사항 (제48조 사항 외)","머리":["권리","반드시 기록","약정이 있는 경우에만 기록"],"행":[["지상권 (법 제69조)","설정의 목적, 범위","존속기간, 지료와 지급시기, 민법 제289조의2제1항 후단의 약정"],["지역권 승역지 (법 제70조)","설정의 목적, 범위, 요역지","민법 제292조제1항 단서, 제297조제1항 단서, 제298조의 약정"],["전세권 (법 제72조)","전세금, 범위","존속기간, 위약금 또는 배상금, 민법 제306조 단서의 약정"],["임차권 (법 제74조)","차임, 범위","차임지급시기, 존속기간, 임차보증금, 양도 또는 전대에 대한 임대인의 동의"],["저당권 (법 제75조제1항)","채권액, 채무자","변제기, 이자와 발생기ㆍ지급시기, 원본ㆍ이자 지급장소, 손해배상 약정, 민법 제358조 단서의 약정, 채권의 조건"],["근저당권 (법 제75조제2항)","채권의 최고액, 채무자","민법 제358조 단서의 약정, 존속기간"]]}],"함정":"법 제70조는 제48조제1항 중 제1호~제4호만 끌어오므로 제5호 권리자는 승역지 기록사항이 아니다. 승역지에는 요역지를, 요역지에는 승역지를 기록한다."},"36회-2차-105":{"한줄":"건축물에 대한 지역자원시설세는 취득하는 때가 아니라 과세기준일에 납세의무가 성립한다.","근거":[{"법령":"지방세기본법","조문":"제34조제1항제10호아목","원문":"건축물 및 선박: 과세기준일"},{"법령":"지방세기본법","조문":"제34조제1항제2호가목","원문":"등록에 대한 등록면허세: 재산권과 그 밖의 권리를 등기하거나 등록하는 때"},{"법령":"지방세기본법","조문":"제34조제1항제8호","원문":"재산세: 과세기준일"},{"법령":"국세기본법","조문":"제21조제2항제1호","원문":"소득세ㆍ법인세: 과세기간이 끝나는 때."},{"법령":"국세기본법","조문":"제21조제2항제10호","원문":"종합부동산세: 과세기준일"}],"선지":[{"번호":1,"판정":"옳음","설명":"양도소득세는 소득세이므로 과세기간이 끝나는 때 성립한다(국세기본법 제21조 제2항 제1호)."},{"번호":2,"판정":"옳음","설명":"종합부동산세는 과세기준일(6월 1일)에 성립한다(국세기본법 제21조 제2항 제10호, 종합부동산세법 제3조)."},{"번호":3,"판정":"옳음","설명":"등록에 대한 등록면허세는 재산권과 그 밖의 권리를 등기하거나 등록하는 때 성립한다. 전세권설정등기도 같다(지방세기본법 제34조 제1항 제2호 가목)."},{"번호":4,"판정":"옳음","설명":"재산세는 과세기준일에 성립한다(지방세기본법 제34조 제1항 제8호)."},{"번호":5,"판정":"틀림","설명":"지역자원시설세 중 건축물 및 선박분은 과세기준일에 성립한다. 취득하는 때에 성립하는 세목은 취득세다(지방세기본법 제34조 제1항 제1호·제10호 아목)."}],"개념":[{"종류":"표","제목":"세목별 납세의무 성립시기","머리":["세목","성립시기","근거"],"행":[["소득세(양도소득세 포함)·법인세","과세기간이 끝나는 때","국세기본법 제21조제2항제1호"],["종합부동산세","과세기준일","국세기본법 제21조제2항제10호"],["상속세 / 증여세","상속이 개시되는 때 / 증여로 재산을 취득하는 때","국세기본법 제21조제2항제2·3호"],["취득세","과세물건을 취득하는 때","지방세기본법 제34조제1항제1호"],["등록면허세(등록)","재산권과 그 밖의 권리를 등기하거나 등록하는 때","지방세기본법 제34조제1항제2호가목"],["재산세","과세기준일","지방세기본법 제34조제1항제8호"],["지역자원시설세(건축물·선박)","과세기준일","지방세기본법 제34조제1항제10호아목"],["지방교육세","과세표준이 되는 세목의 납세의무가 성립하는 때","지방세기본법 제34조제1항제11호"],["지방소득세","소득세·법인세의 납세의무가 성립하는 때","지방세기본법 제34조제1항제7호"],["자동차세(소유)","납기가 있는 달의 1일","지방세기본법 제34조제1항제9호가목"]]},{"종류":"표","제목":"일반 성립시기의 예외","머리":["구분","성립시기","근거"],"행":[["원천징수하는 소득세·법인세","소득금액 또는 수입금액을 지급하는 때","국세기본법 제21조제3항제1호"],["예정신고납부하는 소득세","과세표준이 되는 금액이 발생한 달의 말일","국세기본법 제21조제3항제2호"],["중간예납하는 소득세·법인세","중간예납기간이 끝나는 때","국세기본법 제21조제3항제3호"],["수시부과하는 국세","수시부과할 사유가 발생한 때","국세기본법 제21조제3항제4호"],["특별징수하는 지방소득세","소득세·법인세를 원천징수하는 때","지방세기본법 제34조제2항제1호"],["수시로 부과하는 지방세","수시부과할 사유가 발생하는 때","지방세기본법 제34조제2항제2호"]]}],"함정":"지역자원시설세 건축물·선박분은 취득이 아니라 보유를 과세요건으로 삼아 과세기준일에 성립한다. 양도소득세는 양도일이 아니라 과세기간이 끝나는 때(12월 31일)에 성립하고, 예정신고납부분만 과세표준 금액이 발생한 달의 말일에 성립한다."},"36회-2차-118":{"한줄":"소송비용이 이미 그 지출한 연도의 필요경비에 산입되었다면 자본적지출액 등에서 뺀다.","근거":[{"법령":"소득세법 시행령","조문":"제163조제3항제2호","원문":"양도자산을 취득한 후 쟁송이 있는 경우에 그 소유권을 확보하기 위하여 직접 소요된 소송비용ㆍ화해비용 등의 금액으로서 그 지출한 연도의 각 소득금액의 계산에 있어서 필요경비에 산입된 것을 제외한 금액"},{"법령":"소득세법 시행령","조문":"제163조제5항제1호라목","원문":"매매계약에 따른 인도의무를 이행하기 위하여 양도자가 지출하는 명도비용"},{"법령":"소득세법 시행령","조문":"제163조제1항제3호","원문":"제1호를 적용할 때 당사자 약정에 의한 대금지급방법에 따라 취득원가에 이자상당액을 가산하여 거래가액을 확정하는 경우 당해 이자상당액은 취득원가에 포함한다. 다만, 당초 약정에 의한 거래가액의 지급기일의 지연으로 인하여 추가로 발생하는 이자상당액은 취득원가에 포함하지 아니한다."},{"법령":"소득세법 시행령","조문":"제163조제3항제3호의3","원문":"「재건축초과이익 환수에 관한 법률」에 따른 재건축부담금(재건축부담금의 납부의무자와 양도자가 서로 다른 경우에는 양도자에게 사실상 배분될 재건축부담금상당액을 말한다)"},{"법령":"소득세법 시행령","조문":"제163조제5항제2호","원문":"법 제94조제1항제1호의 자산을 취득함에 있어서 법령등의 규정에 따라 매입한 국민주택채권 및 토지개발채권을 만기전에 양도함으로써 발생하는 매각차손. 이 경우 재정경제부령으로 정하는 금융기관(이하 이 호에서 \"금융기관\"이라 한다) 외의 자에게 양도한 경우에는 동일한 날에 금융기관에 양도하였을 경우 발생하는 매각차손을 한도로 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"소송비용 등은 그 지출한 연도의 각 소득금액 계산에서 필요경비에 산입된 금액을 제외한 금액이 자본적지출액 등이다(소득세법 시행령 제163조 제3항 제2호)."},{"번호":2,"판정":"옳음","설명":"매매계약에 따른 인도의무를 이행하기 위한 명도비용은 양도비 등이다(소득세법 시행령 제163조 제5항 제1호 라목)."},{"번호":3,"판정":"옳음","설명":"약정한 대금지급방법에 따른 이자상당액은 취득원가에 포함하고, 지급기일 지연으로 추가 발생한 이자상당액은 포함하지 않는다(소득세법 시행령 제163조 제1항 제3호)."},{"번호":4,"판정":"옳음","설명":"재건축부담금은 자본적지출액 등에 해당한다. 납부의무자와 양도자가 다르면 양도자에게 사실상 배분될 금액을 말한다(소득세법 시행령 제163조 제3항 제3호의3)."},{"번호":5,"판정":"옳음","설명":"토지 취득 때 매입한 국민주택채권·토지개발채권을 만기 전에 금융기관에 양도한 매각차손은 양도비 등이다(소득세법 시행령 제163조 제5항 제2호)."}],"개념":[{"종류":"표","제목":"자본적지출액 등과 양도비 등(소득세법 시행령 제163조 제3항·제5항)","머리":["구분","해당","주의"],"행":[["자본적지출액 등","용도변경·개량·이용편의 비용(재건축 철거비용 포함)","재해·노후화 등 부득이한 사유의 재건축 철거비용"],["자본적지출액 등","취득 후 소유권 확보 소송비용·화해비용","그 지출한 연도의 필요경비에 산입된 금액은 제외"],["자본적지출액 등","개발부담금, 재건축부담금","납부의무자와 양도자가 다르면 양도자에게 사실상 배분될 금액"],["양도비 등","증권거래세, 신고서·계약서 작성비용, 공증비용·인지대·소개비, 명도비용","양도하기 위해 직접 지출한 비용"],["양도비 등","토지 취득 때 매입한 국민주택채권·토지개발채권의 만기 전 양도 매각차손","금융기관 외의 자에게 양도하면 같은 날 금융기관에 양도했을 때의 매각차손이 한도"],["공통 요건","증명서류 수취·보관 또는 금융거래 증명서류로 지출사실 확인","증명이 없으면 필요경비 불산입"]]},{"종류":"비교","제목":"취득원가에 넣는 이자와 넣지 않는 이자","왼쪽":{"이름":"취득원가에 포함","항목":["당사자 약정에 의한 대금지급방법에 따라 취득원가에 가산한 이자상당액","현재가치할인차금(사업소득 필요경비로 상각한 금액은 공제)"]},"오른쪽":{"이름":"취득원가에 불포함","항목":["당초 약정한 지급기일의 지연으로 추가 발생하는 이자상당액","부당행위계산에 의한 시가초과액"]}}],"함정":"소송비용은 그 지출한 연도에 이미 필요경비로 넣은 금액을 뺀 나머지만 자본적지출액 등이 된다. 같은 비용을 두 번 공제하지 않게 하는 규정이다. ⑤는 부령 명칭만 바뀌었고 내용은 같다.","개정":"시행령 제163조 제5항 제2호의 금융기관을 정하는 부령이 현행 조문(<개정 2025.12.30> 표시)에서 재정경제부령으로 표기되어 선지 ⑤의 부령 명칭을 이에 맞췄다. 정답은 그대로다."},"36회-2차-088":{"한줄":"지적확정측량의 경계는 공사가 완료된 현황대로 결정하고 사업계획도와 다르면 미리 사업시행자에게 통지하므로(영 제55조제5항) ⑤가 틀리다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제55조제5항","원문":"지적확정측량의 경계는 공사가 완료된 현황대로 결정하되, 공사가 완료된 현황이 사업계획도와 다를 때에는 미리 사업시행자에게 그 사실을 통지하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제65조제2항","원문":"지적소관청은 토지의 이동에 따라 지상경계를 새로 정한 경우에는 다음 각 호의 사항을 등록한 지상경계점등록부를 작성ㆍ관리하여야 한다. 1. 토지의 소재 2. 지번 3. 경계점 좌표(경계점좌표등록부 시행지역에 한정한다) 4. 경계점 위치 설명도 5. 그 밖에 국토교통부령으로 정하는 사항"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"규칙 제60조제2항","원문":"법 제65조제2항제5호에서 \"그 밖에 국토교통부령으로 정하는 사항\"이란 다음 각 호의 사항을 말한다. 1. 공부상 지목과 실제 토지이용 지목 2. 경계점의 사진 파일 3. 경계점표지의 종류 및 경계점 위치"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제55조제3항제5호","원문":"관계 법령에 따라 인가ㆍ허가 등을 받아 토지를 분할하려는 경우"}],"선지":[{"번호":1,"판정":"옳음","설명":"토지의 이동에 따라 지상경계를 새로 정한 경우 지상경계점등록부를 작성·관리한다(법 제65조제2항)."},{"번호":2,"판정":"옳음","설명":"경계점 좌표는 경계점좌표등록부 시행지역에 한정하여 지상경계점등록부에 등록한다(법 제65조제2항제3호)."},{"번호":3,"판정":"옳음","설명":"관계 법령에 따라 인가·허가 등을 받아 토지를 분할하려는 경우 지상 경계점에 경계점표지를 설치하여 측량할 수 있다(영 제55조제3항제5호)."},{"번호":4,"판정":"옳음","설명":"경계점 위치 설명도, 경계점표지의 종류 및 경계점 위치는 지상경계점등록부의 등록사항이다(법 제65조제2항제4호, 규칙 제60조제2항제3호)."},{"번호":5,"판정":"틀림","설명":"지적확정측량의 경계는 공사가 완료된 현황대로 결정하고, 현황이 사업계획도와 다르면 미리 사업시행자에게 통지한다. 사업계획도대로 결정하는 것도, 지적측량수행자에게 통지하는 것도 아니다(영 제55조제5항)."}],"개념":[{"종류":"표","제목":"지상경계점등록부(법 제65조제2항, 규칙 제60조제2항)","머리":["구분","등록사항"],"행":[["토지의 소재","법 제65조제2항제1호"],["지번","법 제65조제2항제2호"],["경계점 좌표","경계점좌표등록부 시행지역에 한정(제3호)"],["경계점 위치 설명도","법 제65조제2항제4호"],["공부상 지목과 실제 토지이용 지목","규칙 제60조제2항제1호"],["경계점의 사진 파일","규칙 제60조제2항제2호"],["경계점표지의 종류 및 경계점 위치","규칙 제60조제2항제3호"]]},{"종류":"표","제목":"지적확정측량 경계 결정(영 제55조제5항)","머리":["구분","내용"],"행":[["결정 기준","공사가 완료된 현황"],["사업계획도와 다를 때","미리 사업시행자에게 통지"]]}],"함정":"⑤는 기준(현황과 사업계획도)과 통지 상대(사업시행자와 지적측량수행자)를 모두 바꿨다. 지적확정측량은 공사 완료 현황이 기준이다."},"36회-2차-090":{"한줄":"토지대장과 공유지연명부의 공통 등록사항은 지번, 토지의 고유번호, 소유자의 성명 등이므로 ㄱ, ㄷ, ㄹ을 고른 ③이 옳다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제71조제1항","원문":"토지대장과 임야대장에는 다음 각 호의 사항을 등록하여야 한다. 1. 토지의 소재 2. 지번 3. 지목 4. 면적 5. 소유자의 성명 또는 명칭, 주소 및 주민등록번호(국가, 지방자치단체, 법인, 법인 아닌 사단이나 재단 및 외국인의 경우에는 「부동산등기법」 제49조에 따라 부여된 등록번호를 말한다. 이하 같다) 6. 그 밖에 국토교통부령으로 정하는 사항"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제71조제2항","원문":"제1항제5호의 소유자가 둘 이상이면 공유지연명부에 다음 각 호의 사항을 등록하여야 한다. 1. 토지의 소재 2. 지번 3. 소유권 지분 4. 소유자의 성명 또는 명칭, 주소 및 주민등록번호 5. 그 밖에 국토교통부령으로 정하는 사항"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"규칙 제68조제2항","원문":"법 제71조제1항제6호에서 \"그 밖에 국토교통부령으로 정하는 사항\"이란 다음 각 호의 사항을 말한다. 1. 토지의 고유번호(각 필지를 서로 구별하기 위하여 필지마다 붙이는 고유한 번호를 말한다. 이하 같다) 2. 지적도 또는 임야도의 번호와 필지별 토지대장 또는 임야대장의 장번호 및 축척 3. 토지의 이동사유 4. 토지소유자가 변경된 날과 그 원인 5. 토지등급 또는 기준수확량등급과 그 설정ㆍ수정 연월일 6. 개별공시지가와 그 기준일 7. 그 밖에 국토교통부장관이 정하는 사항"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"규칙 제68조제3항","원문":"법 제71조제2항제5호에서 \"그 밖에 국토교통부령으로 정하는 사항\"이란 다음 각 호의 사항을 말한다. 1. 토지의 고유번호 2. 필지별 공유지연명부의 장번호 3. 토지소유자가 변경된 날과 그 원인"}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄱ, ㄷ만 고르면 ㄹ 소유자의 성명 등이 빠진다(법 제71조제1항제5호, 제2항제4호)."},{"번호":2,"판정":"틀림","설명":"ㄴ 토지의 이동사유는 토지대장에만 있고 ㄷ이 빠졌다(규칙 제68조제2항제3호)."},{"번호":3,"판정":"옳음","설명":"ㄱ 지번, ㄷ 토지의 고유번호, ㄹ 소유자의 성명 등이 공통이다(법 제71조제1항·제2항, 규칙 제68조제2항제1호·제3항제1호)."},{"번호":4,"판정":"틀림","설명":"ㄴ 토지의 이동사유는 토지대장에만 있다(규칙 제68조제2항제3호)."},{"번호":5,"판정":"틀림","설명":"ㄴ 토지의 이동사유는 공유지연명부에 없다(규칙 제68조제3항)."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"지번은 두 공부에 모두 있다(법 제71조제1항제2호, 제2항제2호)."},{"기호":"ㄴ","판정":"틀림","설명":"토지의 이동사유는 토지대장·임야대장에만 있다(규칙 제68조제2항제3호)."},{"기호":"ㄷ","판정":"옳음","설명":"토지의 고유번호는 두 공부에 모두 있다(규칙 제68조제2항제1호, 제3항제1호)."},{"기호":"ㄹ","판정":"옳음","설명":"소유자의 성명 또는 명칭, 주소 및 주민등록번호는 두 공부에 모두 있다(법 제71조제1항제5호, 제2항제4호)."}],"개념":[{"종류":"표","제목":"공부 사이 공통 등록사항","머리":["비교","공통 등록사항"],"행":[["공유지연명부와 대지권등록부","토지의 소재, 지번, 소유권 지분, 소유자의 성명 또는 명칭·주소·주민등록번호, 토지의 고유번호, 토지소유자가 변경된 날과 그 원인"],["토지대장과 공유지연명부","토지의 소재, 지번, 소유자의 성명 또는 명칭·주소·주민등록번호, 토지의 고유번호, 토지소유자가 변경된 날과 그 원인"],["대지권등록부와 경계점좌표등록부","토지의 소재, 지번, 토지의 고유번호"],["대지권에만 있는 사항","대지권 비율, 전유부분의 건물표시, 건물의 명칭, 집합건물별 대지권등록부의 장번호"],["토지대장·임야대장에만 있는 사항","지목, 면적, 지도 번호와 축척, 토지의 이동사유, 토지등급, 개별공시지가"]]},{"종류":"표","제목":"지적공부별 등록사항(법 제71조~제73조, 규칙 제68조·제69조·제71조)","머리":["공부","등록사항"],"행":[["토지대장·임야대장","토지의 소재, 지번, 지목, 면적, 소유자의 성명 또는 명칭·주소·주민등록번호, 토지의 고유번호, 지적도 또는 임야도의 번호와 필지별 장번호 및 축척, 토지의 이동사유, 토지소유자가 변경된 날과 그 원인, 토지등급 또는 기준수확량등급과 설정·수정 연월일, 개별공시지가와 그 기준일"],["공유지연명부","토지의 소재, 지번, 소유권 지분, 소유자의 성명 또는 명칭·주소·주민등록번호, 토지의 고유번호, 필지별 공유지연명부의 장번호, 토지소유자가 변경된 날과 그 원인"],["대지권등록부","토지의 소재, 지번, 대지권 비율, 소유자의 성명 또는 명칭·주소·주민등록번호, 토지의 고유번호, 전유부분의 건물표시, 건물의 명칭, 집합건물별 대지권등록부의 장번호, 토지소유자가 변경된 날과 그 원인, 소유권 지분"],["경계점좌표등록부","토지의 소재, 지번, 좌표, 토지의 고유번호, 지적도면의 번호, 필지별 경계점좌표등록부의 장번호, 부호 및 부호도"],["지적도·임야도","토지의 소재, 지번, 지목, 경계, 지적도면의 색인도, 지적도면의 제명 및 축척, 도곽선과 그 수치, 좌표에 의하여 계산된 경계점 간의 거리(경계점좌표등록부 시행지역), 삼각점 및 지적기준점의 위치, 건축물 및 구조물 등의 위치"]]}],"함정":"토지의 이동사유는 토지대장·임야대장에만 있고 공유지연명부에는 없다. 소유자의 성명 등은 토지대장에서 소유자가 둘 이상이면 공유지연명부에도 등록한다."},"36회-2차-081":{"한줄":"토지의 합병은 토지소유자의 신청으로 지적공부를 정리하는 절차이고 법 제23조제1항에 지적측량 사유로 열거돼 있지 않으므로 ①이 틀리다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제23조제1항","원문":"다음 각 호의 어느 하나에 해당하는 경우에는 지적측량을 하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제23조제1항제3호","원문":"다음 각 목의 어느 하나에 해당하는 경우로서 측량을 할 필요가 있는 경우 가. 제74조에 따라 지적공부를 복구하는 경우 나. 제77조에 따라 토지를 신규등록하는 경우 다. 제78조에 따라 토지를 등록전환하는 경우 라. 제79조에 따라 토지를 분할하는 경우 마. 제82조에 따라 바다가 된 토지의 등록을 말소하는 경우 바. 제83조에 따라 축척을 변경하는 경우 사. 제84조에 따라 지적공부의 등록사항을 정정하는 경우 아. 제86조에 따른 도시개발사업 등의 시행지역에서 토지의 이동이 있는 경우 자. 「지적재조사에 관한 특별법」에 따른 지적재조사사업에 따라 토지의 이동이 있는 경우"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제80조제1항","원문":"토지소유자는 토지를 합병하려면 대통령령으로 정하는 바에 따라 지적소관청에 합병을 신청하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"합병은 지적측량 사유가 아니다. 토지소유자가 합병을 신청하면 지적공부를 정리한다(법 제80조제1항, 제23조제1항)."},{"번호":2,"판정":"옳음","설명":"지적측량성과의 검사는 지적측량을 하여야 하는 경우다(법 제23조제1항제2호)."},{"번호":3,"판정":"옳음","설명":"등록전환으로 측량을 할 필요가 있는 경우는 지적측량을 해야 한다(법 제23조제1항제3호다목)."},{"번호":4,"판정":"옳음","설명":"신규등록으로 측량을 할 필요가 있는 경우는 지적측량을 해야 한다(법 제23조제1항제3호나목)."},{"번호":5,"판정":"옳음","설명":"지적재조사사업에 따라 토지의 이동이 있는 경우 측량이 필요하면 지적측량을 해야 한다(법 제23조제1항제3호자목)."}],"개념":[{"종류":"표","제목":"지적측량 사유가 아닌 토지이동","머리":["토지이동","지적측량"],"행":[["신규등록·등록전환·분할","필요한 경우 실시(제23조제1항제3호)"],["합병","열거 없음. 측량 없이 신청에 따라 지적공부 정리(법 제80조)"],["지목변경","열거 없음"],["바다로 된 토지의 등록말소·축척변경·등록사항정정","필요한 경우 실시(제3호)"]]}],"함정":"분할은 측량 사유이고 합병은 측량 사유가 아니다. 성과 검사(②)는 지적측량을 하여야 하는 경우에는 들어가지만 의뢰 대상에서는 빠진다."},"36회-2차-018":{"한줄":"등록증을 대여한 경우(ㄱ)와 최근 1년 이내 업무정지 2회 후 다시 업무정지 해당 행위를 한 경우(ㄴ)는 법 제38조제1항의 필요적 취소 사유이고, 전속중개계약서 위반(ㄷ)은 업무정지 사유다.","근거":[{"법령":"공인중개사법","조문":"법 제38조제1항제6호","원문":"제19조제1항의 규정을 위반하여 다른 사람에게 자기의 성명 또는 상호를 사용하여 중개업무를 하게 하거나 중개사무소등록증을 양도 또는 대여한 경우"},{"법령":"공인중개사법","조문":"법 제38조제1항제8호","원문":"최근 1년 이내에 이 법에 의하여 2회 이상 업무정지처분을 받고 다시 업무정지처분에 해당하는 행위를 한 경우"},{"법령":"공인중개사법","조문":"법 제39조제1항제3호","원문":"제23조제2항의 규정을 위반하여 국토교통부령으로 정하는 전속중개계약서에 의하지 아니하고 전속중개계약을 체결하거나 계약서를 보존하지 아니한 경우"}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄴ도 등록취소 사유라 ㄱ만 고른 조합은 부족하다."},{"번호":2,"판정":"옳음","설명":"ㄱ, ㄴ이 등록취소 사유이고 ㄷ은 업무정지 사유여서 이 조합이 맞다."},{"번호":3,"판정":"틀림","설명":"ㄷ은 업무정지 사유라 등록취소 사유가 아니다. ㄴ이 빠지기도 했다."},{"번호":4,"판정":"틀림","설명":"ㄷ은 등록취소 사유가 아니고 ㄱ이 빠졌다."},{"번호":5,"판정":"틀림","설명":"ㄷ은 등록취소 사유가 아니므로 세 보기를 모두 고르면 맞지 않는다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"자기의 중개사무소등록증을 다른 사람에게 대여한 경우는 등록취소 사유다(법 제38조제1항제6호)."},{"기호":"ㄴ","판정":"옳음","설명":"최근 1년 이내 2회 이상 업무정지처분을 받고 다시 업무정지 해당 행위를 한 경우는 등록취소 사유다(법 제38조제1항제8호)."},{"기호":"ㄷ","판정":"틀림","설명":"전속중개계약서에 의하지 않은 전속중개계약 체결은 업무정지 사유다(법 제39조제1항제3호). 등록취소 사유가 아니다."}],"개념":[{"종류":"표","제목":"중개사무소 개설등록 취소 사유","머리":["구분","사유","조문"],"행":[["필요적 취소","개인인 개업공인중개사의 사망, 법인의 해산","법 제38조제1항제1호"],["필요적 취소","거짓이나 그 밖의 부정한 방법으로 개설등록","제1항제2호"],["필요적 취소","결격사유 해당(제10조제1항제2호~제6호, 제11호, 제12호)","제1항제3호"],["필요적 취소","이중등록","제1항제4호"],["필요적 취소","다른 개업공인중개사의 소속공인중개사·중개보조원 또는 법인의 사원·임원이 된 경우","제1항제5호"],["필요적 취소","중개보조원 고용 상한(개업공인중개사와 소속공인중개사 합산 수의 5배) 초과","제1항제5호의2"],["필요적 취소","자기의 성명·상호를 사용하여 중개업무를 하게 하거나 등록증을 양도·대여","제1항제6호"],["필요적 취소","업무정지기간 중 중개업무, 자격정지 중인 소속공인중개사에게 중개업무를 하게 함","제1항제7호"],["필요적 취소","최근 1년 이내 2회 이상 업무정지처분을 받고 다시 업무정지 해당 행위","제1항제8호"],["임의적 취소","등록기준 미달, 둘 이상의 중개사무소, 임시 중개시설물, 겸업 위반","법 제38조제2항제1호~제4호"],["임의적 취소","6개월 초과 휴업, 정보 비공개 위반, 거래계약서 거짓 기재, 손해배상 보장조치 미이행, 금지행위","제2항제5호~제9호"],["임의적 취소","최근 1년 이내 3회 이상 업무정지 또는 과태료 처분을 받고 다시 업무정지 또는 과태료 처분 해당 행위(제1항제8호 해당 제외)","제2항제10호"],["임의적 취소","사업자단체 또는 구성원이 공정거래법 위반으로 최근 2년 이내 2회 이상 처분","제2항제11호"]]},{"종류":"표","제목":"개업공인중개사 업무정지 사유와 기준(법 제39조제1항, 시행규칙 별표 4)","머리":["호","사유","정지 기간"],"행":[["1","제10조제1항제1호~제11호에 해당하는 자를 소속공인중개사·중개보조원으로 둠(사유 발생일부터 2개월 이내 해소하면 제외)","6개월"],["2","인장등록을 하지 않거나 등록하지 않은 인장 사용","3개월"],["3","전속중개계약서에 따르지 않고 전속중개계약 체결, 계약서 미보존","3개월"],["4","부동산거래정보망에 정보를 거짓으로 공개 / 거래 완성 사실 미통보","6개월 / 3개월"],["6","중개대상물확인·설명서 미교부, 미보존","3개월"],["7","중개대상물확인·설명서에 서명 및 날인하지 않음","3개월"],["8","거래계약서를 적정하게 작성·교부하지 않거나 보존하지 않음","3개월"],["9","거래계약서에 서명 및 날인하지 않음","3개월"],["10","보고·자료 제출·조사·검사 거부·방해·기피, 명령 불이행, 거짓 보고","3개월"],["11","제38조제2항 각 호 사유에 해당(최근 1년 이내 1회 위반)","6개월"],["12","최근 1년 이내 2회 이상 업무정지 또는 과태료 처분을 받고 다시 과태료 처분에 해당하는 행위","6개월"],["14","그 밖에 이 법 또는 이 법에 따른 명령·처분을 위반(위 호에 해당하지 않는 경우)","1개월"]]}],"함정":"ㄷ에서 전속중개계약서와 일반중개계약서를 구분해야 한다. 전속중개계약서에 따르지 않은 계약 체결은 업무정지 3개월(제39조제1항제3호)이다. ㄱ은 등록증 양도·대여로 읽어도 제19조제1항 위반이라 같은 필요적 취소 사유다."},"36회-2차-024":{"한줄":"산업입지 및 개발에 관한 법률에 따른 토지 공급계약은 영 제3조제3항제5호의 공급계약 근거 법률이라 신고 대상이다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"영 제3조제3항제5호","원문":"5. 「산업입지 및 개발에 관한 법률」"},{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제3조제1항","원문":"① 거래당사자는 다음 각 호의 어느 하나에 해당하는 계약을 체결한 경우 그 실제 거래가격 등 대통령령으로 정하는 사항을 거래계약의 체결일부터 30일 이내에 그 권리의 대상인 부동산등(권리에 관한 계약의 경우에는 그 권리의 대상인 부동산을 말한다)의 소재지를 관할하는 시장(구가 설치되지 아니한 시의 시장 및 특별자치시장과 특별자치도 행정시의 시장을 말한다)ㆍ군수 또는 구청장(이하 \"신고관청\"이라 한다)에게 공동으로 신고하여야 한다. 다만, 거래당사자 중 일방이 국가, 지방자치단체, 대통령령으로 정하는 자의 경우(이하 \"국가등\"이라 한다)에는 국가등이 신고를 하여야 한다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제3조제3항","원문":"③ 「공인중개사법」 제2조제4호에 따른 개업공인중개사(이하 \"개업공인중개사\"라 한다)가 같은 법 제26조제1항에 따라 거래계약서를 작성ㆍ교부한 경우에는 제1항에도 불구하고 해당 개업공인중개사가 같은 항에 따른 신고를 하여야 한다. 이 경우 공동으로 중개를 한 경우에는 해당 개업공인중개사가 공동으로 신고하여야 한다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제3조제5항","원문":"⑤ 제1항부터 제4항까지에 따라 신고를 받은 신고관청은 그 신고 내용을 확인한 후 신고인에게 신고필증을 지체 없이 발급하여야 한다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제3조제6항","원문":"⑥ 부동산등의 매수인은 신고인이 제5항에 따른 신고필증을 발급받은 때에 「부동산등기 특별조치법」 제3조제1항에 따른 검인을 받은 것으로 본다."}],"선지":[{"번호":1,"판정":"옳음","설명":"산업입지 및 개발에 관한 법률은 공급계약 근거 법률이다(영 제3조제3항제5호)."},{"번호":2,"판정":"틀림","설명":"지방자치단체는 국가등이어서 한쪽이 지방자치단체이면 지방자치단체가 신고한다(법 제3조제1항 단서)."},{"번호":3,"판정":"틀림","설명":"개업공인중개사가 거래계약서를 작성·교부한 경우에는 해당 개업공인중개사가 신고하여야 한다(법 제3조제3항). 선택하여 할 수 있는 구조가 아니다."},{"번호":4,"판정":"틀림","설명":"검인을 받은 것으로 보는 때는 신고인이 신고필증을 발급받은 때다. 신고서를 제출한 때가 아니다(법 제3조제6항)."},{"번호":5,"판정":"틀림","설명":"거래당사자 일방이 신고를 거부해 단독으로 신고하는 경우에도 신고기간은 계약 체결일부터 30일이다(법 제3조제1항·제2항)."}],"개념":[{"종류":"표","제목":"신고 주체와 방법(법 제3조)","머리":["상황","신고 주체·방법","근거"],"행":[["거래당사자 직접거래","거래당사자가 공동으로 신고. 계약 체결일부터 30일 이내","법 제3조제1항"],["일방이 국가등","국가등이 신고하고 서명 또는 날인도 국가등이 단독으로 한다","법 제3조제1항 단서, 규칙 제2조제2항"],["국가등의 범위","국가, 지방자치단체, 공공기관, 지방직영기업·지방공사·지방공단","법 제3조제1항 단서, 영 제3조제2항"],["개업공인중개사가 거래계약서를 작성·교부","개업공인중개사가 신고. 공동중개이면 공동으로 신고","법 제3조제3항"],["일방이 신고 거부","다른 일방이 단독 신고. 거래계약서 사본, 계약금 지급 확인 서류, 단독신고사유서 첨부","법 제3조제2항·제4항, 규칙 제2조제3항"],["소속공인중개사","개업공인중개사의 위임을 받아 제출을 대행하고 신분증명서를 보여준다","규칙 제5조제2항"]]},{"종류":"흐름","제목":"부동산 거래신고 절차","단계":[{"이름":"신고서 작성","설명":"거래계약 체결일부터 30일 이내에 별지 제1호서식 작성. 직접거래는 당사자 공동 서명 또는 날인"},{"이름":"제출","설명":"권리 대상 부동산 소재지 신고관청(시장·군수·구청장, 구가 없는 시의 시장·특별자치시장·특별자치도 행정시 시장 포함)에 제출. 신분증명서 제시"},{"이름":"신고필증 발급","설명":"신고내용 확인 후 지체 없이 발급(법 제3조제5항). 규칙상 신고서가 제출된 때 별지 제2호서식으로 발급"},{"이름":"검인 간주","설명":"신고인이 신고필증을 발급받은 때 부동산등의 매수인은 부동산등기 특별조치법 제3조제1항의 검인을 받은 것으로 봄"},{"이름":"정정·변경·해제등","설명":"잘못 기재 시 정정 신청, 등기신청 전 변경신고, 해제등 확정일부터 30일 이내 해제등 신고"}]}],"함정":"신고필증 발급 시점과 신고서 제출 시점이 다르다. 검인 간주는 필증 발급 때다. 단독 신고에도 기간은 30일로 같다."},"36회-2차-031":{"한줄":"증여는 계약에 의한 취득이어서 계약체결일부터 60일 이내에 신고하고, 취득일부터 6개월 규정은 계약 외의 원인에만 적용된다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제8조제1항","원문":"① 외국인등이 대한민국 안의 부동산등을 취득하는 계약(제3조제1항 각 호에 따른 계약은 제외한다)을 체결하였을 때에는 계약체결일부터 60일 이내에 대통령령으로 정하는 바에 따라 신고관청에 신고하여야 한다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제8조제2항","원문":"② 외국인등이 상속ㆍ경매, 그 밖에 대통령령으로 정하는 계약 외의 원인으로 대한민국 안의 부동산등을 취득한 때에는 부동산등을 취득한 날부터 6개월 이내에 대통령령으로 정하는 바에 따라 신고관청에 신고하여야 한다."},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"영 제5조제2항","원문":"② 법 제8조제2항에서 \"대통령령으로 정하는 계약 외의 원인\"이란 다음 각 호의 어느 하나에 해당하는 사유를 말한다. … 1. 「공익사업을 위한 토지 등의 취득 및 보상에 관한 법률」 및 그 밖의 법률에 따른 환매권의 행사 … 2. 법원의 확정판결 … 3. 법인의 합병 … 4. 건축물의 신축ㆍ증축ㆍ개축ㆍ재축"}],"선지":[{"번호":1,"판정":"-","설명":"상속은 법 제8조제2항에 직접 규정된 취득원인이고 취득한 날부터 6개월 이내에 신고한다."},{"번호":2,"판정":"-","설명":"증여는 계약에 의한 취득이다. 계약체결일부터 60일 이내에 신고한다(법 제8조제1항)."},{"번호":3,"판정":"-","설명":"법원의 확정판결은 영 제5조제2항제2호의 계약 외 원인이다. 6개월."},{"번호":4,"판정":"-","설명":"건축물의 신축·증축·개축·재축은 영 제5조제2항제4호의 계약 외 원인이다. 6개월."},{"번호":5,"판정":"-","설명":"환매권 행사는 영 제5조제2항제1호의 계약 외 원인이다. 6개월."}],"개념":[{"종류":"표","제목":"외국인등의 부동산 취득·보유 신고(법 제8조, 영 제5조)","머리":["취득 원인","신고 기한","근거"],"행":[["매매·공급계약 등 법 제3조제1항 각 호의 계약","계약 체결일부터 30일 이내 거래신고(취득신고 대상 아님)","법 제3조, 제8조제1항 괄호"],["그 밖의 취득 계약(증여 등)","계약 체결일부터 60일 이내 취득신고","법 제8조제1항"],["상속·경매","취득한 날부터 6개월 이내","법 제8조제2항"],["환매권 행사, 법원의 확정판결, 법인의 합병, 건축물의 신축·증축·개축·재축","취득한 날부터 6개월 이내","법 제8조제2항, 영 제5조제2항"],["국민·국내 법인이 외국인등으로 변경되어 계속 보유","외국인등으로 변경된 날부터 6개월 이내 계속보유 신고","법 제8조제3항"]]}],"함정":"계약 외의 원인은 상속·경매와 영 제5조제2항의 네 가지(환매권 행사, 확정판결, 합병, 건축물의 신축·증축·개축·재축)다. 증여는 이 목록에 없고 계약이다."},"36회-2차-032":{"한줄":"분묘기지권의 효력 범위 안이라도 기존 분묘 외에 새로운 분묘를 신설할 권능은 포함되지 않는다.","근거":[{"판례":"대법원 2021. 4. 29. 선고 2017다228007 전원합의체 판결","요지":"분묘기지권이 성립한 유형별로 지료 지급의무가 다르다. 토지 소유자의 승낙으로 성립한 경우 성립 당시 지료에 관한 약정이 있으면 그 효력이 분묘 기지의 승계인에게도 미친다. 자기 소유 토지에 분묘를 설치한 사람이 이장 특약 없이 토지를 양도하여 분묘기지권을 취득한 경우 특별한 사정이 없으면 성립한 때부터 지료를 지급해야 한다. 시효로 취득한 분묘기지권자는 토지 소유자가 지료를 청구한 날부터 지료를 지급해야 한다."},{"판례":"대법원 판례(분묘기지권의 성립과 범위)","요지":"분묘기지권은 봉분 등 외부에서 분묘의 존재를 인식할 수 있는 형태를 갖추고 시신이 안장되어 있어야 성립한다. 암장이나 장래의 묘소는 성립하지 않는다. 효력은 분묘 기지와 수호·제사에 필요한 범위의 주위 공지에 미치고, 기존 분묘 외에 새 분묘를 신설할 권능은 포함하지 않는다. 유골이 존재해 원상회복이 가능한 일시적 멸실이면 소멸하지 않는다."},{"판례":"대법원 판례(분묘기지권과 제3자 대항)","요지":"시효로 분묘기지권을 취득한 사람은 등기하지 않아도 제3자에게 대항할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"새 분묘를 신설할 권능은 포함되지 않는다(판례). 기존 분묘 외 신설은 허용되지 않는다."},{"번호":2,"판정":"옳음","설명":"시효로 취득한 분묘기지권도 등기 없이 제3자에게 대항할 수 있다(판례)."},{"번호":3,"판정":"옳음","설명":"일시적 멸실이고 유골이 있어 원상회복이 가능하면 분묘기지권은 존속한다(판례)."},{"번호":4,"판정":"옳음","설명":"분묘 기지와 수호·제사에 필요한 범위의 주위 공지에 효력이 미친다(판례)."},{"번호":5,"판정":"옳음","설명":"승낙에 의한 분묘기지권에서 성립 당시 한 지료 약정의 효력은 분묘 기지의 승계인에게도 미친다(대법원 2021. 4. 29. 선고 2017다228007 전원합의체 판결)."}],"개념":[{"종류":"표","제목":"분묘기지권의 내용(판례)","머리":["항목","내용"],"행":[["성질","지상권 유사의 관습상 물권. 등기 없이 성립하고 제3자에게 대항한다. 등기사항증명서로 확인할 수 없다"],["성립 요건","봉분 등 외부에서 분묘의 존재를 인식할 수 있는 형태를 갖추고 시신이 안장되어 있어야 한다. 암장·평장으로 외형이 없거나 장래의 묘소(가묘)는 불성립"],["존속","특별한 사정이 없으면 권리자가 분묘를 수호·봉사하고 분묘가 존속하는 동안 존속"],["범위","분묘 기지 자체와 수호·제사에 필요한 범위의 주위 공지. 기존 분묘 외에 새 분묘를 신설할 권능은 포함되지 않는다"],["멸실","유골이 존재하여 원상회복이 가능한 일시적 멸실이면 소멸하지 않는다"],["포기","권리자가 포기의 의사표시를 하면 소멸. 점유까지 포기해야 소멸하는 것은 아니다"]]},{"종류":"표","제목":"분묘기지권의 성립 유형과 지료(판례)","머리":["유형","성립","지료 지급의무"],"행":[["승낙형","토지 소유자의 승낙을 받아 분묘 설치","성립 당시 소유자와 분묘 수호·관리자가 지료에 관해 약정했다면 그 약정의 효력은 분묘 기지의 승계인에게도 미친다"],["양도형","자기 소유 토지에 분묘를 설치한 사람이 이장 특약 없이 토지를 양도","특별한 사정이 없으면 분묘기지권이 성립한 때부터 지료 지급의무가 있다"],["시효취득형","타인 토지에 승낙 없이 분묘를 설치하고 20년간 평온·공연하게 점유","토지 소유자가 지료를 청구한 날부터 지료를 지급할 의무가 있다"],["시효취득 제한","장사 등에 관한 법률 시행일(2001. 1. 13.) 이후 승낙 없이 설치한 분묘는 시효취득을 주장할 수 없다. 시행 전에 설치한 분묘는 시효취득이 가능하다","-"]]}],"함정":"분묘기지권의 범위에는 주위 공지가 들어가지만 새 분묘를 설치하는 권능은 들어가지 않는다. 범위를 넓게 읽은 ①이 틀린 선지다."}};